#!/bin/bash
set -uo pipefail

cd /home/ibex
export PATH="/usr/local/bin:/opt/micromamba/envs/ibex/bin:${PATH}"

TEST_NAME="double_fault_cpuctrl"
TB_DIR="/home/ibex/.tb_double_fault_cpuctrl"
BUILD_LOG="${TB_DIR}/build.log"
RUN_LOG="${TB_DIR}/run.log"

emit_test_result_and_exit() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

mkdir -p "${TB_DIR}"
rm -rf build/lowrisc_ibex_double_fault_csrs_tb_*
rm -f "${BUILD_LOG}" "${RUN_LOG}"

cat > "${TB_DIR}/double_fault_csrs_tb.sv" <<'EOF'
module double_fault_csrs_tb (
  input logic clk_i,
  input logic rst_ni,
  input logic csr_save_id_i,
  input logic csr_save_cause_i,
  input logic csr_restore_mret_i,
  input logic [5:0] csr_mcause_i_raw,
  input logic [31:0] pc_id_i,
  input logic [31:0] csr_mtval_i,
  input logic csr_access_i,
  input logic [11:0] csr_addr_i_raw,
  input logic [1:0] csr_op_i_raw,
  input logic csr_op_en_i,
  output logic [31:0] csr_rdata_o,
  output logic illegal_csr_insn_o
);
  import ibex_pkg::*;

  csr_num_e   csr_addr_i;
  csr_op_e    csr_op_i;
  exc_cause_e csr_mcause_i;

  assign csr_addr_i   = csr_num_e'(csr_addr_i_raw);
  assign csr_op_i     = csr_op_e'(csr_op_i_raw);
  assign csr_mcause_i = exc_cause_e'(csr_mcause_i_raw);

  /* verilator lint_off UNUSED */
  priv_lvl_e    priv_mode_id_o;
  priv_lvl_e    priv_mode_lsu_o;
  logic         csr_mstatus_tw_o;
  logic [31:0]  csr_mtvec_o;
  logic         irq_pending_o;
  irqs_t        irqs_o;
  logic         csr_mstatus_mie_o;
  logic [31:0]  csr_mepc_o;
  pmp_cfg_t     csr_pmp_cfg_o[4];
  logic [33:0]  csr_pmp_addr_o[4];
  pmp_mseccfg_t csr_pmp_mseccfg_o;
  logic [31:0]  csr_depc_o;
  logic         debug_single_step_o;
  logic         debug_ebreakm_o;
  logic         debug_ebreaku_o;
  logic         trigger_match_o;
  logic         data_ind_timing_o;
  logic         dummy_instr_en_o;
  logic [2:0]   dummy_instr_mask_o;
  logic         dummy_instr_seed_en_o;
  logic [31:0]  dummy_instr_seed_o;
  logic         icache_enable_o;
  logic         csr_shadow_err_o;
  /* verilator lint_on UNUSED */

  ibex_cs_registers dut (
    .clk_i,
    .rst_ni,
    .hart_id_i                    (32'h0),
    .priv_mode_id_o,
    .priv_mode_lsu_o,
    .csr_mstatus_tw_o,
    .csr_mtvec_o,
    .csr_mtvec_init_i             (1'b0),
    .boot_addr_i                  (32'h0),
    .csr_access_i,
    .csr_addr_i,
    .csr_wdata_i                  (32'h0),
    .csr_op_i,
    .csr_op_en_i,
    .csr_rdata_o,
    .irq_software_i               (1'b0),
    .irq_timer_i                  (1'b0),
    .irq_external_i               (1'b0),
    .irq_fast_i                   (15'h0),
    .nmi_mode_i                   (1'b0),
    .irq_pending_o,
    .irqs_o,
    .csr_mstatus_mie_o,
    .csr_mepc_o,
    .csr_pmp_cfg_o,
    .csr_pmp_addr_o,
    .csr_pmp_mseccfg_o,
    .debug_mode_i                 (1'b0),
    .debug_cause_i                (DBG_CAUSE_NONE),
    .debug_csr_save_i             (1'b0),
    .csr_depc_o,
    .debug_single_step_o,
    .debug_ebreakm_o,
    .debug_ebreaku_o,
    .trigger_match_o,
    .pc_if_i                      (32'h0),
    .pc_id_i,
    .pc_wb_i                      (32'h0),
    .data_ind_timing_o,
    .dummy_instr_en_o,
    .dummy_instr_mask_o,
    .dummy_instr_seed_en_o,
    .dummy_instr_seed_o,
    .icache_enable_o,
    .csr_shadow_err_o,
    .csr_save_if_i                (1'b0),
    .csr_save_id_i,
    .csr_save_wb_i                (1'b0),
    .csr_restore_mret_i,
    .csr_restore_dret_i           (1'b0),
    .csr_save_cause_i,
    .csr_mcause_i,
    .csr_mtval_i,
    .illegal_csr_insn_o,
    .instr_ret_i                 (1'b0),
    .instr_ret_compressed_i      (1'b0),
    .instr_ret_spec_i            (1'b0),
    .instr_ret_compressed_spec_i (1'b0),
    .iside_wait_i                (1'b0),
    .jump_i                      (1'b0),
    .branch_i                    (1'b0),
    .branch_taken_i              (1'b0),
    .mem_load_i                  (1'b0),
    .mem_store_i                 (1'b0),
    .dside_wait_i                (1'b0),
    .mul_wait_i                  (1'b0),
    .div_wait_i                  (1'b0)
  );
endmodule
EOF

cat > "${TB_DIR}/double_fault_csrs_tb.cc" <<'EOF'
#include <cstdint>
#include <iostream>

#include "Vdouble_fault_csrs_tb.h"
#include "verilated.h"

static vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

static void step(Vdouble_fault_csrs_tb &top) {
  top.clk_i = 0;
  top.eval();
  ++main_time;
  top.clk_i = 1;
  top.eval();
  ++main_time;
}

static uint32_t read_cpuctrl(Vdouble_fault_csrs_tb &top) {
  top.csr_access_i = 1;
  top.csr_addr_i_raw = 0x7c0;
  top.csr_op_i_raw = 0;
  top.csr_op_en_i = 1;
  top.eval();
  const uint32_t value = top.csr_rdata_o;
  top.csr_access_i = 0;
  top.csr_op_en_i = 0;
  top.eval();
  return value;
}

static bool expect_cpuctrl(const char *label, uint32_t actual, uint32_t expected) {
  std::cout << label << "=0x" << std::hex << actual << std::dec << std::endl;
  if (actual == expected) {
    return true;
  }

  std::cerr << "DOUBLE_FAULT_TEST_FAIL expected " << label << "=0x" << std::hex
            << expected << " but saw 0x" << actual << std::dec << std::endl;
  return false;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  Vdouble_fault_csrs_tb top;
  top.clk_i = 0;
  top.rst_ni = 0;
  top.csr_save_id_i = 0;
  top.csr_save_cause_i = 0;
  top.csr_restore_mret_i = 0;
  top.csr_mcause_i_raw = 0;
  top.pc_id_i = 0;
  top.csr_mtval_i = 0;
  top.csr_access_i = 0;
  top.csr_addr_i_raw = 0;
  top.csr_op_i_raw = 0;
  top.csr_op_en_i = 0;

  for (int i = 0; i < 4; ++i) {
    step(top);
  }

  top.rst_ni = 1;
  step(top);

  top.csr_mcause_i_raw = 0x02;
  top.pc_id_i = 0x10000000;
  top.csr_mtval_i = 0x11110001;
  top.csr_save_id_i = 1;
  top.csr_save_cause_i = 1;
  step(top);
  top.csr_save_id_i = 0;
  top.csr_save_cause_i = 0;
  step(top);

  if (!expect_cpuctrl("CPUCTRL_AFTER_FIRST", read_cpuctrl(top), 0x40)) {
    top.final();
    return 1;
  }

  top.csr_mcause_i_raw = 0x05;
  top.pc_id_i = 0x10000100;
  top.csr_mtval_i = 0x22220002;
  top.csr_save_id_i = 1;
  top.csr_save_cause_i = 1;
  step(top);
  top.csr_save_id_i = 0;
  top.csr_save_cause_i = 0;
  step(top);

  if (!expect_cpuctrl("CPUCTRL_AFTER_SECOND", read_cpuctrl(top), 0xc0)) {
    top.final();
    return 1;
  }

  top.csr_restore_mret_i = 1;
  step(top);
  top.csr_restore_mret_i = 0;
  step(top);

  if (!expect_cpuctrl("CPUCTRL_AFTER_MRET", read_cpuctrl(top), 0x80)) {
    top.final();
    return 1;
  }

  std::cout << "DOUBLE_FAULT_TEST_PASS" << std::endl;
  top.final();
  return 0;
}
EOF

cat > "${TB_DIR}/double_fault_csrs_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:ibex:double_fault_csrs_tb:0.1"
description: "Minimal CSR-level testbench for Ibex double fault detection"

filesets:
  files_sim:
    depend:
      - lowrisc:prim:assert
      - lowrisc:ibex:ibex_pkg
    files:
      - ../rtl/ibex_counter.sv
      - ../rtl/ibex_csr.sv
      - ../rtl/ibex_cs_registers.sv
      - ../rtl/ibex_pmp_reset_default.svh: { is_include_file: true }
      - double_fault_csrs_tb.sv
    file_type: systemVerilogSource

  files_verilator:
    files:
      - double_fault_csrs_tb.cc: { file_type: cppSource }

targets:
  sim:
    default_tool: verilator
    filesets:
      - files_sim
      - tool_verilator ? (files_verilator)
    toplevel: double_fault_csrs_tb
    tools:
      verilator:
        mode: cc
        verilator_options:
          - '-CFLAGS "-std=c++11 -Wall -g"'
          - '-LDFLAGS "-pthread"'
          - '-Wall'
          - '-Wno-fatal'
EOF

set +e
fusesoc --cores-root=. --cores-root="${TB_DIR}" run --target=sim --setup --build \
  lowrisc:ibex:double_fault_csrs_tb:0.1 2>&1 | tee "${BUILD_LOG}"
build_rc=${PIPESTATUS[0]}
set -e

if [ "${build_rc}" -ne 0 ]; then
  emit_test_result_and_exit "FAIL" "${build_rc}"
fi

SIM_BIN="$(find build -path '*/sim-verilator/Vdouble_fault_csrs_tb' | head -n 1)"
if [ -z "${SIM_BIN}" ]; then
  emit_test_result_and_exit "FAIL" 1
fi

set +e
"${SIM_BIN}" 2>&1 | tee "${RUN_LOG}"
run_rc=${PIPESTATUS[0]}
set -e

if [ "${run_rc}" -eq 0 ]; then
  emit_test_result_and_exit "PASS" 0
fi

emit_test_result_and_exit "FAIL" 1

