#!/bin/bash
set -u -o pipefail

cd /home/ibex

TEST_NAME="load_intg_nmi_vector"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_LOG="${TB_DIR}/build.log"
SIM_LOG="${TB_DIR}/sim.log"

finish_test() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_stubs.sv" <<'EOF'
module prim_buf #(
  parameter int Width = 1
) (
  input  logic [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  assign out_o = in_i;
endmodule

module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule

module prim_flop_en #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             en_i,
  input  logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else if (en_i) begin
      q_o <= d_i;
    end
  end
endmodule

module prim_clock_gating (
  input  logic clk_i,
  input  logic en_i,
  input  logic test_en_i,
  output logic clk_o
);
  logic unused_inputs;
  assign unused_inputs = en_i ^ test_en_i;
  assign clk_o = clk_i;
endmodule

module prim_clock_mux2 #(
  parameter bit NoFpgaBufG = 1'b1
) (
  input  logic clk0_i,
  input  logic clk1_i,
  input  logic sel_i,
  output logic clk_o
);
  logic unused_param;
  assign unused_param = NoFpgaBufG;
  assign clk_o = sel_i ? clk1_i : clk0_i;
endmodule

module prim_and2 (
  input  logic in0_i,
  input  logic in1_i,
  output logic out_o
);
  assign out_o = in0_i & in1_i;
endmodule

module prim_xor2 (
  input  logic in0_i,
  input  logic in1_i,
  output logic out_o
);
  assign out_o = in0_i ^ in1_i;
endmodule

module prim_xnor2 (
  input  logic in0_i,
  input  logic in1_i,
  output logic out_o
);
  assign out_o = ~(in0_i ^ in1_i);
endmodule

module prim_ram_1p import prim_ram_1p_pkg::*; #(
  parameter int Width = 32,
  parameter int Depth = 128,
  parameter int DataBitsPerMask = 1,
  parameter     MemInitFile = "",
  localparam int Aw = $clog2(Depth)
) (
  input  logic             clk_i,
  input  logic             req_i,
  input  logic             write_i,
  input  logic [Aw-1:0]    addr_i,
  input  logic [Width-1:0] wdata_i,
  input  logic [Width-1:0] wmask_i,
  output logic [Width-1:0] rdata_o,
  input  ram_1p_cfg_t      cfg_i
);
  logic unused_cfg;
  logic unused_mem_init;
  logic [Width-1:0] mem [Depth];

  assign unused_cfg = ^cfg_i;
  assign unused_mem_init = (MemInitFile != "");

  always_ff @(posedge clk_i) begin
    if (req_i) begin
      if (write_i) begin
        for (int i = 0; i < Width; i++) begin
          if (wmask_i[i]) begin
            mem[addr_i][i] <= wdata_i[i];
          end
        end
      end else begin
        rdata_o <= mem[addr_i];
      end
    end
  end
endmodule

package prim_count_pkg;
  typedef enum logic {
    CrossCnt,
    DupCnt
  } prim_count_style_e;

  typedef enum logic [1:0] {
    CmpInvalid = 2'b01,
    CmpValid   = 2'b10
  } cmp_valid_e;
endpackage

module prim_count import prim_count_pkg::*; #(
  parameter int Width = 2,
  parameter bit OutSelDnCnt = 1'b1,
  parameter prim_count_style_e CntStyle = CrossCnt,
  parameter bit EnableAlertTriggerSVA = 1'b1
) (
  input  logic             clk_i,
  input  logic             rst_ni,
  input  logic             clr_i,
  input  logic             set_i,
  input  logic [Width-1:0] set_cnt_i,
  input  logic             en_i,
  input  logic [Width-1:0] step_i,
  output logic [Width-1:0] cnt_o,
  output logic             err_o
);
  logic [Width-1:0] cnt_q;
  logic unused_cfg;

  assign unused_cfg = OutSelDnCnt ^ (CntStyle == DupCnt) ^ EnableAlertTriggerSVA;
  assign cnt_o = cnt_q;
  assign err_o = 1'b0;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cnt_q <= '0;
    end else if (clr_i) begin
      cnt_q <= '0;
    end else if (set_i) begin
      cnt_q <= set_cnt_i;
    end else if (en_i) begin
      cnt_q <= cnt_q + step_i;
    end
  end
endmodule
EOF

cat > "${TB_DIR}/tb_internal_irq.sv" <<'EOF'
module tb_internal_irq (
  input logic clk_i
);
  import ibex_pkg::*;

  localparam logic [31:0] BootAddr   = 32'h0000_0200;
  localparam logic [31:0] LoadAddr   = 32'h0000_0020;
  localparam logic [31:0] StatusAddr = 32'h0000_0024;

  logic rst_ni;
  logic instr_req;
  logic instr_gnt;
  logic instr_rvalid;
  logic [31:0] instr_addr;
  logic [38:0] instr_rdata;
  logic instr_err;

  logic data_req;
  logic data_gnt;
  logic data_rvalid;
  logic data_we;
  logic [3:0] data_be;
  logic [31:0] data_addr;
  logic [38:0] data_wdata;
  logic [38:0] data_rdata;
  logic data_err;

  logic dummy_instr_id;
  logic [4:0] rf_raddr_a;
  logic [4:0] rf_raddr_b;
  logic [4:0] rf_waddr_wb;
  logic rf_we_wb;
  logic [31:0] rf_wdata_wb;
  logic [31:0] rf_rdata_a;
  logic [31:0] rf_rdata_b;

  logic [IC_NUM_WAYS-1:0] ic_tag_req;
  logic ic_tag_write;
  logic [IC_INDEX_W-1:0] ic_tag_addr;
  logic [IC_TAG_SIZE-1:0] ic_tag_wdata;
  logic [IC_TAG_SIZE-1:0] ic_tag_rdata [IC_NUM_WAYS];
  logic [IC_NUM_WAYS-1:0] ic_data_req;
  logic ic_data_write;
  logic [IC_INDEX_W-1:0] ic_data_addr;
  logic [IC_LINE_SIZE-1:0] ic_data_wdata;
  logic [IC_LINE_SIZE-1:0] ic_data_rdata [IC_NUM_WAYS];

  logic irq_pending;
  crash_dump_t crash_dump;
  logic double_fault_seen;
  logic alert_minor;
  logic alert_major_internal;
  logic alert_major_bus;
  logic core_busy;

  logic [31:0] imem [0:255];
  logic [31:0] dmem [0:63];
  logic [31:0] rf_mem [0:31];
  logic [31:0] cycle_q;

  logic instr_rsp_valid_q;
  logic [31:0] instr_rsp_addr_q;

  logic data_rsp_valid_q;
  logic [31:0] data_rsp_addr_q;
  logic data_rsp_we_q;
  logic [3:0] data_rsp_be_q;
  logic [38:0] data_rsp_wdata_q;
  logic bad_load_seen_q;

  function automatic logic [31:0] enc_addi(
    input logic [4:0] rd,
    input logic [4:0] rs1,
    input integer imm
  );
    logic signed [11:0] simm;
    begin
      simm = imm[11:0];
      enc_addi = {simm[11:0], rs1, 3'b000, rd, 7'b0010011};
    end
  endfunction

  function automatic logic [31:0] enc_lw(
    input logic [4:0] rd,
    input logic [4:0] rs1,
    input integer imm
  );
    logic signed [11:0] simm;
    begin
      simm = imm[11:0];
      enc_lw = {simm[11:0], rs1, 3'b010, rd, 7'b0000011};
    end
  endfunction

  function automatic logic [31:0] enc_sw(
    input logic [4:0] rs2,
    input logic [4:0] rs1,
    input integer imm
  );
    logic signed [11:0] simm;
    begin
      simm = imm[11:0];
      enc_sw = {simm[11:5], rs2, rs1, 3'b010, simm[4:0], 7'b0100011};
    end
  endfunction

  function automatic logic [31:0] enc_jal(
    input logic [4:0] rd,
    input integer imm
  );
    logic signed [20:0] simm;
    begin
      simm = imm[20:0];
      enc_jal = {simm[20], simm[10:1], simm[11], simm[19:12], rd, 7'b1101111};
    end
  endfunction

  function automatic logic [38:0] good_ecc(input logic [31:0] data_word);
    good_ecc = prim_secded_pkg::prim_secded_inv_39_32_enc(data_word);
  endfunction

  function automatic logic [38:0] bad_ecc(input logic [31:0] data_word);
    bad_ecc = good_ecc(data_word) ^ 39'h40_0000_0000;
  endfunction

  assign rst_ni = (cycle_q >= 32'd5);

  assign instr_gnt = instr_req;
  assign instr_rvalid = instr_rsp_valid_q;
  assign instr_rdata = good_ecc(imem[instr_rsp_addr_q[9:2]]);
  assign instr_err = 1'b0;

  assign data_gnt = data_req;
  assign data_rvalid = data_rsp_valid_q;
  assign data_err = 1'b0;

  always_comb begin
    if (data_rsp_we_q) begin
      data_rdata = good_ecc(32'h0000_0000);
    end else if ((data_rsp_addr_q == LoadAddr) && !bad_load_seen_q) begin
      data_rdata = bad_ecc(dmem[LoadAddr[7:2]]);
    end else begin
      data_rdata = good_ecc(dmem[data_rsp_addr_q[7:2]]);
    end
  end

  always_comb begin
    rf_rdata_a = (rf_raddr_a == 5'd0) ? 32'h0000_0000 : rf_mem[rf_raddr_a];
    rf_rdata_b = (rf_raddr_b == 5'd0) ? 32'h0000_0000 : rf_mem[rf_raddr_b];
  end

  always_ff @(posedge clk_i) begin
    cycle_q <= cycle_q + 32'd1;

    if (!rst_ni) begin
      instr_rsp_valid_q <= 1'b0;
      instr_rsp_addr_q <= 32'h0;
      data_rsp_valid_q <= 1'b0;
      data_rsp_addr_q <= 32'h0;
      data_rsp_we_q <= 1'b0;
      data_rsp_be_q <= 4'h0;
      data_rsp_wdata_q <= '0;
      bad_load_seen_q <= 1'b0;
      for (int i = 0; i < 32; i++) begin
        rf_mem[i] <= 32'h0;
      end
    end else begin
      instr_rsp_valid_q <= instr_req;
      if (instr_req) begin
        instr_rsp_addr_q <= instr_addr;
      end

      data_rsp_valid_q <= data_req;
      if (data_req) begin
        data_rsp_addr_q <= data_addr;
        data_rsp_we_q <= data_we;
        data_rsp_be_q <= data_be;
        data_rsp_wdata_q <= data_wdata;
      end

      if (rf_we_wb && (rf_waddr_wb != 5'd0)) begin
        rf_mem[rf_waddr_wb] <= rf_wdata_wb;
      end

      if (data_rsp_valid_q && !data_rsp_we_q && (data_rsp_addr_q == LoadAddr) && !bad_load_seen_q) begin
        bad_load_seen_q <= 1'b1;
      end

      if (data_rsp_valid_q && data_rsp_we_q) begin
        for (int i = 0; i < 4; i++) begin
          if (data_rsp_be_q[i]) begin
            dmem[data_rsp_addr_q[7:2]][8*i +: 8] <= data_rsp_wdata_q[8*i +: 8];
          end
        end
      end

      if (data_rsp_valid_q && data_rsp_we_q && (data_rsp_addr_q == StatusAddr)) begin
        if (data_rsp_wdata_q[31:0] == 32'd2) begin
          $display("TB_PASS marker=%0d cycle=%0d", data_rsp_wdata_q[31:0], cycle_q);
          $finish;
        end else if (data_rsp_wdata_q[31:0] == 32'd1) begin
          $fatal(1, "TB_FAIL synchronous exception marker=%0d cycle=%0d",
                 data_rsp_wdata_q[31:0], cycle_q);
        end else begin
          $fatal(1, "TB_FAIL unexpected marker=%0d cycle=%0d",
                 data_rsp_wdata_q[31:0], cycle_q);
        end
      end

      if (cycle_q > 32'd300) begin
        $fatal(1, "TB_FAIL timeout cycle=%0d bad_load_seen=%0d", cycle_q, bad_load_seen_q);
      end
    end
  end

  initial begin
    cycle_q = 32'd0;
    instr_rsp_valid_q = 1'b0;
    instr_rsp_addr_q = 32'h0;
    data_rsp_valid_q = 1'b0;
    data_rsp_addr_q = 32'h0;
    data_rsp_we_q = 1'b0;
    data_rsp_be_q = 4'h0;
    data_rsp_wdata_q = '0;
    bad_load_seen_q = 1'b0;

    for (int i = 0; i < 256; i++) begin
      imem[i] = 32'h0000_0013;
    end

    for (int i = 0; i < 64; i++) begin
      dmem[i] = 32'h0000_0000;
    end

    // Exception handler at boot base.
    imem[32'h200 >> 2] = enc_addi(5'd2, 5'd0, 1);
    imem[32'h204 >> 2] = enc_sw(5'd2, 5'd0, StatusAddr);
    imem[32'h208 >> 2] = enc_jal(5'd0, 0);

    // NMI vector jumps to a separate handler body.
    imem[32'h27c >> 2] = enc_jal(5'd0, 32'h300 - 32'h27c);

    // Boot program at boot_addr + 0x80.
    imem[32'h280 >> 2] = enc_lw(5'd1, 5'd0, LoadAddr);
