#!/bin/bash
set -uo pipefail

cd /home/ibex || exit 1
source /home/ibex/.git/.ibex_env.sh >/dev/null 2>&1 || true

TEST_NAME="minstret_ecall_trap"
WORK_DIR="/home/ibex/.tb_${TEST_NAME}"
TEST_DIR="/home/ibex/examples/sw/simple_system/${TEST_NAME}"
SIM_BUILD_DIR="/home/ibex/build/lowrisc_ibex_ibex_simple_system_0"
SIM_BIN="${SIM_BUILD_DIR}/sim-verilator/Vibex_simple_system"
SW_BUILD_LOG="${WORK_DIR}/build_sw.log"
SIM_BUILD_LOG="${WORK_DIR}/build_sim.log"
SIM_LOG="${WORK_DIR}/sim.log"
PROGRAM_LOG="/home/ibex/ibex_simple_system.log"

finish_test() {
  local status="$1"
  local code="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${code}"
}

rm -rf "${WORK_DIR}" "${TEST_DIR}" "${SIM_BUILD_DIR}"
mkdir -p "${WORK_DIR}" "${TEST_DIR}"

cat > "${TEST_DIR}/${TEST_NAME}.c" <<'EOF'
#include "simple_system_common.h"

#include <stdint.h>

volatile uint32_t g_before;
volatile uint32_t g_trap_entry;
volatile uint32_t g_mcause;
volatile uint32_t g_mepc;

void trap_handler(void) __attribute__((naked, aligned(256)));

void trap_handler(void) {
  asm volatile(
      "csrr t0, minstret\n"
      "la   t1, g_trap_entry\n"
      "sw   t0, 0(t1)\n"
      "csrr t0, mcause\n"
      "la   t1, g_mcause\n"
      "sw   t0, 0(t1)\n"
      "csrr t0, mepc\n"
      "la   t1, g_mepc\n"
      "sw   t0, 0(t1)\n"
      "addi t0, t0, 4\n"
      "csrw mepc, t0\n"
      "mret\n");
}

static inline void set_mtvec(void *handler) {
  asm volatile("csrw mtvec, %0" : : "r"(handler) : "memory");
}

int main(void) {
  uint32_t before;
  uint32_t delta;

  puts("ECALL minstret retire test\n");

  pcount_enable(0);
  pcount_reset();
  g_before = 0;
  g_trap_entry = 0;
  g_mcause = 0;
  g_mepc = 0;

  set_mtvec((void *)trap_handler);
  pcount_enable(1);

  asm volatile(
      "csrr %0, minstret\n"
      "ecall\n"
      : "=r"(before)
      :
      : "memory");

  g_before = before;
  delta = g_trap_entry - g_before;

  puts("BEFORE: 0x");
  puthex(g_before);
  putchar('\n');

  puts("TRAP_ENTRY: 0x");
  puthex(g_trap_entry);
  putchar('\n');

  puts("DELTA: 0x");
  puthex(delta);
  putchar('\n');

  puts("MCAUSE: 0x");
  puthex(g_mcause);
  putchar('\n');

  puts("MEPC: 0x");
  puthex(g_mepc);
  putchar('\n');

  if (g_mcause == 11u && delta == 1u) {
    puts("RESULT PASS\n");
    return 0;
  }

  puts("RESULT FAIL\n");
  return 1;
}
EOF

cat > "${TEST_DIR}/Makefile" <<'EOF'
PROGRAM = minstret_ecall_trap
PROGRAM_DIR := $(shell dirname $(realpath $(lastword $(MAKEFILE_LIST))))
PROGRAM_CFLAGS += -O0
include ${PROGRAM_DIR}/../common/common.mk
EOF

rm -f "${PROGRAM_LOG}" "${SIM_LOG}" "${SW_BUILD_LOG}" "${SIM_BUILD_LOG}"

make -C "${TEST_DIR}" clean >"${SW_BUILD_LOG}" 2>&1 || true
make -C "${TEST_DIR}" >>"${SW_BUILD_LOG}" 2>&1
sw_rc=$?
