  --RV32E=0 --RV32M=ibex_pkg::RV32MFast >"${SIM_BUILD_LOG}" 2>&1
build_rc=$?
if [ "${build_rc}" -ne 0 ]; then
  cat "${SIM_BUILD_LOG}"
  finish_test "FAIL" 1
fi

"${SIM_BIN}" --meminit=ram,"${TEST_DIR}/${TEST_NAME}.elf" | tee "${SIM_LOG}"
sim_rc=${PIPESTATUS[0]}

if [ -f "${PROGRAM_LOG}" ]; then
  cat "${PROGRAM_LOG}" | tee -a "${SIM_LOG}"
fi

if [ "${sim_rc}" -eq 0 ] && grep -q "RESULT PASS" "${SIM_LOG}"; then
  finish_test "PASS" 0
fi

finish_test "FAIL" 1

#!/bin/bash
set +e

cd /home/ibex || exit 1

TEST_NAME="fetch_fifo_unaligned_error_pc"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_DIR="${TB_DIR}/build"

mkdir -p "${TB_DIR}" "${BUILD_DIR}"

echo "HWE_BENCH_RESULTS_START"

cat > "${TB_DIR}/tb.cc" <<'EOF'
#include "Vibex_fetch_fifo.h"
#include "verilated.h"

#include <cstdint>
#include <iostream>

namespace {

void eval_low(Vibex_fetch_fifo &top) {
  top.clk_i = 0;
  top.eval();
}

void tick(Vibex_fetch_fifo &top) {
  top.clk_i = 0;
  top.eval();
  top.clk_i = 1;
  top.eval();
}

bool expect_eq(uint32_t actual, uint32_t expected, const char *message) {
  if (actual == expected) {
    return true;
  }

  std::cerr << "TB_FAIL: " << message
            << " expected=0x" << std::hex << expected
            << " actual=0x" << actual << std::dec << std::endl;
  return false;
}

}  // namespace

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  Vibex_fetch_fifo top;

  top.rst_ni = 0;
  top.clear_i = 0;
  top.in_valid_i = 0;
  top.in_addr_i = 0;
  top.in_rdata_i = 0;
  top.in_err_i = 0;
  top.out_ready_i = 1;

  eval_low(top);
  tick(top);
  tick(top);

  top.rst_ni = 1;
  eval_low(top);

  top.clear_i = 1;
  top.in_addr_i = 2;
  tick(top);

  top.clear_i = 0;
  top.in_valid_i = 1;
  top.in_rdata_i = 0x00030000u;
  top.in_err_i = 1;
  eval_low(top);

  std::cout << "OBSERVE out_valid=" << static_cast<int>(top.out_valid_o)
            << " out_addr=0x" << std::hex << top.out_addr_o
            << " out_addr_next=0x" << top.out_addr_next_o
            << " out_err=0x" << static_cast<int>(top.out_err_o)
            << std::dec << std::endl;

  if (!expect_eq(top.out_addr_o, 2u,
                 "unaligned scenario must keep the instruction address at 0x2")) {
    return 1;
  }

  if (!expect_eq(top.out_valid_o, 0u,
                 "errored unaligned 32-bit instruction must wait for its second half")) {
    return 1;
  }

  if (!expect_eq(top.out_addr_next_o, 6u,
                 "errored unaligned 32-bit instruction must increment the PC by 4")) {
    return 1;
  }

  std::cout << "TB_PASS" << std::endl;
  return 0;
}
EOF

verilator --cc --sv -Wno-fatal \
  -Ivendor/lowrisc_ip/prim/rtl \
  --top-module ibex_fetch_fifo \
  rtl/ibex_fetch_fifo.sv \
  --exe "${TB_DIR}/tb.cc" \
  --build \
  -Mdir "${BUILD_DIR}"
rc=$?

if [ $rc -eq 0 ]; then
  "${BUILD_DIR}/Vibex_fetch_fifo"
  rc=$?
fi

if [ $rc -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi

echo "HWE_BENCH_RESULTS_END"

exit $rc

resolved_issues.body:
from a low-power point-of-view, having the main clock running before fetch_enable_i is set high to kick-start it, is not a great idea ;)

I've traced it up to ibex_controller.sv, where in RESET state, the ctrl_busy is still on default 1'b1. Could we maybe make it 1'b0 in reset state?

To make it work, I also add to activate the internal clock when fetch_enable_i is high, otherwise if fetch_enable_i is only 1 cycle long, you miss it.

