  logic [14:0] irq_fast_i;
  logic        irq_nm_i;
  logic        debug_req_i;
  logic        fetch_enable_i;
  logic        core_sleep_o;

  integer cycle_count;
  integer pre_enable_gated_edges;
  integer post_enable_gated_edges;
  logic   fetch_sent_q;
  logic   instr_req_seen_q;

  initial begin
    test_done_o              = 1'b0;
    test_passed_o            = 1'b0;
    test_en_i                = 1'b0;
    hart_id_i                = 32'h0;
    boot_addr_i              = 32'h0;
    instr_gnt_i              = 1'b1;
    instr_rvalid_i           = 1'b0;
    instr_rdata_i            = 32'h00000013;
    instr_err_i              = 1'b0;
    data_gnt_i               = 1'b1;
    data_rvalid_i            = 1'b0;
    data_rdata_i             = 32'h0;
    data_err_i               = 1'b0;
    irq_software_i           = 1'b0;
    irq_timer_i              = 1'b0;
    irq_external_i           = 1'b0;
    irq_fast_i               = 15'h0;
    irq_nm_i                 = 1'b0;
    debug_req_i              = 1'b0;
    fetch_enable_i           = 1'b0;
    cycle_count              = 0;
    pre_enable_gated_edges   = 0;
    post_enable_gated_edges  = 0;
    fetch_sent_q             = 1'b0;
    instr_req_seen_q         = 1'b0;
  end

  ibex_core #(
    .PMPEnable                (1'b0),
    .PMPGranularity           (0),
    .PMPNumRegions            (4),
    .MHPMCounterNum           (0),
    .MHPMCounterWidth         (40),
    .RV32E                    (1'b0),
    .RV32M                    (1'b1),
    .RV32B                    (1'b0),
    .BranchTargetALU          (1'b0),
    .WritebackStage           (1'b0),
    .MultiplierImplementation ("fast"),
    .ICache                   (1'b0),
    .ICacheECC                (1'b0),
    .DbgTriggerEn             (1'b0),
    .SecureIbex               (1'b0),
    .DmHaltAddr               (32'h1A110800),
    .DmExceptionAddr          (32'h1A110808)
  ) dut (
    .clk_i          (clk_i),
    .rst_ni         (rst_ni),
    .test_en_i      (test_en_i),
    .hart_id_i      (hart_id_i),
    .boot_addr_i    (boot_addr_i),
    .instr_req_o    (instr_req_o),
    .instr_gnt_i    (instr_gnt_i),
    .instr_rvalid_i (instr_rvalid_i),
    .instr_addr_o   (instr_addr_o),
    .instr_rdata_i  (instr_rdata_i),
    .instr_err_i    (instr_err_i),
    .data_req_o     (data_req_o),
    .data_gnt_i     (data_gnt_i),
    .data_rvalid_i  (data_rvalid_i),
    .data_we_o      (data_we_o),
    .data_be_o      (data_be_o),
    .data_addr_o    (data_addr_o),
    .data_wdata_o   (data_wdata_o),
    .data_rdata_i   (data_rdata_i),
    .data_err_i     (data_err_i),
    .irq_software_i (irq_software_i),
    .irq_timer_i    (irq_timer_i),
    .irq_external_i (irq_external_i),
    .irq_fast_i     (irq_fast_i),
    .irq_nm_i       (irq_nm_i),
    .debug_req_i    (debug_req_i),
    .fetch_enable_i (fetch_enable_i),
    .core_sleep_o   (core_sleep_o)
  );

  always @(posedge dut.clk) begin
    if (rst_ni) begin
      if (fetch_sent_q) begin
        post_enable_gated_edges <= post_enable_gated_edges + 1;
      end else begin
        pre_enable_gated_edges <= pre_enable_gated_edges + 1;
      end
      $display("GATED_EDGE cycle=%0d fetch_sent=%0b instr_req=%0b", cycle_count, fetch_sent_q,
               instr_req_o);
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      cycle_count             <= 0;
      fetch_enable_i          <= 1'b0;
      fetch_sent_q            <= 1'b0;
      instr_req_seen_q        <= 1'b0;
      test_done_o             <= 1'b0;
      test_passed_o           <= 1'b0;
    end else begin
      cycle_count <= cycle_count + 1;

      if (cycle_count == 4) begin
        fetch_enable_i <= 1'b1;
        fetch_sent_q   <= 1'b1;
        $display("FETCH_ENABLE pulse at cycle=%0d", cycle_count);
      end else begin
        fetch_enable_i <= 1'b0;
      end

      if (fetch_sent_q && instr_req_o) begin
        instr_req_seen_q <= 1'b1;
      end

      if (cycle_count == 12) begin
        test_done_o   <= 1'b1;
        test_passed_o <= (pre_enable_gated_edges == 0) &&
                         (post_enable_gated_edges > 0) &&
                         instr_req_seen_q;
        $display("SUMMARY pre_enable_gated_edges=%0d post_enable_gated_edges=%0d instr_req_seen=%0b core_sleep=%0b",
                 pre_enable_gated_edges, post_enable_gated_edges, instr_req_seen_q, core_sleep_o);
        if ((pre_enable_gated_edges == 0) &&
            (post_enable_gated_edges > 0) &&
            instr_req_seen_q) begin
          $display("TB_RESULT PASS");
        end else begin
          $display("TB_RESULT FAIL");
        end
        $finish;
      end
    end
  end
endmodule
EOF

