#!/bin/bash
cd /home/ibex
set -uo pipefail

TEST_NAME="icache_ready_valid_without_ready"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
SIM_LOG="${TB_DIR}/sim.log"
RESULTS_STARTED=0
RESULTS_ENDED=0

emit_results_start() {
  if [ "${RESULTS_STARTED}" -eq 0 ]; then
    echo "HWE_BENCH_RESULTS_START"
    RESULTS_STARTED=1
  fi
}

emit_results_end() {
  if [ "${RESULTS_STARTED}" -eq 1 ] && [ "${RESULTS_ENDED}" -eq 0 ]; then
    echo "HWE_BENCH_RESULTS_END"
    RESULTS_ENDED=1
  fi
}

finish_test() {
  local result="$1"
  local rc="$2"

  emit_results_start
  echo "TEST: ${TEST_NAME} ... ${result}"
  emit_results_end
  exit "${rc}"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/sim_main.cpp" <<'EOF'
#include "Vibex_icache.h"
#include "verilated.h"

vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

static uint32_t mem_word(uint32_t word_addr) {
  switch (word_addr) {
    case 0x00000000u:
      return 0x00031111u;
    case 0x00000004u:
      return 0xabcd5678u;
    default:
      return 0x00000013u;
  }
}

struct MemPipe {
  bool q1_valid = false;
  bool q2_valid = false;
  uint32_t q1_addr = 0;
  uint32_t q2_addr = 0;
};

static void tick(Vibex_icache *top, MemPipe &mem, int cycle) {
  top->clk_i = 0;
  top->instr_rvalid_i = mem.q2_valid;
  top->instr_rdata_i = mem.q2_valid ? mem_word(mem.q2_addr) : 0;
  top->instr_err_i = 0;
  top->instr_pmp_err_i = 0;
  top->instr_gnt_i = 0;
  top->eval();

  bool req = top->instr_req_o;
  uint32_t req_addr = top->instr_addr_o;
  top->instr_gnt_i = req;
  top->eval();

  req = top->instr_req_o;
  req_addr = top->instr_addr_o;

  top->clk_i = 1;
  top->eval();
  ++main_time;

  if (req || top->instr_rvalid_i || top->valid_o) {
    std::printf("TRACE cycle=%d instr_req=%d instr_addr=%08x instr_rvalid=%d valid=%d ready=%d addr_o=%08x rdata_o=%08x err_o=%d\n",
                cycle,
                req ? 1 : 0,
                req_addr,
                top->instr_rvalid_i ? 1 : 0,
                top->valid_o ? 1 : 0,
                top->ready_i ? 1 : 0,
                top->addr_o,
                top->rdata_o,
                top->err_o ? 1 : 0);
  }

  mem.q2_valid = mem.q1_valid;
  mem.q2_addr = mem.q1_addr;
  mem.q1_valid = req;
  mem.q1_addr = req_addr;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  Vibex_icache *top = new Vibex_icache;
  MemPipe mem;

  top->rst_ni = 0;
  top->req_i = 0;
  top->branch_i = 0;
  top->addr_i = 0;
  top->ready_i = 0;
  top->icache_enable_i = 0;
  top->icache_inval_i = 0;

  for (int cycle = 0; cycle < 4; ++cycle) {
    tick(top, mem, cycle);
  }

  top->rst_ni = 1;

  for (int cycle = 4; cycle < 274; ++cycle) {
    tick(top, mem, cycle);
  }

  top->req_i = 1;
  top->branch_i = 1;
  top->addr_i = 0x00000002u;
  tick(top, mem, 274);
  top->branch_i = 0;

  for (int cycle = 275; cycle < 295; ++cycle) {
    tick(top, mem, cycle);

    if (top->valid_o && !top->ready_i) {
      if ((top->addr_o == 0x00000002u) &&
          (top->rdata_o == 0x11110003u) &&
          !top->err_o) {
        std::printf("TB_PASS observed valid_o while ready_i=0\n");
        top->final();
        delete top;
        return 0;
      }

      std::printf("TB_FAIL unexpected response addr=%08x rdata=%08x err=%d\n",
                  top->addr_o, top->rdata_o, top->err_o ? 1 : 0);
      top->final();
      delete top;
      return 1;
    }
  }

  std::printf("TB_FAIL timeout waiting for valid_o with ready_i=0\n");
  top->final();
  delete top;
  return 1;
}
EOF

verilator --cc --exe --build -Wno-fatal -DSYNTHESIS -UVERILATOR \
  --top-module ibex_icache \
  -Mdir "${TB_DIR}/obj_dir" \
  -I/home/ibex/shared/rtl \
  "${TB_DIR}/sim_main.cpp" \
  /home/ibex/rtl/ibex_icache.sv \
  /home/ibex/shared/rtl/prim_generic_ram_1p.sv \
  /home/ibex/shared/rtl/prim_secded_28_22_dec.sv \
  /home/ibex/shared/rtl/prim_secded_28_22_enc.sv \
  /home/ibex/shared/rtl/prim_secded_72_64_dec.sv \
  /home/ibex/shared/rtl/prim_secded_72_64_enc.sv \
  > "${COMPILE_LOG}" 2>&1
compile_rc=$?

cat "${COMPILE_LOG}"
if [ "${compile_rc}" -ne 0 ]; then
  finish_test "FAIL" "${compile_rc}"
fi

"${TB_DIR}/obj_dir/Vibex_icache" 2>&1 | tee "${SIM_LOG}"
sim_rc=${PIPESTATUS[0]}

if [ "${sim_rc}" -eq 0 ] && grep -q "TB_PASS observed valid_o while ready_i=0" "${SIM_LOG}"; then
  finish_test "PASS" 0
fi

finish_test "FAIL" 1

resolved_issues.body:
I'm currently evaluating PULPissimo platform with Ibex core and I encountered some strange behaviour with interrupts. It seems that after hitting breakpoint `mie` in `mstatus` register is reset to 0.

Here is my setup:

- PULPissimo with Ibex core and [pulp-platform/riscv-dbg](https://github.com/pulp-platform/riscv-dbg) as debug core,
- ZedBoard (Xilinx Zynq, `master` version of all cores) and Terasic DE10-Nano (Altera Cyclone-V, with modifications to make the code compatible with Quartus),
- Digilent HS2 JTAG programmer,
- OpenOCD compiled basing on [instructions from PULPissimo](https://github.com/pulp-platform/pulpissimo/#gdb-and-openocd),
- [pulp-platform/pulp-riscv-gnu-toolchain](https://github.com/pulp-platform/pulp-riscv-gnu-toolchain).

OpenOCD config and log as well as gdb log (including issued commands) can be found [here](https://gist.github.com/MarekPikula/63bd5a35dcffa2361a1a7bc3de5642f9).

Code:
```c
#include <stdint.h>

int main() {
  register int mstatus_mie = (1<<3); // mstatus.mie
  asm volatile ("csrw 0x300, %0" :: "r" (mstatus_mie) );

  uint32_t mstatus[3];
  asm volatile ("csrr %0, 0x300" : "=r" (mstatus[0]));
  asm volatile ("nop");  // First breakpoint

  asm volatile ("csrr %0, 0x300" : "=r" (mstatus[1]));
  asm volatile ("nop");  // Second breakpoint

  asm volatile ("csrw 0x300, %0" :: "r" (mstatus_mie) );
  asm volatile ("csrr %0, 0x300" : "=r" (mstatus[2]));
  asm volatile ("nop");  // Third breakpoint

  return 0;
}
```

What the code does is set `mie` flag in `mstatus` register (0x300) and store it in `mstatus[0]`, then after hitting breakpoint read it to `mstatus[1]` and to confirm, `mstatus` register is written again and result stored in `mstatus[2]`.

Basically after sending `x/3x mstatus` gdb returns: `0x00001808	0x00001800	0x00001808`, so in `mstatus[0]` and `mstatus[2]` `mie` flag is set, whereas in `mstatus[1]` it is not set, although, to my understanding, it should be recovered after going out of debug mode.

Is it expected behaviour? If not what can I do to further test it?

