#include "Vtb_debug_priv.h"
#include "verilated.h"

double sc_time_stamp() {
  return 0;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  Vtb_debug_priv top;
  vluint64_t tick = 0;

  top.clk_i = 0;
  top.rst_ni = 0;

  while (!Verilated::gotFinish()) {
    if (tick == 4) {
      top.rst_ni = 1;
    }

    top.clk_i = 0;
    top.eval();
    tick++;

    top.clk_i = 1;
    top.eval();
    tick++;

    if (top.test_done_o) {
      top.final();
      return top.test_pass_o ? 0 : 1;
    }

    if (tick > 5000) {
      VL_PRINTF("SIM_RESULT FAIL host_timeout tick=%llu\n",
