#!/bin/bash
cd /home/ibex || exit 1

set +e
set -o pipefail

TEST_NAME="lsu_second_req_before_first_rvalid"
TB_ROOT="/home/ibex/.tb_${TEST_NAME}"
CPP_MAIN="${TB_ROOT}/sim_main.cpp"
BUILD_LOG="${TB_ROOT}/build.log"
SIM_LOG="${TB_ROOT}/sim.log"

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

cat > "${CPP_MAIN}" <<'EOF'
#include <cstdlib>
#include <iostream>

#include "Vibex_load_store_unit.h"
#include "verilated.h"

namespace {

constexpr vluint32_t kFirstAddr = 0x00000001u;
constexpr vluint32_t kSecondAddr = 0x00000004u;

void eval_low(Vibex_load_store_unit *top) {
  top->clk_i = 0;
  top->eval();
}

void tick(Vibex_load_store_unit *top) {
  top->clk_i = 1;
  top->eval();
  top->clk_i = 0;
  top->eval();
}

void fail(Vibex_load_store_unit *top, const char *message) {
  std::cerr << message << std::endl;
  top->final();
  delete top;
  std::exit(1);
}

}  // namespace

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);
  auto *top = new Vibex_load_store_unit;

  top->rst_ni = 0;
  top->data_gnt_i = 0;
  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  top->data_pmp_err_i = 0;
  top->data_rdata_i = 0;
  top->data_we_ex_i = 0;
  top->data_type_ex_i = 0;
  top->data_wdata_ex_i = 0;
  top->data_sign_ext_ex_i = 0;
  top->data_req_ex_i = 0;
  top->adder_result_ex_i = kFirstAddr;

  eval_low(top);
  tick(top);
  tick(top);

  top->rst_ni = 1;
  eval_low(top);

  top->data_req_ex_i = 1;
  top->data_gnt_i = 1;
  top->adder_result_ex_i = kFirstAddr;
  eval_low(top);
  tick(top);

  top->data_req_ex_i = 0;
  top->data_gnt_i = 0;
  top->adder_result_ex_i = kSecondAddr;
  eval_low(top);

  bool saw_second_req = false;
  for (int cycle = 0; cycle < 3; ++cycle) {
    if (top->data_req_o) {
      saw_second_req = true;
      std::cout << "Observed second request before first response on cycle "
                << cycle << std::endl;
      top->data_gnt_i = 1;
      eval_low(top);
      tick(top);
      top->data_gnt_i = 0;
      eval_low(top);
      break;
    }

    tick(top);
    eval_low(top);
  }

  if (!saw_second_req) {
    fail(top, "Did not observe the second request before the first response");
  }

  top->data_rdata_i = 0xDEADBEEFu;
  top->data_rvalid_i = 1;
  top->data_err_i = 1;
  eval_low(top);

  if (!top->data_valid_o || !top->load_err_o || top->store_err_o) {
    fail(top, "First response did not raise the expected load error");
  }

  tick(top);

  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  eval_low(top);

  if (!top->busy_o) {
    fail(top, "LSU did not remain busy while waiting for the abandoned second response");
  }

  top->data_rdata_i = 0xCAFEBABEu;
  top->data_rvalid_i = 1;
  eval_low(top);
  tick(top);

  top->data_rvalid_i = 0;
  eval_low(top);

  if (top->busy_o) {
    fail(top, "LSU did not return to IDLE after the second response");
  }

  std::cout << "Scenario completed successfully" << std::endl;
  top->final();
  delete top;
  return 0;
}
EOF

timeout 1200 verilator --cc --top-module ibex_load_store_unit \
  --Mdir "${TB_ROOT}/obj_dir" \
  rtl/ibex_load_store_unit.sv \
  --exe "${CPP_MAIN}" --build 2>&1 | tee "${BUILD_LOG}"
build_rc=${PIPESTATUS[0]}

echo "HWE_BENCH_RESULTS_START"

if [ "${build_rc}" -ne 0 ]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

timeout 1200 "${TB_ROOT}/obj_dir/Vibex_load_store_unit" 2>&1 | tee "${SIM_LOG}"
sim_rc=${PIPESTATUS[0]}

if [ "${sim_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

body:
This PR makes sure the signal `instr_multicycle_done_q` is only evaluated when the decoder currently has a multicycle instruction (load/store, mult/div, branch, jump). If this signal is evaluated
for single-cycle instructions, it can prevent the reg file write enable from being de-asserted in the case of stalls due to the IF stage.

@udinator: Could you please verify that this actually fixes the bug you reported in #216 before we merge it?

