#include <cstdio>

static bool check_instr(Vtb& top, uint32_t instr, bool expected_illegal, const char* name) {
  top.instr_i = instr;
  top.eval();

  bool got_illegal = top.illegal_o != 0;
  if (got_illegal != expected_illegal) {
    std::printf("CHECK_FAIL name=%s expected_illegal=%d got=%d instr=%08x\n",
                name, expected_illegal ? 1 : 0, got_illegal ? 1 : 0, instr);
    return false;
  }

  std::printf("CHECK_PASS name=%s illegal=%d instr=%08x\n",
              name, got_illegal ? 1 : 0, instr);
  return true;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Vtb top;
  bool ok = true;

  ok &= check_instr(top, 0x00012083u, false, "lw");
  ok &= check_instr(top, 0x00016083u, true, "lwu");

  if (!ok) {
    top.final();
    return 1;
  }

  std::puts("DECODER_PASS");
  top.final();
  return 0;
}
EOF

