set -uo pipefail

cd /home/ibex

TEST_NAME="ibex_debug_req_pulse"
WORKDIR="/home/ibex/.verify-${TEST_NAME}"
TB_SV="${WORKDIR}/debug_req_pulse_tb.sv"
CPP_MAIN="${WORKDIR}/sim_main.cpp"
SIM_LOG="${WORKDIR}/sim.log"

report_result() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

rm -rf "${WORKDIR}"
mkdir -p "${WORKDIR}"

cat > "${TB_SV}" <<'EOF'
module debug_req_pulse_tb (
  input  logic        clk,
  input  logic        rst_n,
  input  logic        debug_req,
  output logic [31:0] pc_id_o,
  output logic [31:0] depc_o,
  output logic [31:0] instr_addr_o,
  output logic        debug_mode_o,
  output logic [3:0]  state_o
);
  localparam logic [31:0] BOOT_ADDR = 32'h0001_0000;
  localparam logic [31:0] HALT_ADDR = 32'h0001_0200;

  logic [31:0] instr_rdata;
  logic [31:0] data_rdata = 32'h0;
  logic        instr_req;
  logic        data_req;
  logic        data_we;
  logic [3:0]  data_be;
  logic [31:0] data_addr;
  logic [31:0] data_wdata;
  logic        irq_ack;
  logic [4:0]  irq_id;

  assign pc_id_o      = dut.pc_id;
  assign depc_o       = dut.csr_depc;
  assign debug_mode_o = dut.id_stage_i.controller_i.debug_mode_q;
  assign state_o      = dut.id_stage_i.controller_i.ctrl_fsm_cs;

  function automatic logic [31:0] instr_word(input logic [31:0] addr);
    begin
      unique case (addr)
        HALT_ADDR:         instr_word = 32'h0000_0013;
        HALT_ADDR + 32'd4: instr_word = 32'h0000_0013;
        default:           instr_word = 32'h0000_0013;
      endcase
    end
  endfunction

  always_comb begin
    instr_rdata = instr_word(instr_addr_o);
  end

  ibex_core #(
    .DmHaltAddr(HALT_ADDR),
    .DmExceptionAddr(HALT_ADDR + 32'd8)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .test_en_i(1'b0),
    .core_id_i(4'b0),
    .cluster_id_i(6'b0),
    .boot_addr_i(BOOT_ADDR),
    .instr_req_o(instr_req),
    .instr_gnt_i(1'b1),
    .instr_rvalid_i(1'b1),
    .instr_addr_o(instr_addr_o),
    .instr_rdata_i(instr_rdata),
    .data_req_o(data_req),
    .data_gnt_i(1'b1),
    .data_rvalid_i(1'b1),
    .data_we_o(data_we),
    .data_be_o(data_be),
    .data_addr_o(data_addr),
    .data_wdata_o(data_wdata),
    .data_rdata_i(data_rdata),
    .data_err_i(1'b0),
    .irq_i(1'b0),
    .irq_id_i(5'b0),
    .irq_ack_o(irq_ack),
    .irq_id_o(irq_id),
    .debug_req_i(debug_req),
    .fetch_enable_i(1'b1)
  );

endmodule
EOF

cat > "${CPP_MAIN}" <<'EOF'
#include "Vdebug_req_pulse_tb.h"
#include "verilated.h"

#include <cstdint>
#include <cstdio>

double sc_time_stamp() {
  return 0.0;
}

static void step(Vdebug_req_pulse_tb* top) {
  top->clk = 0;
  top->eval();
  top->clk = 1;
  top->eval();
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Vdebug_req_pulse_tb* top = new Vdebug_req_pulse_tb;

  top->clk = 0;
  top->rst_n = 0;
  top->debug_req = 0;
  top->eval();

  for (int i = 0; i < 8; ++i) {
    step(top);
  }

  top->rst_n = 1;

  int wait_cycles = 0;
  while (wait_cycles < 200 && !(top->state_o == 5 && top->pc_id_o == 0x00010084U)) {
    step(top);
    ++wait_cycles;
  }

  if (!(top->state_o == 5 && top->pc_id_o == 0x00010084U)) {
    std::printf("TB_STATUS timeout\n");
    top->final();
    delete top;
    return 2;
  }

  const uint32_t sampled_pc = top->pc_id_o;
  top->debug_req = 1;
  step(top);
  top->debug_req = 0;

  for (int i = 0; i < 4; ++i) {
    step(top);
  }

  std::printf("TB_TRACE sampled_pc=%08x debug_mode=%u depc=%08x state=%u pc_id=%08x instr_addr=%08x\n",
              sampled_pc,
              static_cast<unsigned>(top->debug_mode_o),
              static_cast<uint32_t>(top->depc_o),
              static_cast<unsigned>(top->state_o),
              static_cast<uint32_t>(top->pc_id_o),
              static_cast<uint32_t>(top->instr_addr_o));

  if (top->debug_mode_o && top->depc_o == 0U) {
    std::printf("TB_STATUS inconsistent_debug_entry\n");
    top->final();
    delete top;
    return 1;
  }

  if (!top->debug_mode_o && top->depc_o == 0U) {
    std::printf("TB_STATUS pulse_ignored_cleanly\n");
    top->final();
    delete top;
    return 0;
  }

  if (top->debug_mode_o && top->depc_o == sampled_pc) {
    std::printf("TB_STATUS debug_captured_pc\n");
    top->final();
    delete top;
    return 0;
  }

  std::printf("TB_STATUS unexpected_state\n");
  top->final();
  delete top;
  return 3;
}
EOF

