tb_script:
#!/bin/bash
cd /home/ibex
set -uo pipefail

TEST_NAME="rvfi_retire_alignment"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"

report_and_exit() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "$rc"
}

rm -rf "$TB_DIR" obj_dir
mkdir -p "$TB_DIR"

cat > "$TB_DIR/rvfi_repro_tb.sv" <<'EOF'
module rvfi_repro_tb (
  input  logic        clk,
  input  logic        rst_n,
  input  logic        test_en,
  input  logic [3:0]  core_id,
  input  logic [5:0]  cluster_id,
  input  logic [31:0] boot_addr,
  output logic        instr_req,
  input  logic        instr_gnt,
  input  logic        instr_rvalid,
  output logic [31:0] instr_addr,
  input  logic [31:0] instr_rdata,
  output logic        data_req,
  input  logic        data_gnt,
  input  logic        data_rvalid,
  output logic        data_we,
  output logic [3:0]  data_be,
  output logic [31:0] data_addr,
  output logic [31:0] data_wdata,
  input  logic [31:0] data_rdata,
  input  logic        data_err,
  input  logic        irq,
  input  logic [4:0]  irq_id,
  output logic        irq_ack,
  output logic [4:0]  irq_id_o,
  input  logic        debug_req,
  output logic        rvfi_valid,
  output logic [63:0] rvfi_order,
  output logic [31:0] rvfi_insn,
  output logic        rvfi_trap,
  output logic        rvfi_halt,
  output logic        rvfi_intr,
  output logic [1:0]  rvfi_mode,
  output logic [4:0]  rvfi_rs1_addr,
  output logic [4:0]  rvfi_rs2_addr,
  output logic [31:0] rvfi_rs1_rdata,
  output logic [31:0] rvfi_rs2_rdata,
  output logic [4:0]  rvfi_rd_addr,
  output logic [31:0] rvfi_rd_wdata,
  output logic [31:0] rvfi_pc_rdata,
  output logic [31:0] rvfi_pc_wdata,
  output logic [31:0] rvfi_mem_addr,
  output logic [3:0]  rvfi_mem_rmask,
  output logic [3:0]  rvfi_mem_wmask,
  output logic [31:0] rvfi_mem_rdata,
  output logic [31:0] rvfi_mem_wdata,
  input  logic        fetch_enable
);

  ibex_core_tracer dut (
    .clk_i          (clk),
    .rst_ni         (rst_n),
    .test_en_i      (test_en),
    .core_id_i      (core_id),
