cat > "$TB_DIR/rvfi_repro_main.cpp" <<'EOF'
#include "Vrvfi_repro_tb.h"
#include "verilated.h"

#include <array>
#include <cstdint>
#include <cstdio>

static vluint64_t main_time = 0;

double sc_time_stamp() {
  return static_cast<double>(main_time);
}

struct InstrBeat {
  uint32_t instr_rdata;
  int instr_gnt;
  int instr_rvalid;
};

struct ExpectedRetire {
  uint64_t order;
  uint32_t pc_rdata;
  uint32_t pc_wdata;
  uint32_t insn;
};

static constexpr std::array<InstrBeat, 12> kStimulus = {{
    {0x81868106U, 1, 0},
    {0x81868106U, 0, 1},
    {0x81868106U, 0, 0},
    {0x00400113U, 1, 0},
    {0x00400113U, 0, 1},
    {0x00400113U, 0, 0},
    {0xff810113U, 1, 0},
    {0xff810113U, 0, 1},
    {0xff810113U, 0, 0},
    {0x4000006fU, 1, 0},
    {0x4000006fU, 0, 1},
    {0x4000006fU, 0, 0},
}};

static constexpr std::array<ExpectedRetire, 4> kExpected = {{
    {0ULL, 0x00000080U, 0x00000082U, 0x00008106U},
    {1ULL, 0x00000082U, 0x00000084U, 0x00008186U},
    {2ULL, 0x00000084U, 0x00000088U, 0x00400113U},
    {3ULL, 0x00000088U, 0x0000008cU, 0xff810113U},
}};

static void tick(Vrvfi_repro_tb& top) {
  top.clk = 0;
  top.eval();
  ++main_time;

  top.clk = 1;
  top.eval();
  ++main_time;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Vrvfi_repro_tb top;
  top.clk = 0;
  top.rst_n = 0;
  top.test_en = 0;
  top.core_id = 0;
  top.cluster_id = 0;
  top.boot_addr = 0;
  top.instr_gnt = 0;
  top.instr_rvalid = 0;
  top.instr_rdata = 0x00000013U;
  top.data_gnt = 1;
  top.data_rvalid = 1;
  top.data_rdata = 0;
  top.data_err = 0;
  top.irq = 0;
  top.irq_id = 0;
  top.debug_req = 0;
  top.fetch_enable = 1;

  size_t matched = 0;

  for (int cycle = 0; cycle < 80 && !Verilated::gotFinish(); ++cycle) {
    if (cycle >= 16 && cycle - 16 < static_cast<int>(kStimulus.size())) {
      const auto& beat = kStimulus[cycle - 16];
      top.instr_rdata = beat.instr_rdata;
      top.instr_gnt = beat.instr_gnt;
      top.instr_rvalid = beat.instr_rvalid;
    } else {
      top.instr_gnt = 0;
      top.instr_rvalid = 0;
    }

    top.rst_n = cycle >= 12;
    tick(top);

    if (!top.rvfi_valid) {
      continue;
    }

    if (matched >= kExpected.size()) {
      std::printf("SIM_FAIL extra_retire order=%llu pc=%08x insn=%08x\n",
                  static_cast<unsigned long long>(top.rvfi_order),
                  top.rvfi_pc_rdata,
                  top.rvfi_insn);
      top.final();
      return 1;
    }

    const auto& expected = kExpected[matched];
    std::printf("RVFI retire[%zu] order=%llu pc=%08x->%08x insn=%08x\n",
                matched,
                static_cast<unsigned long long>(top.rvfi_order),
                top.rvfi_pc_rdata,
                top.rvfi_pc_wdata,
                top.rvfi_insn);

    if (top.rvfi_order != expected.order ||
        top.rvfi_pc_rdata != expected.pc_rdata ||
        top.rvfi_pc_wdata != expected.pc_wdata ||
        top.rvfi_insn != expected.insn) {
      std::printf(
          "SIM_FAIL mismatch idx=%zu got(order=%llu pc_r=%08x pc_w=%08x insn=%08x) expected(order=%llu pc_r=%08x pc_w=%08x insn=%08x)\n",
          matched,
          static_cast<unsigned long long>(top.rvfi_order),
          top.rvfi_pc_rdata,
          top.rvfi_pc_wdata,
          top.rvfi_insn,
          static_cast<unsigned long long>(expected.order),
          expected.pc_rdata,
          expected.pc_wdata,
          expected.insn);
      top.final();
      return 1;
    }

    ++matched;
    if (matched == kExpected.size()) {
      std::printf("SIM_PASS matched=%zu\n", matched);
      top.final();
      return 0;
    }
  }

  std::printf("SIM_FAIL matched=%zu expected=%zu\n", matched, kExpected.size());
  top.final();
  return 1;
}
EOF

verilator -sv --cc --exe --build -DRISCV_FORMAL -Wno-fatal -Wno-PINMISSING \
  --top-module rvfi_repro_tb \
  rtl/ibex_defines.sv \
  rtl/ibex_tracer_defines.sv \
  rtl/ibex_alu.sv \
  rtl/ibex_compressed_decoder.sv \
  rtl/ibex_controller.sv \
  rtl/ibex_cs_registers.sv \
  rtl/ibex_decoder.sv \
  rtl/ibex_ex_block.sv \
  rtl/ibex_fetch_fifo.sv \
  rtl/ibex_id_stage.sv \
  rtl/ibex_if_stage.sv \
  rtl/ibex_int_controller.sv \
  rtl/ibex_load_store_unit.sv \
  rtl/ibex_multdiv_fast.sv \
  rtl/ibex_multdiv_slow.sv \
  rtl/ibex_prefetch_buffer.sv \
  examples/sim/rtl/prim_clock_gating.sv \
  rtl/ibex_register_file_ff.sv \
  rtl/ibex_core.sv \
  rtl/ibex_core_tracer.sv \
  "$TB_DIR/rvfi_repro_tb.sv" \
  "$TB_DIR/rvfi_repro_main.cpp" \
  -o rvfi_repro_sim
build_rc=$?

if [ "$build_rc" -ne 0 ]; then
  report_and_exit "FAIL" "$build_rc"
fi

./obj_dir/rvfi_repro_sim
run_rc=$?

if [ "$run_rc" -eq 0 ]; then
  report_and_exit "PASS" 0
fi

report_and_exit "FAIL" "$run_rc"

