#!/bin/bash
cd /home/ibex || exit 1

set +e

TEST_NAME="compressed_hint_decoder"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
BUILD_DIR="/home/ibex/.tb_build_${TEST_NAME}"

rm -rf "$TB_DIR" "$BUILD_DIR"
mkdir -p "$TB_DIR" "$BUILD_DIR"

cat > "$TB_DIR/decoder_hint_tb.cpp" <<'EOF'
#include "Vibex_compressed_decoder.h"
#include "verilated.h"

#include <cstdint>
#include <cstdio>

namespace {

int run_case(uint32_t instr,
             uint32_t expected_instr,
             bool expected_compressed,
             bool expected_illegal) {
  Vibex_compressed_decoder dut;
  dut.instr_i = instr;
  dut.eval();

  std::printf("input=0x%08x\n", instr);
  std::printf("decoded=0x%08x\n", dut.instr_o);
  std::printf("is_compressed=%d\n", dut.is_compressed_o ? 1 : 0);
  std::printf("illegal=%d\n", dut.illegal_instr_o ? 1 : 0);

  if (dut.instr_o != expected_instr ||
      static_cast<bool>(dut.is_compressed_o) != expected_compressed ||
      static_cast<bool>(dut.illegal_instr_o) != expected_illegal) {
    std::printf("mismatch: expected decoded=0x%08x is_compressed=%d illegal=%d\n",
                expected_instr, expected_compressed ? 1 : 0,
                expected_illegal ? 1 : 0);
    return 1;
  }

  std::printf("match\n");
  return 0;
}

}  // namespace

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  // 0x9056 is a compressed HINT that should decode to add x0, x0, s5.
  return run_case(0x00009056u, 0x01500033u, true, false);
}
EOF

verilator -sv --cc --exe --build \
  --top-module ibex_compressed_decoder \
  -Wno-fatal \
  -Mdir "$BUILD_DIR" \
  rtl/ibex_defines.sv \
  rtl/ibex_compressed_decoder.sv \
  "$TB_DIR/decoder_hint_tb.cpp" \
  -o decoder_hint_tb
build_rc=$?

echo "HWE_BENCH_RESULTS_START"

if [ $build_rc -ne 0 ]; then
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit $build_rc
fi

"$BUILD_DIR/decoder_hint_tb"
run_rc=$?

if [ $run_rc -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi

echo "HWE_BENCH_RESULTS_END"

exit $run_rc

