#!/bin/bash
cd /home/ibex || exit 1

set +e

TEST_NAME="lsu_error_propagation"
TB_DIR="/home/ibex/.tb_${TEST_NAME}"
LOG_FILE="${TB_DIR}/sim.log"

finish_test() {
  local status="$1"
  local rc="$2"

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

rm -rf "${TB_DIR}" obj_dir
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/lsu_error_harness.cpp" <<'EOF'
#include "Vibex_load_store_unit.h"
#include "verilated.h"

#include <cstdint>
#include <cstdio>

static vluint64_t main_time = 0;

double sc_time_stamp() { return static_cast<double>(main_time); }

static void eval_step(Vibex_load_store_unit *top) {
  top->eval();
  ++main_time;
}

static void clock_tick(Vibex_load_store_unit *top) {
  top->clk_i = 0;
  eval_step(top);
  top->clk_i = 1;
  eval_step(top);
}

static void clear_bus(Vibex_load_store_unit *top) {
  top->data_req_ex_i = 0;
  top->data_we_ex_i = 0;
  top->data_type_ex_i = 0;
  top->data_wdata_ex_i = 0;
  top->data_reg_offset_ex_i = 0;
  top->data_sign_ext_ex_i = 0;
  top->adder_result_ex_i = 0;

  top->data_gnt_i = 0;
  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  top->data_rdata_i = 0;
}

static bool issue_error_transaction(Vibex_load_store_unit *top, bool is_store) {
  top->data_type_ex_i = 0;
  top->data_wdata_ex_i = 0xA5A55A5A;
  top->data_reg_offset_ex_i = 0;
  top->data_sign_ext_ex_i = 0;
  top->adder_result_ex_i = 0x20;
  top->data_we_ex_i = is_store ? 1 : 0;
  top->data_req_ex_i = 1;
  top->data_gnt_i = 1;
  eval_step(top);
  clock_tick(top);

  top->data_req_ex_i = 0;
  top->data_gnt_i = 0;
  top->data_rvalid_i = 1;
  top->data_err_i = 1;
  top->data_rdata_i = 0xDEADBEEF;
  eval_step(top);

  bool ok = is_store ? (top->store_err_o == 1 && top->load_err_o == 0)
                     : (top->load_err_o == 1 && top->store_err_o == 0);

  std::printf("CHECK_%s load_err_o=%d store_err_o=%d data_valid_o=%d\n",
              is_store ? "STORE" : "LOAD",
              top->load_err_o,
              top->store_err_o,
              top->data_valid_o);

  clock_tick(top);
  top->data_rvalid_i = 0;
  top->data_err_i = 0;
  eval_step(top);
  clock_tick(top);

  clear_bus(top);
  eval_step(top);
  return ok;
}

int main(int argc, char **argv) {
  Verilated::commandArgs(argc, argv);

  auto *top = new Vibex_load_store_unit;
  clear_bus(top);
  top->clk_i = 0;
  top->rst_ni = 0;
  eval_step(top);
  clock_tick(top);
  clock_tick(top);

  top->rst_ni = 1;
  eval_step(top);
  clock_tick(top);

  bool load_ok = issue_error_transaction(top, false);
  bool store_ok = issue_error_transaction(top, true);

  if (!load_ok || !store_ok) {
    std::printf("RESULT load_ok=%d store_ok=%d\n", load_ok ? 1 : 0, store_ok ? 1 : 0);
    delete top;
    return 1;
  }

  std::printf("RESULT load_ok=1 store_ok=1\n");
  delete top;
  return 0;
}
EOF

verilator -sv --cc rtl/ibex_load_store_unit.sv \
  --exe "${TB_DIR}/lsu_error_harness.cpp" \
  --build --top-module ibex_load_store_unit > "${LOG_FILE}" 2>&1
build_rc=$?

if [ "${build_rc}" -ne 0 ]; then
  cat "${LOG_FILE}"
  finish_test "FAIL" "${build_rc}"
fi

./obj_dir/Vibex_load_store_unit >> "${LOG_FILE}" 2>&1
run_rc=$?
cat "${LOG_FILE}"

if [ "${run_rc}" -eq 0 ]; then
  finish_test "PASS" 0
fi

finish_test "FAIL" "${run_rc}"

#!/bin/bash
set -uo pipefail

cd /home/cva6 || exit 1

TEST_NAME="csr_mie_embedded_mask"
TB_DIR="/home/cva6/.tb_${TEST_NAME}"
