run_verilator_test() {
  local test_name="$1"
  local config_file="$2"
  local top_module="$3"
  local tb_file="$4"
  local mdir="$TB_DIR/$5"
  local build_log="$mdir/build.log"
  local run_log="$mdir/run.log"
  local rc=0

  rm -rf "$mdir"
  mkdir -p "$mdir"

  if "$VERILATOR" --binary --sv --timing --top-module "$top_module" \
      --Mdir "$mdir" -Wno-fatal -Icore/include \
      core/include/config_pkg.sv \
      "$config_file" \
      core/include/riscv_pkg.sv \
      core/include/ariane_pkg.sv \
      core/include/build_config_pkg.sv \
      core/cva6_accel_first_pass_decoder_stub.sv \
      core/decoder.sv \
      "$tb_file" >"$build_log" 2>&1; then
    if "$mdir/V$top_module" >"$run_log" 2>&1; then
      cat "$run_log"
      echo "TEST: $test_name ... PASS"
    else
      rc=$?
      cat "$build_log"
      cat "$run_log"
      echo "TEST: $test_name ... FAIL"
    fi
  else
    rc=$?
    cat "$build_log"
    echo "TEST: $test_name ... FAIL"
  fi

  if [ "$rc" -ne 0 ]; then
    overall_rc=1
  fi
}

echo "HWE_BENCH_RESULTS_START"
run_verilator_test "decoder_zexth_rv64" \
  "core/include/cv64a6_imafdc_sv39_config_pkg.sv" \
  "tb_rv64" \
  "$TB_DIR/tb_rv64.sv" \
  "obj_rv64"
run_verilator_test "decoder_zexth_rv32" \
  "core/include/cv32a60x_config_pkg.sv" \
  "tb_rv32" \
  "$TB_DIR/tb_rv32.sv" \
  "obj_rv32"
echo "HWE_BENCH_RESULTS_END"

exit "$overall_rc"

