    .dirty_v_state_i(1'b0),
    .pc_i('0),
    .csr_exception_o(csr_exception_o),
    .epc_o(),
    .eret_o(),
    .trap_vector_base_o(),
    .priv_lvl_o(priv_lvl_o),
    .v_o(v_o),
    .acc_fflags_ex_i('0),
    .acc_fflags_ex_valid_i(1'b0),
    .fs_o(),
    .vfs_o(),
    .fflags_o(),
    .frm_o(),
    .fprec_o(),
    .vs_o(),
    .irq_ctrl_o(),
    .en_translation_o(),
    .en_g_translation_o(),
    .en_ld_st_translation_o(),
    .en_ld_st_g_translation_o(),
    .ld_st_priv_lvl_o(),
    .ld_st_v_o(),
    .csr_hs_ld_st_inst_i(1'b0),
    .sum_o(),
