cat > "$TB_CPP" <<'EOF'
#include <cstdint>
#include <cstdio>
#include "Vtb.h"
#include "verilated.h"

static void tick(Vtb* top) {
  top->clk_i = 0;
  top->eval();
  top->clk_i = 1;
  top->eval();
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  auto* top = new Vtb;

  top->clk_i = 0;
  top->rst_ni = 0;
  top->phase_i = 0;
  top->eval();
  tick(top);
  tick(top);

  top->rst_ni = 1;
  top->phase_i = 1;
  tick(top);

  top->phase_i = 2;
  tick(top);

  top->phase_i = 3;
  top->clk_i = 0;
  top->eval();

  bool ok = top->exception_valid_o && (top->exception_cause_o == 22);
  if (!ok) {
    std::fprintf(stderr, "valid=%d cause=%llu priv=%u v=%d\n",
                 top->exception_valid_o,
                 static_cast<unsigned long long>(top->exception_cause_o),
                 static_cast<unsigned>(top->priv_lvl_o_dbg),
                 top->v_o_dbg);
  }

  delete top;
  return ok ? 0 : 1;
}
EOF

