#!/bin/bash
set -euo pipefail

cd /home/cva6

if [[ -n "${BASH_ENV:-}" && -f "${BASH_ENV}" ]]; then
  source "${BASH_ENV}"
fi

if [[ -z "${VERILATOR_INSTALL_DIR:-}" && -x /tools/verilator/bin/verilator ]]; then
  export VERILATOR_INSTALL_DIR="/tools/verilator"
fi

export PATH="${VERILATOR_INSTALL_DIR:+$VERILATOR_INSTALL_DIR/bin:}$PATH"
unset VERILATOR_BIN

TEST_NAME="instr_queue_addr_fifo_depth"
TB_DIR="/home/cva6/.tb_instr_queue_addr_fifo_depth"
RUN_LOG="$TB_DIR/run.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

if [[ -n "${VERILATOR_INSTALL_DIR:-}" ]]; then
  VERILATOR_SHIM_ROOT="$TB_DIR/verilator_root"
  mkdir -p "$VERILATOR_SHIM_ROOT/bin"
  ln -sfn "$VERILATOR_INSTALL_DIR/include" "$VERILATOR_SHIM_ROOT/include"
  ln -sfn "$VERILATOR_INSTALL_DIR/bin/verilator_bin" "$VERILATOR_SHIM_ROOT/bin/verilator_bin"
  if [[ -x "$VERILATOR_INSTALL_DIR/share/verilator/bin/verilator_includer" ]]; then
    ln -sfn "$VERILATOR_INSTALL_DIR/share/verilator/bin/verilator_includer" \
      "$VERILATOR_SHIM_ROOT/bin/verilator_includer"
  fi
  export VERILATOR_ROOT="$VERILATOR_SHIM_ROOT"
fi

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import config_pkg::*;
  import ariane_pkg::*;

  localparam config_pkg::cva6_cfg_t CFG = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  localparam type branchpredict_sbe_t = struct packed {
    ariane_pkg::cf_t cf;
    logic [CFG.VLEN-1:0] predict_address;
  };

  localparam type exception_t = struct packed {
    logic [CFG.XLEN-1:0] cause;
    logic [CFG.XLEN-1:0] tval;
    logic [CFG.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  };

  localparam type fetch_entry_t = struct packed {
    logic [CFG.VLEN-1:0] address;
    logic [31:0] instruction;
    branchpredict_sbe_t branch_predict;
    exception_t ex;
  };

  logic clk_i;
  logic rst_ni;
  logic flush_i;
  logic [CFG.INSTR_PER_FETCH-1:0][31:0] instr_i;
  logic [CFG.INSTR_PER_FETCH-1:0][CFG.VLEN-1:0] addr_i;
  logic [CFG.INSTR_PER_FETCH-1:0] valid_i;
  logic ready_o;
  logic [CFG.INSTR_PER_FETCH-1:0] consumed_o;
  ariane_pkg::frontend_exception_t exception_i;
  logic [CFG.VLEN-1:0] exception_addr_i;
  logic [CFG.GPLEN-1:0] exception_gpaddr_i;
  logic [31:0] exception_tinst_i;
  logic exception_gva_i;
  logic [CFG.VLEN-1:0] predict_address_i;
  ariane_pkg::cf_t [CFG.INSTR_PER_FETCH-1:0] cf_type_i;
  logic replay_o;
  logic [CFG.VLEN-1:0] replay_addr_o;
  fetch_entry_t [CFG.NrIssuePorts-1:0] fetch_entry_o;
  logic [CFG.NrIssuePorts-1:0] fetch_entry_valid_o;
  logic [CFG.NrIssuePorts-1:0] fetch_entry_ready_i;

  instr_queue #(
      .CVA6Cfg(CFG),
      .fetch_entry_t(fetch_entry_t)
  ) dut (
      .clk_i,
      .rst_ni,
      .flush_i,
      .instr_i,
      .addr_i,
      .valid_i,
      .ready_o,
      .consumed_o,
      .exception_i,
      .exception_addr_i,
      .exception_gpaddr_i,
      .exception_tinst_i,
      .exception_gva_i,
      .predict_address_i,
      .cf_type_i,
      .replay_o,
      .replay_addr_o,
      .fetch_entry_o,
      .fetch_entry_valid_o,
      .fetch_entry_ready_i
  );

  always #1 clk_i = ~clk_i;

  task automatic drive_branch_packet(input logic [CFG.VLEN-1:0] base_addr,
                                     input logic [CFG.VLEN-1:0] target_addr);
    begin
      instr_i = '0;
      addr_i = '0;
      valid_i = '0;
      cf_type_i = '{default: ariane_pkg::NoCF};
      instr_i[0] = 32'h0000_0063;
      addr_i[0] = base_addr;
      addr_i[1] = base_addr + 32'd2;
      addr_i[2] = base_addr + 32'd4;
      addr_i[3] = base_addr + 32'd6;
      valid_i[0] = 1'b1;
      cf_type_i[0] = ariane_pkg::Branch;
      predict_address_i = target_addr;
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    flush_i = 1'b0;
    instr_i = '0;
    addr_i = '0;
    valid_i = '0;
    exception_i = ariane_pkg::FE_NONE;
    exception_addr_i = '0;
    exception_gpaddr_i = '0;
    exception_tinst_i = '0;
    exception_gva_i = 1'b0;
    predict_address_i = '0;
    cf_type_i = '{default: ariane_pkg::NoCF};
    fetch_entry_ready_i = '0;

    repeat (2) @(negedge clk_i);
    rst_ni = 1'b1;

    drive_branch_packet(32'h1000, 32'h2000);
    @(negedge clk_i);
    if (ready_o !== 1'b1 || replay_o !== 1'b0) begin
      $fatal(1, "unexpected state after first predicted branch packet");
    end

    drive_branch_packet(32'h1002, 32'h2002);
    @(negedge clk_i);
    if (ready_o !== 1'b0) begin
      $fatal(1, "expected address queue backpressure after two outstanding predicted branches");
    end

    drive_branch_packet(32'h1004, 32'h2004);
    @(negedge clk_i);
    if (ready_o !== 1'b0 || replay_o !== 1'b1 || replay_addr_o !== 32'h00001004) begin
      $fatal(1, "expected replay on the third predicted branch packet");
    end

    $display("TB PASS");
    $finish;
  end
endmodule
EOF

