rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb_cva6_rvfi.sv" <<'EOF'
`timescale 1ns/1ps
`include "rvfi_types.svh"

module tb_cva6_rvfi;
  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);

  typedef `RVFI_INSTR_T(CVA6Cfg) rvfi_instr_t;
  typedef `RVFI_CSR_ELMT_T(CVA6Cfg) rvfi_csr_elmt_t;
  typedef `RVFI_CSR_T(CVA6Cfg, rvfi_csr_elmt_t) rvfi_csr_t;
  typedef `RVFI_PROBES_INSTR_T(CVA6Cfg) rvfi_probes_instr_t;
  typedef `RVFI_PROBES_CSR_T(CVA6Cfg) rvfi_probes_csr_t;
  typedef struct packed {
    rvfi_probes_csr_t csr;
    rvfi_probes_instr_t instr;
  } rvfi_probes_t;

  logic clk_i;
  logic rst_ni;
  rvfi_probes_t rvfi_probes_i;
  rvfi_instr_t [CVA6Cfg.NrCommitPorts-1:0] rvfi_instr_o;
  rvfi_csr_t rvfi_csr_o;

  cva6_rvfi #(
      .CVA6Cfg(CVA6Cfg),
      .rvfi_instr_t(rvfi_instr_t),
      .rvfi_csr_t(rvfi_csr_t),
      .rvfi_probes_instr_t(rvfi_probes_instr_t),
      .rvfi_probes_csr_t(rvfi_probes_csr_t),
      .rvfi_probes_t(rvfi_probes_t)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .rvfi_probes_i(rvfi_probes_i),
      .rvfi_instr_o(rvfi_instr_o),
      .rvfi_csr_o(rvfi_csr_o)
  );

  always #5 clk_i = ~clk_i;

  task automatic check_bit(input string label, input logic actual, input logic expected);
    if (actual !== expected) begin
      $error("%s mismatch: expected=%0b actual=%0b", label, expected, actual);
      $fatal(1);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    rvfi_probes_i = '0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    rvfi_probes_i.instr.commit_instr_valid = '1;
    rvfi_probes_i.instr.commit_drop = '0;
    rvfi_probes_i.instr.commit_ack = '0;
    rvfi_probes_i.instr.ex_commit_valid = 1'b1;
    rvfi_probes_i.instr.ex_commit_cause = riscv::ENV_CALL_MMODE;
    rvfi_probes_i.instr.priv_lvl = riscv::PRIV_LVL_M;

    @(posedge clk_i);
    #1;

    check_bit("port0.valid", rvfi_instr_o[0].valid, 1'b1);
    check_bit("port0.trap", rvfi_instr_o[0].trap, 1'b1);
    check_bit("port1.valid", rvfi_instr_o[1].valid, 1'b0);
    check_bit("port1.trap", rvfi_instr_o[1].trap, 1'b0);

    $display("rvfi ecall commit-port behavior is correct");
    $finish(0);
  end
endmodule
EOF

