cat > "$TB_DIR/tb_csr_regfile_mcountinhibit.cpp" <<'EOF'
#include "Vtb_csr_regfile_mcountinhibit.h"
#include "verilated.h"

#include <cstdlib>
#include <iostream>
#include <string>

namespace {

void eval_once(Vtb_csr_regfile_mcountinhibit* top) {
  top->eval();
  if (Verilated::gotFinish()) {
    std::cerr << "Simulation finished unexpectedly" << std::endl;
    std::exit(1);
  }
}

void tick(Vtb_csr_regfile_mcountinhibit* top) {
  top->clk_i = 0;
  eval_once(top);
  top->clk_i = 1;
  eval_once(top);
}

bool expect(bool condition, const std::string& message) {
  if (!condition) {
    std::cerr << message << std::endl;
    return false;
  }
  return true;
}

}  // namespace

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Vtb_csr_regfile_mcountinhibit top;
  top.clk_i = 0;
  top.rst_ni = 0;
  top.do_read_i = 0;
  top.do_write_i = 0;
  top.write_data_i = 0;
  eval_once(&top);

  tick(&top);
  tick(&top);

  top.rst_ni = 1;
  eval_once(&top);
  tick(&top);

  top.do_read_i = 1;
  top.do_write_i = 0;
  top.write_data_i = 0;
  eval_once(&top);

  if (!expect(top.exception_valid_o == 0, "read of mcountinhibit raised an exception")) {
    return 1;
  }
  if (!expect(top.read_data_o == 0, "read of mcountinhibit did not return zero")) {
    return 1;
  }

  top.do_read_i = 0;
  top.do_write_i = 1;
  top.write_data_i = 0xFFFFFFFFu;
  eval_once(&top);

  if (!expect(top.exception_valid_o == 0, "write to mcountinhibit raised an exception")) {
    return 1;
  }

  tick(&top);

  top.do_read_i = 1;
  top.do_write_i = 0;
  top.write_data_i = 0;
  eval_once(&top);

  if (!expect(top.exception_valid_o == 0, "read-after-write of mcountinhibit raised an exception")) {
    return 1;
  }
  if (!expect(top.read_data_o == 0, "mcountinhibit is not read-only zero after write")) {
    return 1;
  }

  return 0;
}
EOF

