+    parameter type                   exception_t   = logic
+) (
+    input logic clk_i,
+    input logic rst_ni,
+    input logic enable_translation_i,
+    input logic enable_g_translation_i,
+    input logic en_ld_st_translation_i,  // enable virtual memory translation for load/stores
+    input logic en_ld_st_g_translation_i,  // enable G-Stage translation for load/stores
+    // IF interface
+    input icache_arsp_t icache_areq_i,
+    output icache_areq_t icache_areq_o,
+    // LSU interface
+    // this is a more minimalistic interface because the actual addressing logic is handled
+    // in the LSU as we distinguish load and stores, what we do here is simple address translation
+    input exception_t misaligned_ex_i,
+    input logic lsu_req_i,  // request address translation
+    input logic [CVA6Cfg.VLEN-1:0] lsu_vaddr_i,  // virtual address in
+    input logic [31:0] lsu_tinst_i,  // transformed instruction in
+    input logic lsu_is_store_i,  // the translation is requested by a store
+    // Cycle 1
+    output logic lsu_valid_o,  // translation is valid
+    output logic [CVA6Cfg.PLEN-1:0] lsu_paddr_o,  // translated address
+    output exception_t lsu_exception_o,  // address translation threw an exception
+    // General control signals
+    input riscv::priv_lvl_t priv_lvl_i,
+    input logic v_i,
+    input riscv::priv_lvl_t ld_st_priv_lvl_i,
+    input logic ld_st_v_i,
+    // PMP
+    input riscv::pmpcfg_t [CVA6Cfg.NrPMPEntries:0] pmpcfg_i,
+    input logic [CVA6Cfg.NrPMPEntries:0][CVA6Cfg.PLEN-3:0] pmpaddr_i,
+    output logic data_allow_o,
+    output logic instr_allow_o,
+    output logic match_any_execute_region_o,
+    output exception_t misaligned_ex_o
+);
+
+  exception_t misaligned_ex_n, misaligned_ex_q;
+  logic lsu_req_n, lsu_req_q;
+  logic lsu_is_store_n, lsu_is_store_q;
+
+  // Wires to PMP checks
+  riscv::pmp_access_t pmp_access_type;
+
+  logic [CVA6Cfg.PLEN-1:0] mmu_vaddr_plen, fetch_vaddr_plen;
+  logic [CVA6Cfg.VLEN-1:0] lsu_vaddr_q;
+  logic [31:0] lsu_tinst_q;
+
+  logic no_locked_data, no_locked_if;
+
+  always_comb begin : vaddr_plen
+    if (CVA6Cfg.VLEN >= CVA6Cfg.PLEN) begin
+      mmu_vaddr_plen   = lsu_vaddr_q[CVA6Cfg.PLEN-1:0];
+      fetch_vaddr_plen = icache_areq_i.fetch_vaddr[CVA6Cfg.PLEN-1:0];
+    end else begin
+      mmu_vaddr_plen   = CVA6Cfg.PLEN'(lsu_vaddr_q);
+      fetch_vaddr_plen = CVA6Cfg.PLEN'(icache_areq_i.fetch_vaddr);
+    end
+  end
+
+  assign misaligned_ex_o = misaligned_ex_q;
+
+  //-----------------------
+  // Instruction Interface
+  //-----------------------
+
+  // check for execute flag on memory
+  assign match_any_execute_region_o = config_pkg::is_inside_execute_regions(
+      CVA6Cfg, {{64 - CVA6Cfg.PLEN{1'b0}}, icache_areq_o.fetch_paddr}
+  );
+
+  // The instruction interface is a simple request response interface
+  always_comb begin : instr_interface
+    icache_areq_o.fetch_valid     = icache_areq_i.fetch_req;
+    icache_areq_o.fetch_paddr     = fetch_vaddr_plen;
+    icache_areq_o.fetch_exception = '0;
+
+    // if it didn't match any execute region throw an `Instruction Access Fault`
+    // or: if we are not translating, check PMPs immediately on the paddr
+    if (!match_any_execute_region_o || !instr_allow_o) begin
+      icache_areq_o.fetch_exception.cause = riscv::INSTR_ACCESS_FAULT;
+      icache_areq_o.fetch_exception.valid = 1'b1;
+
+      if (CVA6Cfg.TvalEn) begin
+        if (enable_translation_i || enable_g_translation_i) begin
+          icache_areq_o.fetch_exception.tval = CVA6Cfg.XLEN'(icache_areq_i.fetch_vaddr);
+        end else begin
+          icache_areq_o.fetch_exception.tval=CVA6Cfg.XLEN'(icache_areq_o.fetch_paddr[CVA6Cfg.PLEN-1:(CVA6Cfg.PLEN > CVA6Cfg.VLEN) ? (CVA6Cfg.PLEN - CVA6Cfg.VLEN) : 0]);
+        end
+      end
+      if (CVA6Cfg.RVH) begin
+        icache_areq_o.fetch_exception.tval2 = '0;
+        icache_areq_o.fetch_exception.tinst = '0;
+        icache_areq_o.fetch_exception.gva   = v_i;
+      end
+    end
+  end
+
+  // Instruction fetch
+  pmp #(
+      .CVA6Cfg   (CVA6Cfg),
+      .PLEN      (CVA6Cfg.PLEN),
+      .PMP_LEN   (CVA6Cfg.PLEN - 2),
+      .NR_ENTRIES(CVA6Cfg.NrPMPEntries)
+  ) i_pmp_if (
+      .addr_i       (icache_areq_o.fetch_paddr),
+      .priv_lvl_i   (priv_lvl_i),
+      // we will always execute on the instruction fetch port
+      .access_type_i(riscv::ACCESS_EXEC),
+      // Configuration
+      .conf_addr_i  (pmpaddr_i),
+      .conf_i       (pmpcfg_i),
+      .allow_o      (instr_allow_o)
+  );
+
+  //-----------------------
+  // Data Interface
+  //-----------------------
+  // The data interface is simpler and only consists of a request/response interface
+  always_comb begin : data_interface
+    // save request and DTLB response
+    lsu_req_n             = lsu_req_i;
+    misaligned_ex_n       = misaligned_ex_i;
+    lsu_is_store_n        = lsu_is_store_i;
+
+    lsu_paddr_o           = mmu_vaddr_plen;
+    lsu_valid_o           = lsu_req_q;
+    lsu_exception_o       = misaligned_ex_q;
+    pmp_access_type       = lsu_is_store_q ? riscv::ACCESS_WRITE : riscv::ACCESS_READ;
+
+    // mute misaligned exceptions if there is no request otherwise they will throw accidental exceptions
+    misaligned_ex_n.valid = misaligned_ex_i.valid & lsu_req_i;
+
+    // If translation is not enabled, check the paddr immediately against PMPs
+    if (lsu_req_q && !misaligned_ex_q.valid && !data_allow_o) begin
+      lsu_exception_o.valid = 1'b1;
+
+      if (CVA6Cfg.TvalEn) begin
+        if (en_ld_st_translation_i || en_ld_st_g_translation_i) begin
+          lsu_exception_o.tval = {
+            {CVA6Cfg.XLEN - CVA6Cfg.VLEN{lsu_vaddr_q[CVA6Cfg.VLEN-1]}}, lsu_vaddr_q
+          };
+        end else begin
+          lsu_exception_o.tval = CVA6Cfg.XLEN'(lsu_paddr_o[CVA6Cfg.PLEN-1:(CVA6Cfg.PLEN>CVA6Cfg.VLEN)?(CVA6Cfg.PLEN-CVA6Cfg.VLEN) : 0]);
+
+        end
+      end
+
+      if (CVA6Cfg.RVH) begin
+        lsu_exception_o.tval2 = '0;
+        lsu_exception_o.tinst = lsu_tinst_q;
+        lsu_exception_o.gva   = ld_st_v_i;
+      end
+
+      if (lsu_is_store_q) begin
+        lsu_exception_o.cause = riscv::ST_ACCESS_FAULT;
+      end else begin
+        lsu_exception_o.cause = riscv::LD_ACCESS_FAULT;
+      end
+    end
+  end
+
+  // Load/store PMP check
+  pmp #(
+      .CVA6Cfg   (CVA6Cfg),
+      .PLEN      (CVA6Cfg.PLEN),
+      .PMP_LEN   (CVA6Cfg.PLEN - 2),
+      .NR_ENTRIES(CVA6Cfg.NrPMPEntries)
+  ) i_pmp_data (
+      .addr_i       (lsu_paddr_o),
+      .priv_lvl_i   (ld_st_priv_lvl_i),
+      .access_type_i(pmp_access_type),
+      // Configuration
+      .conf_addr_i  (pmpaddr_i),
+      .conf_i       (pmpcfg_i),
+      .allow_o      (data_allow_o)
+  );
+
+  // ----------
+  // Registers
+  // ----------
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (~rst_ni) begin
+      lsu_req_q       <= '0;
+      misaligned_ex_q <= '0;
+      lsu_is_store_q  <= '0;
+      lsu_vaddr_q     <= '0;
+      lsu_tinst_q     <= '0;
+    end else begin
+      lsu_req_q       <= lsu_req_n;
+      misaligned_ex_q <= misaligned_ex_n;
+      lsu_is_store_q  <= lsu_is_store_n;
+      lsu_vaddr_q     <= lsu_vaddr_i;
+
+      if (CVA6Cfg.RVH) begin
+        lsu_tinst_q <= lsu_tinst_i;
+      end
+    end
+  end
+
+
+  // ----------------
+  // Assert for PMPs
+  // ----------------
+
+  // synthesis translate_off
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (~rst_ni) begin
+      no_locked_data <= 1'b0;
+    end else begin
+      if (ld_st_priv_lvl_i == riscv::PRIV_LVL_M) begin
+        no_locked_data <= 1'b1;
+        for (int i = 0; i < CVA6Cfg.NrPMPEntries; i++) begin
+          if (pmpcfg_i[i].locked && pmpcfg_i[i].addr_mode != riscv::OFF) begin
+            no_locked_data <= no_locked_data & 1'b0;
+          end else no_locked_data <= no_locked_data & 1'b1;
+        end
+        if (no_locked_data == 1'b1) assert (data_allow_o == 1'b1);
+      end
+    end
+  end
+
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (~rst_ni) begin
+      no_locked_if <= 1'b0;
+    end else begin
+      if (priv_lvl_i == riscv::PRIV_LVL_M) begin
+        no_locked_if <= 1'b1;
+        for (int i = 0; i < CVA6Cfg.NrPMPEntries; i++) begin
+          if (pmpcfg_i[i].locked && pmpcfg_i[i].addr_mode != riscv::OFF) begin
+            no_locked_if <= no_locked_if & 1'b0;
+          end else no_locked_if <= no_locked_if & 1'b1;
+        end
+        if (no_locked_if == 1'b1) assert (instr_allow_o == 1'b1);
+      end
+    end
+  end
+  // synthesis translate_on
+endmodule

tb_script:
#!/bin/bash
set -uo pipefail

cd /home/cva6 || exit 1

source /etc/cva6_tools_path.sh
export VERILATOR_INSTALL_DIR=/tools/verilator-v5.008
export PATH=/tools/verilator-v5.008/bin:$PATH
export CVA6_REPO_DIR=/home/cva6
export HPDCACHE_DIR=/home/cva6/core/cache_subsystem/hpdcache
export TARGET_CFG=cv32a65x
export VERILATOR_ROOT="$VERILATOR_INSTALL_DIR/share/verilator"
VERILATOR_EXE="$VERILATOR_INSTALL_DIR/bin/verilator_bin"

TEST_NAME="pmp_locked_store_cv32a65x"
TB_DIR=/home/cva6/.tb_pmp_store_no_mmu
BUILD_LOG="$TB_DIR/build.log"
RUN_LOG="$TB_DIR/run.log"
OBJ_DIR="$TB_DIR/obj_dir"
RC=0

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

export C_INCLUDE_PATH="$VERILATOR_ROOT/include:$VERILATOR_ROOT/include/vltstd${C_INCLUDE_PATH:+:$C_INCLUDE_PATH}"
export CPLUS_INCLUDE_PATH="$VERILATOR_ROOT/include:$VERILATOR_ROOT/include/vltstd${CPLUS_INCLUDE_PATH:+:$CPLUS_INCLUDE_PATH}"

cat > "$TB_DIR/lsu_pmp_tb.sv" <<'EOF'
module lsu_pmp_tb (
    input  logic clk_i,
    input  logic rst_ni,
    output logic done_o,
    output logic pass_o,
    output logic [31:0] status_code_o
);
  import ariane_pkg::*;

  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);
  localparam logic [CVA6Cfg.XLEN-1:0] TARGET_ADDR = 32'h0000_1000;
  localparam logic [CVA6Cfg.XLEN-1:0] STORE_DATA = 32'h1234_5678;
  localparam logic [31:0] STATUS_PASS = 32'h0000_0000;
  localparam logic [31:0] STATUS_NO_EXCEPTION = 32'h0000_0001;
  localparam logic [31:0] STATUS_TIMEOUT = 32'h0000_0002;
  localparam logic [31:0] STATUS_WRONG_CAUSE = 32'h1000_0000;

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic                    fetch_valid;
    logic [CVA6Cfg.PLEN-1:0] fetch_paddr;
    exception_t              fetch_exception;
  } icache_areq_t;

  typedef struct packed {
    logic                    fetch_req;
    logic [CVA6Cfg.VLEN-1:0] fetch_vaddr;
  } icache_arsp_t;

  typedef struct packed {
    logic                             valid;
    logic [CVA6Cfg.VLEN-1:0]          vaddr;
    logic [31:0]                      tinst;
    logic                             hs_ld_st_inst;
    logic                             hlvx_inst;
    logic                             overflow;
    logic                             g_overflow;
    logic [CVA6Cfg.XLEN-1:0]          data;
    logic [(CVA6Cfg.XLEN/8)-1:0]      be;
    fu_t                              fu;
    fu_op                             operation;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
  } lsu_ctrl_t;

  typedef struct packed {
    fu_t                              fu;
    fu_op                             operation;
    logic [CVA6Cfg.XLEN-1:0]          operand_a;
    logic [CVA6Cfg.XLEN-1:0]          operand_b;
    logic [CVA6Cfg.XLEN-1:0]          imm;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0] trans_id;
  } fu_data_t;

  typedef struct packed {
    logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0] address_index;
    logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]   address_tag;
    logic [CVA6Cfg.XLEN-1:0]               data_wdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0]  data_wuser;
    logic                                  data_req;
    logic                                  data_we;
    logic [(CVA6Cfg.XLEN/8)-1:0]           data_be;
    logic [1:0]                            data_size;
    logic [CVA6Cfg.DcacheIdWidth-1:0]      data_id;
    logic                                  kill_req;
    logic                                  tag_valid;
  } dcache_req_i_t;

  typedef struct packed {
    logic                                 data_gnt;
    logic                                 data_rvalid;
    logic [CVA6Cfg.DcacheIdWidth-1:0]     data_rid;
    logic [CVA6Cfg.XLEN-1:0]              data_rdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0] data_ruser;
  } dcache_req_o_t;

  logic flush_i;
  logic stall_st_pending_i;
  logic no_st_pending_o;
  logic amo_valid_commit_i;
  logic [31:0] tinst_i;
  fu_data_t fu_data_i;
  logic lsu_ready_o;
  logic lsu_valid_i;
  logic [CVA6Cfg.TRANS_ID_BITS-1:0] load_trans_id_o;
  logic [CVA6Cfg.XLEN-1:0] load_result_o;
  logic load_valid_o;
  exception_t load_exception_o;
  logic [CVA6Cfg.TRANS_ID_BITS-1:0] store_trans_id_o;
  logic [CVA6Cfg.XLEN-1:0] store_result_o;
  logic store_valid_o;
  exception_t store_exception_o;
  logic commit_i;
  logic commit_ready_o;
  logic [CVA6Cfg.TRANS_ID_BITS-1:0] commit_tran_id_i;
  logic enable_translation_i;
  logic enable_g_translation_i;
  logic en_ld_st_translation_i;
  logic en_ld_st_g_translation_i;
  icache_arsp_t icache_areq_i;
  icache_areq_t icache_areq_o;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  riscv::priv_lvl_t ld_st_priv_lvl_i;
  logic ld_st_v_i;
  logic csr_hs_ld_st_inst_o;
  logic sum_i;
  logic vs_sum_i;
  logic mxr_i;
  logic vmxr_i;
  logic [CVA6Cfg.PPNW-1:0] satp_ppn_i;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_i;
  logic [CVA6Cfg.PPNW-1:0] vsatp_ppn_i;
  logic [CVA6Cfg.ASID_WIDTH-1:0] vs_asid_i;
  logic [CVA6Cfg.PPNW-1:0] hgatp_ppn_i;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_i;
  logic [CVA6Cfg.ASID_WIDTH-1:0] asid_to_be_flushed_i;
  logic [CVA6Cfg.VMID_WIDTH-1:0] vmid_to_be_flushed_i;
  logic [CVA6Cfg.VLEN-1:0] vaddr_to_be_flushed_i;
  logic [CVA6Cfg.GPLEN-1:0] gpaddr_to_be_flushed_i;
  logic flush_tlb_i;
  logic flush_tlb_vvma_i;
  logic flush_tlb_gvma_i;
  logic itlb_miss_o;
  logic dtlb_miss_o;
  dcache_req_o_t [2:0] dcache_req_ports_i;
  dcache_req_i_t [2:0] dcache_req_ports_o;
  logic dcache_wbuffer_empty_i;
  logic dcache_wbuffer_not_ni_i;
  amo_req_t amo_req_o;
  amo_resp_t amo_resp_i;
  riscv::pmpcfg_t [CVA6Cfg.NrPMPEntries-1:0] pmpcfg_i;
  logic [CVA6Cfg.NrPMPEntries-1:0][CVA6Cfg.PLEN-3:0] pmpaddr_i;
  lsu_ctrl_t rvfi_lsu_ctrl_o;
  logic [CVA6Cfg.PLEN-1:0] rvfi_mem_paddr_o;

  typedef enum logic [1:0] {
    TB_ISSUE,
    TB_WAIT,
    TB_DONE
  } tb_state_t;

  tb_state_t state_q;
  logic [7:0] wait_cycles_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      state_q <= TB_ISSUE;
      wait_cycles_q <= '0;
      done_o <= 1'b0;
      pass_o <= 1'b0;
      status_code_o <= STATUS_TIMEOUT;
    end else if (!done_o) begin
      case (state_q)
        TB_ISSUE: begin
          if (lsu_ready_o) begin
            state_q <= TB_WAIT;
          end
        end
        TB_WAIT: begin
          wait_cycles_q <= wait_cycles_q + 8'd1;
          if (store_valid_o) begin
            done_o <= 1'b1;
            state_q <= TB_DONE;
            if (store_exception_o.valid && (store_exception_o.cause == riscv::ST_ACCESS_FAULT)) begin
              pass_o <= 1'b1;
              status_code_o <= STATUS_PASS;
            end else if (!store_exception_o.valid) begin
              pass_o <= 1'b0;
              status_code_o <= STATUS_NO_EXCEPTION;
            end else begin
              pass_o <= 1'b0;
              status_code_o <= STATUS_WRONG_CAUSE | store_exception_o.cause;
            end
          end else if (wait_cycles_q == 8'd32) begin
            done_o <= 1'b1;
            pass_o <= 1'b0;
            status_code_o <= STATUS_TIMEOUT;
            state_q <= TB_DONE;
          end
        end
        TB_DONE: begin
        end
      endcase
    end
  end

  always_comb begin
    flush_i = 1'b0;
    stall_st_pending_i = 1'b0;
    amo_valid_commit_i = 1'b0;
    tinst_i = '0;
    fu_data_i = '0;
    lsu_valid_i = 1'b0;
    commit_i = 1'b0;
    commit_tran_id_i = '0;
    enable_translation_i = 1'b0;
    enable_g_translation_i = 1'b0;
    en_ld_st_translation_i = 1'b0;
    en_ld_st_g_translation_i = 1'b0;
    icache_areq_i = '0;
    priv_lvl_i = riscv::PRIV_LVL_M;
    v_i = 1'b0;
    ld_st_priv_lvl_i = riscv::PRIV_LVL_M;
    ld_st_v_i = 1'b0;
    sum_i = 1'b0;
    vs_sum_i = 1'b0;
    mxr_i = 1'b0;
    vmxr_i = 1'b0;
    satp_ppn_i = '0;
    asid_i = '0;
    vsatp_ppn_i = '0;
    vs_asid_i = '0;
    hgatp_ppn_i = '0;
    vmid_i = '0;
    asid_to_be_flushed_i = '0;
    vmid_to_be_flushed_i = '0;
    vaddr_to_be_flushed_i = '0;
    gpaddr_to_be_flushed_i = '0;
    flush_tlb_i = 1'b0;
    flush_tlb_vvma_i = 1'b0;
    flush_tlb_gvma_i = 1'b0;
    dcache_req_ports_i = '0;
    dcache_wbuffer_empty_i = 1'b1;
    dcache_wbuffer_not_ni_i = 1'b1;
    amo_resp_i = '0;
    pmpcfg_i = '0;
    pmpaddr_i = '0;

    pmpcfg_i[0].locked = 1'b1;
    pmpcfg_i[0].addr_mode = riscv::NA4;
    pmpcfg_i[0].access_type = '0;
    pmpaddr_i[0] = CVA6Cfg.PLEN'(TARGET_ADDR) >> 2;

    if (!done_o && (state_q == TB_ISSUE) && lsu_ready_o) begin
      lsu_valid_i = 1'b1;
      fu_data_i.fu = STORE;
      fu_data_i.operation = SW;
      fu_data_i.operand_a = TARGET_ADDR;
      fu_data_i.operand_b = STORE_DATA;
      fu_data_i.imm = '0;
      fu_data_i.trans_id = '0;
    end
  end

  load_store_unit #(
      .CVA6Cfg(CVA6Cfg),
      .dcache_req_i_t(dcache_req_i_t),
      .dcache_req_o_t(dcache_req_o_t),
      .exception_t(exception_t),
      .fu_data_t(fu_data_t),
      .icache_areq_t(icache_areq_t),
      .icache_arsp_t(icache_arsp_t),
      .lsu_ctrl_t(lsu_ctrl_t)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .flush_i(flush_i),
      .stall_st_pending_i(stall_st_pending_i),
      .no_st_pending_o(no_st_pending_o),
      .amo_valid_commit_i(amo_valid_commit_i),
      .tinst_i(tinst_i),
      .fu_data_i(fu_data_i),
      .lsu_ready_o(lsu_ready_o),
      .lsu_valid_i(lsu_valid_i),
      .load_trans_id_o(load_trans_id_o),
      .load_result_o(load_result_o),
      .load_valid_o(load_valid_o),
      .load_exception_o(load_exception_o),
