module tb_bht_wrapper (
    input logic clk_i,
    input logic rst_ni,
    input logic flush_bp_i,
    input logic debug_mode_i,
    input logic [31:0] vpc_i,
    input logic update_valid_i,
    input logic [31:0] update_pc_i,
    input logic update_taken_i,
    output logic lane0_valid_o,
    output logic lane0_taken_o,
    output logic lane1_valid_o,
    output logic lane1_taken_o
);

  function automatic config_pkg::cva6_cfg_t make_tb_cfg();
    config_pkg::cva6_cfg_t cfg;
    cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);
    cfg.FpgaEn = 1'b1;
    return cfg;
  endfunction

  localparam config_pkg::cva6_cfg_t TB_CFG = make_tb_cfg();

  typedef struct packed {
    logic valid;
    logic [TB_CFG.VLEN-1:0] pc;
    logic taken;
  } bht_update_t;

  bht_update_t bht_update;
  ariane_pkg::bht_prediction_t [TB_CFG.INSTR_PER_FETCH-1:0] bht_prediction;

  assign bht_update.valid = update_valid_i;
  assign bht_update.pc = update_pc_i;
  assign bht_update.taken = update_taken_i;

  bht #(
      .CVA6Cfg(TB_CFG),
      .bht_update_t(bht_update_t),
      .NR_ENTRIES(TB_CFG.BHTEntries)
  ) i_bht (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .flush_bp_i(flush_bp_i),
      .debug_mode_i(debug_mode_i),
      .vpc_i(vpc_i),
      .bht_update_i(bht_update),
      .bht_prediction_o(bht_prediction)
  );

  assign lane0_valid_o = bht_prediction[0].valid;
  assign lane0_taken_o = bht_prediction[0].taken;
  assign lane1_valid_o = bht_prediction[1].valid;
  assign lane1_taken_o = bht_prediction[1].taken;

endmodule
