    .trap_vector_base_o,
    .priv_lvl_o,
    .v_o,
    .acc_fflags_ex_i,
    .acc_fflags_ex_valid_i,
    .fs_o,
    .vfs_o,
    .fflags_o,
    .frm_o,
    .fprec_o,
    .vs_o,
    .irq_ctrl_o,
    .en_translation_o,
    .en_g_translation_o,
    .en_ld_st_translation_o,
    .en_ld_st_g_translation_o,
    .ld_st_priv_lvl_o,
    .ld_st_v_o,
    .csr_hs_ld_st_inst_i,
    .sum_o,
    .vs_sum_o,
    .mxr_o,
    .vmxr_o,
    .satp_ppn_o,
    .asid_o,
    .vsatp_ppn_o,
    .vs_asid_o,
    .hgatp_ppn_o,
    .vmid_o,
    .irq_i,
    .ipi_i,
    .debug_req_i,
    .set_debug_pc_o,
    .tvm_o,
    .tw_o,
    .vtw_o,
    .tsr_o,
    .hu_o,
    .debug_mode_o,
    .single_step_o,
    .icache_en_o,
    .dcache_en_o,
    .acc_cons_en_o,
    .perf_addr_o,
    .perf_data_o,
    .perf_data_i,
    .perf_we_o,
    .pmpcfg_o,
    .pmpaddr_o,
    .mcountinhibit_o,
    .rvfi_csr_o
  );

  always #5 clk_i = ~clk_i;

  task automatic set_idle_inputs;
    begin
      time_irq_i = 1'b0;
      commit_instr_i = '0;
      commit_instr_i.fu = NONE;
      commit_ack_i = '0;
      boot_addr_i = '0;
      hart_id_i = '0;
      ex_i = '0;
      csr_op_i = ADD;
      csr_addr_i = '0;
      csr_wdata_i = '0;
      dirty_fp_state_i = 1'b0;
      csr_write_fflags_i = 1'b0;
      dirty_v_state_i = 1'b0;
      pc_i = '0;
      acc_fflags_ex_i = '0;
      acc_fflags_ex_valid_i = 1'b0;
      csr_hs_ld_st_inst_i = 1'b0;
      irq_i = '0;
      ipi_i = 1'b0;
      debug_req_i = 1'b0;
      perf_data_i = '0;
    end
  endtask

  task automatic csr_write(input logic [11:0] addr, input logic [CVA6Cfg.XLEN-1:0] data);
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_wdata_i = data;
      csr_op_i = CSR_WRITE;
      @(posedge clk_i);
      #1;
      csr_op_i = ADD;
      csr_addr_i = '0;
      csr_wdata_i = '0;
    end
  endtask

  task automatic expect_read(input logic [11:0] addr, input logic [CVA6Cfg.XLEN-1:0] expected, input string msg);
    logic [CVA6Cfg.XLEN-1:0] observed;
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_op_i = CSR_READ;
      #1;
      observed = csr_rdata_o;
      if (observed !== expected) begin
        $display("Mismatch: %s expected=0x%08x observed=0x%08x", msg, expected, observed);
        $fatal(1);
      end
      @(posedge clk_i);
      #1;
      csr_op_i = ADD;
      csr_addr_i = '0;
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    set_idle_inputs();

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    expect_read(TB_PMPCFG0_ADDR, 32'h0000_0000, "reset state");
    csr_write(TB_PMPCFG0_ADDR, PMP_TOR_RWX);
    expect_read(TB_PMPCFG0_ADDR, PMP_TOR_RWX, "TOR write must stick");
    csr_write(TB_PMPCFG0_ADDR, PMP_NAPOT_RWX);
    expect_read(TB_PMPCFG0_ADDR, PMP_TOR_RWX, "NAPOT write must be WARL-nochange on cv32a65x");

    $display("Observed WARL behavior matches expectation.");
    $finish(0);
  end
endmodule
EOF

