    end
  endtask

  task automatic csr_write(input logic [11:0] addr, input logic [CFG.XLEN-1:0] data);
    begin
      @(negedge clk_i);
      csr_addr_i = addr;
      csr_wdata_i = data;
      csr_op_i = CSR_WRITE;
      @(posedge clk_i);
      #1;
      if (csr_exception_o.valid) begin
        $display("unexpected csr write exception at addr=0x%0h", addr);
        $fatal(1);
