    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);
    #1;

    if (CFG.RVS !== 1'b0 || CFG.RVU !== 1'b0) begin
      $display("unexpected config: this test requires M-mode only");
      $fatal(1);
    end

    csr_write(riscv::CSR_MIE, 32'h0000_0008);
    csr_read_expect_bit3_zero(riscv::CSR_MIE, "mie");

    @(negedge clk_i);
    ipi_i = 1'b1;
    @(posedge clk_i);
    #1;
    csr_read_expect_bit3_zero(riscv::CSR_MIP, "mip");

    $display("software interrupt bits are read-only zero as expected");
    $finish;
  end
endmodule
EOF

