tb_script:
#!/bin/bash
cd /home/cva6 || exit 1

set +e

if [ -s /etc/cva6_tools_path.sh ]; then
  # Reuse prepared tool paths when the harness has already populated them.
  # shellcheck disable=SC1091
  source /etc/cva6_tools_path.sh
fi

# The packaged verilator wrapper expects to resolve both verilator_bin and
# verilator_includer from its own install tree.
# The prepared env points VERILATOR_ROOT to /tools/verilator, which makes the
# wrapper look under /tools/verilator/bin for helper scripts that actually live
# under /tools/verilator/share/verilator/bin.
unset VERILATOR_ROOT
unset VERILATOR_BIN

export PATH="/tools/verilator/bin:${PATH}"

TEST_NAME="rv32_reserved_bit25_illegal_decode"
TB_DIR="/home/cva6/.tb_${TEST_NAME}"
BUILD_LOG="${TB_DIR}/build.log"
RUN_LOG="${TB_DIR}/run.log"
OBJ_DIR="${TB_DIR}/obj_dir"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb_decoder.sv" <<'EOF'
module tb_decoder;
  localparam config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(cva6_config_pkg::cva6_cfg);
  localparam type branchpredict_sbe_t = struct packed {
    ariane_pkg::cf_t         cf;
    logic [CVA6Cfg.VLEN-1:0] predict_address;
  };
  localparam type exception_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0]  cause;
    logic [CVA6Cfg.XLEN-1:0]  tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0]              tinst;
    logic                     gva;
    logic                     valid;
  };
  localparam type irq_ctrl_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0] mie;
    logic [CVA6Cfg.XLEN-1:0] mip;
    logic [CVA6Cfg.XLEN-1:0] mideleg;
    logic [CVA6Cfg.XLEN-1:0] hideleg;
    logic                    sie;
    logic                    global_enable;
  };
  localparam type scoreboard_entry_t = struct packed {
    logic [CVA6Cfg.VLEN-1:0]              pc;
    logic [CVA6Cfg.TRANS_ID_BITS-1:0]     trans_id;
    ariane_pkg::fu_t                      fu;
    ariane_pkg::fu_op                     op;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rs1;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rs2;
    logic [ariane_pkg::REG_ADDR_SIZE-1:0] rd;
    logic [CVA6Cfg.XLEN-1:0]              result;
    logic                                 valid;
    logic                                 use_imm;
    logic                                 use_zimm;
    logic                                 use_pc;
    exception_t                           ex;
    branchpredict_sbe_t                   bp;
    logic                                 is_compressed;
    logic                                 is_macro_instr;
    logic                                 is_last_macro_instr;
    logic                                 is_double_rd_macro_instr;
    logic                                 vfp;
  };
  localparam type interrupts_t = struct packed {
    logic [CVA6Cfg.XLEN-1:0] S_SW;
    logic [CVA6Cfg.XLEN-1:0] VS_SW;
    logic [CVA6Cfg.XLEN-1:0] M_SW;
    logic [CVA6Cfg.XLEN-1:0] S_TIMER;
    logic [CVA6Cfg.XLEN-1:0] VS_TIMER;
    logic [CVA6Cfg.XLEN-1:0] M_TIMER;
    logic [CVA6Cfg.XLEN-1:0] S_EXT;
    logic [CVA6Cfg.XLEN-1:0] VS_EXT;
    logic [CVA6Cfg.XLEN-1:0] M_EXT;
    logic [CVA6Cfg.XLEN-1:0] HS_EXT;
  };
  localparam interrupts_t INTERRUPTS = '{
    S_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_SOFT),
    VS_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_SOFT),
    M_SW: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_SOFT),
    S_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_TIMER),
    VS_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_TIMER),
    M_TIMER: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_TIMER),
    S_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_S_EXT),
    VS_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_VS_EXT),
    M_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_M_EXT),
    HS_EXT: (1 << (CVA6Cfg.XLEN - 1)) | CVA6Cfg.XLEN'(riscv::IRQ_HS_EXT)
  };

  logic debug_req_i;
  logic [CVA6Cfg.VLEN-1:0] pc_i;
  logic is_compressed_i;
  logic [15:0] compressed_instr_i;
  logic is_illegal_i;
  logic [31:0] instruction_i;
  logic is_macro_instr_i;
  logic is_last_macro_instr_i;
  logic is_double_rd_macro_instr_i;
  branchpredict_sbe_t branch_predict_i;
  exception_t ex_i;
  logic [1:0] irq_i;
  irq_ctrl_t irq_ctrl_i;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  logic debug_mode_i;
  riscv::xs_t fs_i;
  riscv::xs_t vfs_i;
  logic [2:0] frm_i;
  riscv::xs_t vs_i;
  logic tvm_i;
  logic tw_i;
  logic vtw_i;
  logic tsr_i;
  logic hu_i;
  scoreboard_entry_t instruction_o;
  logic [31:0] orig_instr_o;
  logic is_control_flow_instr_o;

  decoder #(
    .CVA6Cfg(CVA6Cfg),
    .branchpredict_sbe_t(branchpredict_sbe_t),
    .exception_t(exception_t),
    .irq_ctrl_t(irq_ctrl_t),
    .scoreboard_entry_t(scoreboard_entry_t),
    .interrupts_t(interrupts_t),
    .INTERRUPTS(INTERRUPTS)
  ) dut (
    .debug_req_i(debug_req_i),
    .pc_i(pc_i),
    .is_compressed_i(is_compressed_i),
    .compressed_instr_i(compressed_instr_i),
    .is_illegal_i(is_illegal_i),
    .instruction_i(instruction_i),
    .is_macro_instr_i(is_macro_instr_i),
    .is_last_macro_instr_i(is_last_macro_instr_i),
    .is_double_rd_macro_instr_i(is_double_rd_macro_instr_i),
    .branch_predict_i(branch_predict_i),
    .ex_i(ex_i),
    .irq_i(irq_i),
    .irq_ctrl_i(irq_ctrl_i),
    .priv_lvl_i(priv_lvl_i),
    .v_i(v_i),
    .debug_mode_i(debug_mode_i),
    .fs_i(fs_i),
    .vfs_i(vfs_i),
    .frm_i(frm_i),
    .vs_i(vs_i),
    .tvm_i(tvm_i),
    .tw_i(tw_i),
    .vtw_i(vtw_i),
    .tsr_i(tsr_i),
    .hu_i(hu_i),
    .instruction_o(instruction_o),
    .orig_instr_o(orig_instr_o),
    .is_control_flow_instr_o(is_control_flow_instr_o)
  );

  task automatic expect_illegal(input logic [31:0] instr, input string name);
    begin
      instruction_i = instr;
      #1;
      if (!(instruction_o.ex.valid && instruction_o.ex.cause == riscv::ILLEGAL_INSTR)) begin
        $display("FAIL reserved %s instr=%08x valid=%0d cause=%0d op=%0d",
                 name, instr, instruction_o.ex.valid, instruction_o.ex.cause, instruction_o.op);
        $fatal(1);
      end
    end
  endtask

  task automatic expect_legal(input logic [31:0] instr, input string name);
    begin
      instruction_i = instr;
      #1;
      if (instruction_o.ex.valid) begin
        $display("FAIL legal %s instr=%08x valid=%0d cause=%0d op=%0d",
                 name, instr, instruction_o.ex.valid, instruction_o.ex.cause,
                 instruction_o.op);
        $fatal(1);
      end
    end
  endtask

  initial begin
    debug_req_i = 1'b0;
    pc_i = '0;
    is_compressed_i = 1'b0;
    compressed_instr_i = '0;
    is_illegal_i = 1'b0;
    instruction_i = '0;
    is_macro_instr_i = 1'b0;
    is_last_macro_instr_i = 1'b0;
    is_double_rd_macro_instr_i = 1'b0;
    branch_predict_i = '0;
    ex_i = '0;
    irq_i = '0;
    irq_ctrl_i = '0;
    priv_lvl_i = riscv::PRIV_LVL_M;
    v_i = 1'b0;
    debug_mode_i = 1'b0;
    fs_i = riscv::Off;
    vfs_i = riscv::Off;
    frm_i = '0;
    vs_i = riscv::Off;
    tvm_i = 1'b0;
    tw_i = 1'b0;
    vtw_i = 1'b0;
    tsr_i = 1'b0;
    hu_i = 1'b0;

    expect_legal(32'h48031293, "bclri legal");
    expect_illegal(32'h4a031293, "bclri reserved");
    expect_legal(32'h68031293, "binvi legal");
    expect_illegal(32'h6a031293, "binvi reserved");
    expect_legal(32'h28031293, "bseti legal");
    expect_illegal(32'h2a031293, "bseti reserved");
    expect_legal(32'h48035293, "bexti legal");
    expect_illegal(32'h4a035293, "bexti reserved");
    expect_legal(32'h60035293, "rori legal");
    expect_illegal(32'h62035293, "rori reserved");

    $display("PASS");
    $finish;
  end
endmodule
EOF

timeout 1200s verilator --binary --timing --top-module tb_decoder \
  -Wno-fatal \
  -Wno-WIDTHTRUNC \
  -Wno-UNOPTFLAT \
  --Mdir "${OBJ_DIR}" \
  -Icore/include \
  core/include/config_pkg.sv \
  core/include/cv32a6_imac_sv32_config_pkg.sv \
  core/include/riscv_pkg.sv \
  core/include/ariane_pkg.sv \
  core/include/build_config_pkg.sv \
  core/cva6_accel_first_pass_decoder_stub.sv \
  core/decoder.sv \
  "${TB_DIR}/tb_decoder.sv" \
  > "${BUILD_LOG}" 2>&1
build_rc=$?

run_rc=0
if [ "${build_rc}" -eq 0 ]; then
  timeout 1200s "${OBJ_DIR}/Vtb_decoder" > "${RUN_LOG}" 2>&1
  run_rc=$?
else
  run_rc=${build_rc}
fi

rc=${run_rc}

if [ -f "${BUILD_LOG}" ]; then
  echo "[INFO] Build log tail:"
  tail -n 40 "${BUILD_LOG}"
fi

if [ -f "${RUN_LOG}" ]; then
  echo "[INFO] Run log tail:"
  tail -n 40 "${RUN_LOG}"
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"
exit "${rc}"

