#!/bin/bash
cd /home/cva6 || exit 1

set +e
export PATH="/tools/verilator/bin:$PATH"
# The installed wrapper expects VERILATOR_BIN to be a basename, not an absolute path.
unset VERILATOR_BIN
export VERILATOR_ROOT="/tools/verilator/share/verilator"
VERILATOR_BIN_PATH="/tools/verilator/bin/verilator_bin"

TB_NAME="cva6_mmu_stale_misaligned_exception"
TB_DIR="/home/cva6/.tb_cva6_mmu_stale_misaligned_exception"
OBJ_DIR="$TB_DIR/obj_dir"
LOG_FILE="$TB_DIR/run.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR" "$OBJ_DIR"

cat > "$TB_DIR/cva6_mmu_tb.sv" <<'EOF'
`timescale 1ns/1ps

module cva6_mmu_tb
  import ariane_pkg::*;
#(
    parameter config_pkg::cva6_cfg_t CVA6Cfg = build_config_pkg::build_config(
        cva6_config_pkg::cva6_cfg
    ),
    parameter int unsigned HYP_EXT = CVA6Cfg.RVH ? 1 : 0
) (
    input  logic clk_i,
    input  logic rst_ni,
    output logic done_o,
    output logic fail_o
);

  typedef struct packed {
    logic [CVA6Cfg.XLEN-1:0] cause;
    logic [CVA6Cfg.XLEN-1:0] tval;
    logic [CVA6Cfg.GPLEN-1:0] tval2;
    logic [31:0] tinst;
    logic gva;
    logic valid;
  } exception_t;

  typedef struct packed {
    logic                    fetch_valid;
    logic [CVA6Cfg.PLEN-1:0] fetch_paddr;
    exception_t              fetch_exception;
  } icache_areq_t;

  typedef struct packed {
    logic                    fetch_req;
    logic [CVA6Cfg.VLEN-1:0] fetch_vaddr;
  } icache_arsp_t;

  typedef struct packed {
    logic [CVA6Cfg.DCACHE_INDEX_WIDTH-1:0] address_index;
    logic [CVA6Cfg.DCACHE_TAG_WIDTH-1:0]   address_tag;
    logic [CVA6Cfg.XLEN-1:0]               data_wdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0]  data_wuser;
    logic                                  data_req;
    logic                                  data_we;
    logic [(CVA6Cfg.XLEN/8)-1:0]           data_be;
    logic [1:0]                            data_size;
    logic [CVA6Cfg.DcacheIdWidth-1:0]      data_id;
    logic                                  kill_req;
    logic                                  tag_valid;
  } dcache_req_i_t;

  typedef struct packed {
    logic                                 data_gnt;
    logic                                 data_rvalid;
    logic [CVA6Cfg.DcacheIdWidth-1:0]     data_rid;
    logic [CVA6Cfg.XLEN-1:0]              data_rdata;
    logic [CVA6Cfg.DCACHE_USER_WIDTH-1:0] data_ruser;
  } dcache_req_o_t;

  icache_arsp_t icache_areq_i;
  icache_areq_t icache_areq_o;
  exception_t misaligned_ex_i;
  logic lsu_req_i;
  logic [CVA6Cfg.VLEN-1:0] lsu_vaddr_i;
  logic [31:0] lsu_tinst_i;
  logic lsu_is_store_i;
  logic csr_hs_ld_st_inst_o;
  logic lsu_dtlb_hit_o;
  logic [CVA6Cfg.PPNW-1:0] lsu_dtlb_ppn_o;
  logic lsu_valid_o;
  logic [CVA6Cfg.PLEN-1:0] lsu_paddr_o;
  exception_t lsu_exception_o;
  dcache_req_o_t req_port_i;
  dcache_req_i_t req_port_o;
  riscv::pmpcfg_t [avoid_neg(CVA6Cfg.NrPMPEntries-1):0] pmpcfg_i;
  logic [avoid_neg(CVA6Cfg.NrPMPEntries-1):0][CVA6Cfg.PLEN-3:0] pmpaddr_i;

  function automatic exception_t mk_misaligned_load_ex();
    exception_t ex;
    ex = '0;
    ex.cause = CVA6Cfg.XLEN'(riscv::LD_ADDR_MISALIGNED);
    ex.tval = CVA6Cfg.XLEN'(64'h1234);
    ex.valid = 1'b1;
    return ex;
  endfunction

  task automatic fail_test(input string msg);
    begin
      $display("TB_FAIL: %s", msg);
      fail_o = 1'b1;
      done_o = 1'b1;
    end
  endtask

  cva6_mmu #(
      .CVA6Cfg       (CVA6Cfg),
      .icache_areq_t (icache_areq_t),
      .icache_arsp_t (icache_arsp_t),
      .dcache_req_i_t(dcache_req_i_t),
      .dcache_req_o_t(dcache_req_o_t),
      .exception_t   (exception_t),
      .HYP_EXT       (HYP_EXT)
  ) dut (
      .clk_i,
      .rst_ni,
      .flush_i(1'b0),
      .enable_translation_i(1'b0),
      .enable_g_translation_i(1'b0),
      .en_ld_st_translation_i(1'b0),
      .en_ld_st_g_translation_i(1'b0),
      .icache_areq_i,
      .icache_areq_o,
      .misaligned_ex_i,
      .lsu_req_i,
      .lsu_vaddr_i,
      .lsu_tinst_i,
      .lsu_is_store_i,
      .csr_hs_ld_st_inst_o,
      .lsu_dtlb_hit_o,
      .lsu_dtlb_ppn_o,
      .lsu_valid_o,
      .lsu_paddr_o,
      .lsu_exception_o,
      .priv_lvl_i(riscv::PRIV_LVL_M),
      .v_i(1'b0),
      .ld_st_priv_lvl_i(riscv::PRIV_LVL_M),
      .ld_st_v_i(1'b0),
      .sum_i(1'b0),
      .vs_sum_i(1'b0),
      .mxr_i(1'b0),
      .vmxr_i(1'b0),
      .hlvx_inst_i(1'b0),
      .hs_ld_st_inst_i(1'b0),
      .satp_ppn_i('0),
      .vsatp_ppn_i('0),
      .hgatp_ppn_i('0),
      .asid_i('0),
      .vs_asid_i('0),
      .asid_to_be_flushed_i('0),
      .vmid_i('0),
      .vmid_to_be_flushed_i('0),
      .vaddr_to_be_flushed_i('0),
      .gpaddr_to_be_flushed_i('0),
      .flush_tlb_i(1'b0),
      .flush_tlb_vvma_i(1'b0),
      .flush_tlb_gvma_i(1'b0),
      .itlb_miss_o(),
      .dtlb_miss_o(),
      .req_port_i,
      .req_port_o,
      .pmpcfg_i,
      .pmpaddr_i
  );

  initial begin : test_seq
    done_o = 1'b0;
    fail_o = 1'b0;
    icache_areq_i = '0;
    misaligned_ex_i = '0;
    lsu_req_i = 1'b0;
    lsu_vaddr_i = '0;
    lsu_tinst_i = '0;
    lsu_is_store_i = 1'b0;
    req_port_i = '0;
    pmpcfg_i = '0;
    pmpaddr_i = '0;

    @(posedge rst_ni);

    @(negedge clk_i);
    misaligned_ex_i = mk_misaligned_load_ex();
    lsu_req_i = 1'b1;
    lsu_vaddr_i = CVA6Cfg.VLEN'(64'h8000_1000);

    @(posedge clk_i);
    @(negedge clk_i);
    if (!lsu_valid_o) begin
      fail_test("missing valid response for the original misaligned request");
      disable test_seq;
    end
    if (!lsu_exception_o.valid) begin
      fail_test("missing misaligned exception for the original request");
      disable test_seq;
    end
    if (lsu_exception_o.cause != CVA6Cfg.XLEN'(riscv::LD_ADDR_MISALIGNED)) begin
      fail_test("wrong exception cause for the original request");
      disable test_seq;
    end

    misaligned_ex_i = mk_misaligned_load_ex();
    lsu_req_i = 1'b0;

    @(posedge clk_i);
    @(negedge clk_i);
    if (lsu_valid_o) begin
      fail_test("unexpected valid response without an LSU request");
      disable test_seq;
    end
    if (lsu_exception_o.valid) begin
      fail_test("stale misaligned exception leaked without an LSU request");
      disable test_seq;
    end

    $display("TB_PASS: stale misaligned exception is masked when lsu_req_i is low");
    done_o = 1'b1;
    fail_o = 1'b0;
  end

endmodule
EOF

cat > "$TB_DIR/cva6_mmu_tb.cpp" <<'EOF'
#include "Vcva6_mmu_tb.h"
#include "verilated.h"

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);

  Vcva6_mmu_tb top;
  int cycles = 0;

  top.clk_i = 0;
  top.rst_ni = 0;
  top.eval();

  while (!Verilated::gotFinish() && cycles < 20) {
    if (cycles == 2) {
      top.rst_ni = 1;
    }

    top.clk_i = 0;
    top.eval();

    top.clk_i = 1;
    top.eval();

    if (top.done_o) {
      top.final();
      return top.fail_o ? 1 : 0;
    }

    ++cycles;
  }

  top.final();
  return 2;
}
EOF

