/home/cva6/common/local/util/tc_sram_wrapper.sv
/home/cva6/common/local/util/sram.sv
/home/cva6/core/pmp/src/pmp_entry.sv
/home/cva6/core/pmp/src/pmp.sv
/home/cva6/core/cva6_mmu/cva6_tlb.sv
