/home/cva6/core/cva6_mmu/cva6_ptw.sv
/home/cva6/core/cva6_mmu/cva6_mmu.sv
/home/cva6/.tb_misaligned_lsu_no_spurious_ptw/tb_misaligned_mmu.sv
EOF

set +e
timeout 1200s "$VERILATOR_CMD" --binary --timing -Wno-fatal \
  --top-module tb_misaligned_mmu \
  --Mdir "$TB_DIR/obj_dir" \
  -f "$TB_DIR/files.f" \
  >"$BUILD_LOG" 2>&1
build_rc=$?

if [ "$build_rc" -eq 0 ]; then
  timeout 1200s "$TB_DIR/obj_dir/Vtb_misaligned_mmu" >"$SIM_LOG" 2>&1
  rc=$?
else
  rc=$build_rc
fi

if [ "$build_rc" -ne 0 ]; then
  cat "$BUILD_LOG"
else
  cat "$SIM_LOG"
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TB_NAME} ... PASS"
else
  echo "TEST: ${TB_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

