#!/bin/bash
cd /home/cva6
set -u

TEST_NAME="compressed_decoder_csh_bit6_illegal"

if [[ -f /etc/cva6_tools_path.sh ]]; then
  # Load tool paths selected during prepare.
  source /etc/cva6_tools_path.sh
fi

set +e
timeout 1200s /bin/bash <<'EOF'
set -euo pipefail

cd /home/cva6
TB_DIR="/home/cva6/.tb_csh_bit6_illegal"
rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/decoder_tb.sv" <<'SV'
module decoder_tb (
    input  logic [31:0] instr_i,
