      .CVA6Cfg(CVA6Cfg),
      .CAUSE_LEN(CauseLen),
      .ITYPE_LEN(ItypeLen),
      .IRETIRE_LEN(IretireLen),
      .rvfi_to_iti_t(rvfi_to_iti_t),
