  logic clk_i;
  logic rst_ni;
  icache_areq_t icache_areq_i;
  icache_areq_t icache_areq_o;
  logic [TestCfg.VLEN-1:0] icache_fetch_vaddr_i;
  logic lsu_valid_i;
  logic [TestCfg.PLEN-1:0] lsu_paddr_i;
  logic [TestCfg.VLEN-1:0] lsu_vaddr_i;
  exception_t lsu_exception_i;
  logic lsu_is_store_i;
  logic lsu_valid_o;
  logic [TestCfg.PLEN-1:0] lsu_paddr_o;
  exception_t lsu_exception_o;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  riscv::priv_lvl_t ld_st_priv_lvl_i;
  logic ld_st_v_i;
  riscv::pmpcfg_t [ariane_pkg::avoid_neg(TestCfg.NrPMPEntries-1):0] pmpcfg_i;
  logic [ariane_pkg::avoid_neg(TestCfg.NrPMPEntries-1):0][TestCfg.PLEN-3:0] pmpaddr_i;

  pmp_data_if #(
      .CVA6Cfg(TestCfg),
      .icache_areq_t(icache_areq_t),
      .exception_t(exception_t)
  ) dut (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .icache_areq_i(icache_areq_i),
      .icache_areq_o(icache_areq_o),
      .icache_fetch_vaddr_i(icache_fetch_vaddr_i),
