      .lsu_exception_o(lsu_exception_o),
      .priv_lvl_i(priv_lvl_i),
      .v_i(v_i),
      .ld_st_priv_lvl_i(ld_st_priv_lvl_i),
      .ld_st_v_i(ld_st_v_i),
      .pmpcfg_i(pmpcfg_i),
      .pmpaddr_i(pmpaddr_i)
  );

  task automatic clear_inputs;
    begin
      clk_i = 1'b0;
      rst_ni = 1'b1;
      icache_areq_i = '0;
      icache_fetch_vaddr_i = '0;
      lsu_valid_i = 1'b0;
      lsu_paddr_i = '0;
      lsu_vaddr_i = '0;
      lsu_exception_i = '0;
      lsu_is_store_i = 1'b0;
      priv_lvl_i = riscv::PRIV_LVL_M;
      v_i = 1'b0;
      ld_st_priv_lvl_i = riscv::PRIV_LVL_M;
      ld_st_v_i = 1'b0;
      pmpcfg_i = '0;
      pmpaddr_i = '0;
    end
  endtask

  initial begin
    clear_inputs();
    rst_ni = 1'b0;
    #1ns;
    rst_ni = 1'b1;

    // Invalid fetches must not create a new access fault.
    clear_inputs();
    icache_areq_i.fetch_valid = 1'b0;
    icache_areq_i.fetch_paddr = 'h2000;
    icache_fetch_vaddr_i = 'h2000;
    #1ns;
    if (icache_areq_o.fetch_exception.valid !== 1'b0) begin
      $fatal(1, "invalid fetch generated an instruction exception");
    end

    // A page fault must keep priority over a later PMP access fault.
    clear_inputs();
    icache_areq_i.fetch_valid = 1'b1;
    icache_areq_i.fetch_paddr = 'h2000;
    icache_fetch_vaddr_i = 'h4000;
    icache_areq_i.fetch_exception.valid = 1'b1;
    icache_areq_i.fetch_exception.cause = riscv::INSTR_PAGE_FAULT;
    icache_areq_i.fetch_exception.tval = 'h4000;
    #1ns;
    if (icache_areq_o.fetch_exception.valid !== 1'b1) begin
      $fatal(1, "page fault lost its valid bit");
    end
    if (icache_areq_o.fetch_exception.cause !== riscv::INSTR_PAGE_FAULT) begin
      $fatal(1, "page fault was overwritten by cause %0d", icache_areq_o.fetch_exception.cause);
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

