  branchpredict_sbe_t branch_predict_o;
  logic lsu_ready_i;
  logic [CVA6Cfg.NrIssuePorts-1:0] lsu_valid_o;
  logic [CVA6Cfg.NrIssuePorts-1:0] mult_valid_o;
  logic fpu_ready_i;
