    hart_id_i = '0;
    x_issue_ready_i = 1'b1;
    x_issue_resp_i = '0;
    x_register_ready_i = 1'b1;
    waddr_i = '0;
    wdata_i = '0;
    we_gpr_i = '0;
    we_fpr_i = '0;
