  task automatic configure_consumer();
    issue_instr_valid_i[0] = 1'b1;
    issue_instr_i[0].fu = ariane_pkg::ALU;
    issue_instr_i[0].op = ariane_pkg::ADD;
    issue_instr_i[0].rs1 = 5'd5;
    issue_instr_i[0].rs2 = 5'd0;
    issue_instr_i[0].rd = 5'd6;
