    issue_instr_i[0].use_pc = 1'b0;
    issue_instr_i[0].ex = '0;
    issue_instr_i[0].bp = '0;
    issue_instr_i_prev[0] = issue_instr_i[0];
  endtask

  task automatic configure_producer(input logic producer_has_exception);
    fwd_i.issue_pointer = '0;
    fwd_i.still_issued[3] = 1'b1;
    fwd_i.sbe[3].fu = ariane_pkg::ALU;
    fwd_i.sbe[3].op = ariane_pkg::ADD;
    fwd_i.sbe[3].rd = 5'd5;
    fwd_i.sbe[3].trans_id = 3;
    fwd_i.sbe[3].result = 32'hDEAD_BEEF;
    fwd_i.sbe[3].valid = 1'b1;
    fwd_i.sbe[3].ex.valid = producer_has_exception;
  endtask

  task automatic expect_blocked_exceptional_forward();
    clear_inputs();
    configure_consumer();
    configure_producer(1'b1);
    #1;
    if (issue_ack_o[0] !== 1'b0 || stall_issue_o !== 1'b1) begin
      $display("unexpected exceptional dependency behavior: issue_ack=%0b stall_issue=%0b", issue_ack_o[0], stall_issue_o);
      $fatal(1);
    end
  endtask

  task automatic expect_valid_forward();
    clear_inputs();
    configure_consumer();
    configure_producer(1'b0);
    #1;
    if (issue_ack_o[0] !== 1'b1 || stall_issue_o !== 1'b0) begin
      $display("unexpected valid dependency behavior: issue_ack=%0b stall_issue=%0b", issue_ack_o[0], stall_issue_o);
      $fatal(1);
    end
    if (rs1_forwarding_o[0] !== 32'hDEAD_BEEF) begin
      $display("unexpected forwarded operand: %08x", rs1_forwarding_o[0]);
      $fatal(1);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    clear_inputs();
    #2;
    rst_ni = 1'b1;
    #2;

    expect_blocked_exceptional_forward();
    expect_valid_forward();

    $display("tb completed");
    $finish;
