tb_script:
#!/bin/bash
set -uo pipefail

cd /home/cva6

if [[ -f /etc/cva6_tools_path.sh ]]; then
  # Reuse the environment prepared during stage 1-4.
  source /etc/cva6_tools_path.sh
fi

export NUM_JOBS="${NUM_JOBS:-4}"
export PATH="/tools/verilator/bin:${PATH}"
unset VERILATOR_BIN
export VERILATOR_ROOT="/tools/verilator/share/verilator"

TB_DIR="/home/cva6/.tb_tval_behavior"
LOG_FILE="$TB_DIR/run.log"
VERILATOR_CMD="${VERILATOR_CMD:-/tools/verilator/bin/verilator_bin}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb_top.sv" <<'EOF'
`timescale 1ns/1ps

module tb_top;
  import ariane_pkg::*;

  function automatic config_pkg::cva6_user_cfg_t make_user_cfg;
    config_pkg::cva6_user_cfg_t cfg;
    cfg = cva6_config_pkg::cva6_cfg;
    cfg.RVC = 1'b0;
    return cfg;
  endfunction

  localparam config_pkg::cva6_cfg_t TEST_CFG = build_config_pkg::build_config(make_user_cfg());

  localparam int unsigned XLEN = TEST_CFG.XLEN;
  localparam int unsigned VLEN = TEST_CFG.VLEN;
  localparam int unsigned GPLEN = TEST_CFG.GPLEN;

  typedef struct packed {
    cf_t               cf;
    logic [VLEN-1:0]   predict_address;
  } branchpredict_sbe_t;

  typedef struct packed {
    logic [XLEN-1:0]   cause;
    logic [XLEN-1:0]   tval;
    logic [GPLEN-1:0]  tval2;
    logic [31:0]       tinst;
    logic              gva;
    logic              valid;
  } exception_t;

  typedef struct packed {
    logic [VLEN-1:0]   pc;
    logic [0:0]        trans_id;
    fu_t               fu;
    fu_op              op;
    logic [REG_ADDR_SIZE-1:0] rs1;
    logic [REG_ADDR_SIZE-1:0] rs2;
    logic [REG_ADDR_SIZE-1:0] rd;
    logic [XLEN-1:0]   result;
    logic              valid;
    logic              use_imm;
    logic              use_zimm;
    logic              use_pc;
    exception_t        ex;
    branchpredict_sbe_t bp;
    logic              is_compressed;
    logic              is_macro_instr;
    logic              is_last_macro_instr;
    logic              is_double_rd_macro_instr;
    logic              vfp;
    logic              is_zcmt;
  } scoreboard_entry_t;

  typedef struct packed {
    logic [XLEN-1:0]   mie;
    logic [XLEN-1:0]   mip;
    logic [XLEN-1:0]   mideleg;
    logic [XLEN-1:0]   hideleg;
    logic              sie;
    logic              global_enable;
  } irq_ctrl_t;

  typedef struct packed {
    logic [XLEN-1:0]   S_SW;
    logic [XLEN-1:0]   VS_SW;
    logic [XLEN-1:0]   M_SW;
    logic [XLEN-1:0]   S_TIMER;
    logic [XLEN-1:0]   VS_TIMER;
    logic [XLEN-1:0]   M_TIMER;
    logic [XLEN-1:0]   S_EXT;
    logic [XLEN-1:0]   VS_EXT;
    logic [XLEN-1:0]   M_EXT;
    logic [XLEN-1:0]   HS_EXT;
  } interrupts_t;

  localparam interrupts_t INTERRUPTS = '{
      S_SW:    (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_S_SOFT),
      VS_SW:   (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_VS_SOFT),
      M_SW:    (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_M_SOFT),
      S_TIMER: (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_S_TIMER),
      VS_TIMER:(XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_VS_TIMER),
      M_TIMER: (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_M_TIMER),
      S_EXT:   (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_S_EXT),
      VS_EXT:  (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_VS_EXT),
      M_EXT:   (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_M_EXT),
      HS_EXT:  (XLEN'(1) << (XLEN - 1)) | XLEN'(riscv::IRQ_HS_EXT)
  };

  typedef struct packed {
    logic              valid;
    logic [VLEN-1:0]   pc;
    logic [VLEN-1:0]   target_address;
    logic              is_mispredict;
    logic              is_taken;
    cf_t               cf_type;
  } bp_resolve_t;

  typedef struct packed {
    fu_t               fu;
    fu_op              operation;
    logic [XLEN-1:0]   operand_a;
    logic [XLEN-1:0]   operand_b;
    logic [XLEN-1:0]   imm;
    logic [0:0]        trans_id;
  } fu_data_t;

  logic debug_req_i;
  logic [VLEN-1:0] pc_i;
  logic is_compressed_i;
  logic [15:0] compressed_instr_i;
  logic is_illegal_i;
  logic [31:0] instruction_i;
  logic is_macro_instr_i;
  logic is_last_macro_instr_i;
  logic is_double_rd_macro_instr_i;
  logic is_zcmt_i;
  logic [XLEN-1:0] jump_address_i;
  branchpredict_sbe_t branch_predict_i;
  exception_t ex_i;
  logic [1:0] irq_i;
  irq_ctrl_t irq_ctrl_i;
  riscv::priv_lvl_t priv_lvl_i;
  logic v_i;
  logic debug_mode_i;
  riscv::xs_t fs_i;
  riscv::xs_t vfs_i;
  logic [2:0] frm_i;
  riscv::xs_t vs_i;
  logic tvm_i;
  logic tw_i;
  logic vtw_i;
  logic tsr_i;
  logic hu_i;
  riscv::cbie_t mcbie_i;
  riscv::cbie_t scbie_i;
  riscv::cbie_t hcbie_i;
  logic mcbcfe_i;
  logic scbcfe_i;
  logic hcbcfe_i;
  scoreboard_entry_t instruction_o;
  logic [31:0] orig_instr_o;
  logic is_control_flow_instr_o;
  logic debug_from_trigger_i;

  logic clk_i;
  logic rst_ni;
  fu_data_t fu_data_i;
  logic [VLEN-1:0] branch_pc_i;
  logic is_zcmt_branch_i;
  logic is_compressed_instr_i;
  logic branch_valid_i;
  logic branch_comp_res_i;
  logic [VLEN-1:0] branch_result_o;
  branchpredict_sbe_t branch_predict_branch_i;
  bp_resolve_t resolved_branch_o;
  logic resolve_branch_o;
  exception_t branch_exception_o;

  decoder #(
      .CVA6Cfg(TEST_CFG),
      .branchpredict_sbe_t(branchpredict_sbe_t),
      .exception_t(exception_t),
      .irq_ctrl_t(irq_ctrl_t),
      .scoreboard_entry_t(scoreboard_entry_t),
      .interrupts_t(interrupts_t),
      .INTERRUPTS(INTERRUPTS)
  ) i_decoder (
      .debug_req_i(debug_req_i),
      .pc_i(pc_i),
      .is_compressed_i(is_compressed_i),
      .compressed_instr_i(compressed_instr_i),
      .is_illegal_i(is_illegal_i),
      .instruction_i(instruction_i),
      .is_macro_instr_i(is_macro_instr_i),
      .is_last_macro_instr_i(is_last_macro_instr_i),
      .is_double_rd_macro_instr_i(is_double_rd_macro_instr_i),
      .is_zcmt_i(is_zcmt_i),
      .jump_address_i(jump_address_i),
      .branch_predict_i(branch_predict_i),
      .ex_i(ex_i),
      .irq_i(irq_i),
      .irq_ctrl_i(irq_ctrl_i),
      .priv_lvl_i(priv_lvl_i),
      .v_i(v_i),
      .debug_mode_i(debug_mode_i),
      .fs_i(fs_i),
      .vfs_i(vfs_i),
      .frm_i(frm_i),
      .vs_i(vs_i),
      .tvm_i(tvm_i),
      .tw_i(tw_i),
      .vtw_i(vtw_i),
      .tsr_i(tsr_i),
      .hu_i(hu_i),
      .mcbie_i(mcbie_i),
      .scbie_i(scbie_i),
      .hcbie_i(hcbie_i),
      .mcbcfe_i(mcbcfe_i),
      .scbcfe_i(scbcfe_i),
      .hcbcfe_i(hcbcfe_i),
      .instruction_o(instruction_o),
      .orig_instr_o(orig_instr_o),
      .is_control_flow_instr_o(is_control_flow_instr_o),
      .debug_from_trigger_i(debug_from_trigger_i)
  );

  branch_unit #(
      .CVA6Cfg(TEST_CFG),
      .bp_resolve_t(bp_resolve_t),
      .branchpredict_sbe_t(branchpredict_sbe_t),
      .exception_t(exception_t),
      .fu_data_t(fu_data_t)
  ) i_branch_unit (
      .clk_i(clk_i),
      .rst_ni(rst_ni),
      .v_i(v_i),
      .debug_mode_i(debug_mode_i),
      .fu_data_i(fu_data_i),
      .pc_i(branch_pc_i),
      .is_zcmt_i(is_zcmt_branch_i),
      .is_compressed_instr_i(is_compressed_instr_i),
      .branch_valid_i(branch_valid_i),
      .branch_comp_res_i(branch_comp_res_i),
      .branch_result_o(branch_result_o),
      .branch_predict_i(branch_predict_branch_i),
      .resolved_branch_o(resolved_branch_o),
      .resolve_branch_o(resolve_branch_o),
      .branch_exception_o(branch_exception_o)
  );

  task automatic init_decoder_inputs;
    begin
      debug_req_i = 1'b0;
      pc_i = '0;
      is_compressed_i = 1'b0;
      compressed_instr_i = '0;
      is_illegal_i = 1'b0;
      instruction_i = '0;
      is_macro_instr_i = 1'b0;
      is_last_macro_instr_i = 1'b0;
      is_double_rd_macro_instr_i = 1'b0;
      is_zcmt_i = 1'b0;
      jump_address_i = '0;
      branch_predict_i = '0;
      ex_i = '0;
      irq_i = '0;
      irq_ctrl_i = '0;
      priv_lvl_i = riscv::PRIV_LVL_M;
      v_i = 1'b0;
      debug_mode_i = 1'b0;
      fs_i = riscv::Off;
      vfs_i = riscv::Off;
      frm_i = '0;
      vs_i = riscv::Off;
      tvm_i = 1'b0;
      tw_i = 1'b0;
      vtw_i = 1'b0;
      tsr_i = 1'b0;
      hu_i = 1'b0;
      mcbie_i = riscv::CBIE_ILLEGAL;
      scbie_i = riscv::CBIE_ILLEGAL;
      hcbie_i = riscv::CBIE_ILLEGAL;
      mcbcfe_i = 1'b0;
      scbcfe_i = 1'b0;
      hcbcfe_i = 1'b0;
      debug_from_trigger_i = 1'b0;
    end
  endtask

  task automatic init_branch_inputs;
    begin
      clk_i = 1'b0;
      rst_ni = 1'b1;
      fu_data_i = '0;
      branch_pc_i = '0;
      is_zcmt_branch_i = 1'b0;
      is_compressed_instr_i = 1'b0;
      branch_valid_i = 1'b0;
      branch_comp_res_i = 1'b0;
      branch_predict_branch_i = '0;
    end
  endtask

  task automatic check_equal(
      input string test_name,
      input logic [XLEN-1:0] got,
      input logic [XLEN-1:0] exp,
      inout int failures
  );
    begin
      if (got !== exp) begin
        $display("CHECK %s FAILED: got=0x%08x expected=0x%08x", test_name, got, exp);
        failures = failures + 1;
      end else begin
        $display("CHECK %s PASSED: value=0x%08x", test_name, got);
      end
    end
  endtask

  initial begin
    int failures;
    failures = 0;

    init_decoder_inputs();
    init_branch_inputs();
    #1;

    instruction_i = 32'h0000_0073;  // ecall
    pc_i = 32'h0000_0100;
    #1;
    if (!instruction_o.ex.valid) begin
      $display("CHECK decoder_ecall_valid FAILED: exception not raised");
      failures = failures + 1;
