    check_equal("decoder_ecall_cause", instruction_o.ex.cause, riscv::ENV_CALL_MMODE, failures);
    check_equal("decoder_ecall_tval", instruction_o.ex.tval, 32'h0000_0000, failures);

    instruction_i = 32'h0010_0073;  // ebreak
    pc_i = 32'h0000_0240;
    #1;
    if (!instruction_o.ex.valid) begin
      $display("CHECK decoder_ebreak_valid FAILED: exception not raised");
      failures = failures + 1;
    end
    check_equal("decoder_ebreak_cause", instruction_o.ex.cause, riscv::BREAKPOINT, failures);
    check_equal("decoder_ebreak_tval", instruction_o.ex.tval, 32'h0000_0240, failures);

    init_branch_inputs();
    branch_pc_i = 32'h0000_1000;
    branch_valid_i = 1'b1;
    branch_comp_res_i = 1'b1;
    fu_data_i.fu = CTRL_FLOW;
    fu_data_i.operation = ADD;
    fu_data_i.imm = 32'h0000_0002;
    #1;
    if (!branch_exception_o.valid) begin
