#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

TEST_NAME="mbox_execute_clear_rdptr"
WORK_DIR="/home/caliptra-rtl/.tb_pr252_${TEST_NAME}"
TB_FILE="${WORK_DIR}/pr252_mbox_core_tb.sv"
VF_FILE="${WORK_DIR}/pr252_mbox_core_tb.vf"
SIM_LOG="${WORK_DIR}/sim.log"

rm -rf "${WORK_DIR}"
mkdir -p "${WORK_DIR}"

cat > "${TB_FILE}" <<'SVEOF'
module pr252_mbox_core_tb;
  import soc_ifc_pkg::*;
  import mbox_csr_pkg::*;

  localparam int CLK_HALF_PERIOD = 1;
  localparam logic [SOC_IFC_ADDR_W-1:0] MBOX_ADDR_LOCK    = MBOX_REG_START_ADDR + 18'h0000;
  localparam logic [SOC_IFC_ADDR_W-1:0] MBOX_ADDR_CMD     = MBOX_REG_START_ADDR + 18'h0008;
  localparam logic [SOC_IFC_ADDR_W-1:0] MBOX_ADDR_DLEN    = MBOX_REG_START_ADDR + 18'h000c;
  localparam logic [SOC_IFC_ADDR_W-1:0] MBOX_ADDR_DATAIN  = MBOX_REG_START_ADDR + 18'h0010;
  localparam logic [SOC_IFC_ADDR_W-1:0] MBOX_ADDR_EXECUTE = MBOX_REG_START_ADDR + 18'h0018;

  localparam logic [31:0] WORD0 = 32'h1122_3344;
  localparam logic [31:0] WORD1 = 32'h5566_7788;
  localparam logic [31:0] USER  = 32'hffff_ffff;

  logic clk;
  logic rst_b;
  logic req_dv;
  logic req_hold;
  logic dir_req_dv;
  soc_ifc_req_t req_data;
  logic mbox_error;
  logic [31:0] rdata;
  logic [31:0] dir_rdata;
  logic sha_sram_req_dv;
  logic [MBOX_ADDR_W-1:0] sha_sram_req_addr;
  mbox_sram_resp_t sha_sram_resp;
  logic sha_sram_hold;
  mbox_sram_req_t mbox_sram_req;
  mbox_sram_resp_t mbox_sram_resp;
  logic sram_single_ecc_error;
  logic sram_double_ecc_error;
  logic uc_mbox_data_avail;
  logic soc_mbox_data_avail;
  logic soc_req_mbox_lock;
  mbox_protocol_error_t mbox_protocol_error;
  logic mbox_inv_pauser_axs;
  logic dmi_inc_rdptr;
  mbox_dmi_reg_t dmi_reg;
  logic [MBOX_DATA_AND_ECC_W-1:0] mbox_sram_wdata;
  logic [MBOX_DATA_AND_ECC_W-1:0] mbox_sram_rdata;

  always #CLK_HALF_PERIOD clk = ~clk;

  always_comb begin
    mbox_sram_wdata = mbox_sram_req.wdata;
    mbox_sram_resp.rdata = mbox_sram_rdata;
  end

  caliptra_sram #(
    .DEPTH(MBOX_DEPTH),
    .DATA_WIDTH(MBOX_DATA_AND_ECC_W),
    .ADDR_WIDTH(MBOX_ADDR_W)
  ) mbox_ram (
    .clk_i(clk),
    .cs_i(mbox_sram_req.cs),
    .we_i(mbox_sram_req.we),
    .addr_i(mbox_sram_req.addr),
    .wdata_i(mbox_sram_wdata),
    .rdata_o(mbox_sram_rdata)
  );

  mbox dut (
    .clk(clk),
    .rst_b(rst_b),
    .req_dv(req_dv),
    .req_hold(req_hold),
    .dir_req_dv(dir_req_dv),
    .req_data(req_data),
    .mbox_error(mbox_error),
    .rdata(rdata),
    .dir_rdata(dir_rdata),
    .sha_sram_req_dv(sha_sram_req_dv),
    .sha_sram_req_addr(sha_sram_req_addr),
    .sha_sram_resp(sha_sram_resp),
    .sha_sram_hold(sha_sram_hold),
    .mbox_sram_req(mbox_sram_req),
    .mbox_sram_resp(mbox_sram_resp),
    .sram_single_ecc_error(sram_single_ecc_error),
    .sram_double_ecc_error(sram_double_ecc_error),
    .uc_mbox_data_avail(uc_mbox_data_avail),
    .soc_mbox_data_avail(soc_mbox_data_avail),
    .soc_req_mbox_lock(soc_req_mbox_lock),
    .mbox_protocol_error(mbox_protocol_error),
    .mbox_inv_pauser_axs(mbox_inv_pauser_axs),
    .dmi_inc_rdptr(dmi_inc_rdptr),
    .dmi_reg(dmi_reg)
  );

  task automatic pulse_req(input logic soc_req, input logic write, input logic [SOC_IFC_ADDR_W-1:0] addr, input logic [31:0] data);
    begin
      req_data.addr = addr;
      req_data.wdata = data;
      req_data.user = USER;
      req_data.write = write;
      req_data.soc_req = soc_req;
      req_dv = 1'b1;
      @(posedge clk);
      req_dv = 1'b0;
      req_data = '0;
      while (req_hold) @(posedge clk);
      @(posedge clk);
    end
  endtask

  task automatic do_write(input logic soc_req, input logic [SOC_IFC_ADDR_W-1:0] addr, input logic [31:0] data);
    begin
      pulse_req(soc_req, 1'b1, addr, data);
    end
  endtask

  task automatic do_read(input logic soc_req, input logic [SOC_IFC_ADDR_W-1:0] addr, output logic [31:0] data);
    begin
      pulse_req(soc_req, 1'b0, addr, '0);
      data = rdata;
    end
  endtask

  task automatic run_test;
    logic [31:0] lock_data;
    logic [31:0] rdptr;
    begin
      do_read(1'b0, MBOX_ADDR_LOCK, lock_data);
      if (lock_data != 32'h0) begin
        $error("Expected unlocked mailbox, got 0x%08x", lock_data);
        $fatal(1);
      end

      do_write(1'b0, MBOX_ADDR_CMD, 32'hDEAD_BEEF);
      do_write(1'b0, MBOX_ADDR_DLEN, 32'h8);
      do_write(1'b0, MBOX_ADDR_DATAIN, WORD0);
      do_write(1'b0, MBOX_ADDR_DATAIN, WORD1);
      do_write(1'b0, MBOX_ADDR_EXECUTE, 32'h1);
      repeat (4) @(posedge clk);

      $display("Before DMI increment status=0x%08x rdptr=%0d", dmi_reg.MBOX_STATUS, dmi_reg.MBOX_STATUS[24:10]);
      dmi_inc_rdptr = 1'b1;
      @(posedge clk);
      @(posedge clk);
      dmi_inc_rdptr = 1'b0;
      repeat (2) @(posedge clk);
      $display("After DMI increment status=0x%08x rdptr=%0d", dmi_reg.MBOX_STATUS, dmi_reg.MBOX_STATUS[24:10]);

      do_write(1'b0, MBOX_ADDR_EXECUTE, 32'h0);
      repeat (2) @(posedge clk);

      rdptr = dmi_reg.MBOX_STATUS[24:10];
      $display("Observed dmi_reg.MBOX_STATUS=0x%08x rdptr=%0d", dmi_reg.MBOX_STATUS, rdptr);
      if (rdptr !== 32'd2) begin
        $error("Mailbox read pointer expected 2 after consuming 2 dwords, got %0d", rdptr);
        $fatal(1);
      end

      $display("* TESTCASE PASSED");
      $finish;
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_b = 1'b0;
    req_dv = 1'b0;
    req_data = '0;
    dir_req_dv = 1'b0;
    sha_sram_req_dv = 1'b0;
    sha_sram_req_addr = '0;
    dmi_inc_rdptr = 1'b0;
    repeat (5) @(posedge clk);
    rst_b = 1'b1;
    repeat (2) @(posedge clk);
    run_test();
  end

  initial begin
    repeat (500) @(posedge clk);
    $error("Timeout waiting for mbox execute-clear test");
    $fatal(1);
  end
endmodule
SVEOF

grep -v -E 'soc_ifc_tb_pkg\.sv|soc_ifc_tb\.sv$' /home/caliptra-rtl/src/soc_ifc/config/soc_ifc_tb.vf \
  | sed 's#\${CALIPTRA_ROOT}#/home/caliptra-rtl#g' > "${VF_FILE}"
printf '%s\n' "${TB_FILE}" >> "${VF_FILE}"

pushd "${WORK_DIR}" >/dev/null
set +e
verilator \
  --binary \
  --timing \
  --assert \
  -CFLAGS '-std=c++17' \
  +libext+.v+.sv \
  +define+RV_OPENSOURCE \
  --timescale 1ns/1ps \
  -Wno-WIDTH -Wno-UNOPTFLAT -Wno-LITENDIAN -Wno-CMPCONST -Wno-MULTIDRIVEN -Wno-UNPACKED \
  -f "${VF_FILE}" \
  --top-module pr252_mbox_core_tb \
  > "${SIM_LOG}" 2>&1
build_status=$?
if [[ ${build_status} -eq 0 ]]; then
  ./obj_dir/Vpr252_mbox_core_tb >> "${SIM_LOG}" 2>&1
  run_status=$?
else
  run_status=${build_status}
fi
set -e
popd >/dev/null

echo "HWE_BENCH_RESULTS_START"
if [[ ${run_status} -eq 0 ]] && grep -q '\* TESTCASE PASSED' "${SIM_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  test_status=0
else
  echo "TEST: ${TEST_NAME} ... FAIL"
  test_status=1
fi
echo "HWE_BENCH_RESULTS_END"

tail -n 80 "${SIM_LOG}" || true

exit "${test_status}"

