tb_script:
#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

TEST_NAME="mbox_no_ecc_writeback_on_direct_read"
SCRATCH_DIR="/home/caliptra-rtl/.hwe_${TEST_NAME}"
RUN_LOG="${SCRATCH_DIR}/run.log"

rm -rf "${SCRATCH_DIR}"
mkdir -p "${SCRATCH_DIR}"

cat > "${SCRATCH_DIR}/caliptra_sva.svh" <<'EOF'
`ifndef CALIPTRA_SVA_SVH
`define CALIPTRA_SVA_SVH
`define CALIPTRA_ASSERT_MUTEX(name, sigs, clk, rst)
`define CALIPTRA_ASSERT_NEVER(name, expr, clk, rst)
`endif
EOF

cat > "${SCRATCH_DIR}/rvecc_encode.sv" <<'EOF'
module rvecc_encode(
    input  logic [31:0] din,
    output logic [6:0]  ecc_out
);
  always_comb ecc_out = 7'h0;
endmodule
EOF

cat > "${SCRATCH_DIR}/rvecc_decode.sv" <<'EOF'
module rvecc_decode(
    input  logic        en,
    input  logic        sed_ded,
    input  logic [31:0] din,
    input  logic [6:0]  ecc_in,
    output logic [31:0] dout,
    output logic [6:0]  ecc_out,
    output logic        single_ecc_error,
    output logic        double_ecc_error
);
  always_comb begin
    dout = din;
    ecc_out = ecc_in;
    single_ecc_error = en;
    double_ecc_error = 1'b0;
  end
endmodule
EOF

cat > "${SCRATCH_DIR}/mbox_dir_ecc_tb.sv" <<'EOF'
module mbox_dir_ecc_tb;
  import soc_ifc_pkg::*;
  import mbox_csr_pkg::*;

  logic clk;
  logic rst_b;
  logic req_dv;
  logic req_hold;
  logic dir_req_dv;
  soc_ifc_req_t req_data;
  logic mbox_error;
  logic [31:0] rdata;
  logic [31:0] dir_rdata;
  logic sha_sram_req_dv;
  logic [MBOX_ADDR_W-1:0] sha_sram_req_addr;
  mbox_sram_resp_t sha_sram_resp;
  logic sha_sram_hold;
  mbox_sram_req_t mbox_sram_req;
  mbox_sram_resp_t mbox_sram_resp;
  logic sram_single_ecc_error;
  logic sram_double_ecc_error;
  logic uc_mbox_data_avail;
  logic soc_mbox_data_avail;
  logic soc_req_mbox_lock;
  mbox_protocol_error_t mbox_protocol_error;
  logic mbox_inv_pauser_axs;
  logic dmi_inc_rdptr;
  mbox_dmi_reg_t dmi_reg;

  localparam logic [SOC_IFC_ADDR_W-1:0] MBOX_LOCK_ADDR = MBOX_REG_START_ADDR[SOC_IFC_ADDR_W-1:0];

  always #5 clk = ~clk;

  always_comb begin
    mbox_sram_resp = '{rdata: '{ecc: 7'h55, data: 32'hdead_beef}};
    sha_sram_resp = '{rdata: '{ecc: '0, data: '0}};
  end

  mbox dut (
    .clk(clk),
    .rst_b(rst_b),
    .req_dv(req_dv),
    .req_hold(req_hold),
    .dir_req_dv(dir_req_dv),
    .req_data(req_data),
    .mbox_error(mbox_error),
    .rdata(rdata),
    .dir_rdata(dir_rdata),
    .sha_sram_req_dv(sha_sram_req_dv),
    .sha_sram_req_addr(sha_sram_req_addr),
    .sha_sram_resp(sha_sram_resp),
    .sha_sram_hold(sha_sram_hold),
    .mbox_sram_req(mbox_sram_req),
    .mbox_sram_resp(mbox_sram_resp),
    .sram_single_ecc_error(sram_single_ecc_error),
    .sram_double_ecc_error(sram_double_ecc_error),
    .uc_mbox_data_avail(uc_mbox_data_avail),
    .soc_mbox_data_avail(soc_mbox_data_avail),
    .soc_req_mbox_lock(soc_req_mbox_lock),
    .mbox_protocol_error(mbox_protocol_error),
    .mbox_inv_pauser_axs(mbox_inv_pauser_axs),
    .dmi_inc_rdptr(dmi_inc_rdptr),
    .dmi_reg(dmi_reg)
  );

  task automatic issue_lock_read;
    begin
      req_data = '{addr: MBOX_LOCK_ADDR, wdata: '0, user: 32'h0, write: 1'b0, soc_req: 1'b0};
      req_dv = 1'b1;
      @(posedge clk);
      @(negedge clk);
      req_dv = 1'b0;
      req_data = '0;
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_b = 1'b0;
    req_dv = 1'b0;
    dir_req_dv = 1'b0;
    req_data = '0;
    sha_sram_req_dv = 1'b0;
    sha_sram_req_addr = '0;
    dmi_inc_rdptr = 1'b0;

    repeat (2) @(negedge clk);
    rst_b = 1'b1;
    @(negedge clk);

    issue_lock_read();
    $display("LOCK_OBS lock=%0b soc_has_lock=%0b state=%0d",
             dut.hwif_out.mbox_lock.lock.value, dut.soc_has_lock, dut.mbox_fsm_ps);

    req_data = '{addr: '0, wdata: '0, user: 32'h0, write: 1'b0, soc_req: 1'b0};
    dir_req_dv = 1'b1;
    @(posedge clk);
    $display("STEP1 we=%0b cs=%0b single=%0b en=%0b dir_phase=%0b",
             mbox_sram_req.we, mbox_sram_req.cs, sram_single_ecc_error, dut.sram_rd_ecc_en, dut.dir_req_rd_phase);
    @(posedge clk);
    $display("STEP2 we=%0b cs=%0b single=%0b en=%0b dir_phase=%0b",
             mbox_sram_req.we, mbox_sram_req.cs, sram_single_ecc_error, dut.sram_rd_ecc_en, dut.dir_req_rd_phase);
    if (mbox_sram_req.we !== 1'b0) begin
      $display("* TESTCASE FAILED");
      $fatal(1, "Correctable direct read must not trigger writeback");
    end
    @(negedge clk);
    dir_req_dv = 1'b0;
    req_data = '0;
    @(posedge clk);
    @(negedge clk);

    $display("DIR_ECC we=%0b cs=%0b single=%0b en=%0b dir_rdata=%08x",
             mbox_sram_req.we, mbox_sram_req.cs, sram_single_ecc_error, dut.sram_rd_ecc_en, dir_rdata);
    $display("* TESTCASE PASSED");
    $finish;
  end
endmodule
EOF

cd "${SCRATCH_DIR}"

set +e
timeout 1800s bash -lc "
  cd '${SCRATCH_DIR}' &&
  verilator --binary --timing --top-module mbox_dir_ecc_tb -Wall -Wno-fatal \
    -I'${SCRATCH_DIR}' \
    -I/home/caliptra-rtl/src/soc_ifc/rtl \
    '${SCRATCH_DIR}/rvecc_encode.sv' \
    '${SCRATCH_DIR}/rvecc_decode.sv' \
    /home/caliptra-rtl/src/soc_ifc/rtl/soc_ifc_pkg.sv \
    /home/caliptra-rtl/src/soc_ifc/rtl/mbox_csr_pkg.sv \
    /home/caliptra-rtl/src/soc_ifc/rtl/mbox_csr.sv \
    /home/caliptra-rtl/src/soc_ifc/rtl/mbox.sv \
    '${SCRATCH_DIR}/mbox_dir_ecc_tb.sv' &&
  '${SCRATCH_DIR}/obj_dir/Vmbox_dir_ecc_tb'
" >"${RUN_LOG}" 2>&1
cmd_status=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ "${cmd_status}" -eq 0 ]] && grep -q '\* TESTCASE PASSED' "${RUN_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  result=0
else
  echo "TEST: ${TEST_NAME} ... FAIL"
  result=1
fi
echo "HWE_BENCH_RESULTS_END"

if [[ "${cmd_status}" -eq 124 ]]; then
  echo "[ERROR] ${TEST_NAME} timed out after 1800s"
  tail -n 80 "${RUN_LOG}" || true
  exit 1
fi

if [[ "${result}" -ne 0 ]]; then
  echo "[ERROR] ${TEST_NAME} did not reach a clean PASS result"
  tail -n 80 "${RUN_LOG}" || true
  exit 1
fi

exit 0

