#!/bin/bash
set -euo pipefail

cd /home/caliptra-rtl

TEST_NAME="wdt_early_timeout_poll"
TEST_ROOT="/home/caliptra-rtl/.hwe_pr70/test_suites/hwe_pr70_wdt_poll"
RUN_DIR="/home/caliptra-rtl/.hwe_pr70/verilator/wdt_early_timeout_poll"
SIM_LOG="${RUN_DIR}/hwe_pr70_wdt_poll.log"

mkdir -p "${TEST_ROOT}"
cat > "${TEST_ROOT}/hwe_pr70_wdt_poll.c" <<'EOF'
#include "caliptra_defines.h"
#include "printf.h"
#include <stdint.h>

volatile char *stdout = (char *)STDOUT;

enum printf_verbosity verbosity_g = LOW;

static volatile uint32_t *const wdt_timer1_en = (uint32_t *)CLP_SOC_IFC_REG_CPTRA_WDT_TIMER1_EN;
static volatile uint32_t *const wdt_timer1_ctrl = (uint32_t *)CLP_SOC_IFC_REG_CPTRA_WDT_TIMER1_CTRL;
static volatile uint32_t *const wdt_timer1_period_0 = (uint32_t *)CLP_SOC_IFC_REG_CPTRA_WDT_TIMER1_TIMEOUT_PERIOD_0;
static volatile uint32_t *const wdt_timer1_period_1 = (uint32_t *)CLP_SOC_IFC_REG_CPTRA_WDT_TIMER1_TIMEOUT_PERIOD_1;
static volatile uint32_t *const soc_ifc_notif_sts = (uint32_t *)CLP_SOC_IFC_REG_INTR_BLOCK_RF_NOTIF_INTERNAL_INTR_R;
static volatile uint32_t *const wdt_status = (uint32_t *)CLP_SOC_IFC_REG_CPTRA_WDT_STATUS;

static void short_delay(void) {
    for (volatile uint32_t i = 0; i < 4000; ++i) {
        __asm__ volatile("nop");
    }
}

void main(void) {
    const uint32_t wdt_timeout_mask =
        SOC_IFC_REG_INTR_BLOCK_RF_NOTIF_INTERNAL_INTR_R_NOTIF_WDT_TIMER1_TIMEOUT_STS_MASK;

    VPRINTF(LOW, "----------------------------------------\n");
    VPRINTF(LOW, "WDT early-timeout poll test\n");
    VPRINTF(LOW, "----------------------------------------\n");

    // A large timeout should not fire within this bounded delay.
    *soc_ifc_notif_sts = wdt_timeout_mask;
    *wdt_timer1_period_0 = 0x10000000;
    *wdt_timer1_period_1 = 0x00000000;
    *wdt_timer1_en = SOC_IFC_REG_CPTRA_WDT_TIMER1_EN_TIMER1_EN_MASK;
    *wdt_timer1_ctrl = SOC_IFC_REG_CPTRA_WDT_TIMER1_CTRL_TIMER1_RESTART_MASK;

    short_delay();

    if (((*soc_ifc_notif_sts & wdt_timeout_mask) != 0u) ||
        ((*wdt_status & SOC_IFC_REG_CPTRA_WDT_STATUS_T1_TIMEOUT_MASK) != 0u)) {
        VPRINTF(LOW, "Unexpected early WDT event notif=0x%x status=0x%x\n",
                *soc_ifc_notif_sts, *wdt_status);
        SEND_STDOUT_CTRL(0x1);
    }
}
EOF

mkdir -p "${RUN_DIR}"
rm -f "${SIM_LOG}"

set +e
timeout 1800s make -C "${RUN_DIR}" -f /home/caliptra-rtl/tools/scripts/Makefile \
  TESTNAME=hwe_pr70_wdt_poll \
  TEST_DIR="${TEST_ROOT}" \
  CALIPTRA_ROOT=/home/caliptra-rtl \
  verilator 2>&1 | tee "${SIM_LOG}"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]] && grep -q '\* TESTCASE PASSED' "${SIM_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

