#!/bin/bash
set -euo pipefail

cd /home/rocket-chip

export JAVA_HOME=/usr/lib/jvm/java-11-openjdk-amd64
export PATH="$JAVA_HOME/bin:/tools/bin:/tools/verilator/bin:/tools/riscv/bin:/opt/sbt-current/bin:$PATH"
export RISCV=/tools/riscv
