export SBT_IVY_HOME=/tools/sbt/ivy
export VERILATOR_ROOT="${VERILATOR_ROOT:-/tools/verilator}"

tb_root=/home/rocket-chip/.tb_jtag_async_reset
addon_dir="$tb_root/addon"
addon_src="$addon_dir/src/main/scala/freechips/rocketchip/jtag"
generated_dir="$tb_root/generated"
obj_dir="$tb_root/obj_dir"
cpp_harness="$tb_root/jtag_async_reset_check.cpp"
scala_emitter="$addon_src/JtagTapAsyncResetEmitter.scala"
sim_bin="$obj_dir/VJtagTapController"

mkdir -p "$addon_src"
rm -rf "$generated_dir" "$obj_dir"

cat > "$scala_emitter" <<'EOF'
package freechips.rocketchip.jtag

import java.io.{File, FileWriter}

import freechips.rocketchip.config.Parameters

object JtagTapAsyncResetEmitter extends App {
  require(args.length == 1, "usage: JtagTapAsyncResetEmitter <out-dir>")
  val outDir = new File(args(0))
  outDir.mkdirs()
  val verilog = chisel3.Driver.emitVerilog(new JtagTapController(5, 1)(Parameters.empty))
  val writer = new FileWriter(new File(outDir, "JtagTapController.v"))
  writer.write(verilog)
  writer.close()
}
EOF

cat > "$cpp_harness" <<'EOF'
#include "VJtagTapController.h"
#include "verilated.h"

static void eval(VJtagTapController* top) {
  top->eval();
}

static void set_clock(VJtagTapController* top, int value) {
  top->clock = value;
  eval(top);
}

static void jtag_cycle(VJtagTapController* top, int tms) {
  top->io_jtag_TMS = tms;
  set_clock(top, 0);
  set_clock(top, 1);
  set_clock(top, 0);
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  VJtagTapController top;

  top.reset = 0;
  top.io_jtag_TCK = 0;
  top.io_jtag_TMS = 1;
  top.io_jtag_TDI = 0;
  top.io_control_jtag_reset = 1;
  top.io_dataChainIn_shift = 0;
  top.io_dataChainIn_data = 1;
  top.io_dataChainIn_capture = 0;
  top.io_dataChainIn_update = 0;
  set_clock(&top, 0);

  top.io_control_jtag_reset = 0;
  eval(&top);

  jtag_cycle(&top, 0); // TestLogicReset -> RunTestIdle
  jtag_cycle(&top, 1); // RunTestIdle -> SelectDRScan
  jtag_cycle(&top, 0); // SelectDRScan -> CaptureDR
  jtag_cycle(&top, 0); // CaptureDR -> ShiftDR, then negedge latches TDO/TDO.driven

  if (!(top.io_jtag_TDO_data == 1 && top.io_jtag_TDO_driven == 1)) {
    VL_PRINTF("failed to drive TDO before reset: data=%d driven=%d\n",
              (int)top.io_jtag_TDO_data, (int)top.io_jtag_TDO_driven);
    return 2;
  }

  top.io_control_jtag_reset = 1;
  eval(&top);

  if (top.io_jtag_TDO_data == 0 && top.io_jtag_TDO_driven == 0) {
    VL_PRINTF("PASS async reset cleared TDO outputs immediately\n");
    return 0;
  }

  VL_PRINTF("FAIL async reset did not clear TDO outputs immediately: data=%d driven=%d\n",
            (int)top.io_jtag_TDO_data, (int)top.io_jtag_TDO_driven);
  return 1;
}
EOF

export ROCKETCHIP_ADDONS="${addon_dir#/home/rocket-chip/}"

verilator_includer="$VERILATOR_ROOT/bin/verilator_includer"
if [[ ! -x "$verilator_includer" && -x "$VERILATOR_ROOT/share/verilator/bin/verilator_includer" ]]; then
  verilator_includer="$VERILATOR_ROOT/share/verilator/bin/verilator_includer"
fi

run_reproducer() {
