  verilator --cc "$generated_dir/JtagTapController.v" \
    --top-module JtagTapController \
    --exe "$cpp_harness" \
    --CFLAGS "-std=c++17" \
    --Mdir "$obj_dir"
  make -C "$obj_dir" -f VJtagTapController.mk \
    VERILATOR_INCLUDER="$verilator_includer" \
    VJtagTapController
  "$sim_bin"
}

set +e
output="$(run_reproducer 2>&1)"
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ "$rc" -eq 0 ]]; then
  echo "TEST: jtag_async_reset ... PASS"
else
  echo "TEST: jtag_async_reset ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

printf '%s\n' "$output"
exit "$rc"

