package tbgen

import chisel3._
import chisel3.stage.{ChiselGeneratorAnnotation, ChiselStage}
import chipsalliance.rocketchip.config.Parameters
import top.MinimalConfig
import xiangshan._
import xiangshan.backend.fu.CSR

class CSRMaskWrapper(implicit p: Parameters) extends XSModule {
  val io = IO(new Bundle {
    val wen = Input(Bool())
    val addr = Input(UInt(12.W))
    val wdata = Input(UInt(XLEN.W))
    val rdata = Output(UInt(XLEN.W))
    val pAddrBits = Output(UInt(8.W))
  })

  val csr = Module(new CSR)
  val inBits = Wire(chiselTypeOf(csr.io.in.bits))
  inBits := 0.U.asTypeOf(chiselTypeOf(csr.io.in.bits))
  inBits.src(0) := io.wdata
  inBits.src(1) := 0.U
  inBits.src(2) := 0.U
  inBits.uop.ctrl.imm := io.addr
  inBits.uop.ctrl.fuOpType := Mux(io.wen, CSROpType.wrt, CSROpType.set)

  csr.io.in.valid := true.B
  csr.io.in.bits := inBits
  csr.io.out.ready := true.B
  csr.io.redirectIn.valid := false.B
  csr.io.redirectIn.bits := 0.U.asTypeOf(chiselTypeOf(csr.io.redirectIn.bits))

  csr.csrio.hartId := 0.U
  csr.csrio.perf := 0.U.asTypeOf(chiselTypeOf(csr.csrio.perf))
  csr.csrio.fpu.fflags.valid := false.B
  csr.csrio.fpu.fflags.bits := 0.U
  csr.csrio.fpu.isIllegal := false.B
  csr.csrio.fpu.dirty_fs := false.B
  csr.csrio.exception.valid := false.B
  csr.csrio.exception.bits := 0.U.asTypeOf(chiselTypeOf(csr.csrio.exception.bits))
  csr.csrio.memExceptionVAddr := 0.U
  csr.csrio.externalInterrupt := 0.U.asTypeOf(chiselTypeOf(csr.csrio.externalInterrupt))
  csr.csrio.distributedUpdate := 0.U.asTypeOf(chiselTypeOf(csr.csrio.distributedUpdate))

  io.rdata := csr.io.out.bits.data
  io.pAddrBits := PAddrBits.U
}

object GenerateCSRMaskWrapper extends App {
  private val base = new MinimalConfig(1)
  implicit val p: Parameters = base.alterPartial {
    case XSCoreParamsKey => base(XSTileKey).head
  }
  (new ChiselStage).execute(args, Seq(ChiselGeneratorAnnotation(() => new CSRMaskWrapper)))
}
EOF

  cat > /home/xiangshan/build/tbgen-csr-mask/csr_mask_tb.cpp <<'EOF'
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include "VCSRMaskWrapper.h"
#include "verilated.h"

extern "C" void v_difftest_ArchEvent(unsigned char, unsigned int, unsigned int, unsigned long long, unsigned int) {}
extern "C" void v_difftest_CSRState(unsigned char, unsigned char, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long, unsigned long long) {}

static void step(VCSRMaskWrapper* top) {
  top->clock = 0;
  top->eval();
  top->clock = 1;
  top->eval();
  top->clock = 0;
  top->eval();
}

static void write_csr(VCSRMaskWrapper* top, uint16_t addr, uint64_t data) {
  top->io_wen = 1;
  top->io_addr = addr;
  top->io_wdata = data;
  step(top);
}

static uint64_t read_csr(VCSRMaskWrapper* top, uint16_t addr) {
  top->io_wen = 0;
  top->io_addr = addr;
  top->io_wdata = 0;
  top->eval();
  return top->io_rdata;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  auto* top = new VCSRMaskWrapper;

  top->reset = 1;
  top->io_wen = 0;
  top->io_addr = 0;
  top->io_wdata = 0;
  step(top);
  step(top);
  top->reset = 0;
  step(top);

  write_csr(top, 0x300, 0x0000000000018000ULL);
  uint64_t mstatus = read_csr(top, 0x300);
  if (((mstatus >> 15) & 0x3ULL) != 0ULL) {
    std::cerr << "mstatus.xs changed unexpectedly: 0x" << std::hex << mstatus << std::dec << std::endl;
    delete top;
    return 1;
  }
  if (((mstatus >> 63) & 0x1ULL) != 0ULL) {
    std::cerr << "mstatus.sd changed unexpectedly: 0x" << std::hex << mstatus << std::dec << std::endl;
    delete top;
    return 1;
  }

  const uint64_t satp_write = 0x80000fffffffffffULL;
  const int paddr_bits = top->io_pAddrBits;
  const uint64_t expected_ppn = (1ULL << (paddr_bits - 12)) - 1ULL;
  const uint64_t expected_satp = (0x8ULL << 60) | expected_ppn;
  write_csr(top, 0x180, satp_write);
  uint64_t satp = read_csr(top, 0x180);
  if (satp != expected_satp) {
    std::cerr << "satp readback 0x" << std::hex << satp
              << " != expected 0x" << expected_satp << std::dec << std::endl;
    delete top;
    return 1;
  }

  delete top;
  return 0;
}
EOF
}

