import chisel3.util._
import freechips.rocketchip.diplomacy.{LazyModule, LazyModuleImp}
import top.MinimalConfig
import xiangshan._

class DummyWritebackSource(implicit p: Parameters) extends LazyModule with HasWritebackSource {
  private val exuPorts = Seq(
    Seq(JumpCSRExeUnitCfg),
    Seq(LdExeUnitCfg),
    Seq(LdExeUnitCfg),
    Seq(StaExeUnitCfg),
    Seq(StaExeUnitCfg)
  )

  override val writebackSourceParams: Seq[WritebackSourceParams] = Seq(new WritebackSourceParams(exuPorts))
  override lazy val writebackSourceImp: HasWritebackSourceImp = module

  lazy val module = new LazyModuleImp(this) with HasWritebackSourceImp {
    val io = IO(new Bundle {
      val wb = Input(Vec(exuPorts.length, Valid(new ExuOutput)))
    })

    override def writebackSource: Option[Seq[Seq[Valid[ExuOutput]]]] = Some(Seq(io.wb.toSeq))
  }
}

class RobCommitInstrHarness(implicit p: Parameters) extends Module {
  val io = IO(new Bundle {
    val enq = Input(Bool())
    val wfiEvent = Input(Bool())
    val wbValid = Input(Bool())
    val wbRobIdx = Input(new RobPtr)
    val allocated = Output(new RobPtr)
    val commitUopPerf = Output(UInt(6.W))
    val commitInstrPerf = Output(UInt(6.W))
  })

  val source = LazyModule(new DummyWritebackSource)
  val rob = LazyModule(new Rob)
  rob.addWritebackSink(Seq(source))

  val sourceMod = Module(source.module)
  val robMod = Module(rob.module)
  rob.generateWritebackIO(Some(source), Some(sourceMod))

  val enqUop = WireInit(0.U.asTypeOf(new MicroOp))
  enqUop.ctrl.fuType := FuType.csr
  enqUop.ctrl.fuOpType := CSROpType.wfi
  enqUop.ctrl.commitType := CommitType.NORMAL
  enqUop.cf.pc := "h1000".U

  robMod.io.hartId := 0.U
  robMod.io.redirect.valid := false.B
  robMod.io.redirect.bits := 0.U.asTypeOf(new Redirect)
  robMod.io.enq.needAlloc.foreach(_ := false.B)
  robMod.io.enq.req.foreach { req =>
    req.valid := false.B
    req.bits := 0.U.asTypeOf(new MicroOp)
  }
  robMod.io.enq.needAlloc(0) := io.enq
  robMod.io.enq.req(0).valid := io.enq
  robMod.io.enq.req(0).bits := enqUop
  robMod.io.csr.intrBitSet := false.B
  robMod.io.csr.trapTarget := 0.U
  robMod.io.csr.isXRet := false.B
  robMod.io.csr.wfiEvent := io.wfiEvent

  sourceMod.io.wb.foreach { wb =>
    wb.valid := false.B
    wb.bits := 0.U.asTypeOf(new ExuOutput)
  }
  sourceMod.io.wb(0).valid := io.wbValid
  sourceMod.io.wb(0).bits.uop.robIdx := io.wbRobIdx

  private def perf(name: String): UInt = robMod.getPerfEvents.collectFirst {
    case (n, value) if n.trim == name => value
  }.get

  io.allocated := robMod.io.enq.resp(0)
  io.commitUopPerf := perf("rob_commitUop")
  io.commitInstrPerf := perf("rob_commitInstr")
}

object RobCommitInstrHarnessMain extends App {
  implicit val p: Parameters = new MinimalConfig(1).alter((site, here, up) => {
    case XSCoreParamsKey => up(XSTileKey).head
  })

  (new ChiselStage).emitVerilog(
    new RobCommitInstrHarness,
    Array("--target-dir", "build/rob_commit_instr_perf")
  )
}
