#include <cstdint>
#include <cstdlib>
#include <iostream>
#include "verilated.h"
#include "VRobCommitInstrHarness.h"

static void tick(VRobCommitInstrHarness* top, uint64_t& uop_total, uint64_t& instr_total) {
  top->clock = 1;
  top->eval();
  top->clock = 0;
  top->eval();
  uop_total += top->io_commitUopPerf;
  instr_total += top->io_commitInstrPerf;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  auto* top = new VRobCommitInstrHarness;

  uint64_t uop_total = 0;
  uint64_t instr_total = 0;

  top->clock = 0;
  top->reset = 1;
  top->io_enq = 0;
  top->io_wfiEvent = 0;
  top->io_wbValid = 0;
  top->io_wbRobIdx_flag = 0;
  top->io_wbRobIdx_value = 0;
  top->eval();

  tick(top, uop_total, instr_total);
  tick(top, uop_total, instr_total);

  top->reset = 0;
  top->eval();

  top->io_enq = 1;
  top->eval();
  const uint8_t rob_flag = top->io_allocated_flag;
  const uint8_t rob_value = top->io_allocated_value;
  tick(top, uop_total, instr_total);

  top->io_enq = 0;
  top->io_wbRobIdx_flag = rob_flag;
  top->io_wbRobIdx_value = rob_value;
  top->io_wbValid = 1;
  tick(top, uop_total, instr_total);

  top->io_wbValid = 0;
  tick(top, uop_total, instr_total);
  tick(top, uop_total, instr_total);

  top->io_wfiEvent = 1;
  tick(top, uop_total, instr_total);
  top->io_wfiEvent = 0;

  for (int i = 0; i < 12; ++i) {
    tick(top, uop_total, instr_total);
  }

  std::cout << "commit_uop_total=" << uop_total << "\n";
  std::cout << "commit_instr_total=" << instr_total << "\n";

  delete top;

  if (uop_total != 1) {
    std::cerr << "unexpected commit_uop_total" << std::endl;
    return 2;
  }
  if (instr_total != 1) {
    std::cerr << "unexpected commit_instr_total" << std::endl;
    return 3;
  }
  return 0;
}
