  ldu.io.dcache.resp.valid := io.dcacheRespValid
  ldu.io.dcache.resp.bits := dcacheResp
  ldu.io.dcache.s1_disable_fast_wakeup := false.B
  ldu.io.dcache.s1_bank_conflict := false.B
  ldu.io.dcache.s2_hit := !io.dcacheMiss
  ldu.io.dcache.debug_s1_hit_way := 0.U

