  ldu.io.sbuffer.forwardMask := VecInit(Seq.fill(8)(false.B))
  ldu.io.sbuffer.forwardData := VecInit(Seq.fill(8)(0.U(8.W)))
  ldu.io.sbuffer.dataInvalid := false.B
  ldu.io.sbuffer.matchInvalid := io.matchInvalid

