#include "VLoadUnitReplayHarness.h"
#include "verilated.h"
#include <iostream>

static void tick(VLoadUnitReplayHarness* top) {
  top->clock = 0;
  top->eval();
  top->clock = 1;
  top->eval();
}

static void drive_defaults(VLoadUnitReplayHarness* top) {
  top->io_issueLoad = 0;
  top->io_tlbRespValid = 0;
  top->io_tlbMiss = 0;
  top->io_dcacheRespValid = 0;
  top->io_dcacheMiss = 0;
  top->io_dcacheReplay = 0;
  top->io_matchInvalid = 0;
  top->io_ldldViolation = 0;
  top->io_ldldCheckEnable = 0;
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  auto* top = new VLoadUnitReplayHarness;

  top->reset = 1;
  drive_defaults(top);
  tick(top);
  tick(top);

  top->reset = 0;

  top->io_issueLoad = 1;
  tick(top);

  top->io_issueLoad = 0;
  top->io_tlbRespValid = 1;
  tick(top);

  top->io_tlbRespValid = 0;
  top->io_dcacheRespValid = 1;
