  dut.io.frontend.fromFtq.pc_mem_waddr := 0.U
  dut.io.frontend.fromFtq.pc_mem_wdata := 0.U.asTypeOf(dut.io.frontend.fromFtq.pc_mem_wdata)
  dut.io.frontend.fromFtq.pc_mem_wdata.startAddr := "h80000000".U
  dut.io.frontend.fromFtq.pc_mem_wdata.nextLineAddr := "h80000020".U
  dut.io.frontend.fromFtq.newest_entry_target := "h80000000".U
  dut.io.frontend.fromFtq.newest_entry_ptr := 0.U.asTypeOf(dut.io.frontend.fromFtq.newest_entry_ptr)

  dut.io.frontend.cfVec.foreach { cf =>
    cf.valid := false.B
    cf.bits := 0.U.asTypeOf(cf.bits)
  }
  val cf = dut.io.frontend.cfVec.head
  cf.valid := io.cfValid
  cf.bits.instr := io.cfInstr
  cf.bits.pc := "h80000000".U
  cf.bits.foldpc := 0.U
  cf.bits.pd.valid := true.B
  cf.bits.pd.isRVC := false.B
  cf.bits.pd.brType := BrType.notCFI

  dut.io.memoryViolation.valid := io.memViolationValid
  dut.io.memoryViolation.bits := 0.U.asTypeOf(dut.io.memoryViolation.bits)
  dut.io.memoryViolation.bits.level := RedirectLevel.flushAfter

  val vaddInstr = "h02820457".U(32.W)
  val sawVaddDispatchReg = RegInit(false.B)
