  }

  io.frontendRedirectValid := dut.io.frontend.toFtq.redirect.valid
  io.pendingWindow := RegNext(dut.io.frontend.toFtq.redirect.valid, init = false.B)
  io.wrongPathVsetInDecode := dut.io.hweWrongPathVsetInDecode
  io.sawVaddDispatch := sawVaddDispatchReg
  io.vaddVconfig := vaddVconfigReg
}
