cat > /home/xiangshan/sim_main.cpp <<'EOF'
#include "VCtrlBlockRedirectVsetHarness.h"
#include "verilated.h"
#include <cstdint>
#include <cstdio>

static void step(VCtrlBlockRedirectVsetHarness& top) {
  top.clock = 0;
  top.eval();
  top.clock = 1;
  top.eval();
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Verilated::assertOn(false);
  VCtrlBlockRedirectVsetHarness top;

  const uint32_t vsetivli = 0xcc05f057u;
  const uint32_t vaddvv = 0x02820457u;
  bool sentMemViolation = false;
  bool sentWrongPathVset = false;
  bool sentRightPathVadd = false;
  bool sawPendingWindow = false;
  bool sawWrongPathVsetInDecode = false;

  top.reset = 1;
  top.io_memViolationValid = 0;
  top.io_cfValid = 0;
  top.io_cfInstr = 0;
  for (int i = 0; i < 10; ++i) step(top);
  top.reset = 0;
  for (int i = 0; i < 4; ++i) step(top);

  for (int cycle = 0; cycle < 80; ++cycle) {
    top.io_memViolationValid = 0;
    top.io_cfValid = 0;
    top.io_cfInstr = 0;

    if (!sentMemViolation) {
      top.io_memViolationValid = 1;
      sentMemViolation = true;
    } else if (!sentWrongPathVset && top.io_pendingWindow) {
      top.io_cfValid = 1;
      top.io_cfInstr = vsetivli;
      sentWrongPathVset = true;
      sawPendingWindow = true;
    } else if (sentWrongPathVset && !sentRightPathVadd) {
      top.io_cfValid = 1;
      top.io_cfInstr = vaddvv;
      sentRightPathVadd = true;
    }

    top.clock = 0;
    top.eval();
    if (top.io_wrongPathVsetInDecode) {
      sawWrongPathVsetInDecode = true;
    }
    top.clock = 1;
    top.eval();
    if (top.io_wrongPathVsetInDecode) {
      sawWrongPathVsetInDecode = true;
    }

    if (top.io_sawVaddDispatch) {
      std::fprintf(stderr,
                   "pending_window=%d wrong_path_vset_in_decode=%d vadd_vconfig=0x%x\n",
                   sawPendingWindow ? 1 : 0,
                   sawWrongPathVsetInDecode ? 1 : 0,
                   (unsigned)top.io_vaddVconfig);
      return sawPendingWindow && !sawWrongPathVsetInDecode && top.io_vaddVconfig == 0 ? 0 : 1;
    }
  }

  if (!sawPendingWindow) {
    std::fprintf(stderr, "pending window not observed\n");
    return 2;
  }
  if (sawWrongPathVsetInDecode) {
    std::fprintf(stderr, "wrong-path vset reached decode during pending redirect\n");
    return 4;
  }
  std::fprintf(stderr, "vadd dispatch not observed\n");
  return 3;
}
EOF

