#!/bin/bash
set -euo pipefail

cd /home/xiangshan

TEST_NAME="dcache_wpu_learned_way"
TEST_FILE="src/test/scala/repro/WpuBehaviorTest.scala"
BITUTILS_FILE="utility/src/main/scala/utility/BitUtils.scala"
RUN_LOG="/home/xiangshan/wpu_behavior_test.log"

write_repro_test() {
  mkdir -p "$(dirname "$TEST_FILE")"
  cat > "$TEST_FILE" <<'EOF'
package repro

import chisel3._
import chiseltest._
import chipsalliance.rocketchip.config.Parameters
import org.scalatest.freespec.AnyFreeSpec
import scala.reflect.runtime.universe._
import scala.util.Try
import top.MinimalConfig
import xiangshan.{XSCoreParameters, XSCoreParamsKey, XSTileKey}

object WpuTestConfig {
  private val mirror = runtimeMirror(getClass.getClassLoader)

  private def hasField(obj: AnyRef, name: String): Boolean = {
    val tpe = mirror.reflect(obj).symbol.toType
    tpe.decl(TermName(name)) != NoSymbol
  }

  private def getField(obj: AnyRef, name: String): Any = {
    val instMirror = mirror.reflect(obj)
    val getter = instMirror.symbol.toType.decl(TermName(name)).asMethod
    instMirror.reflectMethod(getter).apply()
  }

  private def setCaseClassFields(obj: AnyRef, updates: Map[String, Any]): AnyRef = {
    val instMirror = mirror.reflect(obj)
    val copy = instMirror.symbol.toType.decl(TermName("copy")).asMethod
    val args = copy.paramLists.flatten.map { p =>
      val name = p.name.toString
      updates.getOrElse(name, getField(obj, name))
    }
    instMirror.reflectMethod(copy)(args: _*).asInstanceOf[AnyRef]
  }

  private def enableDcacheWpu(core: XSCoreParameters): XSCoreParameters = {
    val coreObj = core.asInstanceOf[AnyRef]
    if (hasField(coreObj, "EnableDCacheWPU")) {
      setCaseClassFields(coreObj, Map("EnableDCacheWPU" -> true)).asInstanceOf[XSCoreParameters]
    } else if (hasField(coreObj, "dwpuParameters")) {
      val dwpu = getField(coreObj, "dwpuParameters").asInstanceOf[AnyRef]
      val newDwpu =
        if (hasField(dwpu, "enWPU")) setCaseClassFields(dwpu, Map("enWPU" -> true))
        else dwpu
      setCaseClassFields(coreObj, Map("dwpuParameters" -> newDwpu)).asInstanceOf[XSCoreParameters]
    } else {
      throw new IllegalStateException("No DCache WPU control field found on XSCoreParameters")
    }
  }

  def parameters: Parameters = {
    val cfg = new MinimalConfig(1).alter((site, here, up) => {
      case XSTileKey => up(XSTileKey).map(enableDcacheWpu)
    })
    cfg.alter((site, here, up) => {
      case XSCoreParamsKey => site(XSTileKey).head
    })
  }
}

object DynamicWpuFactory {
  def build()(implicit p: Parameters): Module = {
    def instantiate(name: String, args: Seq[AnyRef]): Option[Module] = Try {
      val cls = Class.forName(name)
      val ctor = cls.getConstructors.find(_.getParameterCount == args.length).getOrElse {
        throw new NoSuchMethodException("No constructor with " + args.length + " args for " + name)
      }
      Module(ctor.newInstance(args: _*).asInstanceOf[Module])
    }.toOption

    instantiate("xiangshan.cache.dcache.DCacheWPU", Seq(p.asInstanceOf[AnyRef]))
      .orElse(instantiate("xiangshan.cache.wpu.DCacheWpuWrapper", Seq(Int.box(1), p.asInstanceOf[AnyRef])))
      .orElse(instantiate("xiangshan.cache.wpu.DCacheWpuWrapper", Seq(p.asInstanceOf[AnyRef])))
      .getOrElse(throw new IllegalStateException("No supported DCache WPU module found"))
  }
}

class DynamicWpuHarness(implicit p: Parameters) extends Module {
  private val inner = DynamicWpuFactory.build()
  private val innerIo = inner.getClass.getMethod("io").invoke(inner).asInstanceOf[Record]
  val io = IO(chiselTypeOf(innerIo))
  io <> innerIo
}

class WpuBehaviorTest extends AnyFreeSpec with ChiselScalatestTester {
  private def field(data: Data, name: String): Data = data.asInstanceOf[Record].elements(name)
  private def elem(data: Data, index: Int): Data = data.asInstanceOf[Aggregate].getElements(index)
  private def pokeUInt(data: Data, value: BigInt): Unit = data.asInstanceOf[UInt].poke(value.U(data.getWidth.W))
  private def pokeBool(data: Data, value: Boolean): Unit = data.asInstanceOf[Bool].poke(value.B)
  private def expectUInt(data: Data, value: BigInt): Unit = data.asInstanceOf[UInt].expect(value.U(data.getWidth.W))

  private def zeroBaseInputs(io: Data): Unit = {
    pokeBool(field(field(io, "req"), "valid"), false)
    pokeUInt(field(field(field(io, "req"), "bits"), "vaddr"), 0)
    pokeBool(field(field(field(field(io, "req"), "bits"), "replayCarry"), "valid"), false)
    pokeUInt(field(field(field(field(io, "req"), "bits"), "replayCarry"), "real_way_en"), 0)
    pokeBool(field(field(io, "check"), "valid"), false)
    pokeUInt(field(field(field(io, "check"), "bits"), "s1_real_tag"), 0)

    val checkBits = field(field(io, "check"), "bits")
    val tagResp = field(checkBits, "s1_tag_resp")
    val metaResp = field(checkBits, "s1_meta_resp")
    val nWays = tagResp.asInstanceOf[Aggregate].getElements.size
    for (i <- 0 until nWays) {
      pokeUInt(elem(tagResp, i), 0)
      pokeUInt(field(field(elem(metaResp, i), "coh"), "state"), 0)
    }
  }

  private def runBase(io: Data, clock: Clock): Unit = {
    val addr = BigInt(0x1234)
    val tagValue = BigInt(0x15)
    val wayOh = BigInt(1) << 3

    zeroBaseInputs(io)
    pokeBool(field(field(io, "req"), "valid"), true)
    pokeUInt(field(field(field(io, "req"), "bits"), "vaddr"), addr)
    clock.step()

    zeroBaseInputs(io)
    pokeBool(field(field(io, "check"), "valid"), true)
    pokeUInt(field(field(field(io, "check"), "bits"), "s1_real_tag"), tagValue)
    pokeUInt(elem(field(field(field(io, "check"), "bits"), "s1_tag_resp"), 3), tagValue)
    pokeUInt(field(field(elem(field(field(field(io, "check"), "bits"), "s1_meta_resp"), 3), "coh"), "state"), 1)
    clock.step()

    zeroBaseInputs(io)
    pokeBool(field(field(io, "req"), "valid"), true)
    pokeUInt(field(field(field(io, "req"), "bits"), "vaddr"), addr)
    clock.step()

    expectUInt(field(field(field(io, "resp"), "bits"), "predict_way_en"), wayOh)
  }

  private def zeroFixInputs(io: Data): Unit = {
    val req0 = elem(field(io, "req"), 0)
    pokeBool(field(req0, "valid"), false)
    pokeUInt(field(field(req0, "bits"), "vaddr"), 0)
    pokeBool(field(field(field(req0, "bits"), "replayCarry"), "valid"), false)
    pokeUInt(field(field(field(req0, "bits"), "replayCarry"), "real_way_en"), 0)

    val lookup0 = elem(field(io, "lookup_upd"), 0)
    pokeBool(field(lookup0, "valid"), false)
    pokeUInt(field(field(lookup0, "bits"), "vaddr"), 0)
    pokeUInt(field(field(lookup0, "bits"), "s1_real_way_en"), 0)
    pokeUInt(field(field(lookup0, "bits"), "s1_pred_way_en"), 0)

    val cf0 = elem(field(io, "cfpred"), 0)
    pokeUInt(field(cf0, "s0_vaddr"), 0)
    pokeUInt(field(cf0, "s1_vaddr"), 0)
    pokeBool(field(cf0, "s1_dm_hit"), false)

    pokeBool(field(field(io, "tagwrite_upd"), "valid"), false)
    pokeUInt(field(field(field(io, "tagwrite_upd"), "bits"), "vaddr"), 0)
    pokeUInt(field(field(field(io, "tagwrite_upd"), "bits"), "s1_real_way_en"), 0)
  }

  private def runFix(io: Data, clock: Clock): Unit = {
    val addr = BigInt(0x1234)
    val wayOh = BigInt(1) << 3

    zeroFixInputs(io)
    val lookup0 = elem(field(io, "lookup_upd"), 0)
    pokeBool(field(lookup0, "valid"), true)
    pokeUInt(field(field(lookup0, "bits"), "vaddr"), addr)
    pokeUInt(field(field(lookup0, "bits"), "s1_real_way_en"), wayOh)
    pokeUInt(field(field(lookup0, "bits"), "s1_pred_way_en"), 0)
    clock.step()

    zeroFixInputs(io)
    val req0 = elem(field(io, "req"), 0)
    pokeBool(field(req0, "valid"), true)
    pokeUInt(field(field(req0, "bits"), "vaddr"), addr)

    field(elem(field(io, "resp"), 0), "valid").asInstanceOf[Bool].expect(true.B)
    expectUInt(field(field(elem(field(io, "resp"), 0), "bits"), "s0_pred_way_en"), wayOh)
  }

  "dcache wpu should predict the learned way" in {
    implicit val p: Parameters = WpuTestConfig.parameters
    test(new DynamicWpuHarness) { c =>
      val io = c.io
      val ioFields = io.asInstanceOf[Record].elements.keySet
      if (ioFields.contains("check")) {
        runBase(io, c.clock)
      } else {
        runFix(io, c.clock)
      }
    }
  }
}
EOF
}

ensure_onehot_compat() {
  if ! grep -q 'OHToUIntStartOne' "$BITUTILS_FILE"; then
    perl -0pi -e 's/def OH1ToUInt\(x: UInt\): UInt = OHToUInt\(OH1ToOH\(x\)\)/def OH1ToUInt(x: UInt): UInt = OHToUInt(OH1ToOH(x))\n  def OHToUIntStartOne(x: UInt): UInt = Mux(x.orR, OHToUInt(x) + 1.U, 0.U)/' "$BITUTILS_FILE"
  fi
}

run_test() {
  export MILL_VERSION
  MILL_VERSION="$(cat .mill-version)"

  set +e
  mill -i XiangShan.test.testOnly repro.WpuBehaviorTest 2>&1 | tee "$RUN_LOG"
  local rc=${PIPESTATUS[0]}
  set -e
  return "$rc"
}

write_repro_test
ensure_onehot_compat

echo "HWE_BENCH_RESULTS_START"
if run_test; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
else
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

