#!/bin/bash
set -euo pipefail

cd /home/xiangshan

TEST_NAME="iprefetch_first_request_after_reset"
REPRO_DIR="/home/xiangshan/build/iprefetch-repro"
WRAPPER_SRC="/home/xiangshan/src/main/scala/xiangshan/frontend/icache/IPrefetchPipeRepro.scala"
VERILATOR_SHIM="/home/xiangshan/local-verilator-root"
MAX_SEEDS=512

rm -rf "$REPRO_DIR" /home/xiangshan/obj_dir "$VERILATOR_SHIM"
mkdir -p "$REPRO_DIR" "$VERILATOR_SHIM/bin"

cat > "$WRAPPER_SRC" <<'EOF'
package xiangshan.frontend.icache

import chisel3._
import chisel3.stage.{ChiselGeneratorAnnotation, ChiselStage}
import org.chipsalliance.cde.config.Parameters
import top.MinimalConfig
import xiangshan.{XSCoreParamsKey, XSTileKey}
import xiangshan.backend.fu.PMPRespBundle

class IPrefetchPipeReproTop(implicit p: Parameters) extends Module {
  private val vAddrBits = p(XSCoreParamsKey).VAddrBits

  val io = IO(new Bundle {
    val ftqValid = Input(Bool())
    val ftqTarget = Input(UInt(vAddrBits.W))
    val ftqReady = Output(Bool())
    val itlbReqValid = Output(Bool())
    val metaReqValid = Output(Bool())
    val prefetchReqValid = Output(Bool())
  })

  val pipe = Module(new IPrefetchPipe)

  pipe.io.fencei := false.B
  pipe.io.ftqReq.req.valid := io.ftqValid
  pipe.io.ftqReq.req.bits.target := io.ftqTarget
  io.ftqReady := pipe.io.ftqReq.req.ready

  pipe.io.iTLBInter.req.ready := true.B
  pipe.io.iTLBInter.resp.valid := false.B
  pipe.io.iTLBInter.resp.bits := 0.U.asTypeOf(pipe.io.iTLBInter.resp.bits)

  pipe.io.metaReadReq.ready := true.B
  pipe.io.metaReadResp := 0.U.asTypeOf(pipe.io.metaReadResp)

  pipe.io.prefetchReq.ready := true.B

  pipe.io.IPFFilterRead.resp.ipf_hit := false.B
  pipe.io.PIQFilterRead.resp.piq_hit := false.B
  pipe.io.ipfRecentWrite := 0.U.asTypeOf(pipe.io.ipfRecentWrite)
  pipe.io.ICacheMissUnitInfo := 0.U.asTypeOf(pipe.io.ICacheMissUnitInfo)
  pipe.io.ICacheMainPipeInfo := 0.U.asTypeOf(pipe.io.ICacheMainPipeInfo)
  pipe.io.pmp.resp := 0.U.asTypeOf(new PMPRespBundle)

  io.itlbReqValid := pipe.io.iTLBInter.req.valid
  io.metaReqValid := pipe.io.metaReadReq.valid
  io.prefetchReqValid := pipe.io.prefetchReq.valid
}

object IPrefetchPipeReproMain extends App {
  private val baseConfig = new MinimalConfig()
  implicit val p: Parameters = baseConfig.alterPartial {
    case XSCoreParamsKey => baseConfig(XSTileKey).head
  }

  (new ChiselStage).execute(
    Array("-X", "verilog", "--target-dir", "build/iprefetch-repro"),
    Seq(ChiselGeneratorAnnotation(() => new IPrefetchPipeReproTop()(p)))
  )
}
EOF

cat > "$REPRO_DIR/LogPerfHelperStub.v" <<'EOF'
module LogPerfHelper(
  output [63:0] timer,
  output logEnable,
  output clean,
  output dump
);
  assign timer = 0;
  assign logEnable = 0;
  assign clean = 0;
  assign dump = 0;
endmodule
EOF

cat > "$REPRO_DIR/sim_main.cpp" <<'EOF'
#include <iomanip>
#include <iostream>
#include <memory>
#include <verilated.h>
#include "VIPrefetchPipeReproTop.h"
#include "VIPrefetchPipeReproTop___024root.h"

static void tick(VerilatedContext* contextp, VIPrefetchPipeReproTop* top) {
  top->clock = 0;
  top->eval();
  contextp->timeInc(1);
  top->clock = 1;
  top->eval();
  contextp->timeInc(1);
}

static bool is_aligned_nonzero(uint64_t value) {
  return value != 0 && (value & 63ULL) == 0;
}

int main(int argc, char** argv) {
  const std::unique_ptr<VerilatedContext> contextp{new VerilatedContext};
  contextp->debug(0);
  contextp->randReset(2);
  contextp->commandArgs(argc, argv);

  const std::unique_ptr<VIPrefetchPipeReproTop> top{new VIPrefetchPipeReproTop{contextp.get(), "TOP"}};

  top->reset = 1;
  top->io_ftqValid = 0;
  top->io_ftqTarget = 0;
  top->eval();
  tick(contextp.get(), top.get());

  top->reset = 0;
  tick(contextp.get(), top.get());

  const uint64_t raw_p1 = top->rootp->IPrefetchPipeReproTop__DOT__pipe__DOT__p1_vaddr;
  const uint64_t raw_p2 = top->rootp->IPrefetchPipeReproTop__DOT__pipe__DOT__p2_vaddr;

  uint64_t target = 0;
  if (is_aligned_nonzero(raw_p1)) {
    target = raw_p1;
  } else if (is_aligned_nonzero(raw_p2)) {
    target = raw_p2;
  } else if (raw_p1 == 0 && raw_p2 == 0) {
    target = 4096ULL;
  } else {
    std::cout << std::hex
              << "RAW_P1=0x" << raw_p1
              << " RAW_P2=0x" << raw_p2
              << std::dec
              << " RESULT=RETRY"
              << std::endl;
    top->final();
    return 2;
  }

  top->clock = 0;
  top->io_ftqValid = 1;
  top->io_ftqTarget = target;
  top->eval();

  std::cout << std::hex
            << "RAW_P1=0x" << raw_p1
            << " RAW_P2=0x" << raw_p2
            << " TARGET=0x" << target
            << std::dec
            << " META_VALID=" << static_cast<int>(top->io_metaReqValid)
            << " ITLB_VALID=" << static_cast<int>(top->io_itlbReqValid)
            << std::endl;

  if (top->io_metaReqValid != 1 || top->io_itlbReqValid != 1) {
    std::cerr << "spurious cancel on first request after reset" << std::endl;
    top->final();
    return 1;
  }

  top->final();
  return 0;
}
EOF

ln -sf /tools/verilator/bin/verilator_bin "$VERILATOR_SHIM/verilator_bin"
ln -sf /tools/verilator/share/verilator/bin/verilator_includer "$VERILATOR_SHIM/bin/verilator_includer"
ln -sf /tools/verilator/include "$VERILATOR_SHIM/include"

export MILL_VERSION="$(cat .mill-version)"
export VERILATOR_ROOT="$VERILATOR_SHIM"

mill -i xiangshan[chisel3].runMain xiangshan.frontend.icache.IPrefetchPipeReproMain >/dev/null
/tools/verilator/bin/verilator \
  --cc --exe --build \
  --top-module IPrefetchPipeReproTop \
  -Wno-fatal -Wno-DECLFILENAME \
  -DRANDOMIZE_REG_INIT \
  "$REPRO_DIR/IPrefetchPipeReproTop.v" \
  "$REPRO_DIR/LogPerfHelperStub.v" \
  "$REPRO_DIR/sim_main.cpp" >/dev/null

decision="undecided"
for seed in $(seq 1 "$MAX_SEEDS"); do
  set +e
  run_output=$(/home/xiangshan/obj_dir/VIPrefetchPipeReproTop "+verilator+seed+$seed" 2>&1)
  rc=$?
  set -e
  echo "seed=$seed $run_output"
  if [ "$rc" -eq 0 ]; then
    decision="pass"
    break
  fi
  if [ "$rc" -eq 1 ]; then
    decision="fail"
    break
  fi
done

echo "HWE_BENCH_RESULTS_START"
if [ "$decision" = "pass" ]; then
  echo "TEST: $TEST_NAME ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: $TEST_NAME ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

