module tb;
  import pwrmgr_pkg::*;
  import pwrmgr_reg_pkg::*;
  import prim_mubi_pkg::*;

  localparam int HoldCycles = 12;

  logic clk = 0;
  logic clk_slow = 0;
  logic rst_n = 0;
  logic rst_slow_n = 0;
  always #5 clk = ~clk;
  always #13 clk_slow = ~clk_slow;

  logic req_pwrup_i;
  pwrup_cause_e pwrup_cause_i;
  logic ack_pwrup_o;
  logic req_pwrdn_o;
  logic ack_pwrdn_i;
  logic low_power_entry_i;
  logic main_pd_ni;
  logic [TotalResetWidth-1:0] reset_reqs_i;
  logic internal_reset_req_i;
  logic ext_reset_req_i;
  logic fsm_invalid_i;
  logic clr_slow_req_o;
  logic usb_ip_clk_en_i;
  logic usb_ip_clk_status_o;
  logic wkup_o;
  logic fall_through_o;
  logic abort_o;
  logic clr_hint_o;
  logic clr_cfg_lock_o;
  pwr_rst_req_t pwr_rst_o;
  pwr_rst_rsp_t pwr_rst_i;
  pwr_clk_req_t ips_clk_en_o;
  pwr_clk_rsp_t clk_en_status_i;
  logic otp_init_o;
  logic otp_done_i;
  logic otp_idle_i;
  logic lc_init_o;
  logic lc_done_i;
  logic lc_idle_i;
  lc_ctrl_pkg::lc_tx_t lc_dft_en_i;
  lc_ctrl_pkg::lc_tx_t lc_hw_debug_en_i;
  logic flash_idle_i;
  prim_mubi_pkg::mubi4_t rom_ctrl_done_i;
  prim_mubi_pkg::mubi4_t rom_ctrl_good_i;
  logic strap_o;
  logic strap_sampled_o;
  logic low_power_o;
  lc_ctrl_pkg::lc_tx_t fetch_en_o;

  assign pwr_rst_i.rst_lc_src_n = ~pwr_rst_o.rst_lc_req;
  assign pwr_rst_i.rst_sys_src_n = ~pwr_rst_o.rst_sys_req;
  assign clk_en_status_i.main_status = ips_clk_en_o.main_ip_clk_en;
  assign clk_en_status_i.io_status = ips_clk_en_o.io_ip_clk_en;
  assign clk_en_status_i.usb_status = ips_clk_en_o.usb_ip_clk_en;

  pwrmgr_fsm_wrapper dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .clk_slow_i(clk_slow),
    .rst_slow_ni(rst_slow_n),
    .req_pwrup_i(req_pwrup_i),
    .pwrup_cause_i(pwrup_cause_i),
    .ack_pwrup_o(ack_pwrup_o),
    .req_pwrdn_o(req_pwrdn_o),
    .ack_pwrdn_i(ack_pwrdn_i),
    .low_power_entry_i(low_power_entry_i),
    .main_pd_ni(main_pd_ni),
    .reset_reqs_i(reset_reqs_i),
    .internal_reset_req_i(internal_reset_req_i),
    .ext_reset_req_i(ext_reset_req_i),
    .fsm_invalid_i(fsm_invalid_i),
    .clr_slow_req_o(clr_slow_req_o),
    .usb_ip_clk_en_i(usb_ip_clk_en_i),
    .usb_ip_clk_status_o(usb_ip_clk_status_o),
    .wkup_o(wkup_o),
    .fall_through_o(fall_through_o),
    .abort_o(abort_o),
    .clr_hint_o(clr_hint_o),
    .clr_cfg_lock_o(clr_cfg_lock_o),
    .pwr_rst_o(pwr_rst_o),
    .pwr_rst_i(pwr_rst_i),
    .ips_clk_en_o(ips_clk_en_o),
    .clk_en_status_i(clk_en_status_i),
    .otp_init_o(otp_init_o),
    .otp_done_i(otp_done_i),
    .otp_idle_i(otp_idle_i),
    .lc_init_o(lc_init_o),
    .lc_done_i(lc_done_i),
    .lc_idle_i(lc_idle_i),
    .lc_dft_en_i(lc_dft_en_i),
    .lc_hw_debug_en_i(lc_hw_debug_en_i),
    .flash_idle_i(flash_idle_i),
    .rom_ctrl_done_i(rom_ctrl_done_i),
    .rom_ctrl_good_i(rom_ctrl_good_i),
    .strap_o(strap_o),
    .strap_sampled_o(strap_sampled_o),
    .low_power_o(low_power_o),
    .fetch_en_o(fetch_en_o)
  );

  task automatic wait_for_active();
    wait (fetch_en_o == lc_ctrl_pkg::On);
    repeat (2) @(posedge clk);
  endtask

  task automatic boot_to_active(input pwrup_cause_e cause);
    pwrup_cause_i = cause;
    req_pwrup_i = 1'b1;
    @(posedge ack_pwrup_o);
    @(posedge clk);
    req_pwrup_i = 1'b0;
    wait_for_active();
  endtask

  task automatic wait_for_reset_hold();
    wait ((fetch_en_o == lc_ctrl_pkg::Off) && (pwr_rst_o.rst_sys_req != '0));
    repeat (2) @(posedge clk);
  endtask

  task automatic require_reset_still_held(input string phase);
    repeat (HoldCycles) @(posedge clk);
    if (fetch_en_o == lc_ctrl_pkg::On) begin
      $fatal(1, "%s resumed CPU fetch early: fetch_en=%0h", phase, fetch_en_o);
    end
    if (pwr_rst_o.rst_sys_req == '0) begin
      $fatal(1, "%s released rst_sys_req early: rst_sys_req=%0h", phase, pwr_rst_o.rst_sys_req);
    end
  endtask

  initial begin
    req_pwrup_i = 1'b0;
    pwrup_cause_i = Por;
    ack_pwrdn_i = 1'b1;
    low_power_entry_i = 1'b0;
    main_pd_ni = 1'b1;
    reset_reqs_i = '0;
    internal_reset_req_i = 1'b0;
    ext_reset_req_i = 1'b0;
    fsm_invalid_i = 1'b0;
    usb_ip_clk_en_i = 1'b1;
    otp_done_i = 1'b1;
    otp_idle_i = 1'b1;
    lc_done_i = 1'b1;
    lc_idle_i = 1'b1;
    lc_dft_en_i = lc_ctrl_pkg::Off;
    lc_hw_debug_en_i = lc_ctrl_pkg::Off;
    flash_idle_i = 1'b1;
    rom_ctrl_done_i = prim_mubi_pkg::MuBi4True;
    rom_ctrl_good_i = prim_mubi_pkg::MuBi4True;

    repeat (5) @(posedge clk);
    rst_n = 1'b1;
    rst_slow_n = 1'b1;

    boot_to_active(Por);

    pwrup_cause_i = Reset;
    reset_reqs_i[ResetSwReqIdx] = 1'b1;
    internal_reset_req_i = 1'b1;
    wait_for_reset_hold();

    reset_reqs_i[ResetSwReqIdx] = 1'b0;
    internal_reset_req_i = 1'b0;
    require_reset_still_held("before external reset assertion");

    reset_reqs_i[NumRstReqs-1] = 1'b1;
    ext_reset_req_i = 1'b1;
    require_reset_still_held("while external reset is asserted");

    reset_reqs_i[NumRstReqs-1] = 1'b0;
    ext_reset_req_i = 1'b0;
    wait_for_active();
    $finish(0);
  end

  initial begin
    #5000ns;
    $fatal(1, "timeout waiting for reset flow completion");
  end
endmodule
"""

