#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="edn_valid_hold"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
LOG="${TB_DIR}/dvsim.log"
RESULT="FAIL"

finish() {
  local rc="${1:-1}"
  trap - EXIT
  echo "HWE_BENCH_RESULTS_START"
  if [[ "${RESULT}" == "PASS" && "${rc}" -eq 0 ]]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

trap 'rc=$?; finish "${rc}"' EXIT

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  source /etc/opentitan_tools_path.sh
fi

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > hw/ip/edn/dv/env/seq_lib/edn_valid_hold_vseq.sv <<'EOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class edn_valid_hold_vseq extends edn_base_vseq;
  `uvm_object_utils(edn_valid_hold_vseq)

  localparam int HoldCycles = 8;
  localparam int StallTimeoutCycles = 100;
  localparam int HandshakeTimeoutCycles = 100;

  string valid_path = "tb.dut.csrng_cmd_o.csrng_req_valid";
  string ready_path = "tb.dut.csrng_cmd_i.csrng_req_ready";

  function new(string name = "edn_valid_hold_vseq");
    super.new(name);
    do_edn_init = 1'b0;
  endfunction

  task automatic read_valid_ready(output bit valid, output bit ready);
    uvm_hdl_data_t value;
    if (!uvm_hdl_read(valid_path, value)) begin
      `uvm_fatal(`gfn, $sformatf("failed to read %0s", valid_path))
    end
    valid = value[0];
    if (!uvm_hdl_read(ready_path, value)) begin
      `uvm_fatal(`gfn, $sformatf("failed to read %0s", ready_path))
    end
    ready = value[0];
  endtask

  task body();
    bit valid, ready;
    bit saw_stall = 1'b0;
    bit saw_handshake = 1'b0;

    super.body();
    device_init();

    if (!uvm_hdl_check_path(valid_path)) begin
      `uvm_fatal(`gfn, $sformatf("missing path %0s", valid_path))
    end
    if (!uvm_hdl_check_path(ready_path)) begin
      `uvm_fatal(`gfn, $sformatf("missing path %0s", ready_path))
    end

    cfg.use_invalid_mubi = 1'b0;
    cfg.which_cmd_sts_err = csrng_pkg::CMD_STS_INVALID_GEN_CMD;
    cfg.m_csrng_agent_cfg.cmd_force_ack = 1'b0;
    cfg.m_csrng_agent_cfg.cmd_zero_delays = 1'b0;
    cfg.m_csrng_agent_cfg.rsp_sts_err = csrng_pkg::CMD_STS_SUCCESS;

    `uvm_info(`gfn, "Forcing csrng_req_ready low before enabling EDN", UVM_MEDIUM)
    `DV_CHECK(uvm_hdl_force(ready_path, 1'b0))
    cfg.clk_rst_vif.wait_n_clks(1);

    wr_cmd(.cmd_type(edn_env_pkg::BootIns), .acmd(csrng_pkg::INS), .clen(0),
           .flags(MuBi4False), .glen(0), .mode(edn_env_pkg::BootReqMode));
    wr_cmd(.cmd_type(edn_env_pkg::BootGen), .acmd(csrng_pkg::GEN), .clen(0),
           .flags(MuBi4False), .glen(1), .mode(edn_env_pkg::BootReqMode));

    ral.ctrl.edn_enable.set(MuBi4True);
    ral.ctrl.boot_req_mode.set(MuBi4True);
    ral.ctrl.auto_req_mode.set(MuBi4False);
    ral.ctrl.cmd_fifo_rst.set(MuBi4False);
    csr_update(.csr(ral.ctrl));

    repeat (StallTimeoutCycles) begin
      read_valid_ready(valid, ready);
      if (valid && !ready) begin
        saw_stall = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_n_clks(1);
    end

    if (!saw_stall) begin
      `DV_CHECK(uvm_hdl_release(ready_path))
      `uvm_fatal(`gfn, "did not observe a stalled csrng request")
    end

    `uvm_info(`gfn, "Injecting CSRNG ack error while csrng_req_ready is forced low", UVM_MEDIUM)
    cfg.m_csrng_agent_cfg.rsp_sts_err = cfg.which_cmd_sts_err;
    cfg.m_csrng_agent_cfg.cmd_zero_delays = 1'b1;
    cfg.m_csrng_agent_cfg.cmd_force_ack = 1'b1;
    cfg.clk_rst_vif.wait_n_clks(2);
    cfg.m_csrng_agent_cfg.cmd_force_ack = 1'b0;
    cfg.m_csrng_agent_cfg.cmd_zero_delays = 1'b0;
    cfg.m_csrng_agent_cfg.rsp_sts_err = csrng_pkg::CMD_STS_SUCCESS;

    repeat (HoldCycles) begin
      cfg.clk_rst_vif.wait_n_clks(1);
      read_valid_ready(valid, ready);
      if (!valid) begin
        `DV_CHECK(uvm_hdl_release(ready_path))
        `uvm_fatal(`gfn,
                   "csrng_req_valid dropped before csrng_req_ready returned high")
      end
    end

    `uvm_info(`gfn, "Releasing csrng_req_ready and waiting for handshake completion", UVM_MEDIUM)
    `DV_CHECK(uvm_hdl_release(ready_path))

    repeat (HandshakeTimeoutCycles) begin
      read_valid_ready(valid, ready);
      if (valid && ready) begin
        saw_handshake = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_n_clks(1);
    end

    if (!saw_handshake) begin
      `uvm_fatal(`gfn, "did not observe csrng valid/ready handshake completion after release")
    end

    csr_spinwait(.ptr(ral.recov_alert_sts.csrng_ack_err), .exp_data(1'b1), .backdoor(1'b1));
    csr_rd_check(.ptr(ral.main_sm_state), .compare_value(edn_pkg::RejectCsrngEntropy));
    cfg.clk_rst_vif.wait_n_clks(10);
  endtask
endclass
EOF

python - <<'PY'
from pathlib import Path

path = Path("hw/ip/edn/dv/env/seq_lib/edn_vseq_list.sv")
text = path.read_text(encoding="utf-8")
line = '`include "edn_valid_hold_vseq.sv"\n'
if line not in text:
