core_path = Path("hw/ip/edn/dv/env/edn_env.core")
core_text = core_path.read_text(encoding="utf-8")
core_line = "      - seq_lib/edn_valid_hold_vseq.sv: {is_include_file: true}\n"
if core_line not in core_text:
    marker = "    file_type: systemVerilogSource\n"
    if marker not in core_text:
        raise SystemExit("failed to locate fileset marker in edn_env.core")
    core_text = core_text.replace(marker, core_line + marker, 1)
    core_path.write_text(core_text, encoding="utf-8")
PY

rm -rf scratch/HEAD/edn-sim-vcs

set +e
timeout 1800 ./util/dvsim/dvsim.py \
  hw/ip/edn/dv/edn_sim_cfg.hjson \
  -i edn_alert \
  -t vcs \
  --build-seed 1 \
  --fixed-seed 1 \
  --reseed 1 \
  --run-opts=+UVM_TEST_SEQ=edn_valid_hold_vseq \
  > >(tee "${LOG}") 2>&1
rc=${PIPESTATUS[0]}
set -e

if [[ "${rc}" -eq 0 ]]; then
  RESULT="PASS"
fi

finish "${rc}"

