  import spi_device_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic data_valid_i;
  spi_byte_t data_i;
  spi_mode_e spi_mode_i;
  cmd_info_t [NumTotalCmdInfo-1:0] cmd_info_i;
  logic sck_status_busy_i;

  io_mode_e io_mode_o;
  sel_datapath_e sel_dp_o;
  sel_datapath_e cmd_only_sel_dp_o;
  cmd_info_t cmd_info_o;
  logic [CmdInfoIdxW-1:0] cmd_info_idx_o;
  cmd_info_t cmd_only_info_o;
  logic [CmdInfoIdxW-1:0] cmd_only_info_idx_o;
  logic cmd_sync_pulse_o;
