  logic [4:0] cmd_config_idx_o;

  spi_cmdparse dut (.*);

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic load_cmd_info;
    int i;
    begin
      for (i = 0; i < NumTotalCmdInfo; i++) begin
        cmd_info_i[i] = CmdInfoInput;
      end

      cmd_info_i[CmdInfoWrEn] = '{
        valid: 1'b1,
        opcode: 8'h06,
        addr_mode: AddrDisabled,
        payload_dir: PayloadIn,
        read_pipeline_mode: RdPipeZeroStages,
        default: '0
      };

      cmd_info_i[CmdInfoReserveStart] = '{
        valid: 1'b1,
        opcode: 8'hA0,
        addr_mode: AddrDisabled,
        payload_dir: PayloadIn,
        read_pipeline_mode: RdPipeZeroStages,
        upload: 1'b1,
        busy: 1'b1,
        default: '0
      };
    end
  endtask

  task automatic reset_dut;
    begin
      data_valid_i = 1'b0;
      data_i = '0;
      sck_status_busy_i = 1'b0;
      rst_ni = 1'b0;
      repeat (2) @(posedge clk_i);
      rst_ni = 1'b1;
      @(negedge clk_i);
