        $fatal(1, "CASE_FAIL %s expected=%0b got=%0b busy=%0b opcode=0x%0h",
               name, expected_dp, cmd_only_sel_dp_o, busy, opcode);
      end else begin
        $display("CASE_PASS %s", name);
      end

      @(posedge clk_i);
      data_valid_i = 1'b0;
      data_i = '0;
    end
  endtask

  initial begin
    cfg_intercept_en_status_i = 1'b0;
    cfg_intercept_en_jedec_i = 1'b0;
    cfg_intercept_en_sfdp_i = 1'b0;
    spi_mode_i = FlashMode;
    load_cmd_info();

    expect_cmd_only_sel("idle_wren_allowed", 1'b0, 8'h06, DpWrEn);
    expect_cmd_only_sel("busy_wren_blocked", 1'b1, 8'h06, DpNone);
    expect_cmd_only_sel("busy_upload_blocked", 1'b1, 8'hA0, DpNone);

    $display("SIM_PASS");
    $finish;
  end

  initial begin
    #1000;
    $fatal(1, "SIM_FAIL timeout");
  end
endmodule
EOF

