tb_script:
#!/bin/bash
set -euo pipefail
cd /home/opentitan

source /etc/opentitan_tools_path.sh 2>/dev/null || true

TB_NAME="keymgr_terminal_reseed"
TB_ROOT="/home/opentitan/.tb_${TB_NAME}"
SCRATCH_ROOT="${TB_ROOT}/scratch"

run_test() {
python - <<'PY'
from pathlib import Path

TB_ROOT = Path("/home/opentitan/.tb_keymgr_terminal_reseed")
TB_ROOT.mkdir(parents=True, exist_ok=True)

vseq = """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_terminal_reseed_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_terminal_reseed_vseq)
  `uvm_object_new

  localparam int unsigned TerminalSettleCycles = 220;
  localparam int unsigned QuietWindowCycles = 240;

  constraint no_reset_invalid_op_c {
    do_op_before_init == 0;
    do_rand_otp_key == 0;
    do_invalid_otp_key == 0;
    is_key_version_err == 0;
  }

  virtual task count_terminal_edn_reqs(int unsigned num_clks, output int unsigned edn_req_cnt);
    bit prev_req_done;

    edn_req_cnt = 0;
    prev_req_done = cfg.keymgr_vif.edn_req_ack_sync_done;
    repeat (num_clks) begin
      cfg.clk_rst_vif.wait_clks(1);
      if (prev_req_done && !cfg.keymgr_vif.edn_req_ack_sync_done) begin
        edn_req_cnt++;
      end
      prev_req_done = cfg.keymgr_vif.edn_req_ack_sync_done;
    end
  endtask : count_terminal_edn_reqs

  virtual task check_terminal_reseed_quiet_window();
    int unsigned late_edn_req_cnt;

    cfg.clk_rst_vif.wait_clks(TerminalSettleCycles);
    count_terminal_edn_reqs(QuietWindowCycles, late_edn_req_cnt);
    `uvm_info(`gfn,
              $sformatf("Observed %0d EDN requests in quiet window after terminal entry",
                        late_edn_req_cnt),
              UVM_MEDIUM)
    `DV_CHECK_EQ(late_edn_req_cnt, 0)
  endtask : check_terminal_reseed_quiet_window

  virtual task body();
    `uvm_info(`gfn, "Start terminal reseed check sequence", UVM_MEDIUM)

    keymgr_advance();
    `DV_CHECK_EQ(current_state, keymgr_pkg::StInit)

    ral.reseed_interval_shadowed.val.set(16'd4);
    csr_update(.csr(ral.reseed_interval_shadowed));

    sema_update_control_csr.get();
    ral.control_shadowed.operation.set(keymgr_pkg::OpDisable);
    csr_update(.csr(ral.control_shadowed));
    sema_update_control_csr.put();
    csr_wr(.ptr(ral.start), .value(1));

    wait_op_done();
    `DV_CHECK_EQ(current_state, keymgr_pkg::StDisabled)

    check_terminal_reseed_quiet_window();
  endtask : body

endclass : keymgr_terminal_reseed_vseq
"""

(TB_ROOT / "keymgr_terminal_reseed_vseq.sv").write_text(vseq, encoding="utf-8")

vseq_list = Path("hw/ip/keymgr/dv/env/seq_lib/keymgr_vseq_list.sv")
vseq_list_text = vseq_list.read_text(encoding="utf-8")
vseq_include = '`include "/home/opentitan/.tb_keymgr_terminal_reseed/keymgr_terminal_reseed_vseq.sv"\n'
if vseq_include not in vseq_list_text:
    marker = '`include "keymgr_stress_all_vseq.sv"\n'
    if marker not in vseq_list_text:
        raise SystemExit("Failed to patch keymgr_vseq_list.sv")
    vseq_list_text = vseq_list_text.replace(marker, marker + vseq_include)
    vseq_list.write_text(vseq_list_text, encoding="utf-8")

sim_cfg = Path("hw/ip/keymgr/dv/keymgr_sim_cfg.hjson")
sim_cfg_text = sim_cfg.read_text(encoding="utf-8")
test_block = """
    {
      name: keymgr_terminal_reseed
      uvm_test_seq: keymgr_terminal_reseed_vseq
      reseed: 1
    }
"""
if "name: keymgr_terminal_reseed" not in sim_cfg_text:
    marker = "  ]\n\n  // List of regressions.\n"
    if marker not in sim_cfg_text:
        raise SystemExit("Failed to patch keymgr_sim_cfg.hjson")
    sim_cfg_text = sim_cfg_text.replace(marker, test_block + "  ]\n\n  // List of regressions.\n")
    sim_cfg.write_text(sim_cfg_text, encoding="utf-8")
PY
py_rc=$?
if [ "${py_rc}" -ne 0 ]; then
  return "${py_rc}"
fi

timeout 1800 ./util/dvsim/dvsim.py hw/ip/keymgr/dv/keymgr_sim_cfg.hjson \
  -i "${TB_NAME}" \
  -t vcs \
  --local \
  -mp 1 \
  --fixed-seed 1 \
  --build-seed 1 \
  --scratch-root "${SCRATCH_ROOT}" \
  --branch tbgen \
  --purge \
  --max-odirs 1 \
  --run-timeout-mins 10 \
  --build-timeout-mins 20 \
  --no-rerun
}

set +e
run_test
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TB_NAME} ... PASS"
else
  echo "TEST: ${TB_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

