#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "sw/device/silicon_creator/lib/cert/cert.h"
#include "sw/device/silicon_creator/lib/error.h"

static uint32_t cert_words[kCertX509Asn1FirstWordsWithSerialNumber] = {0};
static flash_ctrl_error_code_t error_code = {0};

rom_error_t flash_ctrl_info_read(const flash_ctrl_info_page_t *info_page,
                                 uint32_t offset, uint32_t word_count,
                                 void *data) {
  (void)info_page;
  (void)offset;
  memcpy(data, cert_words, word_count * sizeof(uint32_t));
  return kErrorOk;
}

void flash_ctrl_error_code_get(flash_ctrl_error_code_t *out) { *out = error_code; }

rom_error_t flash_ctrl_info_erase(const flash_ctrl_info_page_t *info_page,
                                  flash_ctrl_erase_type_t erase_type) {
  (void)info_page;
  (void)erase_type;
  return kErrorOk;
}

int main(void) {
  uint8_t *bytes = (uint8_t *)cert_words;
  uint8_t expected[20] = {
      0x00, 0x01, 0x02, 0x03, 0x04,
      0x05, 0x06, 0x07, 0x08, 0x09,
