  };
  hardened_bool_t matches = kHardenedBoolFalse;

  bytes[13] = 0x02;
  bytes[14] = 19;
  for (int i = 0; i < 19; ++i) {
    bytes[15 + i] = (uint8_t)(i + 1);
  }

  rom_error_t err = cert_x509_asn1_check_serial_number(
      &(flash_ctrl_info_page_t){0}, expected, &matches);
  printf("err=%08x matches=%u\n", err, matches);
  return (err == kErrorOk && matches == kHardenedBoolTrue) ? 0 : 1;
}
EOF
else
  cat > "${TB_DIR}/repro.c" <<'EOF'
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "sw/device/silicon_creator/lib/cert/cert.h"
#include "sw/device/silicon_creator/lib/error.h"

