rc=$?
if [ "${rc}" -ne 0 ]; then
  emit_result "FAIL" "${rc}"
fi

"${TB_DIR}/repro" >"${RUN_LOG}" 2>&1
rc=$?

if [ "${rc}" -eq 0 ]; then
