#!/bin/bash
set -euo pipefail

cd /home/opentitan

export PATH="$HOME/.local/bin:/tools/verible/bin:/tools/riscv/bin:$PATH"

cat > /home/opentitan/hw/ip/keymgr/dv/env/seq_lib/keymgr_smoke_vseq.sv <<'EOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

// Smoke test tuned to reproduce the idle reseed bug.
class keymgr_smoke_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_smoke_vseq)
  `uvm_object_new

  localparam int ReseedInterval = 8;
  localparam int IdleWindowClks = 64;
  localparam int WaitTimeoutClks = 2000;

  constraint no_invalid_op_before_init_c {
    do_op_before_init == 0;
  }

  virtual task pre_start();
    cfg.keymgr_vif.en_chk = 0;
    super.pre_start();
  endtask

  virtual task keymgr_init();
    `uvm_info(`gfn, "Initializating key manager with a fixed reseed interval", UVM_MEDIUM)
    ral.intr_enable.set(0);
    csr_update(.csr(ral.intr_enable));
    ral.reseed_interval_shadowed.val.set(ReseedInterval);
    csr_update(.csr(ral.reseed_interval_shadowed));
  endtask

  task wait_for_edn_idle();
    int wait_clks = 0;
    do begin
      if (cfg.keymgr_vif.start_edn_req &&
          cfg.keymgr_vif.edn_req_cnt == 0 &&
          !cfg.keymgr_vif.edn_req_sync &&
          !cfg.keymgr_vif.edn_req_ack_sync &&
          !cfg.keymgr_vif.edn_req_ack_sync_done) begin
        return;
      end
      cfg.clk_rst_vif.wait_clks(1);
      wait_clks++;
    end while (wait_clks < WaitTimeoutClks);
    `uvm_fatal(`gfn, "Timed out waiting for the initial EDN reseed to finish")
  endtask

  task check_no_idle_edn_requests(int idle_cycles);
    int cycle = 0;
    repeat (idle_cycles) begin
      cycle++;
      if (cfg.keymgr_vif.edn_req_sync ||
          cfg.keymgr_vif.edn_req_ack_sync ||
          cfg.keymgr_vif.edn_req_ack_sync_done) begin
        `uvm_fatal(`gfn,
                   $sformatf("Unexpected EDN reseed request while keymgr is idle at cycle %0d/%0d",
                             cycle, idle_cycles))
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
  endtask

  task body();
    `uvm_info(`gfn, "Trigger one keymgr operation and check that idle cycles do not reseed",
              UVM_HIGH)
    keymgr_advance(.wait_done(1));
    wait_for_edn_idle();
