tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -uo pipefail

TB_CORE=/home/opentitan/.tb_csrng_prep_rc.core
TB_SV=/home/opentitan/.tb_csrng_prep_rc_tb.sv
TB_BUILD=/home/opentitan/.tb_csrng_prep_rc_build
TB_LOG=/home/opentitan/.tb_csrng_prep_rc.log

rm -rf "$TB_BUILD" "$TB_LOG" "$TB_CORE" "$TB_SV"

cat > "$TB_CORE" <<'EOF'
CAPI=2:
name: "local:dv:csrng_prep_rc_tb:0.1"
description: "Minimal CSRNG ctr_drbg_cmd reseed counter test"
filesets:
  files_rtl:
    depend:
      - lowrisc:prim:assert
      - lowrisc:prim:fifo
      - lowrisc:ip:csrng_pkg
    files:
      - hw/ip/csrng/rtl/csrng_ctr_drbg_cmd.sv
    file_type: systemVerilogSource
  files_tb:
    files:
      - .tb_csrng_prep_rc_tb.sv
    file_type: systemVerilogSource
targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_rtl
      - files_tb
EOF

cat > "$TB_SV" <<'EOF'
module tb;
  import csrng_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic ctr_drbg_cmd_enable_i;
  logic ctr_drbg_cmd_req_i;
  logic ctr_drbg_cmd_rdy_o;
  logic [2:0] ctr_drbg_cmd_ccmd_i;
  logic [3:0] ctr_drbg_cmd_inst_id_i;
  logic ctr_drbg_cmd_glast_i;
  logic [383:0] ctr_drbg_cmd_entropy_i;
  logic ctr_drbg_cmd_entropy_fips_i;
  logic [383:0] ctr_drbg_cmd_adata_i;
  logic [255:0] ctr_drbg_cmd_key_i;
  logic [127:0] ctr_drbg_cmd_v_i;
  logic [31:0] ctr_drbg_cmd_rc_i;
  logic ctr_drbg_cmd_fips_i;
  logic ctr_drbg_cmd_ack_o;
  csrng_cmd_sts_e ctr_drbg_cmd_sts_o;
  logic ctr_drbg_cmd_rdy_i;
  logic [2:0] ctr_drbg_cmd_ccmd_o;
  logic [3:0] ctr_drbg_cmd_inst_id_o;
  logic ctr_drbg_cmd_glast_o;
  logic ctr_drbg_cmd_fips_o;
  logic [383:0] ctr_drbg_cmd_adata_o;
  logic [255:0] ctr_drbg_cmd_key_o;
  logic [127:0] ctr_drbg_cmd_v_o;
  logic [31:0] ctr_drbg_cmd_rc_o;
  logic cmd_upd_req_o;
  logic upd_cmd_rdy_i;
  logic [2:0] cmd_upd_ccmd_o;
  logic [3:0] cmd_upd_inst_id_o;
  logic [383:0] cmd_upd_pdata_o;
  logic [255:0] cmd_upd_key_o;
  logic [127:0] cmd_upd_v_o;
  logic upd_cmd_ack_i;
  logic cmd_upd_rdy_o;
  logic [2:0] upd_cmd_ccmd_i;
  logic [3:0] upd_cmd_inst_id_i;
  logic [255:0] upd_cmd_key_i;
  logic [127:0] upd_cmd_v_i;
  logic [2:0] ctr_drbg_cmd_sfifo_cmdreq_err_o;
  logic [2:0] ctr_drbg_cmd_sfifo_rcstage_err_o;
  logic [2:0] ctr_drbg_cmd_sfifo_keyvrc_err_o;

  csrng_ctr_drbg_cmd dut (
    .clk_i,
    .rst_ni,
    .ctr_drbg_cmd_enable_i,
    .ctr_drbg_cmd_req_i,
    .ctr_drbg_cmd_rdy_o,
    .ctr_drbg_cmd_ccmd_i,
    .ctr_drbg_cmd_inst_id_i,
    .ctr_drbg_cmd_glast_i,
    .ctr_drbg_cmd_entropy_i,
    .ctr_drbg_cmd_entropy_fips_i,
    .ctr_drbg_cmd_adata_i,
    .ctr_drbg_cmd_key_i,
    .ctr_drbg_cmd_v_i,
    .ctr_drbg_cmd_rc_i,
    .ctr_drbg_cmd_fips_i,
    .ctr_drbg_cmd_ack_o,
    .ctr_drbg_cmd_sts_o,
    .ctr_drbg_cmd_rdy_i,
    .ctr_drbg_cmd_ccmd_o,
    .ctr_drbg_cmd_inst_id_o,
    .ctr_drbg_cmd_glast_o,
    .ctr_drbg_cmd_fips_o,
    .ctr_drbg_cmd_adata_o,
    .ctr_drbg_cmd_key_o,
    .ctr_drbg_cmd_v_o,
    .ctr_drbg_cmd_rc_o,
    .cmd_upd_req_o,
    .upd_cmd_rdy_i,
    .cmd_upd_ccmd_o,
    .cmd_upd_inst_id_o,
    .cmd_upd_pdata_o,
    .cmd_upd_key_o,
    .cmd_upd_v_o,
    .upd_cmd_ack_i,
    .cmd_upd_rdy_o,
    .upd_cmd_ccmd_i,
    .upd_cmd_inst_id_i,
    .upd_cmd_key_i,
    .upd_cmd_v_i,
    .ctr_drbg_cmd_sfifo_cmdreq_err_o,
    .ctr_drbg_cmd_sfifo_rcstage_err_o,
    .ctr_drbg_cmd_sfifo_keyvrc_err_o
  );

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 0;
    rst_ni = 0;
    ctr_drbg_cmd_enable_i = 0;
    ctr_drbg_cmd_req_i = 0;
    ctr_drbg_cmd_ccmd_i = INS;
    ctr_drbg_cmd_inst_id_i = '0;
    ctr_drbg_cmd_glast_i = 1'b1;
    ctr_drbg_cmd_entropy_i = '0;
    ctr_drbg_cmd_entropy_fips_i = 1'b0;
    ctr_drbg_cmd_adata_i = '0;
    ctr_drbg_cmd_key_i = '0;
    ctr_drbg_cmd_v_i = '0;
    ctr_drbg_cmd_rc_i = 32'hdeadbeef;
    ctr_drbg_cmd_fips_i = 1'b0;
    ctr_drbg_cmd_rdy_i = 1'b1;
    upd_cmd_rdy_i = 1'b1;
    upd_cmd_ack_i = 1'b1;
    upd_cmd_ccmd_i = INS;
    upd_cmd_inst_id_i = '0;
    upd_cmd_key_i = '0;
    upd_cmd_v_i = '0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    ctr_drbg_cmd_enable_i = 1'b1;

    @(posedge clk_i);
    ctr_drbg_cmd_req_i = 1'b1;
    @(posedge clk_i);
    ctr_drbg_cmd_req_i = 1'b0;

    wait (ctr_drbg_cmd_ack_o === 1'b1);
    @(posedge clk_i);

    if (ctr_drbg_cmd_sts_o !== CMD_STS_SUCCESS) begin
      $display("unexpected status %0d", ctr_drbg_cmd_sts_o);
      $fatal(1);
    end

    if (ctr_drbg_cmd_rc_o !== 32'd0) begin
      $display("reseed counter after instantiate was %0d, expected 0",
               ctr_drbg_cmd_rc_o);
      $fatal(1);
    end

    $display("rc check passed with value %0d", ctr_drbg_cmd_rc_o);
    $finish;
  end

  initial begin
    #2000;
    $display("timeout waiting for ack");
    $fatal(1);
  end
endmodule
EOF

set +e
fusesoc --cores-root /home/opentitan \
  run \
  --build-root "$TB_BUILD" \
  --target=sim \
  --tool=vcs \
  --setup \
  --build \
  --run \
  local:dv:csrng_prep_rc_tb:0.1 > "$TB_LOG" 2>&1
rc=$?
set -e

cat "$TB_LOG"

echo "HWE_BENCH_RESULTS_START"
if grep -q "rc check passed with value 0" "$TB_LOG"; then
  echo "TEST: csrng_prep_rc ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: csrng_prep_rc ... FAIL"
echo "HWE_BENCH_RESULTS_END"
if [[ $rc -eq 0 ]]; then
  exit 1
fi
exit "$rc"

