tb_script:
#!/bin/bash
cd /home/opentitan
set -uo pipefail

TEST_NAME="aes_keyexpand_prd_buffer"
TB_DIR=/home/opentitan/.tb_aes_keyexpand_prd
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/prim_util_pkg.sv" <<'EOF'
package prim_util_pkg;
  function automatic int unsigned vbits(input int unsigned value);
    int unsigned tmp;
    begin
      tmp = (value > 1) ? value - 1 : 1;
      vbits = 0;
      while (tmp > 0) begin
        tmp >>= 1;
        vbits++;
      end
    end
  endfunction
endpackage
EOF

cat > "$TB_DIR/aes_reg_pkg.sv" <<'EOF'
package aes_reg_pkg;
  parameter int unsigned NumRegsIv = 4;
  parameter bit AES_CTRL_SHADOWED_MANUAL_OPERATION_RESVAL = 1'b0;
  parameter int unsigned AES_CTRL_SHADOWED_PRNG_RESEED_RATE_RESVAL = 3'b001;
  parameter bit AES_CTRL_SHADOWED_SIDELOAD_RESVAL = 1'b0;
  parameter int unsigned AES_CTRL_SHADOWED_KEY_LEN_RESVAL = 3'b001;
  parameter int unsigned AES_CTRL_SHADOWED_MODE_RESVAL = 6'b00_0001;
  parameter int unsigned AES_CTRL_SHADOWED_OPERATION_RESVAL = 2'b01;
endpackage
EOF

cat > "$TB_DIR/prim_buf.sv" <<'EOF'
module prim_buf #(
  parameter int Width = 1
) (
  input [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  assign out_o = in_i;
endmodule
EOF

cat > "$TB_DIR/prim_sec_anchor_buf.sv" <<'EOF'
module prim_sec_anchor_buf #(
  parameter int Width = 1
) (
  input [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  assign out_o = in_i;
endmodule
EOF

cat > "$TB_DIR/prim_flop.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = 0
) (
  input clk_i,
  input rst_ni,
  input [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) q_o <= ResetValue;
    else q_o <= d_i;
  end
endmodule
EOF

cat > "$TB_DIR/prim_flop_en.sv" <<'EOF'
module prim_flop_en #(
  parameter int Width = 1,
  parameter bit EnSecBuf = 0,
  parameter logic [Width-1:0] ResetValue = 0
) (
  input clk_i,
  input rst_ni,
  input en_i,
  input [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  logic en;
  assign en = en_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) q_o <= ResetValue;
    else if (en) q_o <= d_i;
  end
endmodule
EOF

cat > "$TB_DIR/prim_xor2.sv" <<'EOF'
module prim_xor2 #(
  parameter int Width = 1
) (
  input [Width-1:0] in0_i,
  input [Width-1:0] in1_i,
  output logic [Width-1:0] out_o
);
  assign out_o = in0_i ^ in1_i;
endmodule
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
