  import aes_pkg::*;

  localparam int W = WidthPRDSBox;

  logic clk;
  logic rst_n;
  logic cfg_valid;
  ciph_op_e op;
  sp2v_e en;
  logic prd_we;
  sp2v_e out_req;
  sp2v_e out_ack;
  logic clear;
  logic [3:0] round;
  key_len_e key_len;
  logic [7:0][31:0] key_i [2];
  logic [7:0][31:0] key_o [2];
  logic [WidthPRDKey-1:0] prd_i;
  logic err_o;
  logic [4*W-1:0] expected_prd_bits;

  aes_key_expand #(
    .AES192Enable(1'b1),
    .SecMasking(1'b1),
    .SecSBoxImpl(SBoxImplDom)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
