        dut.in_prd[3][W-1:0],
        dut.in_prd[2][W-1:0],
        dut.in_prd[1][W-1:0],
        dut.in_prd[0][W-1:0]
      };
    end
  endfunction

  task automatic fail(input string msg);
    begin
      $fatal(1, "TBFAIL: %s", msg);
    end
  endtask

