    key_len = AES_128;
    key_i[0] = '{32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff,
                 32'h01234567, 32'h89abcdef, 32'hfedcba98, 32'h76543210};
    key_i[1] = '{default: 32'h0};
    prd_i = 32'h0000_0000;

    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    @(negedge clk);
    en = SP2V_HIGH;
    prd_we = 1'b1;
    clear = 1'b1;
    round = 4'd0;
    prd_i = 32'h1020_3040;

    @(posedge clk);
    #1;
    expected_prd_bits = prd_bits_now();
    if (expected_prd_bits !== 32'h1020_3040) begin
      fail($sformatf("unexpected initial sampled prd bits: %h", expected_prd_bits));
    end

    @(negedge clk);
    prd_we = 1'b0;
    clear = 1'b0;
    round = 4'd1;
    prd_i = 32'h5566_7788;

    repeat (3) begin
      @(posedge clk);
      #1;
      if (prd_bits_now() !== expected_prd_bits) begin
        fail($sformatf("prd bits changed without prd_we: exp=%h got=%h",
                       expected_prd_bits, prd_bits_now()));
      end
      @(negedge clk);
      prd_i = {prd_i[23:0], prd_i[31:24]} ^ 32'h0f0f_0f0f;
    end

    repeat (20) begin
      @(posedge clk);
      #1;
      if (out_req == SP2V_HIGH) begin
        $display("TBPASS: key_expand buffered PRD bits remained stable");
        $finish;
      end
    end

    fail("timeout waiting for out_req_o");
  end
endmodule
