      default: `uvm_fatal(`gfn, "Invalid 'if_mode'!")
    endcase
  endtask : agent_init

  virtual task body();
    i2c_item addr_item = new("addr_item");
    i2c_item data_item = new("data_item");
    bit [7:0] tx_data[3] = '{8'h11, 8'h22, 8'h33};
    bit [TL_DW-1:0] fmt_lvl;
    bit [TL_DW-1:0] hostidle;
