    initialization();
    `DV_CHECK_RANDOMIZE_FATAL(this)

    rw_bit = 1'b0;
    addr = target_addr0;
    get_timing_values();
    program_registers();

    addr_item.start = 1'b1;
    addr_item.stop  = 1'b0;
    addr_item.read  = 1'b0;
    addr_item.rcont = 1'b0;
    addr_item.nakok = 1'b0;
    addr_item.fbyte = {addr[6:0], 1'b0};
