      data_item.stop  = (i == 2);
      data_item.read  = 1'b0;
      data_item.rcont = 1'b0;
      data_item.nakok = 1'b0;
      data_item.fbyte = tx_data[i];
      program_format_flag(data_item, $sformatf("Programming write data %0d", i), 1);
    end

    `DV_WAIT(cfg.intr_vif.pins[Nak], "Expected the DUT to raise the nak interrupt.",
             cfg.long_spinwait_timeout_ns, `gfn)
    cfg.clk_rst_vif.wait_clks(1_000);

    csr_rd(.ptr(ral.host_fifo_status.fmtlvl), .value(fmt_lvl), .backdoor(1'b1));
    csr_rd(.ptr(ral.status.hostidle), .value(hostidle));
