module prim_fifo_sync #(
  parameter int unsigned Width = 16,
  parameter bit Pass = 1'b0,
  parameter int unsigned Depth = 2,
  parameter bit OutputZeroIfEmpty = 1'b1,
  parameter bit NeverClears = 1'b0,
  parameter bit Secure = 1'b0,
  localparam int unsigned DepthW = (Depth <= 1) ? 1 : $clog2(Depth + 1)
) (
  input clk_i,
  input rst_ni,
  input clr_i,
  input wvalid_i,
  output logic wready_o,
  input [Width-1:0] wdata_i,
  output logic rvalid_o,
  input rready_i,
  output logic [Width-1:0] rdata_o,
  output logic full_o,
  output logic [DepthW-1:0] depth_o,
  output logic err_o
);
  logic full_q;
  logic [Width-1:0] data_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      full_q <= 1'b0;
      data_q <= '0;
    end else if (clr_i) begin
      full_q <= 1'b0;
      data_q <= '0;
    end else begin
      unique case ({wvalid_i && wready_o, rvalid_o && rready_i})
        2'b10: begin
          full_q <= 1'b1;
          data_q <= wdata_i;
        end
        2'b01: begin
          full_q <= 1'b0;
        end
        2'b11: begin
          full_q <= 1'b1;
          data_q <= wdata_i;
        end
        default: ;
      endcase
    end
  end

  assign wready_o = !full_q || (rvalid_o && rready_i);
  assign rvalid_o = full_q;
  assign rdata_o = (OutputZeroIfEmpty && !full_q) ? '0 : data_q;
  assign full_o = full_q;
  assign depth_o = full_q ? DepthW'(1) : '0;
  assign err_o = 1'b0;

  logic unused_params;
  assign unused_params = Pass ^ NeverClears ^ Secure;
endmodule

module tb;
  import dm::*;

  localparam int DmiAddrWidth = $bits(dm::dmi_req_t) - $bits(dm::dtm_op_e) - 32;
  typedef logic [DmiAddrWidth-1:0] dmi_addr_t;

  localparam logic [31:0] DmcontrolDmactive = 32'h0000_0001;
  localparam logic [31:0] DmcontrolAllHartsel = (32'h3ff << 16) |
                                                (32'h3ff << 6)  |
                                                DmcontrolDmactive;

  logic clk = 1'b0;
  logic rst_ni = 1'b0;
  logic dmi_rst_ni = 1'b0;

  logic         dmi_req_valid;
  logic         dmi_req_ready;
  dm::dmi_req_t dmi_req;

  logic          dmi_resp_valid;
  logic          dmi_resp_ready;
  dm::dmi_resp_t dmi_resp;

  logic                       ndmreset;
  logic                       dmactive;
  dm::hartinfo_t [0:0]        hartinfo;
  logic [0:0]                 halted;
  logic [0:0]                 unavailable;
  logic [0:0]                 resumeack;
  logic [19:0]                hartsel;
  logic [0:0]                 haltreq;
  logic [0:0]                 resumereq;
  logic                       clear_resumeack;
  logic                       cmd_valid;
  dm::command_t               cmd;
  dm::cmderr_e                cmderror;
  logic                       cmderror_valid;
  logic                       cmdbusy;
  logic [dm::ProgBufSize-1:0][31:0] progbuf;
  logic [dm::DataCount-1:0][31:0]   data_o;
  logic [dm::DataCount-1:0][31:0]   data_i;
  logic [31:0]                sbaddress;
  logic [31:0]                sbaddress_i;
  logic                       sbaddress_write_valid;
  logic                       sbreadonaddr;
  logic                       sbautoincrement;
  logic [2:0]                 sbaccess;
  logic                       sbreadondata;
  logic [31:0]                sbdata_o;
  logic                       sbdata_read_valid;
  logic                       sbdata_write_valid;
  logic [31:0]                sbdata_i;
  logic                       sbdata_valid;
  logic                       sbbusy;
  logic                       sberror_valid;
  logic [2:0]                 sberror;
  string                      status_path;

  always #5 clk = ~clk;

  dm_csrs #(
    .NrHarts(1),
    .BusWidth(32),
    .SelectableHarts(1'b1)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_ni),
    .testmode_i(1'b0),
    .dmi_rst_ni(dmi_rst_ni),
    .dmi_req_valid_i(dmi_req_valid),
    .dmi_req_ready_o(dmi_req_ready),
    .dmi_req_i(dmi_req),
    .dmi_resp_valid_o(dmi_resp_valid),
    .dmi_resp_ready_i(dmi_resp_ready),
    .dmi_resp_o(dmi_resp),
    .ndmreset_o(ndmreset),
    .dmactive_o(dmactive),
    .hartinfo_i(hartinfo),
    .halted_i(halted),
    .unavailable_i(unavailable),
    .resumeack_i(resumeack),
    .hartsel_o(hartsel),
    .haltreq_o(haltreq),
    .resumereq_o(resumereq),
    .clear_resumeack_o(clear_resumeack),
    .cmd_valid_o(cmd_valid),
    .cmd_o(cmd),
    .cmderror_valid_i(cmderror_valid),
    .cmderror_i(cmderror),
    .cmdbusy_i(cmdbusy),
    .progbuf_o(progbuf),
    .data_o(data_o),
    .data_i(data_i),
    .data_valid_i(1'b0),
    .sbaddress_o(sbaddress),
    .sbaddress_i(sbaddress_i),
    .sbaddress_write_valid_o(sbaddress_write_valid),
    .sbreadonaddr_o(sbreadonaddr),
    .sbautoincrement_o(sbautoincrement),
    .sbaccess_o(sbaccess),
    .sbreadondata_o(sbreadondata),
    .sbdata_o(sbdata_o),
    .sbdata_read_valid_o(sbdata_read_valid),
    .sbdata_write_valid_o(sbdata_write_valid),
    .sbdata_i(sbdata_i),
    .sbdata_valid_i(sbdata_valid),
    .sbbusy_i(sbbusy),
    .sberror_valid_i(sberror_valid),
    .sberror_i(sberror)
  );

  task automatic dmi_xfer(input dm::dtm_op_e op,
                          input dmi_addr_t addr,
                          input logic [31:0] data,
                          output logic [31:0] resp_data,
                          output logic [1:0] resp_status);
    begin
      @(negedge clk);
      dmi_req.addr = addr;
      dmi_req.op = op;
      dmi_req.data = data;
      dmi_req_valid = 1'b1;

      do @(posedge clk); while (!dmi_req_ready);

      @(negedge clk);
      dmi_req_valid = 1'b0;
      dmi_req = '0;

      do @(posedge clk); while (!dmi_resp_valid);
      resp_data = dmi_resp.data;
      resp_status = dmi_resp.resp;
    end
  endtask

  task automatic dmi_write(input dmi_addr_t addr, input logic [31:0] data);
    logic [31:0] unused_data;
    logic [1:0] resp_status;
    begin
      dmi_xfer(dm::DTM_WRITE, addr, data, unused_data, resp_status);
      if (resp_status != dm::DTM_SUCCESS) begin
        record_and_finish("FAIL",
                          $sformatf("DMI write to 0x%0h failed with resp=%0d",
                                    addr,
                                    resp_status));
      end
    end
  endtask

  task automatic dmi_read(input dmi_addr_t addr, output logic [31:0] data);
    logic [1:0] resp_status;
    begin
      dmi_xfer(dm::DTM_READ, addr, '0, data, resp_status);
      if (resp_status != dm::DTM_SUCCESS) begin
        record_and_finish("FAIL",
                          $sformatf("DMI read from 0x%0h failed with resp=%0d",
                                    addr,
                                    resp_status));
      end
    end
  endtask

  task automatic record_and_finish(input string status, input string message);
    integer fd;
    begin
      if (status_path != "") begin
