    begin
      logic [31:0] readback;
      dmi_read(dmi_addr_t'(dm::DMControl), readback);
      if (readback != DmcontrolDmactive) begin
        record_and_finish("FAIL",
                          $sformatf("Unexpected dmcontrol after dmactive enable: got 0x%08x",
