tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="adc_ctrl_status_irq"
TB_ROOT="/home/opentitan/.tb_adc_ctrl_status_irq"
OVERLAY_ROOT="${TB_ROOT}/overlay"
OT_ROOT="${OVERLAY_ROOT}/opentitan"
SCRATCH_ROOT="${TB_ROOT}/scratch"
RESULT="FAIL"

emit_result() {
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${RESULT}"
  echo "HWE_BENCH_RESULTS_END"
}

trap emit_result EXIT

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

python - <<'PY'
from pathlib import Path
import os
import shutil

src = Path("/home/opentitan")
dst = Path("/home/opentitan/.tb_adc_ctrl_status_irq/overlay/opentitan")

dst.mkdir(parents=True, exist_ok=True)

for item in src.iterdir():
    if item.name == ".tb_adc_ctrl_status_irq":
        continue
    if item.name == "hw":
        continue
    target = dst / item.name
    if target.exists() or target.is_symlink():
        if target.is_dir() and not target.is_symlink():
            shutil.rmtree(target)
        else:
            target.unlink()
    os.symlink(item, target, target_is_directory=item.is_dir())

(dst / "hw").mkdir(parents=True, exist_ok=True)

for item in (src / "hw").iterdir():
    target = dst / "hw" / item.name
    if item.name == "ip":
        target.mkdir(parents=True, exist_ok=True)
        for ip_item in item.iterdir():
            ip_target = target / ip_item.name
            if ip_item.name == "adc_ctrl":
                shutil.copytree(ip_item, ip_target, symlinks=True)
            else:
                os.symlink(ip_item, ip_target, target_is_directory=ip_item.is_dir())
    else:
        if target.exists() or target.is_symlink():
            if target.is_dir() and not target.is_symlink():
                shutil.rmtree(target)
            else:
                target.unlink()
        os.symlink(item, target, target_is_directory=item.is_dir())
PY

TB_FILE="${OT_ROOT}/hw/ip/adc_ctrl/dv/tb.sv"
SEQ_FILE="${OT_ROOT}/hw/ip/adc_ctrl/dv/env/seq_lib/adc_ctrl_smoke_vseq.sv"
SIM_CFG="${OT_ROOT}/hw/ip/adc_ctrl/dv/adc_ctrl_sim_cfg.hjson"

python - <<'PY'
from pathlib import Path

tb = Path("/home/opentitan/.tb_adc_ctrl_status_irq/overlay/opentitan/hw/ip/adc_ctrl/dv/tb.sv")
text = tb.read_text(encoding="utf-8")

old_decl = "  wire [NUM_MAX_INTERRUPTS-1:0] interrupts;\n"
new_decl = """  wire [NUM_MAX_INTERRUPTS-1:0] interrupts;\n  tri0 intr_match_done_o;\n  tri0 intr_match_pending_o;\n  wire coll_irq;\n"""

old_dut = """  adc_ctrl dut (\n    .clk_i             (clk),\n    .rst_ni            (rst_n),\n    .clk_aon_i         (clk_aon),\n    .rst_aon_ni        (rst_aon_n),\n    .tl_i              (tl_if.h2d),\n    .tl_o              (tl_if.d2h),\n    .alert_rx_i        (alert_rx),\n    .alert_tx_o        (alert_tx),\n    .adc_o             (adc_o),\n    .adc_i             (adc_i),\n    .intr_match_done_o (interrupts[ADC_CTRL_INTERRUPT_INDEX]),\n    .wkup_req_o        (wakeup_req)\n  );\n"""
new_dut = """  adc_ctrl dut (\n    .clk_i      (clk),\n    .rst_ni     (rst_n),\n    .clk_aon_i  (clk_aon),\n    .rst_aon_ni (rst_aon_n),\n    .tl_i       (tl_if.h2d),\n    .tl_o       (tl_if.d2h),\n    .alert_rx_i (alert_rx),\n    .alert_tx_o (alert_tx),\n    .adc_o      (adc_o),\n    .adc_i      (adc_i),\n    .wkup_req_o (wakeup_req),\n    .*\n  );\n"""
anchor = "  // Push pull agents\n"
insert = """  assign coll_irq = intr_match_done_o | intr_match_pending_o;\n  assign interrupts = ({{(NUM_MAX_INTERRUPTS - 1){1'b0}}, coll_irq} << ADC_CTRL_INTERRUPT_INDEX);\n\n"""

if old_decl in text:
    text = text.replace(old_decl, new_decl, 1)
if old_dut in text:
    text = text.replace(old_dut, new_dut, 1)
if insert not in text:
    if anchor not in text:
        raise SystemExit("Failed to locate insertion point in adc_ctrl dv tb")
    text = text.replace(anchor, insert + anchor, 1)

tb.write_text(text, encoding="utf-8")
PY

if ! grep -q "class adc_ctrl_status_irq_vseq" "${SEQ_FILE}"; then
  cat >> "${SEQ_FILE}" <<'EOF'

class adc_ctrl_status_irq_vseq extends adc_ctrl_base_vseq;

  `uvm_object_utils(adc_ctrl_status_irq_vseq)
  `uvm_object_new

  virtual task pre_start();
    cfg.en_scb = 0;
    cfg.en_cov = 0;
    super.pre_start();
    cfg.testmode = AdcCtrlTestmodeOneShot;
    cfg.adc_intr_ctl = '0;
    cfg.adc_wakeup_ctl = '0;
  endtask

  task body();
    uvm_reg_addr_t intr_state_addr;
    uvm_reg_data_t tl_data;
    uvm_reg_data_t rdata;
    const uvm_reg_data_t coll_intr = 'h1;
    const uvm_reg_data_t one_shot_intr = 1 << ral.adc_intr_status.oneshot.get_lsb_pos();

    csr_wr(ral.adc_en_ctl, 'h0);

    cfg.adc_intr_ctl = one_shot_intr;
    csr_wr(ral.adc_intr_ctl, cfg.adc_intr_ctl);
    csr_wr(ral.intr_enable, coll_intr);

    ral.adc_pd_ctl.pwrup_time.set(cfg.pwrup_time);
    ral.adc_pd_ctl.wakeup_time.set(cfg.wakeup_time);
    csr_wr(ral.adc_pd_ctl, ral.adc_pd_ctl.get());

    csr_wr(ral.adc_intr_status, '1);
    csr_rd_check(.ptr(ral.adc_intr_status), .compare_value(0),
                 .err_msg(called_from(`__FILE__, `__LINE__)));

    ral.adc_en_ctl.adc_enable.set(1);
    ral.adc_en_ctl.oneshot_mode.set(1);
    csr_wr(ral.adc_en_ctl, ral.adc_en_ctl.get());

    wait_all_rx();
    #20us;

    csr_rd_check(.ptr(ral.adc_intr_status), .compare_value(one_shot_intr),
                 .compare_mask(one_shot_intr), .err_msg(called_from(`__FILE__, `__LINE__)));
    csr_rd(ral.adc_chn_val[0], rdata);
    csr_rd(ral.adc_chn_val[1], rdata);

    intr_state_addr = ral.intr_state.get_address();
    tl_data = coll_intr;
    tl_access(.addr(intr_state_addr), .write(1'b1), .data(tl_data));
    cfg.clk_rst_vif.wait_clks(5);

    csr_rd_check(.ptr(ral.intr_state), .compare_value(coll_intr),
                 .compare_mask(coll_intr), .err_msg(called_from(`__FILE__, `__LINE__)));
    `DV_CHECK_EQ(cfg.intr_vif.sample_pin(ADC_CTRL_INTERRUPT_INDEX), 1'b1)

    csr_wr(ral.adc_intr_status, one_shot_intr);
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.adc_intr_status), .compare_value(0),
                 .compare_mask(one_shot_intr), .err_msg(called_from(`__FILE__, `__LINE__)));
    `DV_CHECK_EQ(cfg.intr_vif.sample_pin(ADC_CTRL_INTERRUPT_INDEX), 1'b0)

    csr_wr(ral.adc_en_ctl, 'h0);
    cfg.clk_rst_vif.wait_clks(10);
  endtask

endclass : adc_ctrl_status_irq_vseq
EOF
fi

python - <<'PY'
from pathlib import Path

sim_cfg = Path("/home/opentitan/.tb_adc_ctrl_status_irq/overlay/opentitan/hw/ip/adc_ctrl/dv/adc_ctrl_sim_cfg.hjson")
text = sim_cfg.read_text(encoding="utf-8")

test_block = """    {\n      name: adc_ctrl_status_irq\n      uvm_test_seq: adc_ctrl_status_irq_vseq\n    }\n\n"""
anchor = "  // List of regressions."
insert_before = "\n  ]\n\n" + anchor

if "name: adc_ctrl_status_irq" not in text:
    if insert_before not in text:
        raise SystemExit("Failed to locate tests list in adc_ctrl_sim_cfg.hjson")
    text = text.replace(insert_before, "\n" + test_block + "  ]\n\n" + anchor, 1)

sim_cfg.write_text(text, encoding="utf-8")
PY

pushd "${OT_ROOT}" >/dev/null
set +e
timeout 1800 ./util/dvsim/dvsim.py "${SIM_CFG}" \
  -i "${TEST_NAME}" \
  -t vcs \
  --fixed-seed 1 \
  --build-seed 1 \
  --purge \
  --branch "tb_${TEST_NAME}" \
  -sr "${SCRATCH_ROOT}"
rc=$?
set -e
popd >/dev/null

if [ "${rc}" -eq 0 ]; then
  RESULT="PASS"
fi

exit "${rc}"

