tb_script:
#!/bin/bash
cd /home/opentitan
set -euo pipefail

TB_NAME="i2c_clockpulse_predict"
TB_DIR="/home/opentitan/.tb_${TB_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TB_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import i2c_pkg::*;

  localparam int unsigned TrCycles = 1;
  localparam int unsigned ThighCycles = 4;
  localparam int unsigned ObserveDelayCycles = 3;

  logic clk_i;
  logic rst_ni;
  logic scl_i;
  logic sda_i;
  logic scl_o;
  logic sda_o;

  logic host_enable_i;
  logic target_enable_i;

  logic fmt_fifo_rvalid_i;
  logic fmt_fifo_wvalid_i;
  logic [6:0] fmt_fifo_depth_i;
  logic fmt_fifo_rready_o;
  logic [7:0] fmt_byte_i;
  logic fmt_flag_start_before_i;
  logic fmt_flag_stop_after_i;
  logic fmt_flag_read_bytes_i;
  logic fmt_flag_read_continue_i;
  logic fmt_flag_nak_ok_i;

  logic       rx_fifo_wvalid_o;
  logic [7:0] rx_fifo_wdata_o;

  logic       tx_fifo_rvalid_i;
  logic       tx_fifo_wvalid_i;
  logic [6:0] tx_fifo_depth_i;
  logic       tx_fifo_rready_o;
  logic [7:0] tx_fifo_rdata_i;

  logic        acq_fifo_wvalid_o;
  logic [10:0] acq_fifo_wdata_o;
  logic [6:0]  acq_fifo_depth_i;
  logic        acq_fifo_wready_o;
  logic [10:0] acq_fifo_rdata_i;

  logic host_idle_o;
  logic target_idle_o;

  logic [15:0] thigh_i;
  logic [15:0] tlow_i;
  logic [15:0] t_r_i;
  logic [15:0] t_f_i;
  logic [15:0] thd_sta_i;
  logic [15:0] tsu_sta_i;
  logic [15:0] tsu_sto_i;
  logic [15:0] tsu_dat_i;
  logic [15:0] thd_dat_i;
  logic [15:0] t_buf_i;
  logic [30:0] stretch_timeout_i;
  logic        timeout_enable_i;
  logic [31:0] host_timeout_i;
  logic [30:0] nack_timeout_i;
  logic        nack_timeout_en_i;

  logic [6:0] target_address0_i;
  logic [6:0] target_mask0_i;
  logic [6:0] target_address1_i;
  logic [6:0] target_mask1_i;

  logic event_target_nack_o;
  logic event_nak_o;
  logic event_scl_interference_o;
  logic event_sda_interference_o;
  logic event_stretch_timeout_o;
  logic event_sda_unstable_o;
  logic event_cmd_complete_o;
  logic event_tx_stretch_o;
  logic event_unexp_stop_o;
  logic event_host_timeout_o;

  int observe_ctr;
  int pulse_cycles;
  bit started;
  bit finished;

  i2c_fsm dut (
    .clk_i,
    .rst_ni,
    .scl_i,
    .scl_o,
    .sda_i,
    .sda_o,
    .host_enable_i,
    .target_enable_i,
    .fmt_fifo_rvalid_i,
    .fmt_fifo_wvalid_i,
    .fmt_fifo_depth_i,
    .fmt_fifo_rready_o,
    .fmt_byte_i,
    .fmt_flag_start_before_i,
    .fmt_flag_stop_after_i,
    .fmt_flag_read_bytes_i,
    .fmt_flag_read_continue_i,
    .fmt_flag_nak_ok_i,
    .rx_fifo_wvalid_o,
    .rx_fifo_wdata_o,
    .tx_fifo_rvalid_i,
    .tx_fifo_wvalid_i,
    .tx_fifo_depth_i,
    .tx_fifo_rready_o,
    .tx_fifo_rdata_i,
    .acq_fifo_wvalid_o,
    .acq_fifo_wdata_o,
    .acq_fifo_depth_i,
    .acq_fifo_wready_o,
    .acq_fifo_rdata_i,
    .host_idle_o,
    .target_idle_o,
    .thigh_i,
    .tlow_i,
    .t_r_i,
    .t_f_i,
    .thd_sta_i,
    .tsu_sta_i,
    .tsu_sto_i,
    .tsu_dat_i,
    .thd_dat_i,
    .t_buf_i,
    .stretch_timeout_i,
    .timeout_enable_i,
    .host_timeout_i,
    .nack_timeout_i,
    .nack_timeout_en_i,
    .target_address0_i,
    .target_mask0_i,
    .target_address1_i,
    .target_mask1_i,
    .event_target_nack_o,
    .event_nak_o,
    .event_scl_interference_o,
    .event_sda_interference_o,
    .event_stretch_timeout_o,
    .event_sda_unstable_o,
    .event_cmd_complete_o,
    .event_tx_stretch_o,
    .event_unexp_stop_o,
    .event_host_timeout_o
  );

  always #5 clk_i = ~clk_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      observe_ctr <= 0;
      scl_i <= 1'b0;
    end else if (!started) begin
      observe_ctr <= 0;
      scl_i <= 1'b0;
    end else if (observe_ctr < ObserveDelayCycles) begin
      observe_ctr <= observe_ctr + 1;
      scl_i <= 1'b0;
    end else begin
      scl_i <= 1'b1;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      sda_i <= 1'b1;
    end else begin
      sda_i <= 1'b1;
    end
  end

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      pulse_cycles <= 0;
      finished <= 1'b0;
    end else if (!finished) begin
      if (dut.state_q == dut.ClockPulse) begin
        pulse_cycles <= pulse_cycles + 1;
      end else if (started) begin
        finished <= 1'b1;
        if (pulse_cycles != (TrCycles + ThighCycles)) begin
          $display("TB_RESULT: FAIL ClockPulse mismatch: measured=%0d expected=%0d",
                   pulse_cycles, TrCycles + ThighCycles);
          $finish;
        end
        $display("TB_RESULT: PASS clockpulse_cycles=%0d expected_no_stretch=%0d", pulse_cycles,
                 TrCycles + ThighCycles);
        $finish;
      end
    end
  end

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    started = 1'b0;

    host_enable_i = 1'b1;
    target_enable_i = 1'b0;

    fmt_fifo_rvalid_i = 1'b0;
    fmt_fifo_wvalid_i = 1'b0;
    fmt_fifo_depth_i = '0;
    fmt_byte_i = 8'hA5;
    fmt_flag_start_before_i = 1'b0;
    fmt_flag_stop_after_i = 1'b0;
    fmt_flag_read_bytes_i = 1'b0;
    fmt_flag_read_continue_i = 1'b0;
    fmt_flag_nak_ok_i = 1'b1;

    tx_fifo_rvalid_i = 1'b0;
    tx_fifo_wvalid_i = 1'b0;
    tx_fifo_depth_i = '0;
    tx_fifo_rdata_i = '0;

    acq_fifo_depth_i = '0;
    acq_fifo_rdata_i = '0;

    thigh_i = ThighCycles;
    tlow_i = 16'd8;
    t_r_i = TrCycles;
    t_f_i = 16'd1;
    thd_sta_i = 16'd4;
    tsu_sta_i = 16'd4;
    tsu_sto_i = 16'd4;
    tsu_dat_i = 16'd1;
    thd_dat_i = 16'd1;
    t_buf_i = 16'd4;
    stretch_timeout_i = 31'd100;
    timeout_enable_i = 1'b0;
    host_timeout_i = 32'd100;
    nack_timeout_i = 31'd100;
    nack_timeout_en_i = 1'b0;

    target_address0_i = '0;
    target_mask0_i = '0;
    target_address1_i = '0;
    target_mask1_i = '0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    @(negedge clk_i);
    force dut.state_q = dut.ClockPulse;
    force dut.tcount_q = TrCycles + ThighCycles;
    force dut.stretch_idle_cnt = '0;
    force dut.scl_q = 1'b0;
    force dut.sda_q = 1'b1;
    started = 1'b1;
    @(posedge clk_i);
    release dut.state_q;
    release dut.tcount_q;
    release dut.stretch_idle_cnt;
    release dut.scl_q;
    release dut.sda_q;
  end

  initial begin
    #1000;
    $display("TB_RESULT: FAIL Timed out waiting for ClockPulse measurement");
    $finish;
  end
endmodule
EOF

if ! vcs -full64 -sverilog \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  /home/opentitan/hw/ip/prim/rtl/prim_assert.sv \
  /home/opentitan/hw/ip/i2c/rtl/i2c_pkg.sv \
  /home/opentitan/hw/ip/i2c/rtl/i2c_fsm.sv \
  "${TB_DIR}/tb.sv" \
  -top tb \
  -o "${TB_DIR}/simv" \
  -l "${COMPILE_LOG}"; then
  emit_result "FAIL"
  exit 1
fi

sim_rc=0
"${TB_DIR}/simv" -l "${RUN_LOG}" || sim_rc=$?

if grep -q "TB_RESULT: PASS" "${RUN_LOG}"; then
  emit_result "PASS"
  exit 0
fi

if grep -q "TB_RESULT: FAIL" "${RUN_LOG}" || [ "${sim_rc}" -ne 0 ]; then
  emit_result "FAIL"
  exit 1
fi

emit_result "FAIL"
exit 1

