#!/bin/bash
cd /home/opentitan || exit 1
set +e

echo "HWE_BENCH_RESULTS_START"
cleanup() {
  echo "HWE_BENCH_RESULTS_END"
}
trap cleanup EXIT

python - <<'PY'
from pathlib import Path

vseq_path = Path("hw/ip/i2c/dv/env/seq_lib/i2c_acq_fifo_depth_vseq.sv")
vseq_path.write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class i2c_acq_fifo_depth_vseq extends i2c_target_smoke_vseq;
  `uvm_object_utils(i2c_acq_fifo_depth_vseq)
  `uvm_object_new

  localparam int unsigned StopTimeoutNs = 20_000_000;
  localparam int unsigned PayloadBytes = 80;

  virtual task pre_start();
    super.pre_start();
    cfg.wr_pct = 1;
    cfg.rd_pct = 0;
    cfg.rs_pct = 0;
    cfg.min_data = PayloadBytes;
    cfg.max_data = PayloadBytes;
    cfg.spinwait_timeout_ns = StopTimeoutNs;
    cfg.long_spinwait_timeout_ns = StopTimeoutNs;
  endtask

  virtual task body();
    i2c_target_base_seq m_i2c_host_seq;
    i2c_item txn_q[$];

    initialization();
    get_timing_values();
    program_registers();
    cfg.m_i2c_agent_cfg.got_stop = 0;

    `uvm_create_obj(i2c_target_base_seq, m_i2c_host_seq)
    create_txn(txn_q);
    fetch_txn(txn_q, m_i2c_host_seq.req_q);

    fork
      begin
        m_i2c_host_seq.start(p_sequencer.i2c_sequencer_h);
      end
      begin
        `DV_WAIT(cfg.m_i2c_agent_cfg.got_stop,
                 "got_stop wait timeout occurred!",
                 StopTimeoutNs,
                 "i2c_acq_fifo_depth_vseq")
      end
    join

    process_acq();
  endtask
endclass
""",
    encoding="utf-8",
)

vseq_list = Path("hw/ip/i2c/dv/env/seq_lib/i2c_vseq_list.sv")
include_line = '`include "i2c_acq_fifo_depth_vseq.sv"\n'
vseq_list_text = vseq_list.read_text(encoding="utf-8")
if include_line not in vseq_list_text:
    vseq_list.write_text(vseq_list_text + include_line, encoding="utf-8")

core = Path("hw/ip/i2c/dv/env/i2c_env.core")
core_line = "      - seq_lib/i2c_acq_fifo_depth_vseq.sv: {is_include_file: true}\n"
core_text = core.read_text(encoding="utf-8")
if core_line not in core_text:
    core_marker = "      - seq_lib/i2c_glitch_vseq.sv: {is_include_file: true}\n"
    if core_marker not in core_text:
        raise SystemExit("Failed to locate i2c_env.core insertion point")
    core.write_text(core_text.replace(core_marker, core_marker + core_line), encoding="utf-8")

sim_cfg = Path("hw/ip/i2c/dv/i2c_sim_cfg.hjson")
sim_cfg_text = sim_cfg.read_text(encoding="utf-8")
test_block = """    {
      name: i2c_acq_fifo_depth
      uvm_test_seq: i2c_acq_fifo_depth_vseq
      run_opts: ["+i2c_agent_mode=Host", "+test_timeout_ns=50_000_000"]
      reseed: 1
    }
"""
if "name: i2c_acq_fifo_depth\n" not in sim_cfg_text:
    sim_cfg_marker = "  ]\n\n  // List of regressions.\n"
    if sim_cfg_marker not in sim_cfg_text:
        raise SystemExit("Failed to locate i2c_sim_cfg.hjson insertion point")
    sim_cfg.write_text(
        sim_cfg_text.replace(sim_cfg_marker, test_block + "  ]\n\n  // List of regressions.\n"),
        encoding="utf-8",
    )
PY
prep_rc=$?

if [ "$prep_rc" -ne 0 ]; then
  echo "TEST: i2c_acq_fifo_depth ... FAIL"
  exit "$prep_rc"
fi

rm -rf /home/opentitan/scratch/HEAD/i2c-sim-vcs
./util/dvsim/dvsim.py \
  hw/ip/i2c/dv/i2c_sim_cfg.hjson \
  -i i2c_acq_fifo_depth \
  -t vcs \
  --fixed-seed 1 \
  --build-seed 1 \
  --reseed 1
rc=$?

if [ "$rc" -eq 0 ]; then
  echo "TEST: i2c_acq_fifo_depth ... PASS"
else
  echo "TEST: i2c_acq_fifo_depth ... FAIL"
fi

exit "$rc"

