tb_script:
#!/bin/bash
cd /home/opentitan || exit 1

set +e
set -o pipefail

TEST_NAME="spid_status_continuous_polling"
SCRATCH_ROOT="/home/opentitan/.tb_spid_status_rotate"
RUN_LOG="${SCRATCH_ROOT}/dvsim.log"
TB_PATH="hw/ip/spi_device/pre_dv/tb/spid_status_tb.sv"

mkdir -p "${SCRATCH_ROOT}"

cat > "${TB_PATH}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

module spid_status_tb;

  import spi_device_pkg::*;
  import spid_common::*;

  localparam time ClkPeriod = 10000;
  localparam time SckPeriod = 14000;
  localparam logic [23:0] ForcedStatus = 24'hBE_AA_28;

  wire clk, rst_n;
  clk_rst_if main_clk (
    .clk,
    .rst_n
  );

  wire sck, sck_rst_n;
  clk_rst_if sck_clk (
    .clk   (sck),
    .rst_n (sck_rst_n)
  );

  spi_if sif(sck);

  virtual spi_if.tb tb_sif = sif.tb;

  logic [3:0] dut_sd_en, dut_sd;

  for (genvar i = 0; i < 4; i++) begin : g_dut_sif
    assign sif.sd_out[i] = dut_sd_en[i] ? dut_sd[i] : 1'bz;
  end

  wire gated_sck = (~sif.csb) ? sck : 1'b0;
  wire gated_sck_inverted = ~gated_sck;
  logic rst_spi_n;
  assign rst_spi_n = sck_rst_n && ~sif.csb;

  sel_datapath_e dut_sel_dp;
  logic [CmdInfoIdxW-1:0] cmd_info_idx;
  cmd_info_t cmd_info;

  logic sys_status_we;
  logic [23:0] sys_status_in, sys_status_out;
  logic busy_set;
  spi_mode_e spi_mode;

  logic s2p_valid;
  spi_byte_t s2p_data;

  logic p2s_valid, p2s_sent;
  logic [7:0] p2s_data;
  io_mode_e dut_iomode, s2p_iomode;
  logic sck_we_set, sck_we_clr;

  task automatic read_status_bytes(
    input  spi_data_t opcode,
    input  int unsigned count,
    output spi_queue_t response
  );
    spi_fifo_t txn[$];

    txn.push_back('{data: opcode, dir: DirIn,  mode: IoSingle});
    for (int unsigned i = 0; i < count; i++) begin
      txn.push_back('{data: '0, dir: DirOut, mode: IoNone});
    end

    response = {};
    spi_transaction(tb_sif, txn, response);
  endtask

  task automatic check_repeated_status(
    input spi_data_t opcode,
    input spi_data_t expected
  );
    spi_queue_t response;
    read_status_bytes(opcode, 3, response);

    if (response.size() != 3) begin
      $error("opcode 0x%0h returned %0d bytes", opcode, response.size());
      $fatal(1);
    end

    foreach (response[i]) begin
      if (response[i] !== expected) begin
        $error("opcode 0x%0h byte[%0d] expected 0x%0h got 0x%0h",
               opcode, i, expected, response[i]);
        $fatal(1);
      end
    end

    $display("opcode 0x%0h returned repeated byte 0x%0h", opcode, expected);
  endtask

  initial begin
    sck_clk.set_period_ps(SckPeriod);
    sck_clk.set_active();
    main_clk.set_period_ps(ClkPeriod);
    main_clk.set_active();

    sif.csb = 1'b1;
    sif.sd_in = 'z;
    busy_set = 1'b0;
    sys_status_we = 1'b0;
    sys_status_in = '0;
    spi_mode = FlashMode;

    sck_clk.apply_reset();
    main_clk.apply_reset();

    fork
      begin
        #20us;
        $display("TEST TIMED OUT!!");
        $fatal(1);
      end
      begin
        repeat (10) @(sck_clk.cbn);
        force dut.sck_status_staged = ForcedStatus;
        force dut.sck_status_committed = ForcedStatus;

        check_repeated_status(8'h05, 8'h28);
        repeat (10) @(sck_clk.cbn);
        check_repeated_status(8'h35, 8'hAA);
        repeat (10) @(sck_clk.cbn);
        check_repeated_status(8'h15, 8'hBE);

        $display("TEST PASSED CHECKS");
        $finish;
      end
    join_any
  end

  spid_status dut (
    .clk_i  (gated_sck),
    .rst_ni (rst_spi_n),
    .clk_out_i (gated_sck_inverted),
    .clk_csb_i (sif.csb),
    .sys_clk_i  (clk),
    .sys_rst_ni (rst_n),
    .sys_csb_deasserted_pulse_i (1'b0),
    .sys_status_we_i (sys_status_we),
    .sys_status_i    (sys_status_in),
    .sys_status_o    (sys_status_out),
    .sel_dp_i       (dut_sel_dp),
    .cmd_info_i     (cmd_info),
    .cmd_info_idx_i (cmd_info_idx),
    .outclk_p2s_valid_o (p2s_valid),
    .outclk_p2s_byte_o  (p2s_data),
    .outclk_p2s_sent_i  (p2s_sent),
    .io_mode_o   (dut_iomode),
    .inclk_busy_set_i  (busy_set),
    .inclk_we_set_i (sck_we_set),
    .inclk_we_clr_i (sck_we_clr),
    .csb_busy_broadcast_o ()
  );

  spi_cmdparse cmdparse (
    .clk_i  (gated_sck),
    .rst_ni (rst_spi_n),
    .data_valid_i (s2p_valid),
    .data_i       (s2p_data),
    .spi_mode_i   (spi_mode),
    .cmd_info_i   (spid_common::CmdInfo),
    .io_mode_o    (s2p_iomode),
    .sel_dp_o       (dut_sel_dp),
    .cmd_info_o     (cmd_info),
    .cmd_info_idx_o (cmd_info_idx),
    .cfg_intercept_en_status_i (1'b1),
    .cfg_intercept_en_jedec_i  (1'b1),
    .cfg_intercept_en_sfdp_i   (1'b1),
    .intercept_status_o (),
    .intercept_jedec_o  (),
    .intercept_sfdp_o   (),
    .cmd_config_req_o (),
    .cmd_config_idx_o ()
  );

  assign sck_we_set = (dut_sel_dp == DpWrEn);
  assign sck_we_clr = (dut_sel_dp == DpWrDi);

  spi_s2p s2p (
    .clk_i  (gated_sck),
    .rst_ni (rst_spi_n),
    .s_i    (sif.sd_in),
    .data_valid_o (s2p_valid),
    .data_o       (s2p_data),
    .order_i      (1'b0),
    .io_mode_i    (s2p_iomode)
  );

  spi_p2s p2s (
    .clk_i  (gated_sck_inverted),
    .rst_ni (rst_spi_n),
    .data_valid_i (p2s_valid),
    .data_i       (p2s_data),
    .data_sent_o  (p2s_sent),
    .csb_i        (sif.csb),
    .s_en_o       (dut_sd_en),
    .s_o          (dut_sd),
    .cpha_i       (1'b0),
    .order_i      (1'b0),
    .io_mode_i    (dut_iomode)
  );

endmodule : spid_status_tb
EOF

rm -rf "${SCRATCH_ROOT}"
mkdir -p "${SCRATCH_ROOT}"
export PATH="/tools/riscv/bin:/tools/verible/bin:${PATH}"

timeout 1800 ./util/dvsim/dvsim.py hw/ip/spi_device/pre_dv/spid_status_sim_cfg.hjson \
  -i spid_status_smoke \
  -t vcs \
  --fixed-seed 1 \
  --build-seed 1 \
  --scratch-root "${SCRATCH_ROOT}" 2>&1 | tee "${RUN_LOG}"
rc=$?

if [ "${rc}" -eq 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
else
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
fi

exit "${rc}"

