    .cfg_use_diff_rcvr_i(cfg_use_diff_rcvr_i),
    .cfg_pinflip_i(cfg_pinflip_i),
    .diff_rx_ok_i(diff_rx_ok_i),
    .usb_d_i(usb_d_i),
    .usb_dp_i(usb_dp_i),
    .usb_dn_i(usb_dn_i),
    .tx_en_i(tx_en_i),
    .bit_strobe_o(bit_strobe_o),
    .pkt_start_o(pkt_start_o),
    .pkt_end_o(pkt_end_o),
    .pid_o(pid_o),
    .addr_o(addr_o),
    .endp_o(endp_o),
    .frame_num_o(frame_num_o),
    .rx_data_put_o(rx_data_put_o),
    .rx_data_o(rx_data_o),
    .valid_packet_o(valid_packet_o),
    .rx_idle_det_o(rx_idle_det_o),
    .rx_j_det_o(rx_j_det_o),
    .crc_error_o(crc_error_o),
    .pid_error_o(pid_error_o),
    .bitstuff_error_o(bitstuff_error_o)
  );

  always #10 clk_i = ~clk_i;

  task automatic drive_line(input bit is_j);
    begin
      usb_d_i  = is_j;
      usb_dp_i = is_j;
      usb_dn_i = ~is_j;
      repeat (ClocksPerBit) @(posedge clk_i);
    end
  endtask

  task automatic drive_sync();
    begin
      drive_line(LineK);
      drive_line(LineJ);
      drive_line(LineK);
      drive_line(LineJ);
      drive_line(LineK);
      drive_line(LineK);
    end
  endtask

  task automatic drive_pre_pid();
    bit current_line;
    bit [7:0] pid_bits;
    int idx;
    begin
      current_line = LineK;
      pid_bits = 8'b00111100;
      for (idx = 0; idx < 8; idx++) begin
        if (pid_bits[idx] == 1'b0) begin
          current_line = ~current_line;
        end
        drive_line(current_line);
      end
    end
  endtask

  int pkt_end_seen;
  int bitstuff_seen;

  always @(posedge clk_i) begin
    if (pkt_end_o) begin
      pkt_end_seen <= pkt_end_seen + 1;
    end
    if (bitstuff_error_o) begin
      bitstuff_seen <= bitstuff_seen + 1;
    end
  end

  initial begin
    clk_i = 0;
    rst_ni = 0;
    link_reset_i = 0;
    cfg_eop_single_bit_i = 0;
    cfg_use_diff_rcvr_i = 1;
    cfg_pinflip_i = 0;
    diff_rx_ok_i = 1;
    tx_en_i = 0;
    usb_d_i = LineJ;
    usb_dp_i = 1;
    usb_dn_i = 0;
    pkt_end_seen = 0;
    bitstuff_seen = 0;

    repeat (8) @(posedge clk_i);
    rst_ni = 1;
    repeat (4) @(posedge clk_i);

    repeat (8) drive_line(LineJ);
    drive_sync();
    drive_pre_pid();
    repeat (TrailBits) drive_line(LineK);
    repeat (20) @(posedge clk_i);

    if (bitstuff_seen != 0) begin
      $display("TB_STATUS: FAIL unexpected bitstuff error after PRE PID");
      $finish;
    end
    if (pkt_end_seen == 0) begin
      $display("TB_STATUS: FAIL receiver did not retire PRE packet");
      $finish;
    end

    $display("TB_STATUS: PASS pkt_end_seen=%0d bitstuff_seen=%0d", pkt_end_seen, bitstuff_seen);
    $finish;
  end
endmodule
EOF

