module tb;
  import csrng_pkg::*;

  localparam logic [127:0] ExpBus = 128'h0123_4567_89ab_cdef_fedc_ba98_7654_3210;

  logic clk_i;
  logic rst_ni;
  logic cs_enable_i;
  logic cmd_stage_vld_i;
  logic [3:0] cmd_stage_shid_i;
  logic [31:0] cmd_stage_bus_i;
  logic cmd_stage_rdy_o;
  logic cmd_arb_req_o;
  logic cmd_arb_sop_o;
  logic cmd_arb_mop_o;
  logic cmd_arb_eop_o;
  logic cmd_arb_gnt_i;
  logic [31:0] cmd_arb_bus_o;
  logic cmd_ack_i;
  logic cmd_ack_sts_i;
  logic cmd_stage_ack_o;
  logic cmd_stage_ack_sts_o;
  logic genbits_vld_i;
  logic [127:0] genbits_bus_i;
  logic genbits_fips_i;
  logic genbits_vld_o;
  logic genbits_rdy_i;
  logic [127:0] genbits_bus_o;
  logic genbits_fips_o;
  logic [2:0] cmd_stage_sfifo_cmd_err_o;
  logic [2:0] cmd_stage_sfifo_genbits_err_o;
  logic cmd_gen_cnt_err_o;
  logic cmd_stage_sm_err_o;

  csrng_cmd_stage dut (
    .clk_i,
    .rst_ni,
    .cs_enable_i,
    .cmd_stage_vld_i,
    .cmd_stage_shid_i,
    .cmd_stage_bus_i,
    .cmd_stage_rdy_o,
    .cmd_arb_req_o,
    .cmd_arb_sop_o,
    .cmd_arb_mop_o,
    .cmd_arb_eop_o,
    .cmd_arb_gnt_i,
    .cmd_arb_bus_o,
    .cmd_ack_i,
    .cmd_ack_sts_i,
    .cmd_stage_ack_o,
    .cmd_stage_ack_sts_o,
    .genbits_vld_i,
    .genbits_bus_i,
    .genbits_fips_i,
    .genbits_vld_o,
    .genbits_rdy_i,
    .genbits_bus_o,
    .genbits_fips_o,
    .cmd_stage_sfifo_cmd_err_o,
    .cmd_stage_sfifo_genbits_err_o,
    .cmd_gen_cnt_err_o,
    .cmd_stage_sm_err_o
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic check_true(input logic cond, input string msg);
    if (!cond) begin
      $fatal(1, "%s", msg);
    end
  endtask

  initial begin
    rst_ni = 1'b0;
    cs_enable_i = 1'b0;
    cmd_stage_vld_i = 1'b0;
    cmd_stage_shid_i = '0;
    cmd_stage_bus_i = '0;
    cmd_arb_gnt_i = 1'b0;
    cmd_ack_i = 1'b0;
    cmd_ack_sts_i = 1'b0;
    genbits_vld_i = 1'b0;
    genbits_bus_i = '0;
    genbits_fips_i = 1'b0;
    genbits_rdy_i = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    cs_enable_i = 1'b1;

    @(posedge clk_i);
    genbits_bus_i = ExpBus;
    genbits_fips_i = 1'b1;
    genbits_vld_i = 1'b1;

    @(posedge clk_i);
    genbits_vld_i = 1'b0;
    genbits_bus_i = '0;
    genbits_fips_i = 1'b0;

    @(negedge clk_i);
    check_true(genbits_vld_o === 1'b1, "genbits_vld_o did not assert after push");
    check_true(genbits_bus_o === ExpBus, "genbits_bus_o mismatch while valid");
    check_true(genbits_fips_o === 1'b1, "genbits_fips_o mismatch while valid");

    genbits_rdy_i = 1'b1;
    @(posedge clk_i);
    genbits_rdy_i = 1'b0;

    @(negedge clk_i);
    check_true(genbits_vld_o === 1'b0, "genbits_vld_o should deassert after pop");
    check_true(genbits_bus_o === ExpBus, "genbits_bus_o should retain last value after pop");
    check_true(genbits_fips_o === 1'b1, "genbits_fips_o should retain last value after pop");

    $display("TB_PASS");
    $finish;
  end
endmodule
SV

