#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="lc_ctrl_claim_transition_if_regwen"
TB_ROOT="/home/opentitan/.tb_${TEST_NAME}"
SCRATCH_ROOT="${TB_ROOT}/scratch"
LOG="${TB_ROOT}/dvsim.log"
SEQ_FILE="hw/ip/lc_ctrl/dv/env/seq_lib/${TEST_NAME}_vseq.sv"
VSEQ_LIST="hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_vseq_list.sv"
ENV_CORE="hw/ip/lc_ctrl/dv/env/lc_ctrl_env.core"
SIM_CFG="hw/ip/lc_ctrl/dv/lc_ctrl_base_sim_cfg.hjson"
RESULT="FAIL"

emit_result() {
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${RESULT}"
  echo "HWE_BENCH_RESULTS_END"
}

trap emit_result EXIT

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

cat > "${SEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class lc_ctrl_claim_transition_if_regwen_vseq extends lc_ctrl_base_vseq;
  `uvm_object_utils(lc_ctrl_claim_transition_if_regwen_vseq)
  `uvm_object_new

  virtual task pre_start();
    super.pre_start();
    cfg.en_scb = 0;
  endtask

  virtual task drive_otp_i(bit rand_otp_i = 1);
    lc_state = LcStRaw;
    lc_cnt   = LcCnt0;
    cfg.lc_ctrl_vif.init(.lc_state(lc_state), .lc_cnt(lc_cnt), .otp_device_id(cfg.otp_device_id),
                         .otp_manuf_state(cfg.otp_manuf_state),
                         .otp_vendor_test_status(cfg.otp_vendor_test_status));
  endtask

  virtual task wait_for_transition_regwen(bit exp);
    uvm_reg_data_t val = '0;
    repeat (20) begin
      csr_rd(ral.transition_regwen, val);
      if (val == exp) break;
      cfg.clk_rst_vif.wait_clks(5);
    end
    `DV_CHECK_EQ(val, exp)
  endtask

  virtual task body();
    csr_rd_check(.ptr(ral.claim_transition_if_regwen), .compare_value(1));

    csr_wr(.ptr(ral.claim_transition_if), .value(CLAIM_TRANS_VAL));
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.claim_transition_if), .compare_value(CLAIM_TRANS_VAL));
    wait_for_transition_regwen(1);

    csr_wr(.ptr(ral.claim_transition_if), .value(0));
    cfg.clk_rst_vif.wait_clks(5);
    wait_for_transition_regwen(0);

    csr_wr(.ptr(ral.claim_transition_if_regwen), .value(0));
    csr_rd_check(.ptr(ral.claim_transition_if_regwen), .compare_value(0));

    csr_wr(.ptr(ral.claim_transition_if), .value(CLAIM_TRANS_VAL), .check(UVM_NO_CHECK), .predict(0));
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.claim_transition_if), .compare_value(0));
    wait_for_transition_regwen(0);
  endtask
endclass
EOF

python - <<'PY'
from pathlib import Path

test_name = "lc_ctrl_claim_transition_if_regwen"
include_line = f'`include "{test_name}_vseq.sv"\n'
vseq_list = Path("hw/ip/lc_ctrl/dv/env/seq_lib/lc_ctrl_vseq_list.sv")
text = vseq_list.read_text(encoding="utf-8")
if include_line not in text:
    text += include_line
vseq_list.write_text(text, encoding="utf-8")

env_core = Path("hw/ip/lc_ctrl/dv/env/lc_ctrl_env.core")
text = env_core.read_text(encoding="utf-8")
core_line = f'      - seq_lib/{test_name}_vseq.sv: {{is_include_file: true}}\n'
anchor = '      - seq_lib/lc_ctrl_stress_all_vseq.sv: {is_include_file: true}\n'
if core_line not in text:
    if anchor not in text:
        raise SystemExit("Unable to locate seq_lib anchor in lc_ctrl_env.core")
    text = text.replace(anchor, anchor + core_line, 1)
env_core.write_text(text, encoding="utf-8")

sim_cfg = Path("hw/ip/lc_ctrl/dv/lc_ctrl_sim_cfg.hjson")
text = sim_cfg.read_text(encoding="utf-8")
if test_name not in text:
    needle = '  ]\n\n  // List of regressions.\n'
    insert = (
        '    {\n'
        f'      name: "{test_name}"\n'
        f'      uvm_test_seq: {test_name}_vseq\n'
        '      run_opts: ["+en_scb=0"]\n'
        '      reseed: 1\n'
        '    }\n'
    )
    if needle not in text:
        raise SystemExit("Unable to locate tests list terminator in lc_ctrl_sim_cfg.hjson")
    text = text.replace(needle, insert + needle, 1)
sim_cfg.write_text(text, encoding="utf-8")
PY

set +e
/usr/bin/timeout -k 30 1800 \
  ./util/dvsim/dvsim.py hw/ip/lc_ctrl/dv/lc_ctrl_sim_cfg.hjson \
  -i "${TEST_NAME}" \
  -t vcs \
  --build-seed 1 \
  --fixed-seed 1 \
  --scratch-root "${SCRATCH_ROOT}" \
  2>&1 | tee "${LOG}"
rc=${PIPESTATUS[0]}
set -e

if [[ ${rc} -eq 0 ]]; then
  RESULT="PASS"
fi

exit ${rc}

