#!/bin/bash
set -euo pipefail

cd /home/opentitan

python - <<'PY'
from pathlib import Path

base = Path("hw/ip/spi_device/dv/env/seq_lib/spi_device_pass_base_vseq.sv")
text = base.read_text(encoding="utf-8")
old = """      `DV_CHECK_STD_RANDOMIZE_WITH_FATAL(sck_polarity_phase,
          // TODO (#16339), add back 'b11 once this issue is fixed
          sck_polarity_phase inside {0};)"""
new = """      `DV_CHECK_STD_RANDOMIZE_WITH_FATAL(sck_polarity_phase,
          sck_polarity_phase inside {'b11};)"""
if new not in text:
    if old not in text:
        raise SystemExit("mode-3 constraint block not found")
    text = text.replace(old, new, 1)
    base.write_text(text, encoding="utf-8")

Path("hw/ip/spi_device/dv/env/seq_lib/spi_device_pass_cmd_filtering_vseq.sv").write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

// Minimal mode-3 passthrough filtering scenario.
class spi_device_pass_cmd_filtering_vseq extends spi_device_pass_base_vseq;
  `uvm_object_utils(spi_device_pass_cmd_filtering_vseq)
  `uvm_object_new

  virtual task body();
    allow_set_cmd_info_invalid = 0;
    allow_use_invalid_opcode = 0;
    allow_addr_swap = 0;
    allow_payload_swap = 0;
    allow_intercept = 0;
    allow_upload = 0;
    allow_write_enable_disable = 0;
    allow_addr_cfg_cmd = 0;
    spi_device_flash_pass_init();

    opcode = READ_JEDEC;
    payload_size = 3;
    read_start_addr = '0;

    cfg_cmd_filter(1'b1, opcode);
    spi_host_xfer_flash_item(opcode, payload_size, read_start_addr, 1'b0);

    cfg.clk_rst_vif.wait_clks(20);

    cfg_cmd_filter(1'b0, opcode);
    spi_host_xfer_flash_item(opcode, payload_size, read_start_addr, 1'b0);
  endtask : body

endclass : spi_device_pass_cmd_filtering_vseq
""",
    encoding="utf-8",
)
PY

set +e
timeout 1700s python util/dvsim/dvsim.py hw/ip/spi_device/dv/spi_device_sim_cfg.hjson \
