rm -rf "$RUN_ROOT"/*

cat > hw/ip/edn/dv/env/seq_lib/edn_disable_vseq.sv <<'SVEOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class edn_disable_vseq extends edn_base_vseq;
  `uvm_object_utils(edn_disable_vseq)
  `uvm_object_new

  localparam string SendGencmdQPath = "tb.dut.u_edn_core.send_gencmd_q";
  localparam string BootWrCmdGenfifoPath = "tb.dut.u_edn_core.boot_wr_cmd_genfifo";
  localparam string GenerateCmdLoadPath = "tb.dut.u_edn_core.generate_cmd_load";
  localparam string GenerateCmdBusPath = "tb.dut.u_edn_core.generate_cmd_bus";
  localparam string AutoReqModeBusyPath = "tb.dut.u_edn_core.auto_req_mode_busy";
  localparam string SendGenCmdEnablePath = "tb.dut.u_edn_core.edn_enable_fo[14]";
  localparam string GencmdPushPath = "tb.dut.u_edn_core.sfifo_gencmd_push";
  localparam string GencmdWdataPath = "tb.dut.u_edn_core.sfifo_gencmd_wdata";

  task pre_start();
    do_edn_init = 0;
    do_dut_shutdown = 0;
    super.pre_start();
  endtask

  task automatic force_disable_window_and_check();
    uvm_hdl_data_t zero_val, one_val, x_val, push_val, wdata_val;

    zero_val = '0;
    one_val = '0;
    one_val[0] = 1'b1;
    x_val = 'x;

    // Recreate the issue-reported post-disable condition:
    // send_gencmd_q is still asserted while the SendGenCmd enable fanout has dropped.
    `DV_CHECK(uvm_hdl_force(SendGencmdQPath, one_val))
    `DV_CHECK(uvm_hdl_force(BootWrCmdGenfifoPath, zero_val))
    `DV_CHECK(uvm_hdl_force(GenerateCmdLoadPath, zero_val))
    `DV_CHECK(uvm_hdl_force(AutoReqModeBusyPath, zero_val))
    `DV_CHECK(uvm_hdl_force(GenerateCmdBusPath, x_val))
    `DV_CHECK(uvm_hdl_force(SendGenCmdEnablePath, zero_val))

    #1ps;
    `DV_CHECK(uvm_hdl_read(GencmdPushPath, push_val))
    `DV_CHECK(uvm_hdl_read(GencmdWdataPath, wdata_val))

    if (push_val[0] === 1'b1 && $isunknown(wdata_val[31:0])) begin
      `uvm_fatal(`gfn, $sformatf(
          "Observed X pushed into gencmd FIFO while SendGenCmd enable is low: push=%b wdata=%h",
          push_val[0], wdata_val[31:0]))
    end

    `uvm_info(`gfn, $sformatf(
        "No illegal post-disable gencmd FIFO push observed: push=%b wdata=%h",
        push_val[0], wdata_val[31:0]), UVM_LOW)

    `DV_CHECK(uvm_hdl_release(SendGencmdQPath))
    `DV_CHECK(uvm_hdl_release(BootWrCmdGenfifoPath))
    `DV_CHECK(uvm_hdl_release(GenerateCmdLoadPath))
    `DV_CHECK(uvm_hdl_release(AutoReqModeBusyPath))
    `DV_CHECK(uvm_hdl_release(GenerateCmdBusPath))
    `DV_CHECK(uvm_hdl_release(SendGenCmdEnablePath))
  endtask

  task body();
    super.body();
    cfg.clk_rst_vif.wait_clks(5);
    force_disable_window_and_check();
    cfg.clk_rst_vif.wait_clks(5);
  endtask

  virtual task post_start();
    // Keep teardown empty to avoid unrelated register traffic after the focused check above.
  endtask

endclass
SVEOF

