#!/bin/bash
cd /home/opentitan || exit 1
set +e
set -o pipefail

TEST_NAME="keymgr_sideload_sel_glitch"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
mkdir -p "$TB_DIR"

finish() {
  local rc="$1"
  echo "HWE_BENCH_RESULTS_START"
  if [ "$rc" -eq 0 ]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
  exit "$rc"
}

python - <<'PY'
from pathlib import Path

vseq = Path("hw/ip/keymgr/dv/env/seq_lib/keymgr_sideload_sel_glitch_vseq.sv")
vseq.write_text(
    """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_sideload_sel_glitch_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_sideload_sel_glitch_vseq)
  `uvm_object_new

  string glitch_path = "tb.dut.u_sideload_ctrl.otbn_key_o.valid";

  task body();
    `uvm_info(`gfn, "Key manager sideload select glitch seq start", UVM_MEDIUM)

    cfg.en_scb = 0;
    cfg.keymgr_vif.en_chk = 0;
    ral.default_map.set_auto_predict(1);

    $assertoff(0, "tb.keymgr_kmac_intf");
    $assertoff(0, "tb.dut.u_ctrl.DataEn_A");
    $assertoff(0, "tb.dut.u_ctrl.DataEnDis_A");
    $assertoff(0, "tb.dut.u_ctrl.CntZero_A");
    $assertoff(0, "tb.dut.u_kmac_if.LastStrb_A");
    $assertoff(0, "tb.dut.KmacDataKnownO_A");

    `DV_CHECK_FATAL(uvm_hdl_check_path(glitch_path),
                    $sformatf("Missing HDL path %0s", glitch_path))

    repeat (2) keymgr_advance(.wait_done(1));

    keymgr_generate(.operation(keymgr_pkg::OpGenHwOut),
                    .key_dest(keymgr_pkg::Kmac),
                    .wait_done(0));

    `DV_WAIT(cfg.keymgr_vif.kmac_data_req.last, , 500_000, `gfn)
    cfg.clk_rst_vif.wait_clks(1);
    `DV_CHECK_FATAL(uvm_hdl_force(glitch_path, 1'b1),
                    $sformatf("Failed to force %0s", glitch_path))

    `DV_WAIT(cfg.keymgr_vif.kmac_data_rsp.done, , 500_000, `gfn)
    cfg.clk_rst_vif.wait_clks(1);
    `DV_CHECK_FATAL(uvm_hdl_release(glitch_path),
                    $sformatf("Failed to release %0s", glitch_path))

    cfg.clk_rst_vif.wait_clks(5);
    check_fatal_alert_nonblocking("fatal_fault_err");
    csr_rd_check(.ptr(ral.fault_status.side_ctrl_sel), .compare_value(1));

    csr_spinwait(.ptr(ral.op_status.status),
                 .exp_data(keymgr_pkg::OpWip),
                 .compare_op(CompareOpNe));
    check_after_fi();
  endtask

  task post_start();
    expect_fatal_alerts = 1;
    super.post_start();
    $asserton(0, "tb.keymgr_kmac_intf");
    $asserton(0, "tb.dut.u_ctrl.DataEn_A");
    $asserton(0, "tb.dut.u_ctrl.DataEnDis_A");
    $asserton(0, "tb.dut.u_ctrl.CntZero_A");
    $asserton(0, "tb.dut.u_kmac_if.LastStrb_A");
    $asserton(0, "tb.dut.KmacDataKnownO_A");
  endtask
endclass
""",
    encoding="utf-8",
)

core = Path("hw/ip/keymgr/dv/env/keymgr_env.core")
core_text = core.read_text(encoding="utf-8")
core_needle = '      - seq_lib/keymgr_kmac_rsp_err_vseq.sv: {is_include_file: true}\n'
core_insert = core_needle + '      - seq_lib/keymgr_sideload_sel_glitch_vseq.sv: {is_include_file: true}\n'
if "keymgr_sideload_sel_glitch_vseq.sv" not in core_text:
    core_text = core_text.replace(core_needle, core_insert)
core.write_text(core_text, encoding="utf-8")

vlist = Path("hw/ip/keymgr/dv/env/seq_lib/keymgr_vseq_list.sv")
vlist_text = vlist.read_text(encoding="utf-8")
vlist_needle = '`include "keymgr_kmac_rsp_err_vseq.sv"\n'
vlist_insert = vlist_needle + '`include "keymgr_sideload_sel_glitch_vseq.sv"\n'
if "keymgr_sideload_sel_glitch_vseq.sv" not in vlist_text:
    vlist_text = vlist_text.replace(vlist_needle, vlist_insert)
vlist.write_text(vlist_text, encoding="utf-8")
PY
rc=$?
if [ "$rc" -ne 0 ]; then
