#!/bin/bash
set +e

cd /home/opentitan || exit 1

TEST_NAME="rstmgr_err_code_race"
TB_ROOT="/home/opentitan/.tb_rstmgr_err_code"
TB_FILE="${TB_ROOT}/tb.sv"
PRIM_PKG_FILE="${TB_ROOT}/prim_pkg.sv"
PRIM_BUF_FILE="${TB_ROOT}/prim_buf.sv"
FILELIST="${TB_ROOT}/files.f"
SIMV="${TB_ROOT}/simv"
COMPILE_LOG="${TB_ROOT}/compile.log"
RUN_LOG="${TB_ROOT}/run.log"

report_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

cat > "${PRIM_PKG_FILE}" <<'EOF'
package prim_pkg;
  typedef enum int {
    ImplGeneric = 0,
    ImplXilinx = 1
  } impl_e;
endpackage
EOF

cat > "${PRIM_BUF_FILE}" <<'EOF'
module prim_buf #(
  parameter int Width = 1,
  parameter prim_pkg::impl_e Impl = prim_pkg::ImplGeneric
) (
  input        [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  if (Impl == prim_pkg::ImplGeneric) begin : gen_generic
    prim_generic_buf #(
      .Width(Width)
    ) u_impl_generic (
      .in_i,
      .out_o
    );
  end else begin : gen_fallback
    prim_generic_buf #(
      .Width(Width)
    ) u_impl_generic (
      .in_i,
      .out_o
    );
  end
endmodule
EOF

cat > "${TB_FILE}" <<'EOF'
module tb;
  import top_pkg::*;
  import tlul_pkg::*;
  import rstmgr_reg_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic clk_por_i;
  logic rst_por_ni;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  rstmgr_reg2hw_t reg2hw;
  rstmgr_hw2reg_t hw2reg;
  logic intg_err_o;
  logic devmode_i;

  rstmgr_reg_top dut (
    .clk_i,
    .rst_ni,
    .clk_por_i,
    .rst_por_ni,
    .tl_i,
    .tl_o,
    .reg2hw,
    .hw2reg,
    .intg_err_o,
    .devmode_i
  );

  always #5 clk_i = ~clk_i;
  always #5 clk_por_i = ~clk_por_i;

  initial begin
    clk_i = 1'b0;
    clk_por_i = 1'b0;
    rst_ni = 1'b0;
    rst_por_ni = 1'b0;
    tl_i = TL_H2D_DEFAULT;
    hw2reg = '0;
    devmode_i = 1'b0;

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_por_ni = 1'b1;

    // Reproduce the race: HW raises fsm_err while SW tries to clear ERR_CODE.
    @(negedge clk_i);
    hw2reg.err_code.fsm_err.d = 1'b1;
    hw2reg.err_code.fsm_err.de = 1'b1;
    force dut.reg_we = 1'b1;
    force dut.reg_addr = RSTMGR_ERR_CODE_OFFSET;
    force dut.reg_wdata = 32'h0000_0004;
    force dut.reg_error = 1'b0;

    @(posedge clk_i);
    #1;
    release dut.reg_we;
    release dut.reg_addr;
    release dut.reg_wdata;
    release dut.reg_error;
    hw2reg.err_code.fsm_err.de = 1'b0;

    repeat (2) @(posedge clk_i);

    if (reg2hw.err_code.fsm_err.q !== 1'b1) begin
      $display("Observed err_code.fsm_err.q=%0b", reg2hw.err_code.fsm_err.q);
      $fatal(1, "err_code.fsm_err was cleared by a concurrent SW write");
    end

    $display("Observed err_code.fsm_err.q=%0b", reg2hw.err_code.fsm_err.q);
    $finish;
  end
endmodule
EOF

cat > "${FILELIST}" <<EOF
${PRIM_PKG_FILE}
/home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_subreg_pkg.sv
