from pathlib import Path


def ensure_file(path_str: str, content: str) -> None:
    path = Path(path_str)
    path.write_text(content, encoding="utf-8")


def ensure_line_after(path_str: str, anchor: str, addition: str) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if addition.strip() in text:
        return
    if anchor not in text:
        raise SystemExit(f"anchor not found in {path}: {anchor}")
    path.write_text(text.replace(anchor, anchor + "\n" + addition), encoding="utf-8")


def ensure_block_after(path_str: str, anchor: str, block: str) -> None:
    path = Path(path_str)
    text = path.read_text(encoding="utf-8")
    if block.strip() in text:
        return
    if anchor not in text:
        raise SystemExit(f"anchor not found in {path}: {anchor}")
    path.write_text(text.replace(anchor, anchor + "\n\n" + block), encoding="utf-8")


