// SPDX-License-Identifier: Apache-2.0

class entropy_src_corrupted_push_vseq extends entropy_src_base_vseq;
  `uvm_object_utils(entropy_src_corrupted_push_vseq)
  `uvm_object_new

  localparam string AlertPath  = "tb.dut.u_entropy_src_core.es_fw_ov_disable_alert";
  localparam string RawPath    = "tb.dut.u_entropy_src_core.main_stage_push_raw";
  localparam string PushPath   = "tb.dut.u_entropy_src_core.main_stage_push";
  localparam string BypassPath = "tb.dut.u_entropy_src_core.es_bypass_mode";
  localparam string FlushPath  = "tb.dut.u_entropy_src_core.sha3_flush_q";

  task pre_start();
    do_entropy_src_init = 0;
    do_interrupt = 0;
    super.pre_start();
  endtask

  task automatic force_bit(string path, bit value);
    if (!uvm_hdl_check_path(path)) begin
      `uvm_fatal(`gfn, $sformatf("HDL path not found: %0s", path))
    end
    `DV_CHECK_FATAL(uvm_hdl_force(path, value))
  endtask

  task automatic release_bit(string path);
    `DV_CHECK_FATAL(uvm_hdl_release(path))
  endtask

  task automatic check_push(bit exp, string label);
    uvm_hdl_data_t value;
    bit observed;
    #0;
    `DV_CHECK_FATAL(uvm_hdl_read(PushPath, value))
    observed = value[0];
    `DV_CHECK_EQ_FATAL(observed, exp,
        $sformatf("%0s expected main_stage_push=%0b, got %0b", label, exp, observed))
    `uvm_info(`gfn, $sformatf("%0s observed main_stage_push=%0b", label, observed), UVM_MEDIUM)
  endtask

  task body();
    wait(!cfg.under_reset);
    cfg.entropy_src_assert_vif.assert_off_err();

    force_bit(BypassPath, 1'b0);
    force_bit(FlushPath, 1'b0);
    force_bit(RawPath, 1'b0);
    force_bit(AlertPath, 1'b0);
    cfg.clk_rst_vif.wait_clks(2);

    force_bit(AlertPath, 1'b1);
    cfg.clk_rst_vif.wait_clks(1);
    force_bit(AlertPath, 1'b0);

    force_bit(RawPath, 1'b1);
    check_push(1'b0, "first post-alert push");
    cfg.clk_rst_vif.wait_clks(1);
    check_push(1'b0, "second post-alert push");
    cfg.clk_rst_vif.wait_clks(1);
    check_push(1'b1, "third post-alert push");

    release_bit(RawPath);
    release_bit(AlertPath);
    release_bit(BypassPath);
    release_bit(FlushPath);
  endtask
endclass
