class flash_ctrl_fifo_ctr_redun_vseq extends flash_ctrl_common_vseq;
  `uvm_object_utils(flash_ctrl_fifo_ctr_redun_vseq)
  `uvm_object_new

  localparam string TargetAlert = "fatal_std_err";
  localparam string TargetPath =
      "tb.dut.u_to_rd_fifo.u_rspfifo.gen_normal_fifo.u_fifo_cnt.gen_secure_ptrs.u_wptr.up_cnt_q[0]";

  virtual task pre_start();
    expect_fatal_alerts = 1'b1;
    super.pre_start();
  endtask

  virtual task body();
    uvm_hdl_data_t orig_value;
    uvm_hdl_data_t force_value;

    cfg.clk_rst_vif.wait_clks(5);
    `DV_CHECK_FATAL(uvm_hdl_check_path(TargetPath),
                    $sformatf("Missing expected secure FIFO path: %0s", TargetPath))
    `DV_CHECK_FATAL(uvm_hdl_read(TargetPath, orig_value),
                    $sformatf("Failed to read %0s", TargetPath))

    $assertoff(0, "tb.dut.u_to_rd_fifo.u_rspfifo.DataKnown_A");
    $assertoff(0, "tb.dut.u_to_rd_fifo.u_rspfifo.DepthKnown_A");
    $assertoff(0, "tb.dut.u_to_rd_fifo.u_rspfifo.RvalidKnown_A");
    $assertoff(0, "tb.dut.u_to_rd_fifo.u_rspfifo.WreadyKnown_A");

    force_value = orig_value ^ 1;
    `DV_CHECK_FATAL(uvm_hdl_force(TargetPath, force_value),
                    $sformatf("Failed to force %0s", TargetPath))
    cfg.clk_rst_vif.wait_clks(2);
    `DV_CHECK_FATAL(uvm_hdl_release(TargetPath),
                    $sformatf("Failed to release %0s", TargetPath))

    wait_alert_trigger(TargetAlert, .wait_complete(1));
    cfg.clk_rst_vif.wait_clks(10);
    dut_init("HARD");
    $asserton(0, "tb.dut.u_to_rd_fifo.u_rspfifo.DataKnown_A");
    $asserton(0, "tb.dut.u_to_rd_fifo.u_rspfifo.DepthKnown_A");
    $asserton(0, "tb.dut.u_to_rd_fifo.u_rspfifo.RvalidKnown_A");
