    hw2reg_wrap.alert_cause[0] = 1'b1;
    hw2reg_wrap.class_accum_cnt[0] = 16'h0011;
    hw2reg_wrap.class_esc_cnt[0] = 32'h11111111;
    hw2reg_wrap.class_esc_state[0] = Phase0;
  endtask

  task automatic drive_second_escalation();
    hw2reg_wrap = '0;
    hw2reg_wrap.alert_cause[1] = 1'b1;
    hw2reg_wrap.class_accum_cnt[1] = 16'h0022;
    hw2reg_wrap.class_esc_cnt[1] = 32'h22222222;
    hw2reg_wrap.class_esc_state[1] = Phase0;
  endtask

  task automatic pulse_latch();
    latch_any = 1'b1;
    @(posedge clk_i);
    #1;
    latch_any = 1'b0;
  endtask

  task automatic pulse_classd_clear();
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.q = 1'b1;
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.qe = 1'b1;
    @(posedge clk_i);
    #1;
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.q = 1'b0;
    tb_ctrl_pkg::reg2hw_stub.classd_clr_shadowed.qe = 1'b0;
  endtask

