    clk_i = 1'b0;
    rst_ni = 1'b0;
    rst_shadowed_ni = 1'b0;
    tl_i = '0;
    hw2reg_wrap = '0;
    latch_any = 1'b0;
    clear_stub_regs();

    repeat (3) @(posedge clk_i);
    #1;
    rst_ni = 1'b1;
    rst_shadowed_ni = 1'b1;
    repeat (2) @(posedge clk_i);
    #1;

    drive_first_escalation();
    pulse_latch();
    repeat (1) @(posedge clk_i);
    #1;
    first_snapshot = crashdump_o;

    if (first_snapshot.class_esc_cnt[0] !== 32'h11111111 ||
        first_snapshot.class_esc_state[0] !== Phase0) begin
      $fatal(1, "failed to capture initial crashdump snapshot");
    end

    pulse_classd_clear();
    drive_second_escalation();
    pulse_latch();
    repeat (1) @(posedge clk_i);
    #1;

    if (crashdump_o !== first_snapshot) begin
      $fatal(1, "crashdump changed after unrelated clear re-armed latch");
    end

    $display("TB PASS");
    $finish;
  end
endmodule
