compile_rc=$?

run_rc=1
pass=0
exit_code=1
if [ $compile_rc -eq 0 ]; then
  timeout 1200s "$SIMV" -l "$RUN_LOG"
  run_rc=$?
  # VCS may still exit with 0 after $fatal, so gate PASS on the explicit success marker.
  if [ $run_rc -eq 0 ] && grep -q "TB PASS" "$RUN_LOG"; then
    pass=1
  fi
fi

echo "HWE_BENCH_RESULTS_START"
if [ $compile_rc -eq 0 ] && [ $pass -eq 1 ]; then
  echo "TEST: alert_handler_crashdump_latch ... PASS"
  exit_code=0
else
  echo "TEST: alert_handler_crashdump_latch ... FAIL"
  if [ $compile_rc -ne 0 ]; then
    exit_code=$compile_rc
  elif [ $run_rc -ne 0 ]; then
    exit_code=$run_rc
  fi
fi
echo "HWE_BENCH_RESULTS_END"

exit $exit_code

