#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="keccak_round_waits_for_rand_valid"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
STATUS_FILE="${TB_DIR}/sim.status"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
