cat > "${TB_DIR}/tb.sv" <<'SV'
`timescale 1ns/1ps

module tb;
  import prim_mubi_pkg::*;
  import lc_ctrl_pkg::*;

  localparam int Width = 800;
  localparam int DInWidth = 64;
  localparam int Share = 2;
  localparam int DInAddr = $clog2(Width / DInWidth);
  localparam string StatusFile = "sim.status";

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic valid_i = 1'b0;
  logic [DInAddr-1:0] addr_i = '0;
  logic [DInWidth-1:0] data_i [Share];
  logic ready_o;
  logic run_i = 1'b0;
  logic rand_valid_i = 1'b0;
  logic rand_early_i = 1'b0;
  logic [Width/2-1:0] rand_data_i = '0;
  logic rand_consumed_o;
  logic complete_o;
  logic [Width-1:0] state_o [Share];
  lc_tx_t lc_escalate_en_i = Off;
  logic sparse_fsm_error_o;
  logic round_count_error_o;
  logic clear_i = 1'b0;

  bit saw_resume_pulse = 1'b0;

  keccak_round #(
    .Width(Width),
    .EnMasking(1'b1)
  ) dut (
    .clk_i,
    .rst_ni,
    .valid_i,
    .addr_i,
    .data_i,
    .ready_o,
    .run_i,
    .rand_valid_i,
    .rand_early_i,
    .rand_data_i,
    .rand_consumed_o,
    .complete_o,
    .state_o,
    .lc_escalate_en_i,
    .sparse_fsm_error_o,
    .round_count_error_o,
    .clear_i
  );

  always #5 clk_i = ~clk_i;

  always @(rand_consumed_o) begin
    if (rand_valid_i && rand_consumed_o === 1'b1) begin
      saw_resume_pulse = 1'b1;
    end
  end

  task automatic write_status(input string status);
    int fd;
    begin
      fd = $fopen(StatusFile, "w");
      if (fd) begin
        $fdisplay(fd, "%s", status);
        $fclose(fd);
      end
    end
  endtask

  task automatic fail(input string msg);
    begin
      $display("TB_FAIL: %s", msg);
      write_status("FAIL");
      $fatal(1);
    end
  endtask

  task automatic pass(input string msg);
    begin
      $display("TB_PASS: %s", msg);
      write_status("PASS");
      $finish;
    end
  endtask

  initial begin
    data_i[0] = '0;
    data_i[1] = '0;
    write_status("START");

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    run_i = 1'b1;
    rand_valid_i = 1'b1;
    @(posedge clk_i);
    run_i = 1'b0;
    @(posedge clk_i);
    rand_valid_i = 1'b0;
    saw_resume_pulse = 1'b0;
    #1;
    if (rand_consumed_o !== 1'b1) begin
      fail("Phase2Cycle1 did not consume randomness before the stall point");
    end

    @(posedge clk_i);
    #1;
    if (rand_consumed_o !== 1'b0) begin
      fail("rand_consumed_o asserted while rand_valid_i was low");
    end
    if (complete_o !== 1'b0) begin
      fail("complete_o asserted before fresh randomness returned");
    end

    repeat (2) @(posedge clk_i);
    #1;
    if (rand_consumed_o !== 1'b0) begin
      fail("keccak_round continued consuming randomness while rand_valid_i stayed low");
    end

    rand_valid_i = 1'b1;
    for (int i = 0; i < 4; i++) begin
      #1;
      if (saw_resume_pulse) begin
        i = 4;
      end else begin
        @(posedge clk_i);
      end
    end
    if (!saw_resume_pulse) begin
      fail("keccak_round did not resume consuming randomness after rand_valid_i returned");
    end

    repeat (120) begin
      @(posedge clk_i);
      #1;
      if (complete_o === 1'b1) begin
        pass("keccak_round waits for rand_valid_i before consuming new randomness");
      end
    end

    fail("timed out waiting for keccak_round to complete after randomness resumed");
  end
endmodule
SV

set +e
timeout --preserve-status 1800 vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+"${TB_DIR}/stubs" \
  "${TB_DIR}/stubs/prim_mubi_pkg.sv" \
  "${TB_DIR}/stubs/lc_ctrl_pkg.sv" \
  "${TB_DIR}/stubs/prim_count_pkg.sv" \
  "${TB_DIR}/stubs/prim_sec_anchor_buf.sv" \
  "${TB_DIR}/stubs/prim_count.sv" \
  "${TB_DIR}/stubs/keccak_2share.sv" \
  hw/ip/kmac/rtl/sha3_pkg.sv \
  hw/ip/kmac/rtl/keccak_round.sv \
  "${TB_DIR}/tb.sv" \
  -top tb \
  -o "${TB_DIR}/simv" \
  -l "${TB_DIR}/compile.log"
compile_rc=$?
set -e

if [[ "${compile_rc}" -ne 0 ]]; then
  tail -n 80 "${TB_DIR}/compile.log" || true
  emit_result FAIL
  exit 1
fi

rm -f "${STATUS_FILE}"

set +e
(
  cd "${TB_DIR}"
  timeout --preserve-status 1800 ./simv -l run.log
)
sim_rc=$?
set -e

if [[ "${sim_rc}" -eq 124 ]]; then
  tail -n 80 "${TB_DIR}/run.log" || true
  emit_result FAIL
  exit 1
fi

sim_status=""
if [[ -f "${STATUS_FILE}" ]]; then
  sim_status="$(tr -d '\r\n' < "${STATUS_FILE}")"
fi

if [[ "${sim_status}" == "PASS" ]]; then
  emit_result PASS
  exit 0
fi

tail -n 80 "${TB_DIR}/run.log" || true
emit_result FAIL
exit 1

