#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="spi_passthrough_sck_gate"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/prim_clock_gating.sv" <<'EOF'
module prim_clock_gating #(
  parameter bit NoFpgaGate = 1'b0,
  parameter bit FpgaBufGlobal = 1'b1
) (
  input        clk_i,
  input        en_i,
  input        test_en_i,
  output logic clk_o
);
  assign clk_o = (en_i || test_en_i) ? clk_i : 1'b0;
endmodule
EOF

cat > "$TB_DIR/prim_assert_stub.sv" <<'EOF'
`define ASSERT_I(__name, __prop)
`define ASSERT(__name, __prop)
`define ASSERT_KNOWN(__name, __sig)
`define ASSUME(__name, __prop)
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import spi_device_pkg::*;

  logic clk_i;
  logic clk_out_i;
  logic rst_ni;

  logic [255:0] cfg_cmd_filter_i;
  logic [31:0] cfg_addr_mask_i;
  logic [31:0] cfg_addr_value_i;
  logic [31:0] cfg_payload_mask_i;
  logic [31:0] cfg_payload_data_i;
  logic        cfg_addr_4b_en_i;
  spi_mode_e   spi_mode_i;
  logic        passthrough_block_i;
  cmd_info_t [NumTotalCmdInfo-1:0] cmd_info_i;

  logic        host_sck_i;
  logic        host_csb_i;
  logic [3:0]  host_s_i;
  logic [3:0]  host_s_o;
  logic [3:0]  host_s_en_o;

  passthrough_req_t passthrough_o;
  passthrough_rsp_t passthrough_i;

  logic mailbox_hit_i;
  logic event_cmd_filtered_o;

  spi_passthrough dut (
    .clk_i,
    .rst_ni,
    .clk_out_i,
    .cfg_cmd_filter_i,
    .cfg_addr_mask_i,
    .cfg_addr_value_i,
    .cfg_payload_mask_i,
    .cfg_payload_data_i,
    .cfg_addr_4b_en_i,
    .spi_mode_i,
    .passthrough_block_i,
    .cmd_info_i,
    .host_sck_i,
    .host_csb_i,
    .host_s_i,
    .host_s_o,
    .host_s_en_o,
    .passthrough_o,
    .passthrough_i,
    .mailbox_hit_i,
    .event_cmd_filtered_o
  );

  assign clk_out_i = ~host_sck_i;
  assign clk_i = host_sck_i;

  task automatic fail_now(input string msg);
    $display("TB_FAIL: %s", msg);
    $fatal(1);
  endtask

  task automatic drive_bit(input bit value);
    host_s_i[0] = value;
    #5;
    host_sck_i = 1'b1;
    #1;
    #4;
    host_sck_i = 1'b0;
    #1;
    #4;
  endtask

  task automatic send_byte(input byte value);
    for (int i = 7; i >= 0; i--) begin
      drive_bit(value[i]);
    end
  endtask

  initial begin
    cfg_cmd_filter_i     = '1;
    cfg_addr_mask_i      = '0;
    cfg_addr_value_i     = '0;
    cfg_payload_mask_i   = '0;
    cfg_payload_data_i   = '0;
    cfg_addr_4b_en_i     = 1'b0;
    spi_mode_i           = PassThrough;
    passthrough_block_i  = 1'b0;
    cmd_info_i           = '0;
    host_sck_i           = 1'b0;
    host_csb_i           = 1'b1;
    host_s_i             = '0;
    passthrough_i        = '0;
    mailbox_hit_i        = 1'b0;
    rst_ni               = 1'b0;

    #20;
    rst_ni = 1'b1;
    #10;

    host_csb_i = 1'b0;
    #2;
    if (passthrough_o.csb !== 1'b0) begin
      fail_now("passthrough CSB did not follow the host before filtering");
    end

    send_byte(8'h03);
    #2;

    #10;
    if (passthrough_o.csb !== 1'b1) begin
      fail_now("passthrough CSB was not deasserted after a filtered command");
    end

    repeat (4) begin
      host_s_i[0] = $urandom_range(0, 1);
      #5;
      host_sck_i = 1'b1;
      #1;
      if (passthrough_o.sck !== 1'b0) begin
        fail_now("downstream SCK toggled after the command was filtered");
      end
      #4;
      host_sck_i = 1'b0;
      #5;
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps -licqueue \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log" \
  /home/opentitan/hw/ip/spi_device/rtl/spi_device_reg_pkg.sv \
  /home/opentitan/hw/ip/spi_device/rtl/spi_device_pkg.sv \
  "$TB_DIR/prim_assert_stub.sv" \
  "$TB_DIR/prim_clock_gating.sv" \
  /home/opentitan/hw/ip/spi_device/rtl/spi_passthrough.sv \
  "$TB_DIR/tb.sv"
compile_rc=$?

if [ $compile_rc -ne 0 ]; then
  cat "$TB_DIR/compile.log"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit $compile_rc
fi

"$TB_DIR/simv" -l "$TB_DIR/sim.log"
run_rc=$?

echo "HWE_BENCH_RESULTS_START"
if grep -q "TB_PASS" "$TB_DIR/sim.log" \
  && ! grep -Eq "TB_FAIL|Fatal:" "$TB_DIR/sim.log"; then
  tail -n 20 "$TB_DIR/sim.log"
  echo "TEST: $TEST_NAME ... PASS"
else
  tail -n 80 "$TB_DIR/sim.log"
  echo "TEST: $TEST_NAME ... FAIL"
  if [ $run_rc -eq 0 ]; then
    run_rc=1
  fi
fi
echo "HWE_BENCH_RESULTS_END"

exit $run_rc

#!/bin/bash
cd /home/opentitan
set -euo pipefail

TEST_NAME="flash_phy_core_ctrl_erase_lockup"
TB_DIR="/home/opentitan/.tb_flash_phy_core_ctrl_erase_lockup"
BUILD_DIR="$TB_DIR/build"
RUN_LOG="$TB_DIR/fusesoc_run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/flash_phy_core_lockup_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:flash_phy_core_lockup_tb:0.1"
description: "Minimal flash_phy_core controller erase lockup reproducer"

filesets:
  files_tb:
    depend:
      - lowrisc:ip:flash_ctrl:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  default: &default_target
    toplevel: flash_phy_core_lockup_tb
    filesets:
      - files_tb

  sim:
    <<: *default_target
    default_tool: vcs
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module flash_phy_core_lockup_tb;
  import flash_phy_pkg::*;
  import flash_ctrl_pkg::flash_part_e;
  import flash_ctrl_pkg::flash_prog_e;
  import flash_ctrl_pkg::FlashPartData;
  import flash_ctrl_pkg::FlashProgNormal;
  import prim_mubi_pkg::mubi4_t;
  import prim_mubi_pkg::MuBi4False;

  logic clk;
  logic rst_ni;

  logic host_req_i;
  logic host_scramble_en_i;
  logic host_ecc_en_i;
  logic [BusBankAddrW-1:0] host_addr_i;
  logic req_i;
  logic scramble_en_i;
  logic ecc_en_i;
  logic he_en_i;
  logic rd_i;
  logic prog_i;
  logic pg_erase_i;
  logic bk_erase_i;
  logic erase_suspend_req_i;
  flash_part_e part_i;
  logic [InfoTypesWidth-1:0] info_sel_i;
  logic [BusBankAddrW-1:0] addr_i;
  logic [BusFullWidth-1:0] prog_data_i;
  logic prog_last_i;
  flash_prog_e prog_type_i;
  logic [KeySize-1:0] addr_key_i;
  logic [KeySize-1:0] data_key_i;
  logic [KeySize-1:0] rand_addr_key_i;
  logic [KeySize-1:0] rand_data_key_i;
  logic rd_buf_en_i;
  mubi4_t flash_disable_i;
  flash_phy_prim_flash_rsp_t prim_flash_rsp_i;
  flash_phy_prim_flash_req_t prim_flash_req_o;
  logic host_req_rdy_o;
  logic host_req_done_o;
  logic rd_done_o;
  logic prog_done_o;
  logic erase_done_o;
  logic [BusFullWidth-1:0] rd_data_o;
  logic rd_err_o;
  logic ecc_single_err_o;
  logic [BusBankAddrW-1:0] ecc_addr_o;
  logic fsm_err_o;
  logic prog_intg_err_o;
  logic relbl_ecc_err_o;
  logic intg_ecc_err_o;
  logic spurious_ack_o;
  logic arb_err_o;
  logic host_gnt_err_o;

  logic macro_req;
  integer done_countdown;
  bit saw_macro_req;
  bit saw_erase_done;

  flash_phy_core dut (
    .clk_i(clk),
    .rst_ni,
    .host_req_i,
    .host_scramble_en_i,
    .host_ecc_en_i,
    .host_addr_i,
    .req_i,
    .scramble_en_i,
    .ecc_en_i,
    .he_en_i,
    .rd_i,
    .prog_i,
    .pg_erase_i,
    .bk_erase_i,
    .erase_suspend_req_i,
    .part_i,
    .info_sel_i,
    .addr_i,
    .prog_data_i,
    .prog_last_i,
    .prog_type_i,
    .addr_key_i,
    .data_key_i,
    .rand_addr_key_i,
    .rand_data_key_i,
    .rd_buf_en_i,
    .flash_disable_i,
    .prim_flash_rsp_i,
    .prim_flash_req_o,
    .host_req_rdy_o,
    .host_req_done_o,
    .rd_done_o,
    .prog_done_o,
    .erase_done_o,
    .rd_data_o,
    .rd_err_o,
    .ecc_single_err_o,
    .ecc_addr_o,
    .fsm_err_o,
    .prog_intg_err_o,
    .relbl_ecc_err_o,
    .intg_ecc_err_o,
    .spurious_ack_o,
    .arb_err_o,
    .host_gnt_err_o
  );

  defparam dut.u_state_regs.EnableAlertTriggerSVA = 0;
  defparam dut.gen_prog_data.u_prog.u_state_regs.EnableAlertTriggerSVA = 0;

  assign macro_req = prim_flash_req_o.rd_req |
                     prim_flash_req_o.prog_req |
                     prim_flash_req_o.pg_erase_req |
                     prim_flash_req_o.bk_erase_req |
                     prim_flash_req_o.erase_suspend_req;

  always #5 clk = ~clk;

  always_comb begin
    prim_flash_rsp_i.ack = macro_req;
    prim_flash_rsp_i.rdata = '1;
  end

  always_ff @(posedge clk or negedge rst_ni) begin
    if (!rst_ni) begin
      prim_flash_rsp_i.done <= 1'b0;
      done_countdown <= -1;
    end else begin
      prim_flash_rsp_i.done <= 1'b0;
      if (macro_req && done_countdown < 0) begin
        done_countdown <= 2;
      end else if (done_countdown == 0) begin
        prim_flash_rsp_i.done <= 1'b1;
        done_countdown <= -1;
      end else if (done_countdown > 0) begin
        done_countdown <= done_countdown - 1;
      end
    end
  end

  initial begin
    clk = 1'b0;
    rst_ni = 1'b0;
    host_req_i = 1'b0;
    host_scramble_en_i = 1'b0;
    host_ecc_en_i = 1'b0;
    host_addr_i = '0;
    req_i = 1'b0;
    scramble_en_i = 1'b0;
    ecc_en_i = 1'b0;
    he_en_i = 1'b0;
    rd_i = 1'b0;
    prog_i = 1'b0;
    pg_erase_i = 1'b0;
    bk_erase_i = 1'b0;
    erase_suspend_req_i = 1'b0;
    part_i = FlashPartData;
    info_sel_i = '0;
    addr_i = '0;
    prog_data_i = '0;
    prog_last_i = 1'b1;
    prog_type_i = FlashProgNormal;
    addr_key_i = '0;
    data_key_i = '0;
    rand_addr_key_i = '0;
    rand_data_key_i = '0;
    rd_buf_en_i = 1'b0;
    flash_disable_i = MuBi4False;
    saw_macro_req = 1'b0;
    saw_erase_done = 1'b0;

    repeat (5) @(posedge clk);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk);

    req_i = 1'b1;
    pg_erase_i = 1'b1;

    repeat (40) begin
      @(posedge clk);
      if (prim_flash_req_o.pg_erase_req) begin
        saw_macro_req = 1'b1;
      end
      if (erase_done_o) begin
        saw_erase_done = 1'b1;
        req_i = 1'b0;
        pg_erase_i = 1'b0;
      end
    end

    if (!saw_macro_req) begin
      $display("TB_FAIL: controller erase request never reached the flash macro");
      $fatal(1);
    end

    if (!saw_erase_done) begin
      $display("TB_FAIL: controller erase request did not complete");
      $fatal(1);
    end

    if (fsm_err_o || arb_err_o || host_gnt_err_o || prog_intg_err_o ||
        relbl_ecc_err_o || intg_ecc_err_o || spurious_ack_o) begin
      $display("TB_FAIL: unexpected internal error output asserted");
      $fatal(1);
    end

    $display("TB_PASS: controller erase completed when flash ack behaved like ready");
    $finish;
  end
endmodule
EOF

set +e
timeout 1800s fusesoc --cores-root /home/opentitan --cores-root "$TB_DIR" \
  run --no-export --target=sim --tool=vcs --flag=fileset_ip --build-root "$BUILD_DIR" \
  lowrisc:dv:flash_phy_core_lockup_tb 2>&1 | tee "$RUN_LOG"
rc=${PIPESTATUS[0]}
set -e

if [[ $rc -eq 0 ]] && grep -q "TB_PASS:" "$RUN_LOG" && ! grep -q "TB_FAIL:" "$RUN_LOG"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit "$rc"

#!/bin/bash
set -euo pipefail

cd /home/opentitan || exit 1

TEST_NAME="spi_p2s_dummy_cycle_gate"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
TB_SRC="${TB_DIR}/tb.sv"
FILES_F="${TB_DIR}/files.f"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
PASS_SENTINEL="${TB_DIR}/sim.pass"
FAIL_SENTINEL="${TB_DIR}/sim.fail"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_SRC}" <<'EOF'
`timescale 1ns/1ps

module tb;
  import spi_device_pkg::*;

  string pass_sentinel = "/home/opentitan/.tb_spi_p2s_dummy_cycle_gate/sim.pass";
  string fail_sentinel = "/home/opentitan/.tb_spi_p2s_dummy_cycle_gate/sim.fail";

  logic clk_i = 0;
  logic rst_ni = 0;
  logic data_valid_i = 0;
  spi_byte_t data_i = 8'hA5;
  logic data_sent_o;
  logic csb_i = 0;
  logic [3:0] s_en_o;
  logic [3:0] s_o;
  logic cpha_i = 1'b1;
  logic order_i = 1'b0;
  io_mode_e io_mode_i = SingleIO;

  spi_p2s dut (
    .clk_i,
    .rst_ni,
    .data_valid_i,
    .data_i,
    .data_sent_o,
    .csb_i,
    .s_en_o,
    .s_o,
    .cpha_i,
    .order_i,
    .io_mode_i
  );

  always #5 clk_i = ~clk_i;

  task automatic tb_fail(input string msg);
    begin
      $display("TB_CHECK_FAIL %0s", msg);
      void'($system({"touch ", fail_sentinel}));
      $finish;
    end
  endtask

  initial begin
    #500;
    tb_fail("timeout waiting for spi_p2s check to complete");
  end

  initial begin
    repeat (2) @(posedge clk_i);
    @(negedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    io_mode_i = DualIO;
    data_valid_i = 1'b1;

    // Drain an initial byte so the next valid phase starts after a payload-sized transfer.
    repeat (8) @(posedge clk_i);
    #1;
    if (data_sent_o !== 1'b0) begin
      tb_fail($sformatf("data_sent_o unexpectedly high after initial transfer, got %b",
                        data_sent_o));
    end

    // Four dummy cycles for a Fast Read Dual transaction must not advance the transfer.
    data_valid_i = 1'b0;
    repeat (4) begin
      @(posedge clk_i);
      #1;
      if (data_sent_o !== 1'b0) begin
        tb_fail($sformatf("data_sent_o asserted during dummy cycles, got %b",
                          data_sent_o));
      end
      if (s_en_o !== 4'b0000) begin
        tb_fail($sformatf("s_en_o should be 0000 during dummy cycles, got %b", s_en_o));
      end
    end

    data_valid_i = 1'b1;

    @(posedge clk_i);
    #1;
    if (s_en_o !== 4'b0011) begin
      tb_fail($sformatf("expected DualIO enable 0011 when payload resumes, got %b", s_en_o));
    end
    if (data_sent_o !== 1'b0) begin
      tb_fail($sformatf("data_sent_o asserted too early after dummy cycles, got %b",
                        data_sent_o));
    end

    @(posedge clk_i);
    #1;
    if (data_sent_o !== 1'b1) begin
      tb_fail($sformatf("expected data_sent_o after two valid DualIO beats, got %b",
                        data_sent_o));
    end

    $display("TB_CHECK_PASS");
    void'($system({"touch ", pass_sentinel}));
