#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="rv_dm_sba_badaddr_error"
SCRATCH_ROOT="/home/opentitan/.tb_${TEST_NAME}"

python - <<'PY'
from pathlib import Path

seq_lib = Path("/home/opentitan/hw/ip/rv_dm/dv/env/seq_lib/rv_dm_sba_tl_access_vseq_lib.sv")
seq_marker = "class rv_dm_sba_badaddr_error_vseq extends rv_dm_base_vseq;"
seq_block = """

class rv_dm_sba_badaddr_error_vseq extends rv_dm_base_vseq;
  `uvm_object_utils(rv_dm_sba_badaddr_error_vseq)
  `uvm_object_new

  constraint lc_hw_debug_en_c {
    lc_hw_debug_en == lc_ctrl_pkg::On;
  }

  constraint scanmode_c {
    scanmode == prim_mubi_pkg::MuBi4False;
  }

  constraint unavailable_c {
    unavailable == 0;
  }

  virtual task body();
    sba_access_item req;

    cfg.rv_dm_vif.disable_tlul_assert_host_sba_resp_svas = 1'b1;
    sba_tl_device_seq_stop();
    sba_tl_device_seq_start(.min_rsp_delay(0),
                            .max_rsp_delay(0),
                            .rsp_abort_pct(0),
                            .d_error_pct(100),
                            .d_chan_intg_err_pct(0));

    req = sba_access_item::type_id::create("req_err");
    req.disable_req_randomization();
    req.disable_rsp_randomization();
    req.bus_op = BusOpWrite;
    req.size = SbaAccessSize32b;
    req.addr = 32'h0000_0100;
    req.wdata = 32'hdead_beef;
    req.readonaddr = 1'b0;
    req.readondata = 1'b0;
    req.autoincrement = 1'b0;

    sba_access(.jtag_dmi_ral(jtag_dmi_ral), .cfg(cfg.m_jtag_agent_cfg), .req(req));

    `DV_CHECK_EQ(req.is_err, SbaErrBadAddr)
    `DV_CHECK_EQ(req.is_busy_err, 1'b0)
    `DV_CHECK_EQ(req.timed_out, 1'b0)
  endtask

endclass
"""
text = seq_lib.read_text(encoding="utf-8")
if seq_marker not in text:
    seq_lib.write_text(text + seq_block, encoding="utf-8")

cfg_path = Path("/home/opentitan/hw/ip/rv_dm/dv/rv_dm_sim_cfg.hjson")
cfg_marker = "name: rv_dm_sba_badaddr_error"
cfg_anchor = """    {
      name: rv_dm_autoincr_sba_tl_access
      uvm_test_seq: rv_dm_autoincr_sba_tl_access_vseq
      reseed: 20
    }
"""
cfg_block = """    {
      name: rv_dm_sba_badaddr_error
      uvm_test_seq: rv_dm_sba_badaddr_error_vseq
      run_opts: ["+en_scb=0"]
      reseed: 1
    }
"""
cfg_text = cfg_path.read_text(encoding="utf-8")
if cfg_marker not in cfg_text:
    cfg_path.write_text(cfg_text.replace(cfg_anchor, cfg_anchor + cfg_block), encoding="utf-8")
PY
inject_rc=$?

if [ "$inject_rc" -ne 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "$inject_rc"
fi

rm -rf "$SCRATCH_ROOT"
timeout 1800s python util/dvsim/dvsim.py \
  hw/ip/rv_dm/dv/rv_dm_sim_cfg.hjson \
  -i rv_dm_sba_badaddr_error \
  -t vcs \
  --fixed-seed 1 \
  --build-seed 1 \
  --scratch-root "$SCRATCH_ROOT"
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

resolved_issues.body:
On investigation of the implementation of the [security countermeasure verification framework](https://docs.opentitan.org/doc/ug/sec_cm_dv_framework/) it seems that the LC State and LC Count registers can be implemented using prim_sparse_fsm_flop which should enable the pre-defined security countermeasure tests for those registers.

Currently they are implemented using prim_flop:

```
 logic [LcStateWidth-1:0] lc_state_raw_q;
  assign lc_state_q = lc_state_e'(lc_state_raw_q);
  prim_flop #(
    .Width(LcStateWidth),
    .ResetValue(LcStateWidth'(LcStScrap))
  ) u_state_regs (
    .clk_i,
    .rst_ni,
    .d_i ( lc_state_d     ),
    .q_o ( lc_state_raw_q )
  );

  logic [LcCountWidth-1:0] lc_cnt_raw_q;
  assign lc_cnt_q = lc_cnt_e'(lc_cnt_raw_q);
  prim_flop #(
    .Width(LcCountWidth),
    .ResetValue(LcCountWidth'(LcCnt24))
  ) u_cnt_regs (
    .clk_i,
    .rst_ni,
    .d_i ( lc_cnt_d     ),
    .q_o ( lc_cnt_raw_q )
  );
```
This is different from LC FSM registers which use prim_sparse_fsm_flop, the interface appears to be the same except for the type parameter (StateEnumT).
```
  logic [FsmStateWidth-1:0] fsm_state_raw_q;
  assign fsm_state_q = fsm_state_e'(fsm_state_raw_q);
  prim_sparse_fsm_flop #(
    .StateEnumT(fsm_state_e),
    .Width(FsmStateWidth),
    .ResetValue(FsmStateWidth'(ResetSt))
  ) u_fsm_state_regs (
    .clk_i,
    .rst_ni,
    .state_i ( fsm_state_d     ),
    .state_o ( fsm_state_raw_q )
  );

```

