cat > "${SEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class spi_device_pass_busy_block_vseq extends spi_device_pass_base_vseq;
  `uvm_object_utils(spi_device_pass_busy_block_vseq)
  `uvm_object_new

  localparam bit [7:0] PassCmd = 8'hA5;
  localparam bit [23:0] PassAddr = 24'h123456;
  localparam string PassEnPath = "tb.pass_out.passthrough_en";

  virtual task body();
    bit [31:0] device_word_rsp;
    bit [31:0] address_command;
    uvm_hdl_data_t pass_en;
    int unsigned cmd_info_idx;

    spi_device_passthrough_init();
    cfg.clk_rst_vif.wait_clks(20);

    `DV_CHECK_FATAL(uvm_hdl_check_path(PassEnPath))
    `DV_CHECK_FATAL(uvm_hdl_read(PassEnPath, pass_en))
    `DV_CHECK_EQ(pass_en[0], 1'b1, "Passthrough should start enabled")

    cmd_info_idx = spi_device_pkg::CmdInfoReserveStart;
    ral.cmd_info[cmd_info_idx].valid.set(1'b1);
    ral.cmd_info[cmd_info_idx].opcode.set(PassCmd);
    ral.cmd_info[cmd_info_idx].addr_mode.set(Addr3B);
    ral.cmd_info[cmd_info_idx].addr_swap_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].mbyte_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].dummy_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].dummy_size.set('0);
    ral.cmd_info[cmd_info_idx].payload_en.set(4'b0001);
    ral.cmd_info[cmd_info_idx].payload_dir.set(PayloadIn);
    ral.cmd_info[cmd_info_idx].payload_swap_en.set(1'b0);
    ral.cmd_info[cmd_info_idx].upload.set(1'b1);
    ral.cmd_info[cmd_info_idx].busy.set(1'b1);
    csr_update(.csr(ral.cmd_info[cmd_info_idx]));

    order_cmd_bits(PassCmd, PassAddr, address_command);
    spi_host_xfer_word(address_command, device_word_rsp);

    cfg.clk_rst_vif.wait_clks(50);
    csr_rd_check(.ptr(ral.flash_status), .compare_value(32'h1));

    `DV_CHECK_FATAL(uvm_hdl_read(PassEnPath, pass_en))
    `DV_CHECK_EQ(pass_en[0], 1'b0, "Passthrough must be blocked while BUSY is set")
  endtask
endclass
EOF

if ! grep -Fq 'spi_device_pass_busy_block_vseq.sv' "${VSEQ_LIST}"; then
