tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -u
set -o pipefail

TEST_NAME="rv_dm_sba_subword_vcs"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
SUCCESS_STAMP="${TB_DIR}/success.stamp"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'SV'
`timescale 1ns/1ps

module tb;
  import dm::*;

  logic clk_i;
  logic rst_ni;
  logic dmi_rst_ni;
  logic testmode_i;

  logic dmi_req_valid_i;
  logic dmi_req_ready_o;
  dmi_req_t dmi_req_i;
  logic dmi_resp_valid_o;
  logic dmi_resp_ready_i;
  dmi_resp_t dmi_resp_o;

  logic ndmreset_o;
  logic dmactive_o;
  hartinfo_t [0:0] hartinfo_i;
  logic [0:0] halted_i;
  logic [0:0] unavailable_i;
  logic [0:0] resumeack_i;
  logic [19:0] hartsel_o;
  logic [0:0] haltreq_o;
  logic [0:0] resumereq_o;
  logic clear_resumeack_o;

  logic cmd_valid_o;
  command_t cmd_o;
  logic cmderror_valid_i;
  cmderr_e cmderror_i;
  logic cmdbusy_i;

  logic [dm::ProgBufSize-1:0][31:0] progbuf_o;
  logic [dm::DataCount-1:0][31:0] data_o;
  logic [dm::DataCount-1:0][31:0] data_i;
  logic data_valid_i;

  logic [31:0] sbaddress_from_sba;
  logic [31:0] sbaddress_to_sba;
  logic sbaddress_write_valid_o;
  logic sbreadonaddr_o;
  logic sbautoincrement_o;
  logic [2:0] sbaccess_o;
  logic sbreadondata_o;
  logic [31:0] sbdata_to_sba;
  logic sbdata_read_valid_o;
  logic sbdata_write_valid_o;
  logic [31:0] sbdata_from_sba;
  logic sbdata_valid_from_sba;
  logic sbbusy_from_sba;
  logic sberror_valid_from_sba;
  logic [2:0] sberror_from_sba;

  logic master_req_o;
  logic [31:0] master_add_o;
  logic master_we_o;
  logic [31:0] master_wdata_o;
  logic [3:0] master_be_o;
  logic master_gnt_i;
  logic master_r_valid_i;
  logic [31:0] master_r_rdata_i;

  logic seen_req;
  logic [3:0] seen_be;
  logic [31:0] seen_wdata;
  logic [31:0] resp_data;
  string success_file;
  integer success_fd;

  dm_csrs #(
    .NrHarts(1),
    .BusWidth(32)
  ) u_dm_csrs (
    .clk_i,
    .rst_ni,
    .testmode_i,
    .dmi_rst_ni,
    .dmi_req_valid_i,
    .dmi_req_ready_o,
    .dmi_req_i,
    .dmi_resp_valid_o,
    .dmi_resp_ready_i,
    .dmi_resp_o,
    .ndmreset_o,
    .dmactive_o,
    .hartinfo_i,
    .halted_i,
    .unavailable_i,
    .resumeack_i,
    .hartsel_o,
    .haltreq_o,
    .resumereq_o,
    .clear_resumeack_o,
    .cmd_valid_o,
    .cmd_o,
    .cmderror_valid_i,
    .cmderror_i,
    .cmdbusy_i,
    .progbuf_o,
    .data_o,
    .data_i,
    .data_valid_i,
    .sbaddress_o(sbaddress_to_sba),
    .sbaddress_i(sbaddress_from_sba),
    .sbaddress_write_valid_o,
    .sbreadonaddr_o,
    .sbautoincrement_o,
    .sbaccess_o,
    .sbreadondata_o,
    .sbdata_o(sbdata_to_sba),
    .sbdata_read_valid_o,
    .sbdata_write_valid_o,
    .sbdata_i(sbdata_from_sba),
    .sbdata_valid_i(sbdata_valid_from_sba),
    .sbbusy_i(sbbusy_from_sba),
    .sberror_valid_i(sberror_valid_from_sba),
    .sberror_i(sberror_from_sba)
  );

  dm_sba #(
    .BusWidth(32)
  ) u_dm_sba (
    .clk_i,
    .rst_ni,
    .dmactive_i(dmactive_o),
    .master_req_o,
    .master_add_o,
    .master_we_o,
    .master_wdata_o,
    .master_be_o,
    .master_gnt_i,
    .master_r_valid_i,
    .master_r_rdata_i,
    .sbaddress_i(sbaddress_to_sba),
    .sbaddress_write_valid_i(sbaddress_write_valid_o),
    .sbreadonaddr_i(sbreadonaddr_o),
    .sbaddress_o(sbaddress_from_sba),
    .sbautoincrement_i(sbautoincrement_o),
    .sbaccess_i(sbaccess_o),
    .sbreadondata_i(sbreadondata_o),
    .sbdata_i(sbdata_to_sba),
    .sbdata_read_valid_i(sbdata_read_valid_o),
    .sbdata_write_valid_i(sbdata_write_valid_o),
    .sbdata_o(sbdata_from_sba),
    .sbdata_valid_o(sbdata_valid_from_sba),
    .sbbusy_o(sbbusy_from_sba),
    .sberror_valid_o(sberror_valid_from_sba),
    .sberror_o(sberror_from_sba)
  );

  initial clk_i = 0;
  always #5 clk_i = ~clk_i;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      master_r_valid_i <= 1'b0;
      seen_req <= 1'b0;
      seen_be <= '0;
      seen_wdata <= '0;
    end else begin
      master_r_valid_i <= master_req_o;
      if (master_req_o && master_we_o && !seen_req) begin
        seen_req <= 1'b1;
        seen_be <= master_be_o;
        seen_wdata <= master_wdata_o;
      end
    end
  end

  assign master_gnt_i = 1'b1;
  assign master_r_rdata_i = 32'h11223344;

  task automatic dmi_write(input logic [6:0] addr, input logic [31:0] data);
    begin
      @(negedge clk_i);
      dmi_req_i.addr = addr;
      dmi_req_i.op = DTM_WRITE;
      dmi_req_i.data = data;
      dmi_req_valid_i = 1'b1;
      do @(posedge clk_i); while (!dmi_req_ready_o);
      @(negedge clk_i);
      dmi_req_valid_i = 1'b0;
      dmi_req_i = '0;
      do @(posedge clk_i); while (!dmi_resp_valid_o);
      resp_data = dmi_resp_o.data;
    end
  endtask

  initial begin
    testmode_i = 1'b0;
    dmi_req_valid_i = 1'b0;
    dmi_req_i = '0;
    dmi_resp_ready_i = 1'b1;
    halted_i = '0;
    unavailable_i = '0;
    resumeack_i = '0;
    hartinfo_i = '0;
    cmderror_valid_i = 1'b0;
    cmderror_i = CmdErrNone;
    cmdbusy_i = 1'b0;
    data_i = '0;
    data_valid_i = 1'b0;
    rst_ni = 1'b0;
    dmi_rst_ni = 1'b0;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    dmi_rst_ni = 1'b1;
    repeat (5) @(posedge clk_i);

    dmi_write(DMControl[6:0], 32'h0000_0001);
    repeat (2) @(posedge clk_i);
    if (dmactive_o !== 1'b1) begin
      $display("TB_ERROR: dmactive did not assert");
      $fatal(1);
    end

    dmi_write(SBCS[6:0], 32'h0000_0000);
    dmi_write(SBAddress0[6:0], 32'h0000_0001);
    dmi_write(SBData0[6:0], 32'h0000_00A5);

    repeat (10) @(posedge clk_i);
    if (!seen_req) begin
      $display("TB_ERROR: no SBA write request observed");
      $fatal(1);
    end

    if (seen_be !== 4'b0010) begin
      $display("TB_ERROR: expected byte enable 0010 for 8-bit write at addr 1, got %b", seen_be);
      $fatal(1);
    end

    if (seen_wdata !== 32'h0000_A500) begin
      $display("TB_ERROR: expected shifted write data 0x0000A500, got 0x%08x", seen_wdata);
      $fatal(1);
    end

    if (!$value$plusargs("success_file=%s", success_file)) begin
      $display("TB_ERROR: missing success_file plusarg");
      $fatal(1);
    end

    success_fd = $fopen(success_file, "w");
    if (success_fd == 0) begin
      $display("TB_ERROR: failed to create success stamp %s", success_file);
      $fatal(1);
    end

    $fdisplay(success_fd, "PASS");
    $fclose(success_fd);
    $display("TB_SUCCESS: observed 8-bit SBA write with be=%b wdata=0x%08x", seen_be, seen_wdata);
    $finish;
  end
endmodule
SV

set +e
vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  -l "${COMPILE_LOG}" \
  /home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv \
  /home/opentitan/hw/ip/prim/rtl/prim_fifo_sync.sv \
  /home/opentitan/hw/vendor/pulp_riscv_dbg/src/dm_pkg.sv \
  /home/opentitan/hw/vendor/pulp_riscv_dbg/src/dm_csrs.sv \
  /home/opentitan/hw/vendor/pulp_riscv_dbg/src/dm_sba.sv \
  "${TB_DIR}/tb.sv" \
  -o "${TB_DIR}/simv"
compile_rc=$?

sim_rc=1
if [ "${compile_rc}" -eq 0 ]; then
  rm -f "${SUCCESS_STAMP}"
  "${TB_DIR}/simv" +success_file="${SUCCESS_STAMP}" -l "${RUN_LOG}"
  sim_rc=$?
fi
set -e

if [ "${compile_rc}" -eq 0 ] && [ "${sim_rc}" -eq 0 ] && [ -f "${SUCCESS_STAMP}" ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

if [ "${compile_rc}" -ne 0 ] && [ -f "${COMPILE_LOG}" ]; then
  tail -n 40 "${COMPILE_LOG}"
elif [ -f "${RUN_LOG}" ]; then
  tail -n 40 "${RUN_LOG}"
fi

echo "HWE_BENCH_RESULTS_START"
echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

resolved_issues.body:
@zi-v @arnonsha 
During full chip simulation a bug was found on the clocks bypass logic.

The bug involve the incorrect step down  (div4-to-div2) of the IO clock in the lc_ctrl/clkmgr 
module/s during other clocks bypass modes.

In order to fix the issue, the AST added a new signal to indicate to the lc_ctrl/clkmgr
modules that the IO clock is 48Mhz. 
The interface to the lc_ctrl/clkmgr needs to include a new signal:

-	clk_src_io_48m_o    //  0: 96MHz, 1: 48MHz

This signal is needed to be used for the div4/div2 selection in the lc_ctrl/clkmgr module/s.

The reason that this signal is needed relate to the fact the lc_ctrl/clkmgr moduless are not aware of  clocks  bypass other modes. 

// IO Clock Source is 48MHz
////////////////////////////////////////
// Oscillator source is always 96MHz. 
// External Bypass source is assume to be 96MHz until it is ebabled as 48MHz 
assign clk_src_io_48m_o = io_clk_byp_sel && io_clk_byp_en && !ext_freq_is_96m;

See monorail Issue 101: [Gold] IO clock is 48MHz indication from AST for mode details.

