tb_script:
#!/bin/bash
cd /home/opentitan
set -uo pipefail
set +e

TEST_NAME="entropy_src_fw_ov_main_sm"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
BUILD_LOG="${TB_DIR}/build.log"
RUN_LOG="${TB_DIR}/run.log"
SIM_BIN="${TB_DIR}/simv"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_assert.sv" <<'EOF'
`ifndef PRIM_ASSERT_SV
`define PRIM_ASSERT_SV
`define ASSERT_INIT_NET(__name, __expr)
`endif
EOF

cat > "${TB_DIR}/prim_flop.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input logic clk_i,
  input logic rst_ni,
  input logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule
EOF

python - <<'PY'
from pathlib import Path
import re

tb_dir = Path("/home/opentitan/.tb_entropy_src_fw_ov_main_sm")
rtl_path = Path("/home/opentitan/hw/ip/entropy_src/rtl/entropy_src_main_sm.sv")
text = rtl_path.read_text(encoding="utf-8")
match = re.search(r"module\s+entropy_src_main_sm\b.*?\((.*?)\);\s*", text, re.S)
if match is None:
    raise SystemExit("Unable to parse entropy_src_main_sm module header")
ports = re.findall(r"\b(?:input|output|inout)\b[^;\n,]*?\b([A-Za-z_][A-Za-z0-9_]*)\b(?=\s*(?:,|\n))", match.group(1))

decls = """
  logic clk_i;
  logic rst_ni;
  logic enable_i;
  logic fw_ov_ent_insert_i;
  logic fw_ov_sha3_start_i;
  logic fw_ov_entropy_insert_i;
  logic fw_ov_insert_i;
  logic fw_ov_mode_i;
  logic sha3_absorbed_i;
  logic sha3_block_processed_i;
  logic ht_done_pulse_i;
  logic ht_fail_pulse_i;
  logic alert_thresh_fail_i;
  logic sfifo_esfinal_full_i;
  logic rst_alert_cntr_o;
  logic bypass_mode_i;
  logic main_stage_rdy_i;
  logic bypass_stage_rdy_i;
  logic sha3_state_vld_i;
  logic main_stage_push_o;
  logic bypass_stage_pop_o;
  logic boot_phase_done_o;
  logic sha3_start_o;
  logic sha3_process_o;
  logic sha3_done_o;
  logic cs_aes_halt_req_o;
  logic cs_aes_halt_ack_i;
  logic local_escalate_i;
  logic main_sm_alert_o;
  logic main_sm_idle_o;
"""

signal_names = [
    "clk_i", "rst_ni", "enable_i", "fw_ov_ent_insert_i", "fw_ov_sha3_start_i",
    "fw_ov_entropy_insert_i", "fw_ov_insert_i", "fw_ov_mode_i",
    "sha3_absorbed_i", "sha3_block_processed_i", "ht_done_pulse_i",
    "ht_fail_pulse_i", "alert_thresh_fail_i", "sfifo_esfinal_full_i",
    "rst_alert_cntr_o", "bypass_mode_i", "main_stage_rdy_i",
    "bypass_stage_rdy_i", "sha3_state_vld_i", "main_stage_push_o",
    "bypass_stage_pop_o", "boot_phase_done_o", "sha3_start_o",
    "sha3_process_o", "sha3_done_o", "cs_aes_halt_req_o",
    "cs_aes_halt_ack_i", "local_escalate_i", "main_sm_alert_o",
    "main_sm_idle_o",
]
inst = ",\n".join(f"    .{name}({name})" for name in signal_names if name in ports)

template = """`timescale 1ns/1ps

module tb;
__DECLS__
  bit phase2_started;
  bit saw_early_start;
  bit saw_early_process;
  bit saw_start_after_fw_cmd;
  bit saw_process_after_fw_cmd;
  bit saw_main_push;

  entropy_src_main_sm dut (
__INST__
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  always @(negedge rst_ni) begin
    saw_early_start <= 1'b0;
    saw_early_process <= 1'b0;
    saw_start_after_fw_cmd <= 1'b0;
    saw_process_after_fw_cmd <= 1'b0;
    saw_main_push <= 1'b0;
  end

  always @(posedge sha3_start_o) begin
    if (rst_ni) begin
      if (!phase2_started || !fw_ov_sha3_start_i) begin
        saw_early_start <= 1'b1;
      end else begin
        saw_start_after_fw_cmd <= 1'b1;
      end
    end
  end

  always @(posedge sha3_process_o) begin
    if (rst_ni) begin
      if (!phase2_started) begin
        saw_early_process <= 1'b1;
      end else if (!fw_ov_sha3_start_i) begin
        saw_process_after_fw_cmd <= 1'b1;
      end
    end
  end

  always @(posedge main_stage_push_o) begin
    if (rst_ni && phase2_started) begin
      saw_main_push <= 1'b1;
    end
  end

  task automatic pulse_ht_done(input logic fail);
    begin
      @(negedge clk_i);
      ht_fail_pulse_i = fail;
      ht_done_pulse_i = 1'b1;
      @(negedge clk_i);
      ht_done_pulse_i = 1'b0;
      ht_fail_pulse_i = 1'b0;
    end
  endtask

  task automatic wait_cycles(input int count);
    repeat (count) @(posedge clk_i);
  endtask

  initial begin
    rst_ni = 1'b0;
    enable_i = 1'b0;
    fw_ov_ent_insert_i = 1'b1;
    fw_ov_entropy_insert_i = 1'b1;
    fw_ov_insert_i = 1'b1;
    fw_ov_mode_i = 1'b1;
    fw_ov_sha3_start_i = 1'b0;
    sha3_absorbed_i = 1'b0;
    sha3_block_processed_i = 1'b0;
    ht_done_pulse_i = 1'b0;
    ht_fail_pulse_i = 1'b0;
    alert_thresh_fail_i = 1'b0;
    sfifo_esfinal_full_i = 1'b0;
    bypass_mode_i = 1'b0;
    main_stage_rdy_i = 1'b1;
    bypass_stage_rdy_i = 1'b0;
    sha3_state_vld_i = 1'b0;
    cs_aes_halt_ack_i = 1'b1;
    local_escalate_i = 1'b0;
    phase2_started = 1'b0;
    saw_early_start = 1'b0;
    saw_early_process = 1'b0;
    saw_start_after_fw_cmd = 1'b0;
    saw_process_after_fw_cmd = 1'b0;
    saw_main_push = 1'b0;

    wait_cycles(2);
    rst_ni = 1'b1;
    wait_cycles(1);
    enable_i = 1'b1;

    pulse_ht_done(1'b0);
    pulse_ht_done(1'b0);
    wait_cycles(8);

    if (saw_early_start || saw_early_process) begin
      $fatal(1, "sha3 activity started before explicit FW start control");
    end

    phase2_started = 1'b1;

    @(negedge clk_i);
    fw_ov_sha3_start_i = 1'b1;
    wait_cycles(4);

    if (!saw_start_after_fw_cmd) begin
      $fatal(1, "sha3_start_o never asserted after explicit FW start control");
    end

    @(negedge clk_i);
    fw_ov_sha3_start_i = 1'b0;
    sha3_absorbed_i = 1'b1;
    sha3_block_processed_i = 1'b1;
    @(negedge clk_i);
    sha3_absorbed_i = 1'b0;
    sha3_block_processed_i = 1'b0;

    repeat (20) begin
      @(posedge clk_i);
      if (saw_process_after_fw_cmd) begin
        @(negedge clk_i);
        sha3_state_vld_i = 1'b1;
        @(negedge clk_i);
        sha3_state_vld_i = 1'b0;
        break;
      end
    end

    if (!saw_process_after_fw_cmd) begin
      $fatal(1, "sha3_process_o never asserted after FW released start control");
    end

    repeat (20) begin
      @(posedge clk_i);
      if (saw_main_push) begin
        $display("TB PASS");
        $finish;
      end
    end

    $fatal(1, "SHA3 flow never produced main_stage_push_o");
  end
endmodule
"""

tb = template.replace("__DECLS__", decls).replace("__INST__", inst)
(tb_dir / "tb.sv").write_text(tb, encoding="utf-8")
PY

timeout 1200 bash -lc "
  set -e
  cd /home/opentitan
  vcs -full64 -licqueue -sverilog \
    +incdir+${TB_DIR} \
    -Mdir=${TB_DIR}/csrc \
    -o ${SIM_BIN} \
    ${TB_DIR}/tb.sv \
    hw/ip/entropy_src/rtl/entropy_src_main_sm.sv \
    hw/ip/prim/rtl/prim_sparse_fsm_flop.sv \
    ${TB_DIR}/prim_flop.sv \
    > ${BUILD_LOG} 2>&1
  ${SIM_BIN} > ${RUN_LOG} 2>&1
"
rc=$?

if [[ ${rc} -eq 0 ]] && [[ -f "${RUN_LOG}" ]]; then
  if grep -q "Fatal:" "${RUN_LOG}" || ! grep -q "TB PASS" "${RUN_LOG}"; then
    rc=1
  fi
fi

if [[ ${rc} -eq 0 ]]; then
  emit_result "PASS"
else
  [[ -f "${BUILD_LOG}" ]] && tail -n 80 "${BUILD_LOG}"
  [[ -f "${RUN_LOG}" ]] && tail -n 80 "${RUN_LOG}"
  emit_result "FAIL"
fi

exit "${rc}"

