`timescale 1ns/1ps

module prim_buf #(
  parameter int Width = 1
) (
  input        [Width-1:0] in_i,
  output logic [Width-1:0] out_o
);
  assign out_o = in_i;
endmodule

module prim_flop #(
  parameter int               Width      = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule

module tb_prim_count_default_max;
  import prim_count_pkg::*;
  import "DPI-C" function void tb_dpi_exit(input int status);

  localparam int Width = 4;

  logic clk_i;
  logic rst_ni;
  logic clr_i;
  logic set_i;
  logic [Width-1:0] set_cnt_i;
  logic en_i;
  logic [Width-1:0] step_i;
  logic [Width-1:0] cnt_o;
  logic err_o;
  string scenario;

  prim_count #(
    .Width(Width),
    .OutSelDnCnt(1'b1),
    .CntStyle(CrossCnt)
  ) u_dut (
    .clk_i,
    .rst_ni,
    .clr_i,
    .set_i,
    .set_cnt_i,
    .en_i,
    .step_i,
    .cnt_o,
    .err_o
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic pulse_set(input logic [Width-1:0] value);
    begin
      @(negedge clk_i);
      set_cnt_i = value;
      set_i = 1'b1;
      @(negedge clk_i);
      set_i = 1'b0;
    end
  endtask

  task automatic pulse_clr();
    begin
      @(negedge clk_i);
      clr_i = 1'b1;
      @(negedge clk_i);
      clr_i = 1'b0;
    end
  endtask

  task automatic expect_default_max(input string tag);
    begin
      #1;
      if (cnt_o !== {Width{1'b1}}) begin
        $display("scenario %s: expected cnt_o=%0h, got %0h", tag, {Width{1'b1}}, cnt_o);
        tb_dpi_exit(1);
      end
      if (err_o !== 1'b0) begin
        $display("scenario %s: expected err_o=0, got %0b", tag, err_o);
        tb_dpi_exit(1);
      end
    end
  endtask

  initial begin
    if (!$value$plusargs("scenario=%s", scenario)) scenario = "reset_default_max";

    rst_ni = 1'b0;
    clr_i = 1'b0;
    set_i = 1'b0;
    set_cnt_i = '0;
    en_i = 1'b0;
    step_i = 4'h1;

    repeat (2) @(negedge clk_i);
    rst_ni = 1'b1;
    @(posedge clk_i);

    if (scenario == "reset_default_max") begin
      expect_default_max(scenario);
    end else if (scenario == "clear_restores_default_max") begin
      pulse_set(4'h9);
      pulse_clr();
      expect_default_max(scenario);
    end else begin
      $display("unknown scenario %s", scenario);
      tb_dpi_exit(1);
    end

    $display("scenario %s observed default max as expected", scenario);
    tb_dpi_exit(0);
  end
endmodule
EOF

