tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="prim_alert_init_pending_ping"
TB_DIR="/home/opentitan/.tb_prim_alert_init_pending_ping"
BUILD_ROOT="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_alert_init_pending_ping_tb.core" <<'EOF'
CAPI=2:
name: "local:dv:prim_alert_init_pending_ping_tb:0.1"
description: "Minimal prim_alert_receiver pending ping reproducer"

filesets:
  files_tb:
    depend:
      - lowrisc:prim:alert
    files:
      - tb.sv: {file_type: systemVerilogSource}

targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_tb
    tools:
      vcs:
        vcs_options:
          - -timescale=1ns/1ps
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import prim_alert_pkg::*;
  import prim_mubi_pkg::*;

  localparam logic [2:0] Idle        = 3'd0;
  localparam logic [2:0] InitReq     = 3'd4;
  localparam logic [2:0] InitAckWait = 3'd5;

  logic clk = 1'b0;
  logic rst_n = 1'b0;
  mubi4_t init_trig = MuBi4False;
  logic ping_req = 1'b0;
  logic ping_ok;
  logic integ_fail;
  logic alert_o;
  alert_rx_t alert_rx;
  alert_tx_t alert_tx;

  logic ping_sample;
  bit saw_post_init_toggle;
  bit saw_ping_ok;

  always #5 clk = ~clk;

  prim_alert_receiver #(
    .AsyncOn(1'b0)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .init_trig_i(init_trig),
    .ping_req_i(ping_req),
    .ping_ok_o(ping_ok),
    .integ_fail_o(integ_fail),
    .alert_o(alert_o),
    .alert_rx_o(alert_rx),
    .alert_tx_i(alert_tx)
  );

  task automatic fail(input string msg);
    begin
      $display("TB_FAIL: %s", msg);
      $fatal(1, "%s", msg);
    end
  endtask

  task automatic wait_for_state(
      input logic [2:0] expected,
      input int cycles,
      input string msg);
    begin
      repeat (cycles) begin
        @(posedge clk);
        if (dut.state_q === expected) return;
      end
      fail(msg);
    end
  endtask

  task automatic drive_idle;
    begin
      alert_tx.alert_p = 1'b0;
      alert_tx.alert_n = 1'b1;
    end
  endtask

  task automatic drive_sigint;
    begin
      alert_tx.alert_p = 1'b1;
      alert_tx.alert_n = 1'b1;
    end
  endtask

  task automatic drive_alert_handshake;
    begin
      alert_tx.alert_p = 1'b1;
      alert_tx.alert_n = 1'b0;
    end
  endtask

  initial begin
    drive_idle();

    repeat (3) @(posedge clk);
    rst_n = 1'b1;

    // The testbench injects synthetic signal-integrity patterns directly on alert_tx.
    // Disable edge/event assertions that assume only legal differential transitions.
    $assertoff(0, tb.dut.u_decode_alert.gen_sync_assert.RiseCheck_A);
    $assertoff(0, tb.dut.u_decode_alert.gen_sync_assert.FallCheck_A);
    $assertoff(0, tb.dut.u_decode_alert.gen_sync_assert.EventCheck_A);

    // Finish the reset-triggered initialization handshake.
    wait_for_state(InitReq, 2, "receiver did not enter InitReq after reset");
    drive_sigint();
    wait_for_state(InitAckWait, 4, "receiver did not enter InitAckWait during reset init");
    drive_idle();
    wait_for_state(Idle, 8, "receiver did not return to Idle after reset init");

    // Trigger a second init sequence explicitly.
    @(negedge clk);
    init_trig = MuBi4True;
    @(negedge clk);
    init_trig = MuBi4False;

    wait_for_state(InitReq, 3, "receiver did not re-enter InitReq");
    drive_sigint();
    wait_for_state(InitAckWait, 4, "receiver did not reach InitAckWait for explicit init");

    // A ping request that arrives after init_trig is deasserted must stay pending
    // until the receiver leaves InitAckWait.
    ping_sample = alert_rx.ping_p;
    @(negedge clk);
    ping_req = 1'b1;

    repeat (3) begin
      @(posedge clk);
      if (dut.state_q !== InitAckWait) begin
        fail("receiver left InitAckWait before the pending-ping window was checked");
      end
      if (alert_rx.ping_p !== ping_sample) begin
        fail("ping pair toggled while receiver was still in InitAckWait");
      end
    end

    // Once the init handshake finishes, the queued ping must be emitted exactly once.
    drive_idle();
    saw_post_init_toggle = 1'b0;
    repeat (5) begin
      @(posedge clk);
      if (alert_rx.ping_p !== ping_sample) begin
        ping_sample = alert_rx.ping_p;
        saw_post_init_toggle = 1'b1;
        break;
      end
    end
    if (!saw_post_init_toggle) begin
      fail("queued ping request was not emitted after leaving InitAckWait");
    end

    wait_for_state(Idle, 6, "receiver did not return to Idle after init recovery");

    // Emulate the sender response to complete the ping handshake.
    drive_alert_handshake();
    saw_ping_ok = 1'b0;
    repeat (4) begin
      @(posedge clk);
      if (alert_o) begin
        fail("alert_o asserted during a ping response");
      end
      if (ping_ok) begin
        saw_ping_ok = 1'b1;
        break;
      end
    end
    if (!saw_ping_ok) begin
      fail("ping_ok was not observed after the pending ping was emitted");
    end

    @(negedge clk);
    ping_req = 1'b0;
    drive_idle();
    repeat (3) @(posedge clk);

    if (integ_fail) begin
      fail("integ_fail asserted unexpectedly");
    end

    $display("TB_PASS: pending ping stayed queued through init and completed afterwards");
    $finish;
  end

  initial begin
    #10000;
    fail("watchdog timeout");
  end
endmodule
EOF

rm -rf "${BUILD_ROOT}"

set +e
timeout 1800s fusesoc \
  --cores-root /home/opentitan \
  --cores-root "${TB_DIR}" \
  run \
  --no-export \
  --build-root "${BUILD_ROOT}" \
  --target sim \
  --tool vcs \
  local:dv:prim_alert_init_pending_ping_tb:0.1 \
  > "${RUN_LOG}" 2>&1
rc=$?
set -e

[ -f "${RUN_LOG}" ] && tail -n 200 "${RUN_LOG}"

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ] \
  && grep -q "TB_PASS: pending ping stayed queued through init and completed afterwards" "${RUN_LOG}" \
  && ! grep -q "TB_FAIL:" "${RUN_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

