#!/bin/bash
set -euo pipefail

cd /home/opentitan

TB_DIR=/home/opentitan/.tb_boot_data_ecc
mkdir -p "$TB_DIR"

cat > sw/device/silicon_creator/lib/boot_data_functest.c <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

#include <stddef.h>

#include "sw/device/lib/base/bitfield.h"
#include "sw/device/lib/runtime/log.h"
#include "sw/device/lib/testing/check.h"
#include "sw/device/silicon_creator/lib/base/abs_mmio.h"
#include "sw/device/silicon_creator/lib/boot_data.h"
#include "sw/device/silicon_creator/lib/drivers/flash_ctrl.h"
#include "sw/device/silicon_creator/lib/test_main.h"

#include "flash_ctrl_regs.h"  // Generated.
#include "hw/top_earlgrey/sw/autogen/top_earlgrey.h"

const test_config_t kTestConfig;

static const flash_ctrl_info_page_t kPages[2] = {
    kFlashCtrlInfoPageBootData0,
    kFlashCtrlInfoPageBootData1,
};

static void boot_data_pages_cfg_set(void) {
  const uint32_t offsets[] = {
      FLASH_CTRL_BANK1_INFO0_PAGE_CFG_SHADOWED_0_REG_OFFSET,
      FLASH_CTRL_BANK1_INFO0_PAGE_CFG_SHADOWED_1_REG_OFFSET,
  };

  for (size_t i = 0; i < ARRAYSIZE(offsets); ++i) {
    uint32_t addr = TOP_EARLGREY_FLASH_CTRL_CORE_BASE_ADDR + offsets[i];
    uint32_t reg = abs_mmio_read32(addr);
    reg = bitfield_bit32_write(
        reg, FLASH_CTRL_BANK0_INFO0_PAGE_CFG_SHADOWED_0_EN_0_BIT, true);
    reg = bitfield_bit32_write(
        reg, FLASH_CTRL_BANK0_INFO0_PAGE_CFG_SHADOWED_0_RD_EN_0_BIT, false);
    reg = bitfield_bit32_write(
        reg, FLASH_CTRL_BANK0_INFO0_PAGE_CFG_SHADOWED_0_PROG_EN_0_BIT, false);
    reg = bitfield_bit32_write(
        reg, FLASH_CTRL_BANK0_INFO0_PAGE_CFG_SHADOWED_0_ERASE_EN_0_BIT, false);
    reg = bitfield_bit32_write(
        reg, FLASH_CTRL_BANK0_INFO0_PAGE_CFG_SHADOWED_0_SCRAMBLE_EN_0_BIT,
        true);
    reg = bitfield_bit32_write(
        reg, FLASH_CTRL_BANK0_INFO0_PAGE_CFG_SHADOWED_0_ECC_EN_0_BIT, true);
    abs_mmio_write32_shadowed(addr, reg);
  }
}

static void boot_data_pages_mp_set(hardened_bool_t perm) {
  for (size_t i = 0; i < ARRAYSIZE(kPages); ++i) {
    flash_ctrl_info_mp_set(kPages[i], (flash_ctrl_mp_t){
                                          .read = perm,
                                          .write = perm,
                                          .erase = perm,
                                      });
  }
}

static void erase_boot_data_pages(void) {
  boot_data_pages_mp_set(kHardenedBoolTrue);
  for (size_t i = 0; i < ARRAYSIZE(kPages); ++i) {
    CHECK(flash_ctrl_info_erase(kPages[i], kFlashCtrlEraseTypePage) == kErrorOk,
          "Flash page erase failed.");
  }
  boot_data_pages_mp_set(kHardenedBoolFalse);
}

static rom_error_t invalidate_first_entry(void) {
  enum {
    kWordOffset = sizeof(hmac_digest_t),
  };

  if (offsetof(boot_data_t, identifier) == kWordOffset) {
    uint32_t zero = 0;
    return flash_ctrl_info_write(kFlashCtrlInfoPageBootData0, kWordOffset, 1,
                                 &zero);
  }

  uint32_t zeros[2] = {0, 0};
  return flash_ctrl_info_write(kFlashCtrlInfoPageBootData0, kWordOffset,
                               ARRAYSIZE(zeros), zeros);
}

bool test_main(void) {
  flash_ctrl_init();
  boot_data_pages_cfg_set();
  erase_boot_data_pages();

  boot_data_t boot_data = {
      .counter = 0,
      .min_security_version_rom_ext = 0,
  };

  LOG_INFO("identifier offset: %u", (unsigned)offsetof(boot_data_t, identifier));
  LOG_INFO("first boot_data_write");
  CHECK(boot_data_write(&boot_data) == kErrorOk, "first boot_data_write failed");

  boot_data_pages_mp_set(kHardenedBoolTrue);
  rom_error_t write_error = invalidate_first_entry();
  boot_data_pages_mp_set(kHardenedBoolFalse);
  LOG_INFO("manual invalidate error: 0x%x", write_error);
  CHECK(write_error == kErrorOk, "manual invalidate failed: 0x%x", write_error);

  uint32_t invalidation_word[2] = {0};
  boot_data_pages_mp_set(kHardenedBoolTrue);
  rom_error_t read_error = flash_ctrl_info_read(
      kFlashCtrlInfoPageBootData0, sizeof(hmac_digest_t),
      ARRAYSIZE(invalidation_word), invalidation_word);
  boot_data_pages_mp_set(kHardenedBoolFalse);

  LOG_INFO("raw invalidation read error: 0x%x", read_error);
  CHECK(read_error == kErrorOk, "raw invalidation word read failed: 0x%x",
        read_error);
  CHECK(invalidation_word[0] == 0 && invalidation_word[1] == 0,
        "unexpected invalidation word contents: 0x%x 0x%x",
        invalidation_word[0], invalidation_word[1]);
  return true;
}
EOF

cat > "$TB_DIR/chip_cfg.hjson" <<'EOF'
{
  import_cfgs: ["{proj_root}/hw/top_earlgrey/dv/chip_sim_cfg.hjson"]
  tests: [
    {
