      sw_images: ["sw/device/silicon_creator/testing/sw_silicon_creator_lib_boot_data_functest:1"]
      en_run_modes: ["sw_test_mode"]
    }
  ]
}
EOF

set +e
timeout 1800 ./util/dvsim/dvsim.py "$TB_DIR/chip_cfg.hjson" \
  -i chip_sw_boot_data_ecc_scramble \
  -t vcs \
  --fixed-seed=1 \
