  > "$TB_DIR/dvsim.log" 2>&1
rc=$?
set -e

cat "$TB_DIR/dvsim.log"

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: chip_sw_boot_data_ecc_scramble ... PASS"
else
  echo "TEST: chip_sw_boot_data_ecc_scramble ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

