    ht_done_pulse_i = 1'b1;
    tick();
    ht_done_pulse_i = 1'b0;
    if (cs_aes_halt_req_o !== 1'b0) begin
      fail("Missing delay cycle between final startup pass and Sha3Prep");
    end

    tick();
    if (cs_aes_halt_req_o !== 1'b1) begin
      fail("Expected halt request after the inserted delay cycle");
    end

    cs_aes_halt_ack_i = 1'b1;
    tick();
    cs_aes_halt_ack_i = 1'b0;
    if (sha3_process_o !== 1'b1) begin
