python - <<'PY'
from pathlib import Path

root = Path("/home/opentitan")
common_vseq_path = root / "hw/ip/rom_ctrl/dv/env/seq_lib/rom_ctrl_common_vseq.sv"
sim_cfg_path = root / "hw/ip/rom_ctrl/dv/rom_ctrl_sim_cfg.hjson"
scoreboard_path = root / "hw/dv/sv/cip_lib/cip_base_scoreboard.sv"

vseq_class = """

class rom_ctrl_passthru_vseq extends rom_ctrl_base_vseq;
  `uvm_object_utils(rom_ctrl_passthru_vseq)
  `uvm_object_new

  localparam bit [TL_AW-1:0] TestAddr = 'h0;

  virtual task body();
    logic [38:0] stored_word;
    logic [38:0] exp_word;
    tlul_pkg::tl_d_user_t act_d_user;
    cip_tl_host_single_seq tl_seq;

    wait (prim_mubi_pkg::mubi4_test_true_strict(cfg.rom_ctrl_vif.pwrmgr_data.done));
    cfg.clk_rst_vif.wait_clks(2);

    stored_word = cfg.mem_bkdr_util_h.rom_encrypt_read32(TestAddr,
                                                         RND_CNST_SCR_KEY,
                                                         RND_CNST_SCR_NONCE,
                                                         1'b0);
    stored_word[32] = ~stored_word[32];
    write_raw_word(TestAddr, stored_word);
    exp_word = cfg.mem_bkdr_util_h.rom_encrypt_read32(TestAddr,
                                                      RND_CNST_SCR_KEY,
                                                      RND_CNST_SCR_NONCE,
                                                      1'b1);

    `uvm_create_on(tl_seq, p_sequencer.tl_sequencer_hs["rom_ctrl_rom_reg_block"])
    if (cfg.zero_delays) begin
      tl_seq.min_req_delay = 0;
      tl_seq.max_req_delay = 0;
    end
    `DV_CHECK_RANDOMIZE_WITH_FATAL(tl_seq,
        addr == TestAddr;
        write == 1'b0;
        mask == '1;
        data == '0;)
    `uvm_send_pri(tl_seq, 100)

    act_d_user = tlul_pkg::tl_d_user_t'(tl_seq.rsp.d_user);

    `DV_CHECK_EQ(tl_seq.rsp.rsp_completed, 1)
    `DV_CHECK_EQ(tl_seq.rsp.d_error, 0)
    `DV_CHECK_EQ(tl_seq.rsp.d_data, exp_word[31:0],
                 $sformatf("Expected read data 0x%0h, got 0x%0h",
                           exp_word[31:0], tl_seq.rsp.d_data))
    `DV_CHECK_EQ(act_d_user.data_intg, exp_word[38:32],
                 $sformatf("Expected passthru data_intg 0x%0h, got 0x%0h",
                           exp_word[38:32], act_d_user.data_intg))
    csr_utils_pkg::wait_no_outstanding_access();
  endtask

  virtual function void write_raw_word(bit [TL_AW-1:0] addr, logic [38:0] raw_word);
    int addr_lsb = cfg.mem_bkdr_util_h.get_addr_lsb();
    int addr_width = cfg.mem_bkdr_util_h.get_addr_width();
    logic [TL_AW-1:0] bus_addr = '0;
    logic addr_arr[] = new[addr_width];
    logic scrambled_addr[];
    logic nonce_arr[] = new[sram_scrambler_pkg::SRAM_BLOCK_WIDTH];

    nonce_arr = {<<{RND_CNST_SCR_NONCE}};
    for (int i = 0; i < addr_width; i++) begin
      addr_arr[i] = addr[addr_lsb + i];
    end

    scrambled_addr = sram_scrambler_pkg::encrypt_sram_addr(addr_arr, addr_width, nonce_arr);

    for (int i = 0; i < addr_lsb; i++) begin
      bus_addr[i] = addr[i];
    end
    for (int i = 0; i < addr_width; i++) begin
      bus_addr[addr_lsb + i] = scrambled_addr[i];
    end

    cfg.mem_bkdr_util_h.write39integ(bus_addr, raw_word);
  endfunction

endclass : rom_ctrl_passthru_vseq
"""

common_text = common_vseq_path.read_text(encoding="utf-8")
if "class rom_ctrl_passthru_vseq extends rom_ctrl_base_vseq;" not in common_text:
    common_vseq_path.write_text(common_text.rstrip() + vseq_class + "\n", encoding="utf-8")

sim_cfg_text = sim_cfg_path.read_text(encoding="utf-8")
test_block = """    {
      name: rom_ctrl_passthru
      uvm_test_seq: rom_ctrl_passthru_vseq
    }
"""
marker = "\n    // TODO: add more tests here\n"
if "name: rom_ctrl_passthru" not in sim_cfg_text:
    if marker not in sim_cfg_text:
        raise SystemExit("Failed to find insertion point in rom_ctrl_sim_cfg.hjson")
    sim_cfg_text = sim_cfg_text.replace(marker, test_block + marker, 1)
    sim_cfg_path.write_text(sim_cfg_text, encoding="utf-8")

scoreboard_text = scoreboard_path.read_text(encoding="utf-8")
old_check = "      if (en_d_user_intg_chk) void'(item.is_d_chan_intg_ok(.throw_error(1)));"
new_check = """      if (en_d_user_intg_chk && !$test$plusargs("rom_ctrl_passthru_skip_d_user_intg_chk")) begin
        void'(item.is_d_chan_intg_ok(.throw_error(1)));
      end"""
if "rom_ctrl_passthru_skip_d_user_intg_chk" not in scoreboard_text:
    if old_check not in scoreboard_text:
        raise SystemExit("Failed to find d_user integrity check in cip_base_scoreboard.sv")
    scoreboard_text = scoreboard_text.replace(old_check, new_check, 1)
    scoreboard_path.write_text(scoreboard_text, encoding="utf-8")
PY

