exit 1

#!/bin/bash

set -euo pipefail

cd /home/opentitan || exit 1

TEST_NAME="pwrmgr_fsm_strap_timing"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
BUILD_DIR="/home/opentitan/build/lowrisc_dv_pwrmgr_fsm_strap_tb_0.1"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}" "${BUILD_DIR}"
mkdir -p "${TB_DIR}"

# Keep all temporary RTL copies inside /home/opentitan so the script is self-contained.
cp /home/opentitan/hw/ip/pwrmgr/rtl/pwrmgr_reg_pkg.sv "${TB_DIR}/pwrmgr_reg_pkg.sv"
cp /home/opentitan/hw/ip/pwrmgr/rtl/pwrmgr_pkg.sv "${TB_DIR}/pwrmgr_pkg.sv"
cp /home/opentitan/hw/ip/pwrmgr/rtl/pwrmgr_fsm.sv "${TB_DIR}/pwrmgr_fsm.sv"

cat > "${TB_DIR}/pwrmgr_fsm_strap_tb.sv" <<'EOF'
module pwrmgr_fsm_strap_tb;
  import pwrmgr_pkg::*;
  import pwrmgr_reg_pkg::*;
  import prim_mubi_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic clk_slow_i;
  logic rst_slow_ni;
  logic req_pwrup_i;
  pwrup_cause_e pwrup_cause_i;
  logic ack_pwrup_o;
  logic req_pwrdn_o;
  logic ack_pwrdn_i;
  logic low_power_entry_i;
  logic main_pd_ni;
  logic [TotalResetWidth-1:0] reset_reqs_i;
  logic fsm_invalid_i;
  logic clr_slow_req_o;
  logic clr_slow_ack_i;
  logic usb_ip_clk_en_i;
  logic usb_ip_clk_status_o;
  logic wkup_o;
  logic fall_through_o;
  logic abort_o;
  logic clr_hint_o;
  logic clr_cfg_lock_o;
  pwr_rst_req_t pwr_rst_o;
  pwr_rst_rsp_t pwr_rst_i;
  pwr_clk_req_t ips_clk_en_o;
  pwr_clk_rsp_t clk_en_status_i;
  logic otp_init_o;
  logic otp_done_i;
  logic otp_idle_i;
  logic lc_init_o;
  logic lc_done_i;
  logic lc_idle_i;
  logic flash_idle_i;
  prim_mubi_pkg::mubi4_t rom_ctrl_done_i;
  prim_mubi_pkg::mubi4_t rom_ctrl_good_i;
  logic strap_o;
  logic low_power_o;
  lc_ctrl_pkg::lc_tx_t fetch_en_o;

  int cycles;

  pwrmgr_fsm dut (
    .clk_i,
    .rst_ni,
    .clk_slow_i,
    .rst_slow_ni,
    .req_pwrup_i,
    .pwrup_cause_i,
    .ack_pwrup_o,
    .req_pwrdn_o,
    .ack_pwrdn_i,
    .low_power_entry_i,
    .main_pd_ni,
    .reset_reqs_i,
    .fsm_invalid_i,
    .clr_slow_req_o,
    .clr_slow_ack_i,
    .usb_ip_clk_en_i,
    .usb_ip_clk_status_o,
    .wkup_o,
    .fall_through_o,
    .abort_o,
    .clr_hint_o,
    .clr_cfg_lock_o,
    .pwr_rst_o,
    .pwr_rst_i,
    .ips_clk_en_o,
    .clk_en_status_i,
    .otp_init_o,
    .otp_done_i,
    .otp_idle_i,
    .lc_init_o,
    .lc_done_i,
    .lc_idle_i,
    .flash_idle_i,
    .rom_ctrl_done_i,
    .rom_ctrl_good_i,
    .strap_o,
    .low_power_o,
    .fetch_en_o
  );

  initial begin
    clk_i = 0;
    forever #5 clk_i = ~clk_i;
  end

  initial begin
    clk_slow_i = 0;
    forever #7 clk_slow_i = ~clk_slow_i;
  end

  always @(posedge clk_i) begin
    cycles <= cycles + 1;
    if (cycles > 200) begin
      $fatal(1, "Timeout waiting for strap event");
    end
    if (strap_o) begin
      if (pwr_rst_o.rst_sys_req !== '0 ||
          rom_ctrl_done_i !== MuBi4True ||
          rom_ctrl_good_i !== MuBi4True) begin
        $display("RUNTIME_FAIL: strap asserted before sys reset release or ROM success");
        $fatal(1, "Unexpected strap timing");
      end
      $display("RUNTIME_PASS: strap asserted after sys reset release and ROM success");
      #1;
      $finish;
    end
  end

  initial begin
    cycles = 0;
    rst_ni = 0;
    rst_slow_ni = 0;
    req_pwrup_i = 0;
    pwrup_cause_i = Por;
    ack_pwrdn_i = 0;
    low_power_entry_i = 0;
    main_pd_ni = 1;
    reset_reqs_i = '0;
    fsm_invalid_i = 0;
    clr_slow_ack_i = 0;
    usb_ip_clk_en_i = 0;
    pwr_rst_i = '{rst_lc_src_n: '1, rst_sys_src_n: '0};
    clk_en_status_i = '{main_status: 1'b1, io_status: 1'b1, usb_status: 1'b0};
    otp_done_i = 1;
    otp_idle_i = 1;
    lc_done_i = 1;
    lc_idle_i = 1;
    flash_idle_i = 1;
    rom_ctrl_done_i = MuBi4False;
    rom_ctrl_good_i = MuBi4False;

    repeat (3) @(posedge clk_i);
    rst_ni = 1;
    rst_slow_ni = 1;
    @(posedge clk_i);
    req_pwrup_i = 1;

    wait (ack_pwrup_o == 1'b1);
    @(posedge clk_i);
    req_pwrup_i = 0;

    wait (pwr_rst_o.rst_sys_req == '0);
    repeat (2) @(posedge clk_i);
    rom_ctrl_done_i = MuBi4True;
    rom_ctrl_good_i = MuBi4True;
  end
endmodule
EOF

cat > "${TB_DIR}/pwrmgr_fsm_strap_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:pwrmgr_fsm_strap_tb:0.1"
description: "Minimal pwrmgr_fsm strap timing reproducer"

filesets:
  files_dv:
    depend:
      - lowrisc:prim:assert:0.1
      - lowrisc:prim:flop
      - lowrisc:prim:flop_2sync
      - lowrisc:prim:lc_sender
      - lowrisc:prim:mubi
      - lowrisc:prim:sec_anchor
      - lowrisc:ip:lc_ctrl_pkg
      - lowrisc:ip:rom_ctrl_pkg
    files:
      - pwrmgr_reg_pkg.sv
      - pwrmgr_pkg.sv
      - pwrmgr_fsm.sv
      - pwrmgr_fsm_strap_tb.sv
    file_type: systemVerilogSource

targets:
  default:
    filesets:
      - files_dv
    toplevel: pwrmgr_fsm_strap_tb
EOF

export PATH="/tools/riscv/bin:/tools/verible/bin:${PATH}"

set +e
fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" run --target=default --tool=vcs \
  lowrisc:dv:pwrmgr_fsm_strap_tb:0.1 2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]] && grep -q "RUNTIME_PASS:" "${RUN_LOG}" && ! grep -q "RUNTIME_FAIL:" "${RUN_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

