tb_script:
#!/bin/bash

test_name="rv_core_ibex_sw_recov_readback"

main() {
  set -euo pipefail

  cd /home/opentitan

  for d in /tools/riscv/bin /tools/verible/bin; do
    if [ -d "$d" ]; then
      export PATH="$d:$PATH"
    fi
  done

  local tb_dir="/home/opentitan/.tb_rv_core_ibex_sw_recov"
  local build_dir="$tb_dir/build"

  rm -rf "$tb_dir"
  mkdir -p "$tb_dir"

  local meta
  meta="$(python - <<'PY'
from pathlib import Path
import re
import sys

text = Path("hw/ip/rv_core_ibex/rtl/rv_core_ibex_reg_pkg.sv").read_text(encoding="utf-8")
candidates = [
    ("RV_CORE_IBEX_SW_RECOV_ERR_OFFSET", "5"),
    ("RV_CORE_IBEX_SW_ALERT_1_OFFSET", "1"),
]
for symbol, disabled in candidates:
    match = re.search(rf"{symbol}\s*=\s*\d+'h\s*([0-9a-fA-F]+)", text)
    if match:
        print(match.group(1), disabled)
        sys.exit(0)
sys.exit(1)
PY
)"

  local recov_offset_hex disabled_hex
  read -r recov_offset_hex disabled_hex <<<"$meta"

  export TB_DIR="$tb_dir"
  export RECOV_OFFSET_HEX="$recov_offset_hex"
  export DISABLED_HEX="$disabled_hex"

  python - <<'PY'
from pathlib import Path
import os

tb_dir = Path(os.environ["TB_DIR"])
recov_offset_hex = os.environ["RECOV_OFFSET_HEX"]
disabled_hex = os.environ["DISABLED_HEX"]

core_text = """CAPI=2:
name: "lowrisc:dv:rv_core_ibex_sw_recov_tb:0.1"
description: "Minimal rv_core_ibex recoverable alert regression"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:rv_core_ibex:0.1
      - lowrisc:prim:alert
    files:
      - rv_core_ibex_sw_recov_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    toplevel: rv_core_ibex_sw_recov_tb
    filesets:
      - files_dv
    default_tool: vcs
    tools:
      vcs:
        vcs_options:
          - "-timescale=1ns/1ps"
"""

sv_text = f"""module rv_core_ibex_sw_recov_tb;
  import ibex_pkg::*;
  import rv_core_ibex_pkg::*;
  import rv_core_ibex_reg_pkg::*;
  import tlul_pkg::*;
  import prim_alert_pkg::*;
  import prim_esc_pkg::*;
  import prim_ram_1p_pkg::*;
  import prim_mubi_pkg::*;
  import lc_ctrl_pkg::*;
  import pwrmgr_pkg::*;

  localparam int unsigned RecovOffset = 32'h{recov_offset_hex};
  localparam logic [31:0] DisabledValue = 32'h{disabled_hex};

  logic clk;
  logic rst_n;
  logic clk_esc;
  logic rst_esc_n;

  tl_h2d_t cfg_tl_i;
  tl_d2h_t cfg_tl_o;
  tl_h2d_t corei_tl_o;
  tl_d2h_t corei_tl_i;
  tl_h2d_t cored_tl_o;
  tl_d2h_t cored_tl_i;
  alert_rx_t [rv_core_ibex_reg_pkg::NumAlerts-1:0] alert_rx;
  alert_tx_t [rv_core_ibex_reg_pkg::NumAlerts-1:0] alert_tx;
  alert_rx_t recov_alert_rx;
  logic recov_alert_pulse;
  logic recov_ping_ok;
  logic recov_integ_fail;
  logic recov_alert_p_prev;
  prim_esc_pkg::esc_rx_t esc_rx;
  pwr_cpu_t pwrmgr;
  crash_dump_t crash_dump;
  int unsigned recov_count;
  int unsigned start_count;
  logic [31:0] reg_readback;

  always #5 clk = ~clk;
  always #5 clk_esc = ~clk_esc;

  always_comb begin
    alert_rx = {{rv_core_ibex_reg_pkg::NumAlerts{{ALERT_RX_DEFAULT}}}};
    alert_rx[1] = recov_alert_rx;
  end

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      recov_count <= 0;
      recov_alert_p_prev <= 0;
    end else begin
      if (!recov_alert_p_prev && alert_tx[1].alert_p) recov_count <= recov_count + 1;
      recov_alert_p_prev <= alert_tx[1].alert_p;
    end
  end

  prim_alert_receiver #(
    .AsyncOn(1'b0)
  ) u_recov_receiver (
    .clk_i(clk),
    .rst_ni(rst_n),
    .init_trig_i(MuBi4False),
    .ping_req_i(1'b0),
    .ping_ok_o(recov_ping_ok),
    .integ_fail_o(recov_integ_fail),
    .alert_o(recov_alert_pulse),
    .alert_rx_o(recov_alert_rx),
    .alert_tx_i(alert_tx[1])
  );

  rv_core_ibex #(
    .AlertAsyncOn({{rv_core_ibex_reg_pkg::NumAlerts{{1'b0}}}}),
    .PMPEnable(1'b0),
    .PMPGranularity(0),
    .PMPNumRegions(4),
    .MHPMCounterNum(0),
    .MHPMCounterWidth(32),
    .RV32E(1'b0),
    .RV32M(ibex_pkg::RV32MNone),
    .RV32B(ibex_pkg::RV32BNone),
    .RegFile(ibex_pkg::RegFileFF),
    .BranchTargetALU(1'b0),
    .WritebackStage(1'b0),
    .ICache(1'b0),
    .ICacheECC(1'b0),
    .BranchPredictor(1'b0),
    .DbgTriggerEn(1'b0),
    .SecureIbex(1'b0),
    .PipeLine(1'b0)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .clk_esc_i(clk_esc),
    .rst_esc_ni(rst_esc_n),
    .rst_cpu_n_o(),
    .ram_cfg_i(RAM_1P_CFG_DEFAULT),
    .hart_id_i(32'h0),
    .boot_addr_i(32'h0),
    .corei_tl_h_o(corei_tl_o),
    .corei_tl_h_i(corei_tl_i),
    .cored_tl_h_o(cored_tl_o),
    .cored_tl_h_i(cored_tl_i),
    .irq_software_i(1'b0),
    .irq_timer_i(1'b0),
    .irq_external_i(1'b0),
    .esc_tx_i(ESC_TX_DEFAULT),
    .esc_rx_o(esc_rx),
    .nmi_wdog_i(1'b0),
    .debug_req_i(1'b0),
    .crash_dump_o(crash_dump),
    .lc_cpu_en_i(Off),
    .pwrmgr_cpu_en_i(Off),
    .pwrmgr_o(pwrmgr),
    .scan_rst_ni(rst_n),
    .scanmode_i(MuBi4False),
    .cfg_tl_d_i(cfg_tl_i),
    .cfg_tl_d_o(cfg_tl_o),
    .alert_rx_i(alert_rx),
    .alert_tx_o(alert_tx)
  );

  task automatic tl_write(input logic [31:0] addr, input logic [31:0] data);
    tl_h2d_t req;
    req = TL_H2D_DEFAULT;
    req.a_valid = 1'b1;
    req.a_opcode = PutFullData;
    req.a_param = '0;
    req.a_size = 2;
    req.a_source = '0;
    req.a_address = addr;
    req.a_mask = 4'hf;
    req.a_data = data;
    req.a_user = TL_A_USER_DEFAULT;
    req.a_user.cmd_intg = get_cmd_intg(req);
    req.a_user.data_intg = get_data_intg(req.a_data);
    @(negedge clk);
    cfg_tl_i = req;
    @(posedge clk);
    if (!cfg_tl_o.a_ready) begin
      $error("TL write did not handshake for addr 0x%08x", addr);
      $fatal(1);
    end
    @(negedge clk);
    cfg_tl_i = TL_H2D_DEFAULT;
    @(posedge clk);
    if (!cfg_tl_o.d_valid || cfg_tl_o.d_error) begin
      $error("TL write failed for addr 0x%08x", addr);
      $fatal(1);
    end
  endtask

  task automatic tl_read(input logic [31:0] addr, output logic [31:0] data);
    tl_h2d_t req;
    req = TL_H2D_DEFAULT;
    req.a_valid = 1'b1;
    req.a_opcode = Get;
    req.a_param = '0;
    req.a_size = 2;
    req.a_source = '0;
    req.a_address = addr;
    req.a_mask = 4'hf;
    req.a_user = TL_A_USER_DEFAULT;
    req.a_user.cmd_intg = get_cmd_intg(req);
    @(negedge clk);
    cfg_tl_i = req;
    @(posedge clk);
    if (!cfg_tl_o.a_ready) begin
      $error("TL read did not handshake for addr 0x%08x", addr);
      $fatal(1);
    end
    @(negedge clk);
    cfg_tl_i = TL_H2D_DEFAULT;
    @(posedge clk);
    if (!cfg_tl_o.d_valid || cfg_tl_o.d_error) begin
      $error("TL read failed for addr 0x%08x", addr);
      $fatal(1);
    end
    data = cfg_tl_o.d_data;
  endtask

  initial begin
    clk = 1'b0;
    clk_esc = 1'b0;
    rst_n = 1'b0;
    rst_esc_n = 1'b0;
    cfg_tl_i = TL_H2D_DEFAULT;
    corei_tl_i = TL_D2H_DEFAULT;
    cored_tl_i = TL_D2H_DEFAULT;

    repeat (5) @(posedge clk);
    rst_n = 1'b1;
    rst_esc_n = 1'b1;

    repeat (20) @(posedge clk);
    start_count = recov_count;
    tl_write(RecovOffset, 32'h0);
    repeat (40) @(posedge clk);
    tl_read(RecovOffset, reg_readback);

    $display("RECOV_ALERT_COUNT=%0d", recov_count - start_count);
    $display("RECOV_READBACK=0x%08x", reg_readback);
    if (recov_integ_fail) begin
      $error("Receiver saw integrity failure");
      $fatal(1);
    end
    if ((recov_count - start_count) == 0) begin
      $error("Recoverable alert did not trigger");
      $fatal(1);
    end
    if (reg_readback == DisabledValue) begin
      $display("TB_PASS");
      $finish;
    end

    $error("Expected disabled value 0x%08x, saw 0x%08x", DisabledValue, reg_readback);
    $fatal(1);
  end
endmodule
"""

(tb_dir / "rv_core_ibex_sw_recov_tb.core").write_text(core_text, encoding="ascii")
(tb_dir / "rv_core_ibex_sw_recov_tb.sv").write_text(sv_text, encoding="ascii")
PY

  rm -rf "$build_dir"

  set +e
  timeout 1800 fusesoc \
    --cores-root /home/opentitan \
    --cores-root "$tb_dir" \
    run \
    --flag fileset_ip \
    --no-export \
    --build-root "$build_dir" \
    --target=sim \
    --tool=vcs \
    --setup \
    --build \
    --run \
    lowrisc:dv:rv_core_ibex_sw_recov_tb:0.1 | tee "$tb_dir/run.log"
  local rc=${PIPESTATUS[0]}
  set -e

  if [ "$rc" -eq 124 ]; then
    return 124
  fi

  if [ "$rc" -ne 0 ]; then
    return "$rc"
  fi

  # FuseSoC/VCS does not reliably propagate `$fatal` as a non-zero shell status here.
  # Only treat the run as passing when the testbench's explicit success sentinel is present.
  if ! grep -Fqx "TB_PASS" "$tb_dir/run.log"; then
    return 1
  fi

  return 0
}

print_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${test_name} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

if main; then
  print_result "PASS"
  exit 0
else
  rc=$?
  print_result "FAIL"
  exit "$rc"
fi

#!/bin/bash
cd /home/opentitan
set -uo pipefail

TEST_NAME="adc_ctrl_oneshot_handshake"
TB_DIR="/home/opentitan/.tb_adc_ctrl_oneshot_handshake"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

echo "HWE_BENCH_RESULTS_START"
trap 'echo "HWE_BENCH_RESULTS_END"' EXIT

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import adc_ctrl_reg_pkg::*;

  localparam logic [9:0] FirstSample  = 10'h155;
  localparam logic [9:0] SecondSample = 10'h2aa;

  logic clk_aon_i = 1'b0;
  logic rst_aon_ni = 1'b0;
  logic cfg_fsm_rst_i = 1'b0;
  logic cfg_adc_enable_i = 1'b0;
  logic cfg_oneshot_mode_i = 1'b1;
  logic cfg_lp_mode_i = 1'b0;
  logic [3:0] cfg_pwrup_time_i = '0;
  logic [23:0] cfg_wakeup_time_i = '0;
  logic [7:0] cfg_lp_sample_cnt_i = '0;
  logic [15:0] cfg_np_sample_cnt_i = '0;
  logic [NumAdcFilter-1:0] adc_ctrl_match_i = '0;
  logic [9:0] adc_d_i = '0;
  logic adc_d_val_i = 1'b0;

  logic adc_pd_o;
  logic [1:0] adc_chn_sel_o;
  logic chn0_val_we_o;
  logic chn1_val_we_o;
  logic [9:0] chn0_val_o;
  logic [9:0] chn1_val_o;
  logic adc_ctrl_done_o;
  logic oneshot_done_o;

  adc_ctrl_fsm dut (
    .clk_aon_i,
    .rst_aon_ni,
    .cfg_fsm_rst_i,
    .cfg_adc_enable_i,
    .cfg_oneshot_mode_i,
    .cfg_lp_mode_i,
    .cfg_pwrup_time_i,
    .cfg_wakeup_time_i,
    .cfg_lp_sample_cnt_i,
    .cfg_np_sample_cnt_i,
    .adc_ctrl_match_i,
    .adc_d_i,
    .adc_d_val_i,
    .adc_pd_o,
    .adc_chn_sel_o,
    .chn0_val_we_o,
    .chn1_val_we_o,
    .chn0_val_o,
    .chn1_val_o,
    .adc_ctrl_done_o,
    .oneshot_done_o
  );

  always #5 clk_aon_i = ~clk_aon_i;

  task automatic wait_for_ch0_phase();
    int timeout_cycles = 30;
    while ((adc_chn_sel_o !== 2'b01) && (timeout_cycles > 0)) begin
      @(negedge clk_aon_i);
      timeout_cycles--;
    end
    if (adc_chn_sel_o !== 2'b01) begin
      $fatal(1, "Timed out waiting for the channel-0 sample phase");
    end
  endtask

  initial begin
    repeat (2) @(posedge clk_aon_i);
    @(negedge clk_aon_i);
    rst_aon_ni = 1'b1;
    @(negedge clk_aon_i);
    cfg_adc_enable_i = 1'b1;

    wait_for_ch0_phase();

    // First ADC value remains valid for multiple cycles. The fixed RTL must
    // not progress to channel 1 until valid drops.
    @(negedge clk_aon_i);
    adc_d_i = FirstSample;
    adc_d_val_i = 1'b1;
    #1;
    if (oneshot_done_o) begin
      $fatal(1, "oneshot_done_o asserted too early on the first valid pulse");
    end

    repeat (2) begin
      @(negedge clk_aon_i);
      #1;
      if (oneshot_done_o) begin
        $fatal(1, "oneshot_done_o asserted before adc_d_val_i deasserted");
      end
      if (chn1_val_we_o) begin
        $fatal(1, "channel 1 sampled while adc_d_val_i stayed high");
      end
    end

    @(negedge clk_aon_i);
    adc_d_val_i = 1'b0;
    #1;
    if (oneshot_done_o) begin
      $fatal(1, "oneshot_done_o asserted during the valid-low handshake gap");
    end

    // The second valid pulse should now be consumed as the channel-1 sample.
    @(negedge clk_aon_i);
    adc_d_i = SecondSample;
    adc_d_val_i = 1'b1;
    #1;
    if (!oneshot_done_o) begin
      $fatal(1, "oneshot_done_o did not assert on the second valid pulse");
    end

    @(negedge clk_aon_i);
    #1;
    if (!chn1_val_we_o) begin
      $fatal(1, "channel 1 write enable missing on the second valid pulse");
    end
    if (chn0_val_o !== FirstSample) begin
      $fatal(1, "channel 0 captured the wrong sample value");
    end
    if (chn1_val_o !== SecondSample) begin
      $fatal(1, "channel 1 captured the wrong sample value");
    end

    adc_d_val_i = 1'b0;
    @(negedge clk_aon_i);
    #1;
    if (adc_pd_o !== 1'b1) begin
      $fatal(1, "FSM did not return to power-down after oneshot completion");
    end

    $display("TB_PASS");
    $finish;
  end

  initial begin
    #1000;
    $fatal(1, "Timed out waiting for the handshake scenario to complete");
  end
endmodule
EOF

timeout 1800s vcs -full64 -sverilog \
  -timescale=1ns/1ps \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log" \
  hw/ip/adc_ctrl/rtl/adc_ctrl_reg_pkg.sv \
  hw/ip/adc_ctrl/rtl/adc_ctrl_fsm.sv \
  "$TB_DIR/tb.sv"
compile_rc=$?

if [ $compile_rc -ne 0 ]; then
  [ -f "$TB_DIR/compile.log" ] && tail -n 200 "$TB_DIR/compile.log"
  echo "TEST: $TEST_NAME ... FAIL"
  exit $compile_rc
fi

timeout 1800s "$TB_DIR/simv" > "$TB_DIR/run.log" 2>&1
run_rc=$?
[ -f "$TB_DIR/run.log" ] && cat "$TB_DIR/run.log"

# VCS can still exit with code 0 after $fatal, so require the explicit
# success marker from the testbench as well.
if [ $run_rc -eq 0 ] && grep -q "TB_PASS" "$TB_DIR/run.log"; then
  echo "TEST: $TEST_NAME ... PASS"
  exit 0
fi

echo "TEST: $TEST_NAME ... FAIL"
exit 1

