#!/bin/bash
cd /home/opentitan
set +e

source /etc/opentitan_tools_path.sh 2>/dev/null || true

TEST_NAME="pwrmgr_rom_ctrl_invalid_mubi"
TB_DIR="/home/opentitan/.tb_pwrmgr_rom_mubi"
BUILD_DIR="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/pwrmgr_fsm_mubi_invalid.core" <<'EOF'
CAPI=2:
name: "local:dv:pwrmgr_fsm_mubi_invalid:0.1"
description: "Minimal pwrmgr_fsm invalid-mubi reproducer"
filesets:
  files_dut:
    depend:
      - lowrisc:ip:lc_ctrl_pkg
      - lowrisc:prim:assert
      - lowrisc:prim:flop
      - lowrisc:prim:flop_2sync
      - lowrisc:prim:lc_sender
      - lowrisc:prim:mubi
      - lowrisc:prim:sec_anchor
    files:
      - ../hw/ip/pwrmgr/rtl/pwrmgr_reg_pkg.sv
      - ../hw/ip/pwrmgr/rtl/pwrmgr_pkg.sv
      - ../hw/ip/pwrmgr/rtl/pwrmgr_fsm.sv
    file_type: systemVerilogSource
  files_tb:
