cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import pwrmgr_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i = 1'b0;
  logic clk_slow_i = 1'b0;
  logic rst_ni = 1'b0;
  logic rst_slow_ni = 1'b0;
  logic req_pwrup_i = 1'b0;
  pwrup_cause_e pwrup_cause_i = Por;
  logic ack_pwrup_o;
  logic req_pwrdn_o;
  logic ack_pwrdn_i = 1'b0;
  logic low_power_entry_i = 1'b0;
  logic main_pd_ni = 1'b1;
  logic [TotalResetWidth-1:0] reset_reqs_i = '0;
  logic fsm_invalid_i = 1'b0;
  logic clr_slow_req_o;
  logic clr_slow_ack_i = 1'b0;
  logic usb_ip_clk_en_i = 1'b1;
  logic usb_ip_clk_status_o;
  logic wkup_o;
  logic fall_through_o;
  logic abort_o;
  logic clr_hint_o;
  logic clr_cfg_lock_o;
  pwr_rst_req_t pwr_rst_o;
  pwr_rst_rsp_t pwr_rst_i;
  pwr_clk_req_t ips_clk_en_o;
  pwr_clk_rsp_t clk_en_status_i;
  logic otp_init_o;
  logic otp_done_i = 1'b1;
  logic otp_idle_i = 1'b1;
  logic lc_init_o;
  logic lc_done_i = 1'b1;
  logic lc_idle_i = 1'b1;
  logic flash_idle_i = 1'b1;
  logic [3:0] rom_ctrl_done_i = 4'b0000;
  logic [3:0] rom_ctrl_good_i = 4'b0000;
  logic strap_o;
  logic low_power_o;
  lc_tx_t fetch_en_o;

  pwrmgr_fsm dut (
    .clk_i,
    .rst_ni,
    .clk_slow_i,
    .rst_slow_ni,
    .req_pwrup_i,
    .pwrup_cause_i,
    .ack_pwrup_o,
    .req_pwrdn_o,
    .ack_pwrdn_i,
    .low_power_entry_i,
    .main_pd_ni,
    .reset_reqs_i,
    .fsm_invalid_i,
    .clr_slow_req_o,
    .clr_slow_ack_i,
    .usb_ip_clk_en_i,
    .usb_ip_clk_status_o,
    .wkup_o,
    .fall_through_o,
    .abort_o,
    .clr_hint_o,
    .clr_cfg_lock_o,
    .pwr_rst_o,
    .pwr_rst_i,
    .ips_clk_en_o,
    .clk_en_status_i,
    .otp_init_o,
    .otp_done_i,
    .otp_idle_i,
    .lc_init_o,
    .lc_done_i,
    .lc_idle_i,
    .flash_idle_i,
    .rom_ctrl_done_i,
    .rom_ctrl_good_i,
    .strap_o,
    .low_power_o,
    .fetch_en_o
  );

  always #5 clk_i = ~clk_i;
  always #17 clk_slow_i = ~clk_slow_i;

  task automatic wait_for_state(input fast_pwr_state_e exp_state, input int max_cycles,
                                input string state_name);
    int cycles;
    begin
      for (cycles = 0; cycles < max_cycles; cycles++) begin
        @(posedge clk_i);
        if (dut.state_q == exp_state) return;
      end
      $display("TB_FAIL: timeout waiting for %s, saw state %0h", state_name, dut.state_q);
      $fatal(1);
    end
  endtask

  initial begin
    pwr_rst_i = '{rst_lc_src_n: {PowerDomains{1'b1}},
                  rst_sys_src_n: {PowerDomains{1'b1}}};
    clk_en_status_i = '{main_status: 1'b1, io_status: 1'b1, usb_status: 1'b1};

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_slow_ni = 1'b1;
    req_pwrup_i = 1'b1;

    wait_for_state(FastPwrStateAckPwrUp, 200, "AckPwrUp");
    @(posedge clk_i);
    req_pwrup_i = 1'b0;

    wait_for_state(FastPwrStateRomCheck, 200, "RomCheck");
    rom_ctrl_done_i = 4'b0001;
    rom_ctrl_good_i = 4'b0001;

    repeat (4) @(posedge clk_i);

    if (dut.state_q == FastPwrStateActive) begin
      $display("TB_FAIL: invalid mubi pattern advanced FSM to Active");
      $fatal(1);
    end

    if (dut.state_q != FastPwrStateRomCheck) begin
      $display("TB_FAIL: unexpected state %0h", dut.state_q);
      $fatal(1);
    end

    $display("TB_PASS: invalid mubi pattern rejected in RomCheck");
    $finish;
  end
endmodule
EOF

fusesoc --cores-root . --cores-root "${TB_DIR}" \
  run --build-root "${BUILD_DIR}" --no-export --target=sim --tool=vcs \
  local:dv:pwrmgr_fsm_mubi_invalid:0.1 \
  2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="mubi_sync_stability"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
RUN_LOG="${TB_DIR}/run.log"
CORE_NAME="lowrisc:dv:${TEST_NAME}:0.1"
BUILD_DIR="/home/opentitan/build/lowrisc_dv_${TEST_NAME}_0.1"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}" "${BUILD_DIR}"
mkdir -p "${TB_DIR}/tb"

cat > "${TB_DIR}/${TEST_NAME}.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:mubi_sync_stability:0.1"
description: "Minimal VCS testbench for prim_mubi4_sync StabilityCheck"
filesets:
  files_rtl:
    depend:
      - lowrisc:prim:all:0.1
      - lowrisc:prim:mubi:0.1
      - lowrisc:prim:sec_anchor:0.1
    file_type: systemVerilogSource

  files_dv:
    files:
      - tb/mubi_sync_stability_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: mubi_sync_stability_tb
    filesets:
      - files_rtl
      - files_dv
    tools:
      vcs:
        vcs_options:
          - +warn=noLNX_OS_VERUN
EOF

cat > "${TB_DIR}/tb/mubi_sync_stability_tb.sv" <<'EOF'
module mubi_sync_stability_tb;
  import prim_mubi_pkg::*;

  logic clk_i;
  logic rst_ni;
  mubi4_t mubi_i;
  mubi4_t [0:0] mubi_o;

  prim_mubi4_sync #(
    .NumCopies(1),
    .AsyncOn(1'b1),
    .StabilityCheck(1'b1),
    .ResetValue(MuBi4False)
  ) dut (
    .clk_i,
    .rst_ni,
    .mubi_i,
    .mubi_o
  );

  always #5 clk_i = ~clk_i;

  task automatic expect_value(input string step, input mubi4_t expected);
    #1;
    if (mubi_o[0] !== expected) begin
      $error("%s expected %h got %h", step, expected, mubi_o[0]);
      $fatal(1);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    mubi_i = MuBi4False;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    repeat (3) begin
      @(posedge clk_i);
      expect_value("warmup", MuBi4False);
    end

    @(negedge clk_i);
    mubi_i = mubi4_t'(4'h6);
    @(posedge clk_i);
    expect_value("invalid_seen_stage1", MuBi4False);

    @(negedge clk_i);
    mubi_i = MuBi4True;
    @(posedge clk_i);
    expect_value("invalid_filtered", MuBi4False);

    @(posedge clk_i);
    expect_value("first_true_filtered", MuBi4False);

    @(posedge clk_i);
    expect_value("stable_true_visible", MuBi4True);

    $display("MUBI_SYNC_STABILITY_TEST_PASS");
    $finish;
  end
endmodule
EOF

set +e
fusesoc --cores-root=. --cores-root="${TB_DIR}" run --target=sim --tool=vcs "${CORE_NAME}" 2>&1 | tee "${RUN_LOG}"
cmd_rc=${PIPESTATUS[0]}
set -e

echo "INFO: fusesoc_rc=${cmd_rc}"

if grep -q "MUBI_SYNC_STABILITY_TEST_PASS" "${RUN_LOG}"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

