tb_script:
#!/bin/bash
cd /home/opentitan
set -uo pipefail

export PATH="/tools/riscv/bin:/tools/verible/bin:$PATH"

TB_DIR=/home/opentitan/.tb_spi_host_access
BUILD_ROOT="$TB_DIR/build"
RUN_LOG="$BUILD_ROOT/sim-vcs/vcs.log"
TEST_NAME="spi_host_access"

mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import tlul_pkg::*;
  import top_pkg::*;
  import spi_host_reg_pkg::*;
  import prim_alert_pkg::*;
  import spi_device_pkg::*;

  localparam int ClkPeriodNs = 10;
  localparam logic [TL_AW-1:0] RXDATA_ADDR = 32'h24;
  localparam logic [TL_AW-1:0] TXDATA_ADDR = 32'h28;

  logic clk;
  logic rst_n;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  alert_rx_t [NumAlerts-1:0] alert_rx_i;
  alert_tx_t [NumAlerts-1:0] alert_tx_o;
  logic             cio_sck_o;
  logic             cio_sck_en_o;
  logic [NumCS-1:0] cio_csb_o;
  logic [NumCS-1:0] cio_csb_en_o;
  logic [3:0]       cio_sd_o;
  logic [3:0]       cio_sd_en_o;
  logic [3:0]       cio_sd_i;
  passthrough_req_t passthrough_i;
  passthrough_rsp_t passthrough_o;
  logic             intr_error_o;
  logic             intr_spi_event_o;

  spi_host dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .tl_i(tl_i),
    .tl_o(tl_o),
    .alert_rx_i(alert_rx_i),
    .alert_tx_o(alert_tx_o),
    .cio_sck_o(cio_sck_o),
    .cio_sck_en_o(cio_sck_en_o),
    .cio_csb_o(cio_csb_o),
    .cio_csb_en_o(cio_csb_en_o),
    .cio_sd_o(cio_sd_o),
    .cio_sd_en_o(cio_sd_en_o),
    .cio_sd_i(cio_sd_i),
    .passthrough_i(passthrough_i),
    .passthrough_o(passthrough_o),
    .intr_error_o(intr_error_o),
    .intr_spi_event_o(intr_spi_event_o)
  );

  initial clk = 1'b0;
  always #(ClkPeriodNs/2) clk = ~clk;

  task automatic set_default_bus;
    begin
      tl_i = TL_H2D_DEFAULT;
      tl_i.d_ready = 1'b1;
    end
  endtask

  task automatic tl_access(
      input  bit               write,
      input  logic [TL_AW-1:0] addr,
      input  logic [31:0]      wdata,
      input  logic [3:0]       mask,
      output logic             err,
      output logic [31:0]      rdata
  );
    tl_h2d_t req;
    begin
      req = TL_H2D_DEFAULT;
      req.d_ready = 1'b1;
      req.a_valid = 1'b1;
      req.a_opcode = write ? ((mask == 4'hf) ? PutFullData : PutPartialData) : Get;
      req.a_size = 2;
      req.a_source = '0;
      req.a_address = addr;
      req.a_mask = mask;
      req.a_data = wdata;
      req.a_user = TL_A_USER_DEFAULT;
      req.a_user.cmd_intg = get_cmd_intg(req);
      req.a_user.data_intg = get_data_intg(wdata);

      @(negedge clk);
      tl_i = req;
      do begin
        @(posedge clk);
      end while (!(tl_i.a_valid && tl_o.a_ready));

      @(negedge clk);
      set_default_bus();

      do begin
        @(posedge clk);
      end while (!tl_o.d_valid);

      err = tl_o.d_error;
      rdata = tl_o.d_data;
      @(posedge clk);
    end
  endtask

  task automatic expect_write_error(input logic [TL_AW-1:0] addr);
    logic err;
    logic [31:0] rdata;
    begin
      tl_access(1'b1, addr, 32'hA5A5_5A5A, 4'hf, err, rdata);
      if (!err) begin
        $error("expected write to 0x%0h to fail, but err=0 rdata=0x%08x", addr, rdata);
        $fatal(1);
      end
    end
  endtask

  task automatic expect_read_error(input logic [TL_AW-1:0] addr);
    logic err;
    logic [31:0] rdata;
    begin
      tl_access(1'b0, addr, 32'h0, 4'hf, err, rdata);
      if (!err) begin
        $error("expected read from 0x%0h to fail, but err=0 rdata=0x%08x", addr, rdata);
        $fatal(1);
      end
    end
  endtask

  initial begin
    int i;
    rst_n = 1'b0;
    cio_sd_i = '0;
    passthrough_i = PASSTHROUGH_REQ_DEFAULT;
    for (i = 0; i < NumAlerts; i++) begin
      alert_rx_i[i] = ALERT_RX_DEFAULT;
    end
    set_default_bus();

    repeat (5) @(posedge clk);
    rst_n = 1'b1;
    repeat (5) @(posedge clk);

    expect_write_error(RXDATA_ADDR);
    expect_read_error(TXDATA_ADDR);

    $display("SIM_PASS");
    $finish;
  end
endmodule
EOF

