tb_script:
#!/bin/bash
set -uo pipefail

cd /home/opentitan || exit 1

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  source /etc/opentitan_tools_path.sh
fi

TB_NAME="tlul_adapter_rsp_intg"
TB_DIR="/home/opentitan/.tb_${TB_NAME}"
BUILD_DIR="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import prim_mubi_pkg::*;
  import tlul_pkg::*;

  logic clk = 1'b0;
  logic rst_n = 1'b0;
  always #5 clk = ~clk;

  tl_h2d_t tl_i;
  tl_d2h_t tl_o;

  logic req;
  mubi4_e req_type;
  logic gnt;
  logic we;
  logic [11:0] addr;
  logic [31:0] wdata;
  logic [31:0] wmask;
  logic intg_error;
  logic [31:0] rdata;
  logic rvalid;
  logic [1:0] rerror;
  logic rsp_intg_err;
  logic saw_rsp_intg_err;

  logic pending_read;
  logic [31:0] mem_word;

  assign gnt = 1'b1;
  assign rerror = 2'b00;

  tlul_adapter_sram #(
    .SramAw(12),
    .SramDw(32),
    .Outstanding(4),
    .ByteAccess(1'b1),
    .CmdIntgCheck(1'b1),
    .EnableRspIntgGen(1'b1),
    .EnableDataIntgGen(1'b1)
  ) dut (
    .clk_i(clk),
    .rst_ni(rst_n),
    .tl_i(tl_i),
    .tl_o(tl_o),
    .en_ifetch_i(MuBi4False),
    .req_o(req),
    .req_type_o(req_type),
    .gnt_i(gnt),
    .we_o(we),
    .addr_o(addr),
    .wdata_o(wdata),
    .wmask_o(wmask),
    .intg_error_o(intg_error),
    .rdata_i(rdata),
    .rvalid_i(rvalid),
    .rerror_i(rerror)
  );

  tlul_rsp_intg_chk u_rsp_chk (
    .tl_i(tl_o),
    .err_o(rsp_intg_err)
  );

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      pending_read <= 1'b0;
      rvalid <= 1'b0;
      rdata <= '0;
      mem_word <= 32'h1122_3344;
      saw_rsp_intg_err <= 1'b0;
    end else begin
      if (tl_o.d_valid && tl_i.d_ready && rsp_intg_err) begin
        saw_rsp_intg_err <= 1'b1;
      end
      rvalid <= pending_read;
      if (pending_read) begin
        rdata <= mem_word;
      end
      pending_read <= req && gnt && !we;
      if (req && gnt && we) begin
        for (int i = 0; i < 4; i++) begin
          if (|wmask[i*8 +: 8]) begin
            mem_word[i*8 +: 8] <= wdata[i*8 +: 8];
          end
        end
      end
    end
  end

  always @(posedge clk) begin
    if (rst_n && req && gnt) begin
      $display("TB TRACE req we=%0b addr=0x%0h wmask=0x%0h wdata=0x%0h t=%0t",
               we, addr, wmask, wdata, $time);
    end
    if (rst_n && rvalid) begin
      $display("TB TRACE rvalid rdata=0x%0h t=%0t", rdata, $time);
    end
    if (rst_n && tl_o.d_valid && tl_i.d_ready) begin
      $display("TB TRACE host_rsp opcode=%0d size=%0d data=0x%0h rsp_err=%0b t=%0t",
               tl_o.d_opcode, tl_o.d_size, tl_o.d_data, rsp_intg_err, $time);
    end
  end

  task automatic send_partial_write();
    tl_h2d_t req_item;

    req_item = TL_H2D_DEFAULT;
    req_item.a_valid = 1'b1;
    req_item.a_opcode = PutPartialData;
    req_item.a_size = 2'h0;
    req_item.a_source = '0;
    req_item.a_address = '0;
    req_item.a_mask = 4'b0001;
    req_item.a_data = 32'h0000_00AA;
    req_item.a_user = TL_A_USER_DEFAULT;
    req_item.a_user.cmd_intg = get_cmd_intg(req_item);

    @(negedge clk);
    tl_i = req_item;
    do begin
      @(posedge clk);
    end while (!tl_o.a_ready);
    @(negedge clk);
    tl_i = TL_H2D_DEFAULT;
  endtask

  initial begin
    tl_i = TL_H2D_DEFAULT;

    repeat (5) @(posedge clk);
    rst_n = 1'b1;

    fork
      begin
        repeat (2) @(posedge clk);
        send_partial_write();
        @(posedge clk iff (tl_o.d_valid && tl_i.d_ready));
        #1;
        if (tl_o.d_size !== 2'h0) begin
          $fatal(1, "Expected byte-sized response, got d_size=%0d", tl_o.d_size);
        end
        if (saw_rsp_intg_err) begin
          $fatal(1, "Response integrity mismatch detected");
        end
        $display("TB PASS");
        $finish;
      end
      begin
        repeat (200) @(posedge clk);
        $fatal(1, "Timed out waiting for the write response");
      end
    join_any
    disable fork;
  end
endmodule
EOF

cat > "${TB_DIR}/tb.core" <<'EOF'
CAPI=2:
name: "mswe:tb:tlul_adapter_rsp_intg:0.1"
description: "Minimal TLUL adapter SRAM response integrity reproducer"

filesets:
  files_dv:
    depend:
      - lowrisc:tlul:adapter_sram:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource

parameters:
  SYNTHESIS:
    datatype: bool
    paramtype: vlogdefine

targets:
  default:
    default_tool: vcs
    parameters:
      - SYNTHESIS=true
    filesets:
      - files_dv
    toplevel: tb
EOF

set +e
timeout 1800 fusesoc \
  --cores-root /home/opentitan \
  --cores-root "${TB_DIR}" \
  run \
  --target default \
  --tool vcs \
  --no-export \
  --build-root "${BUILD_DIR}" \
  mswe:tb:tlul_adapter_rsp_intg:0.1 \
  2>&1 | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]] && grep -Fqx "TB PASS" "${RUN_LOG}"; then
  echo "TEST: ${TB_NAME} ... PASS"
  final_rc=0
else
  echo "TEST: ${TB_NAME} ... FAIL"
  final_rc=1
fi
echo "HWE_BENCH_RESULTS_END"

exit "${final_rc}"

