      q_prev <= ResetValue;
      q_curr <= ResetValue;
    end else begin
      q_prev <= q_curr;
      q_curr <= d_i;
    end
  end

  assign q_sync_o = q_curr;
  assign q_posedge_pulse_o = ~q_prev & q_curr;
  assign q_negedge_pulse_o = q_prev & ~q_curr;
endmodule
