tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set +e

TB_DIR=/home/opentitan/.tb_flash_lcmgr_fault
BUILD_DIR="$TB_DIR/build"
RUN_LOG="$TB_DIR/fusesoc_run.log"

rm -rf "$BUILD_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/flash_lcmgr_fault.core" <<'EOF'
CAPI=2:
name: "tbgen:dv:flash_lcmgr_fault:0.1"
description: "Minimal flash_ctrl_lcmgr single-bit upset simulation"

filesets:
  files_tb:
    depend:
      - lowrisc:ip:flash_ctrl_pkg
      - lowrisc:ip:flash_ctrl:0.1
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    toplevel: flash_lcmgr_fault_tb
    filesets:
      - files_tb
    default_tool: vcs
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module flash_lcmgr_fault_tb;
  import flash_ctrl_pkg::*;
  import flash_ctrl_reg_pkg::*;
  import lc_ctrl_pkg::*;
  import otp_ctrl_pkg::*;
  import top_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic clk_otp_i;
  logic rst_otp_ni;
  logic init_i;
  logic provision_en_i;
  flash_ctrl_reg2hw_control_reg_t ctrl_o;
  logic req_o;
  logic [top_pkg::TL_AW-1:0] addr_o;
  logic done_i;
  flash_ctrl_err_t err_i;
  logic rready_o;
  logic rvalid_i;
  logic wvalid_o;
  logic wready_i;
  logic [BusWidth-1:0] rdata_i;
  logic [BusWidth-1:0] wdata_o;
  lc_tx_t rma_req_i;
  lc_tx_t rma_ack_o;
  logic [NumSeeds-1:0][SeedWidth-1:0] seeds_o;
  flash_lcmgr_phase_e phase_o;
  logic fatal_err_o;
  logic seed_err_o;
  logic rd_buf_en_o;
  flash_otp_key_req_t otp_key_req_o;
  flash_otp_key_rsp_t otp_key_rsp_i;
  flash_key_t addr_key_o;
  flash_key_t data_key_o;
  flash_key_t rand_addr_key_o;
  flash_key_t rand_data_key_o;
  logic edn_req_o;
  logic edn_ack_i;
  logic lfsr_en_o;
  logic [BusWidth-1:0] rand_i;
  logic init_busy_o;

  flash_ctrl_lcmgr dut (.*);

  always #5 clk_i = ~clk_i;
  always #7 clk_otp_i = ~clk_otp_i;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    clk_otp_i = 1'b0;
    rst_otp_ni = 1'b0;
    init_i = 1'b0;
    provision_en_i = 1'b0;
    done_i = 1'b0;
    err_i = '0;
    rvalid_i = 1'b0;
    wready_i = 1'b1;
    rdata_i = '0;
    rma_req_i = lc_ctrl_pkg::Off;
    edn_ack_i = 1'b1;
    rand_i = 64'h0123_4567_89ab_cdef;
    otp_key_rsp_i = otp_ctrl_pkg::FLASH_OTP_KEY_RSP_DEFAULT;
    otp_key_rsp_i.data_ack = 1'b0;
    otp_key_rsp_i.addr_ack = 1'b0;
    otp_key_rsp_i.seed_valid = 1'b0;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_otp_ni = 1'b1;

    repeat (2) @(posedge clk_i);

    if ($bits(dut.rma_state_q) == 3) begin
      $display("LEGACY_RMA_FSM width=%0d", $bits(dut.rma_state_q));
      force dut.rma_state_q = 3'b011;
    end else begin
      $display("HARDENED_RMA_FSM width=%0d", $bits(dut.rma_state_q));
      force dut.rma_state_q = 10'b0100011101;
    end

    @(posedge clk_i);
    release dut.rma_state_q;
    @(posedge clk_i);

    if ($bits(dut.rma_state_q) == 3) begin
      if (dut.err_sts != lc_ctrl_pkg::On) begin
        $fatal(1, "Legacy FSM unexpectedly flagged an upset, err_sts=%b", dut.err_sts);
      end
      $display("LEGACY_NO_DETECTION err_sts=%b", dut.err_sts);
      $fatal(1, "Single-bit RMA FSM upset was not detected");
    end else begin
      if (dut.err_sts != lc_ctrl_pkg::Off) begin
        $fatal(1, "Sparse FSM failed to flag an upset, err_sts=%b", dut.err_sts);
      end
      if (^fatal_err_o !== 1'bX && fatal_err_o !== 1'b1) begin
        $fatal(1, "fatal_err_o was not asserted");
      end
      $display("SPARSE_DETECTED err_sts=%b fatal_err_o=%b", dut.err_sts, fatal_err_o);
      $finish;
    end
  end

  initial begin
    repeat (40) @(posedge clk_i);
    $fatal(1, "Timed out waiting for flash_ctrl_lcmgr upset detection");
  end
endmodule
EOF

timeout 1200 fusesoc --cores-root /home/opentitan --cores-root "$TB_DIR" \
  run --no-export --build-root "$BUILD_DIR" --target=sim --tool=vcs \
  --flag fileset_ip \
  tbgen:dv:flash_lcmgr_fault:0.1 >"$RUN_LOG" 2>&1
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ] && grep -q "SPARSE_DETECTED" "$RUN_LOG"; then
  echo "TEST: flash_lcmgr_fsm_fault ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: flash_lcmgr_fsm_fault ... FAIL"
echo "HWE_BENCH_RESULTS_END"

if [ -f "$RUN_LOG" ]; then
  tail -n 80 "$RUN_LOG" >&2
fi

exit 1

