#!/bin/bash
set -euo pipefail
cd /home/opentitan

TEST_NAME="keymgr_init_lc_disable"
TB_ROOT="/home/opentitan/.tb_${TEST_NAME}"
SCRATCH_ROOT="${TB_ROOT}/scratch"
SEQ_FILE="hw/ip/keymgr/dv/env/seq_lib/${TEST_NAME}_vseq.sv"
CORE_FILE="hw/ip/keymgr/dv/env/keymgr_env.core"
VSEQ_LIST_FILE="hw/ip/keymgr/dv/env/seq_lib/keymgr_vseq_list.sv"
SIM_CFG_FILE="hw/ip/keymgr/dv/keymgr_sim_cfg.hjson"
IF_FILE="hw/ip/keymgr/dv/env/keymgr_if.sv"
RUN_LOG="${TB_ROOT}/dvsim.log"

report_result() {
  local rc=$?
  trap - EXIT
  echo "HWE_BENCH_RESULTS_START"
  if [[ ${rc} -eq 0 ]]; then
    echo "TEST: ${TEST_NAME} ... PASS"
  else
    echo "TEST: ${TEST_NAME} ... FAIL"
  fi
  echo "HWE_BENCH_RESULTS_END"
  exit "${rc}"
}

trap report_result EXIT

rm -rf "${TB_ROOT}"
mkdir -p "${TB_ROOT}"

cat > "${SEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_init_lc_disable_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_init_lc_disable_vseq)
  `uvm_object_new

  constraint do_op_before_init_c {
    do_op_before_init == 0;
  }

  virtual task body();
    bit [TL_DW-1:0] op_status;
    bit [TL_DW-1:0] err_code;

    `uvm_info(`gfn, "Trigger lc disable during reset advance", UVM_MEDIUM)

    ral.control.start.set(1'b1);
    ral.control.operation.set(keymgr_pkg::OpAdvance);
    csr_update(.csr(ral.control));
    ral.control.start.set(1'b0);

    // Drop lc enable while the controller is still in the randomization phase so that the
    // synchronized disable reaches StCtrlRootKey / init deterministically.
    cfg.keymgr_vif.wait_for_init_disable_window();
    cfg.keymgr_vif.keymgr_en = lc_ctrl_pkg::Off;

    csr_spinwait(.ptr(ral.op_status.status),
                 .exp_data(keymgr_pkg::OpWip),
                 .compare_op(CompareOpNe),
                 .spinwait_delay_ns(100));

    csr_rd(.ptr(ral.op_status), .value(op_status));
    `DV_CHECK_EQ(op_status[2:0], keymgr_pkg::OpDoneFail)

    csr_rd(.ptr(ral.err_code), .value(err_code));
    `DV_CHECK_EQ(err_code[keymgr_pkg::ErrInvalidOp], 1'b1)
  endtask : body

endclass : keymgr_init_lc_disable_vseq
EOF

