  always @(posedge clk_i) begin
    if (!rst_ni) saw_sba_valid <= 1'b0;
    else if (sba_tl_h_o.a_valid) saw_sba_valid <= 1'b1;
  end

  initial begin
    regs_tl_d_i = tlul_pkg::TL_H2D_DEFAULT;
    rom_tl_d_i = tlul_pkg::TL_H2D_DEFAULT;
    sba_tl_h_i = tlul_pkg::TL_D2H_DEFAULT;
    alert_rx_i = '{default: prim_alert_pkg::ALERT_RX_DEFAULT};
    unavailable_i = '0;
    lc_hw_debug_en_i = lc_ctrl_pkg::Off;
    scanmode_i = lc_ctrl_pkg::Off;
    scan_rst_ni = 1'b1;
    rst_ni = 1'b0;
    jtag_i.trst_n = 1'b0;
    jtag_i.tms = 1'b1;
    jtag_i.tdi = 1'b0;

    repeat (10) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (10) @(posedge clk_i);
    jtag_i.trst_n = 1'b1;
    repeat (10) @(negedge jtag_i.tck);

    jtag_dmi_wr(7'h10, 32'h00000001);
    jtag_dmi_wr(7'h38, 32'h00047000);
    jtag_dmi_wr(7'h39, 32'h00000040);
    jtag_dmi_wr(7'h3c, 32'h12345678);
    jtag_dmi_wr(7'h38, 32'h00147000);
    jtag_dmi_wr(7'h39, 32'h00000040);
    jtag_dmi_rd(7'h3c);
    jtag_dmi_rd(7'h3c);

    repeat (100) @(posedge clk_i);

    if (saw_sba_valid) begin
      $display("Observed unauthorized SBA request while lc_hw_debug_en_i=Off");
      $fatal(1);
    end

    $display("No SBA request observed while lc_hw_debug_en_i=Off");
    $finish;
  end

  task automatic jtag_dmi_wr(input bit [6:0] addr, input bit [31:0] data);
    bit [63:0] dout;
    jtag_shift(5, 5'h11, 41, {addr, data, 2'h2}, dout);
  endtask

  task automatic jtag_dmi_rd(input bit [6:0] addr);
    bit [63:0] dout;
    jtag_shift(5, 5'h11, 41, {addr, 32'h0, 2'h1}, dout);
    jtag_shift(5, 5'h11, 41, {addr, 32'h0, 2'h0}, dout);
  endtask

  task automatic jtag_shift(
    input int alen,
    input bit [4:0] addr,
    input int dlen,
    input bit [63:0] din,
    output bit [63:0] dout
  );
    jtag_shift_ir(alen, addr);
    jtag_shift_dr(dlen, din, dout);
  endtask

  task automatic jtag_shift_ir(input int alen, input bit [4:0] addr);
    jtag_i.tms = 1'b1;
    jtag_i.tdi = 1'b0;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b1;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b0;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b0;
    @(negedge jtag_i.tck);
    for (int i = 0; i < alen; i++) begin
      jtag_i.tms = (i == alen - 1);
      jtag_i.tdi = addr[i];
      @(negedge jtag_i.tck);
    end
    jtag_i.tms = 1'b1;
    jtag_i.tdi = 1'b0;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b0;
    @(negedge jtag_i.tck);
  endtask

  task automatic jtag_shift_dr(input int dlen, input bit [63:0] data, output bit [63:0] dout);
    jtag_i.tms = 1'b1;
    jtag_i.tdi = 1'b0;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b0;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b0;
    @(negedge jtag_i.tck);
    for (int i = 0; i < dlen - 1; i++) begin
      jtag_i.tms = 1'b0;
      jtag_i.tdi = data[i];
      @(posedge jtag_i.tck);
      dout[i] = jtag_o.tdo;
      @(negedge jtag_i.tck);
    end
    jtag_i.tms = 1'b1;
    jtag_i.tdi = data[dlen - 1];
    @(posedge jtag_i.tck);
    dout[dlen - 1] = jtag_o.tdo;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b1;
    jtag_i.tdi = 1'b0;
    @(negedge jtag_i.tck);
    jtag_i.tms = 1'b0;
    @(negedge jtag_i.tck);
  endtask
endmodule
SV

