#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="keymgr_sideload_clear_independence"
TB_DIR="/home/opentitan/.tb_keymgr_sideload_clear"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_util_pkg.sv" <<'EOF'
package prim_util_pkg;
  function automatic int vbits(int value);
    if (value <= 1) begin
      return 1;
    end
    return $clog2(value);
  endfunction
endpackage
EOF

cat > "${TB_DIR}/keymgr_reg_pkg.sv" <<'EOF'
package keymgr_reg_pkg;
  parameter int NumSwBindingReg = 1;
  parameter int NumSaltReg = 1;
endpackage
EOF

cat > "${TB_DIR}/edn_pkg.sv" <<'EOF'
package edn_pkg;
  parameter int ENDPOINT_BUS_WIDTH = 32;
endpackage
EOF

cat > "${TB_DIR}/kmac_pkg.sv" <<'EOF'
package kmac_pkg;
  parameter int AppDigestW = 384;
endpackage
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import keymgr_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic init_i;
  keymgr_sideload_clr_e clr_key_i;
  logic wipe_key_i;
  logic [Shares-1:0][RandWidth-1:0] entropy_i;
  keymgr_key_dest_e dest_sel_i;
  keymgr_gen_out_e key_sel_i;
  logic data_en_i;
  logic data_valid_i;
  hw_key_req_t key_i;
  logic [Shares-1:0][kmac_pkg::AppDigestW-1:0] data_i;
  logic prng_en_o;
  hw_key_req_t aes_key_o;
  hw_key_req_t kmac_key_o;
  otbn_key_req_t otbn_key_o;

  keymgr_sideload_key_ctrl dut (
    .clk_i,
    .rst_ni,
    .init_i,
    .clr_key_i,
    .wipe_key_i,
    .entropy_i,
    .dest_sel_i,
    .key_sel_i,
    .data_en_i,
    .data_valid_i,
    .key_i,
    .data_i,
    .prng_en_o,
    .aes_key_o,
    .kmac_key_o,
    .otbn_key_o
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic tick(input int cycles);
    repeat (cycles) @(posedge clk_i);
  endtask

  task automatic reset_inputs();
    begin
      init_i = 1'b0;
      clr_key_i = SideLoadClrIdle;
      wipe_key_i = 1'b0;
      dest_sel_i = None;
      key_sel_i = HwKey;
      data_en_i = 1'b0;
      data_valid_i = 1'b0;
      key_i = '0;
      data_i = '0;
    end
  endtask

  task automatic load_sideload_key(
    input keymgr_key_dest_e dest,
    input logic [kmac_pkg::AppDigestW-1:0] share0,
    input logic [kmac_pkg::AppDigestW-1:0] share1
  );
    begin
      @(negedge clk_i);
      dest_sel_i = dest;
      key_sel_i = HwKey;
      data_en_i = 1'b1;
      data_valid_i = 1'b1;
      key_i.valid = 1'b1;
      data_i[0] = share0;
      data_i[1] = share1;
      @(negedge clk_i);
      dest_sel_i = None;
      data_en_i = 1'b0;
      data_valid_i = 1'b0;
      key_i.valid = 1'b0;
      data_i = '0;
    end
  endtask

  initial begin
    reset_inputs();
    entropy_i[0] = 32'h11112222;
    entropy_i[1] = 32'h33334444;

    rst_ni = 1'b0;
    tick(2);
    rst_ni = 1'b1;

    @(negedge clk_i);
    init_i = 1'b1;
    @(negedge clk_i);
    init_i = 1'b0;
    tick(1);

    load_sideload_key(Aes, 384'h0000_0000_0000_0000_0000_0000_0000_0000_0123_4567_89ab_cdef,
                      384'h0000_0000_0000_0000_0000_0000_0000_0000_fedc_ba98_7654_3210);
    tick(1);
    if (aes_key_o.valid !== 1'b1) begin
      $fatal(1, "AES sideload key did not become valid");
    end

    load_sideload_key(Otbn, 384'h0000_0000_0000_0000_0123_4567_89ab_cdef_fedc_ba98_7654_3210_1111_2222_3333_4444,
                       384'h0000_0000_0000_0000_ffff_eeee_dddd_cccc_bbbb_aaaa_9999_8888_7777_6666_5555_4444);
    tick(1);
    if (otbn_key_o.valid !== 1'b1) begin
      $fatal(1, "OTBN sideload key did not become valid");
    end
    if (aes_key_o.valid !== 1'b1) begin
      $fatal(1, "AES sideload key unexpectedly dropped before clear");
    end

    @(negedge clk_i);
    clr_key_i = SideLoadClrOtbn;
    @(negedge clk_i);
    clr_key_i = SideLoadClrIdle;
    tick(2);

    if (otbn_key_o.valid !== 1'b0) begin
      $fatal(1, "OTBN sideload key was not cleared");
    end
    if (aes_key_o.valid !== 1'b1) begin
      $fatal(1, "AES sideload key was cleared when OTBN was cleared");
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<'EOF'
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/.tb_keymgr_sideload_clear/prim_util_pkg.sv
/home/opentitan/.tb_keymgr_sideload_clear/keymgr_reg_pkg.sv
/home/opentitan/.tb_keymgr_sideload_clear/edn_pkg.sv
/home/opentitan/.tb_keymgr_sideload_clear/kmac_pkg.sv
/home/opentitan/hw/ip/keymgr/rtl/keymgr_pkg.sv
/home/opentitan/hw/ip/keymgr/rtl/keymgr_sideload_key.sv
/home/opentitan/hw/ip/keymgr/rtl/keymgr_sideload_key_ctrl.sv
/home/opentitan/.tb_keymgr_sideload_clear/tb.sv
EOF

timeout 1800 bash -lc "
  cd '${TB_DIR}' &&
  vcs -full64 -sverilog +define+SYNTHESIS -f '${TB_DIR}/files.f' -l '${COMPILE_LOG}' -o '${TB_DIR}/simv' &&
  '${TB_DIR}/simv' -l '${RUN_LOG}'
"
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [[ ${rc} -eq 0 ]] && grep -q 'TB_PASS' "${RUN_LOG}"; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

if [[ ${rc} -eq 0 ]]; then
  rc=1
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit ${rc}

#!/bin/bash
cd /home/opentitan || exit 1
set +e

cat > hw/ip/aes/dv/env/seq_lib/aes_shadow_field_update_vseq.sv <<'SV'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class aes_shadow_field_update_vseq extends aes_base_vseq;
  `uvm_object_utils(aes_shadow_field_update_vseq)
  `uvm_object_new

  virtual task pre_start();
    super.pre_start();
    cfg.en_scb = 0;
  endtask

  virtual task body();
    bit [TL_DW-1:0] first_ctrl;
    bit [TL_DW-1:0] second_ctrl;
    bit [TL_DW-1:0] read_ctrl;
    bit             alert_triggered;
    string          alert_name;

    alert_name = ral.ctrl_shadowed.get_update_err_alert_name();
    first_ctrl = '0;
    second_ctrl = '0;
    alert_triggered = 0;

    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));

    // Keep all fields identical across the two writes except manual_operation.
    // On the fixed design, operation still commits while manual_operation is blocked.
    first_ctrl[0] = 1'b1;
    first_ctrl[6:1] = aes_pkg::AES_ECB;
    first_ctrl[9:7] = aes_pkg::AES_128;
    first_ctrl[10] = 1'b1;

    second_ctrl = first_ctrl;
    second_ctrl[10] = 1'b0;

    csr_wr(.ptr(ral.ctrl_shadowed), .value(first_ctrl), .en_shadow_wr(0), .blocking(1),
           .predict(0));
    shadow_reg_wr(ral.ctrl_shadowed, second_ctrl, alert_triggered);

    `DV_SPINWAIT(if (!alert_triggered) begin
                   while (!cfg.m_alert_agent_cfg[alert_name].vif.get_alert()) begin
                     cfg.clk_rst_vif.wait_clks(1);
                   end
                 end,
                 $sformatf("%0s update_err alert not detected", alert_name))
    `DV_SPINWAIT(cfg.m_alert_agent_cfg[alert_name].vif.wait_ack_complete();,
                 $sformatf("timeout for alert:%0s", alert_name))

    csr_rd(.ptr(ral.ctrl_shadowed), .value(read_ctrl), .blocking(1));

    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.operation, read_ctrl), 1'b1)
    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.manual_operation, read_ctrl), 1'b0)
    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.mode, read_ctrl), aes_pkg::AES_ECB)
    `DV_CHECK_EQ(get_field_val(ral.ctrl_shadowed.key_len, read_ctrl), aes_pkg::AES_128)
  endtask

endclass
SV

