#!/bin/bash
cd /home/opentitan

set -uo pipefail
set +e
export PATH="/tools/riscv/bin:/tools/verible/bin:${PATH}"

TEST_NAME="aon_timer_wkup_latched"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
SCRATCH_DIR="${TB_DIR}/scratch"
RUN_LOG="${TB_DIR}/dvsim.log"
VSEQ_PATH="/home/opentitan/hw/ip/aon_timer/dv/env/seq_lib/aon_timer_smoke_vseq.sv"

mkdir -p "${TB_DIR}"
rm -rf "${SCRATCH_DIR}"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

cat > "${VSEQ_PATH}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class aon_timer_smoke_vseq extends aon_timer_base_vseq;
  `uvm_object_utils(aon_timer_smoke_vseq)

  localparam int WkupReqIdx = 1;

  constraint deterministic_c {
    initial_lc_escalate_en == 0;
    initial_sleep_mode == 0;
  }

  `uvm_object_new

  task pre_start();
    if (cfg == null) set_handles();
    cfg.en_scb = 0;
    super.pre_start();
  endtask : pre_start

  task body();
    bit asserted;
    bit [31:0] cause;

    cfg.sleep_vif.drive(1'b1);
    cfg.aon_clk_rst_vif.wait_clks(4);
    `DV_CHECK_EQ(cfg.aon_intr_vif.sample_pin(.idx(WkupReqIdx)), 1'b0)

    csr_wr(.ptr(ral.wkup_thold), .value(32'd0));
    csr_wr(.ptr(ral.wkup_ctrl), .value(32'h1));

    for (int i = 0; i < 20; i++) begin
      cfg.aon_clk_rst_vif.wait_clks(1);
      if (cfg.aon_intr_vif.sample_pin(.idx(WkupReqIdx)) == 1'b1) begin
        asserted = 1'b1;
        break;
      end
    end

    if (!asserted) begin
      `uvm_fatal(`gfn, "Wakeup request did not assert")
    end

    csr_spinwait(.ptr(ral.wkup_cause.cause), .exp_data(1'b1));
    csr_rd(.ptr(ral.wkup_cause), .value(cause));
    `DV_CHECK_EQ(cause[0], 1'b1)

    cfg.sleep_vif.drive(1'b0);
    cfg.aon_clk_rst_vif.wait_clks(4);
    `DV_CHECK_EQ(cfg.aon_intr_vif.sample_pin(.idx(WkupReqIdx)), 1'b1,
                 "Wakeup request dropped before software cleared WKUP_CAUSE")

    csr_wr(.ptr(ral.wkup_cause), .value(32'd0));
    cfg.aon_clk_rst_vif.wait_clks(6);
    `DV_CHECK_EQ(cfg.aon_intr_vif.sample_pin(.idx(WkupReqIdx)), 1'b0,
                 "Wakeup request did not clear after software ack")
  endtask : body

endclass : aon_timer_smoke_vseq
EOF

./util/dvsim/dvsim.py \
  hw/ip/aon_timer/dv/aon_timer_sim_cfg.hjson \
  -i aon_timer_smoke \
  -t vcs \
  --local \
  --max-parallel 1 \
  --fixed-seed 1 \
  --reseed 1 \
  --purge \
  --scratch-root "${SCRATCH_DIR}" \
  > "${RUN_LOG}" 2>&1
rc=$?

if [ "${rc}" -eq 0 ]; then
  emit_result PASS
  exit 0
fi

tail -n 200 "${RUN_LOG}"
emit_result FAIL
exit 1

