package prim_util_pkg;
  function automatic int vbits(input int value);
    int tmp;
    begin
      if (value <= 1) return 1;
      tmp = value - 1;
      vbits = 0;
      while (tmp > 0) begin
        vbits++;
        tmp = tmp >> 1;
      end
    end
  endfunction
endpackage

package keymgr_reg_pkg;
  parameter int NumSaltReg = 8;
  parameter int NumSwBindingReg = 8;
endpackage

package edn_pkg;
