    kmac_data_i[0] = 256'hdeadbeef;
    kmac_data_i[1] = '0;

    begin
      keymgr_op_status_e done_status;
      logic [ErrLastPos-1:0] done_error;
      keymgr_working_state_e final_state;
      run_advance(done_status, done_error, final_state);

`ifdef FIX_KMAC_PARAM
      if (done_status != OpDoneSuccess) begin
        $fatal(1, "Expected OpDoneSuccess, got %0d", done_status);
      end
      if (final_state != StCreatorRootKey) begin
        $fatal(1, "Expected StCreatorRootKey, got %0d", final_state);
      end
      $display("FIXED_PATH_PASS");
      $finish(0);
`else
      if (done_status != OpDoneFail) begin
        $fatal(1, "Expected OpDoneFail, got %0d", done_status);
      end
      if (!done_error[ErrInvalidOut]) begin
        $fatal(1, "Expected ErrInvalidOut to be asserted, got %b", done_error);
      end
      if (final_state != StDisabled) begin
        $fatal(1, "Expected StDisabled, got %0d", final_state);
      end
      $display("BUG_REPRODUCED");
      $fatal(1, "Base design disables keymgr when share1 is zero");
`endif
    end
  end
endmodule
