compile_and_run() {
  local build_dir="$1"
  local extra_define="$2"
  local compile_log="$build_dir/compile.log"
  local run_log="$build_dir/run.log"

  rm -rf "$build_dir"
  mkdir -p "$build_dir"

  local vcs_cmd=(
    vcs
    -full64
    -sverilog
    -timescale=1ns/1ps
    +define+SYNTHESIS
    +incdir+/home/opentitan/hw/ip/prim/rtl
  )

  if [[ -n "$extra_define" ]]; then
    vcs_cmd+=("$extra_define")
  fi

  vcs_cmd+=(
    "$TB_DIR/stubs.sv"
    "/home/opentitan/hw/ip/keymgr/rtl/keymgr_pkg.sv"
    "/home/opentitan/hw/ip/keymgr/rtl/keymgr_cnt.sv"
    "/home/opentitan/hw/ip/keymgr/rtl/keymgr_ctrl.sv"
    "$TB_DIR/tb.sv"
    -top
    tb
    -o
    "$build_dir/simv"
  )

  "${vcs_cmd[@]}" >"$compile_log" 2>&1
  local compile_rc=$?
  if [[ $compile_rc -ne 0 ]]; then
    tail -n 60 "$compile_log"
    return 125
  fi

  "$build_dir/simv" >"$run_log" 2>&1
  cat "$run_log"

  if grep -q "FIXED_PATH_PASS" "$run_log"; then
    return 0
  fi
  if grep -q "BUG_REPRODUCED" "$run_log"; then
    return 1
  fi
  return 2
}

rc=0
compile_and_run "$TB_DIR/build_fix_param" "+define+FIX_KMAC_PARAM"
rc=$?
if [[ $rc -ne 0 ]]; then
  compile_and_run "$TB_DIR/build_legacy" ""
  rc=$?
fi

echo "HWE_BENCH_RESULTS_START"
if [[ $rc -eq 0 ]]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

