#!/bin/bash
cd /home/opentitan
set -uo pipefail
set +e

TEST_NAME="rstmgr_reset_sync"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
BUILD_DIR="${TB_DIR}/build"
BUILD_LOG="${TB_DIR}/build.log"
RUN_LOG="${TB_DIR}/run.log"
SIM_BIN="${TB_DIR}/simv"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

python - <<'PY'
from pathlib import Path
import re

tb_dir = Path("/home/opentitan/.tb_rstmgr_reset_sync")
tb_path = tb_dir / "tb.sv"

candidates = [
    Path("/home/opentitan/hw/top_earlgrey/ip/rstmgr/rtl/autogen/rstmgr.sv"),
    Path("/home/opentitan/hw/ip/rstmgr/rtl/rstmgr.sv"),
]
rtl_path = next((p for p in candidates if p.exists()), None)
if rtl_path is None:
    raise SystemExit("Unable to locate rstmgr RTL source")

text = rtl_path.read_text(encoding="utf-8")
match = re.search(r"module\s+rstmgr\b.*?\((.*?)\);\s*", text, re.S)
if match is None:
    raise SystemExit(f"Unable to parse rstmgr module header from {rtl_path}")

header = match.group(1)
ports = re.findall(r"\b(?:input|output|inout)\b[^;\n,]*?\b([A-Za-z_][A-Za-z0-9_]*)\b(?=\s*(?:,|\n))", header)
has_split_por = any(name != "rst_ni" and "por" in name.lower() for name in ports)

decls = {
    "clk_i": "logic clk_i = 1'b0;",
    "clk_aon_i": "logic clk_aon_i = 1'b0;",
    "clk_main_i": "logic clk_main_i = 1'b0;",
    "clk_io_i": "logic clk_io_i = 1'b0;",
    "clk_io_div2_i": "logic clk_io_div2_i = 1'b0;",
    "clk_io_div4_i": "logic clk_io_div4_i = 1'b0;",
    "clk_usb_i": "logic clk_usb_i = 1'b0;",
    "scan_rst_ni": "logic scan_rst_ni;",
    "rst_cpu_n_i": "logic rst_cpu_n_i;",
    "ndmreset_req_i": "logic ndmreset_req_i;",
    "scanmode_i": "lc_ctrl_pkg::lc_tx_t scanmode_i;",
    "tl_i": "tlul_pkg::tl_h2d_t tl_i;",
    "tl_o": "tlul_pkg::tl_d2h_t tl_o;",
    "alert_rx_i": "prim_alert_pkg::alert_rx_t [NumAlerts-1:0] alert_rx_i;",
    "alert_tx_o": "prim_alert_pkg::alert_tx_t [NumAlerts-1:0] alert_tx_o;",
    "pwr_i": "pwrmgr_pkg::pwr_rst_req_t pwr_i;",
    "pwr_o": "pwrmgr_pkg::pwr_rst_rsp_t pwr_o;",
    "alert_dump_i": "alert_pkg::alert_crashdump_t alert_dump_i;",
    "cpu_dump_i": "ibex_pkg::crash_dump_t cpu_dump_i;",
    "resets_ast_o": "rstmgr_ast_out_t resets_ast_o;",
    "resets_o": "rstmgr_out_t resets_o;",
}

extra_por_inputs = [name for name in ports if name != "rst_ni" and "por" in name.lower()]
for name in extra_por_inputs:
    decls[name] = f"wire {name} = por_n;"

for name in ports:
    if name not in decls and name not in {"rst_ni"}:
        raise SystemExit(f"Unhandled rstmgr port in generated TB: {name}")

connections = []
for name in ports:
    if name == "rst_ni":
        connections.append(f"    .{name}(rst_ni)")
    else:
        connections.append(f"    .{name}({name})")
conn_text = ",\n".join(connections)
sync_block = ""
if has_split_por:
    sync_block = (
        "  always_ff @(posedge clk_i or negedge por_n) begin\n"
        "    if (!por_n) begin\n"
        "      rst_sync_ff1 <= 1'b0;\n"
        "      rst_sync_ff2 <= 1'b0;\n"
        "    end else begin\n"
        "      rst_sync_ff1 <= 1'b1;\n"
        "      rst_sync_ff2 <= rst_sync_ff1;\n"
        "    end\n"
        "  end\n"
    )

tb = f"""module tb;
  import rstmgr_pkg::*;
  import rstmgr_reg_pkg::*;

  logic por_n = 1'b0;
  logic rst_sync_ff1;
  logic rst_sync_ff2;
  {'wire rst_ni = rst_sync_ff2;' if has_split_por else 'wire rst_ni = por_n;'}
  {chr(10).join('  ' + decls[name] for name in ports if name != 'rst_ni')}

  time last_clk_i_edge = 0;
  bit saw_release = 0;

  always #10 clk_i = ~clk_i;
  always #4 clk_aon_i = ~clk_aon_i;
  always #7 clk_main_i = ~clk_main_i;
  always #6 clk_io_i = ~clk_io_i;
  always #5 clk_io_div2_i = ~clk_io_div2_i;
  always #10 clk_io_div4_i = ~clk_io_div4_i;
  always #9 clk_usb_i = ~clk_usb_i;

{sync_block}

  always @(posedge clk_i) begin
    last_clk_i_edge = $time;
  end

  always @(posedge dut.u_reg.rst_ni) begin
    saw_release = 1'b1;
    if ($time != last_clk_i_edge) begin
      $display("RESET_RELEASE_MISALIGNED release=%0t last_clk=%0t", $time, last_clk_i_edge);
      $fatal(1, "u_reg.rst_ni deasserted off the clk_i edge");
    end
    $display("RESET_RELEASE_ALIGNED release=%0t", $time);
  end

  initial begin
    tl_i = '{{default: '0}};
    alert_rx_i = '{{default: prim_alert_pkg::ALERT_RX_DEFAULT}};
    pwr_i = '{{default: '0}};
    alert_dump_i = '0;
    cpu_dump_i = '0;
    scan_rst_ni = 1'b1;
    scanmode_i = lc_ctrl_pkg::Off;
    rst_cpu_n_i = 1'b1;
    ndmreset_req_i = 1'b0;
    pwr_i.reset_cause = pwrmgr_pkg::ResetNone;

    repeat (3) @(posedge clk_i);
    #1;
    por_n = 1'b1;

    repeat (120) @(posedge clk_i);
    if (!saw_release) begin
      $fatal(1, "u_reg.rst_ni never deasserted");
    end
    $display("TB PASS");
    $finish;
  end

  rstmgr dut (
{conn_text}
  );
endmodule
"""

tb_path.write_text(tb, encoding="utf-8")
PY
gen_rc=$?
if [[ ${gen_rc} -ne 0 ]]; then
  emit_result "FAIL"
  exit "${gen_rc}"
fi

cat > "${TB_DIR}/rstmgr_reset_sync_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:rstmgr_reset_sync_tb:0.1"
description: "Behavioral rstmgr reset synchrony testbench"

filesets:
  files_tb:
    depend:
      - lowrisc:ip:rstmgr
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: tb
    filesets:
      - files_tb
EOF

timeout 1700 fusesoc --cores-root . --cores-root "${TB_DIR}" run \
  --build-root "${TB_DIR}/build" \
  --flag=fileset_top \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:rstmgr_reset_sync_tb:0.1 \
  > "${BUILD_LOG}" 2>&1
rc=$?

if [[ ${rc} -eq 0 ]] && [[ -f "${BUILD_LOG}" ]]; then
  if grep -q "Fatal:" "${BUILD_LOG}" || ! grep -q "TB PASS" "${BUILD_LOG}"; then
    rc=1
  fi
fi

if [[ ${rc} -eq 0 ]]; then
  emit_result "PASS"
else
  if [[ -f "${BUILD_LOG}" ]]; then
    tail -n 80 "${BUILD_LOG}"
  fi
  emit_result "FAIL"
fi

exit "${rc}"

