cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import flash_ctrl_pkg::*;

  bit creator_rma_attr, owner_rma_attr, isolated_rma_attr;
  bit creator_wipe, owner_wipe, isolated_wipe, data0_wipe, data1_wipe;

  function automatic bit is_rma_prog_erase_cfg(info_page_cfg_t cfg);
    return cfg.en && cfg.rd_en && cfg.prog_en && cfg.erase_en &&
           cfg.scramble_en && cfg.ecc_en && cfg.he_en;
  endfunction

  initial begin
    foreach (HwInfoPageAttr[i]) begin
      if (HwInfoPageAttr[i].phase == PhaseRma && is_rma_prog_erase_cfg(HwInfoPageAttr[i].cfg)) begin
        if (HwInfoPageAttr[i].page.sel == SeedInfoSel &&
            HwInfoPageAttr[i].page.addr == {SeedBank, CreatorInfoPage}) creator_rma_attr = 1'b1;
        if (HwInfoPageAttr[i].page.sel == SeedInfoSel &&
            HwInfoPageAttr[i].page.addr == {SeedBank, OwnerInfoPage}) owner_rma_attr = 1'b1;
        if (HwInfoPageAttr[i].page.sel == SeedInfoSel &&
            HwInfoPageAttr[i].page.addr == {SeedBank, IsolatedInfoPage}) isolated_rma_attr = 1'b1;
      end
    end

    foreach (RmaWipeEntries[i]) begin
      if (RmaWipeEntries[i].bank == SeedBank &&
          RmaWipeEntries[i].part == FlashPartInfo &&
          RmaWipeEntries[i].info_sel == SeedInfoSel &&
          RmaWipeEntries[i].start_page == {1'b0, CreatorInfoPage} &&
          RmaWipeEntries[i].num_pages == 1) creator_wipe = 1'b1;
      if (RmaWipeEntries[i].bank == SeedBank &&
          RmaWipeEntries[i].part == FlashPartInfo &&
          RmaWipeEntries[i].info_sel == SeedInfoSel &&
          RmaWipeEntries[i].start_page == {1'b0, OwnerInfoPage} &&
          RmaWipeEntries[i].num_pages == 1) owner_wipe = 1'b1;
      if (RmaWipeEntries[i].bank == SeedBank &&
          RmaWipeEntries[i].part == FlashPartInfo &&
          RmaWipeEntries[i].info_sel == SeedInfoSel &&
          RmaWipeEntries[i].start_page == {1'b0, IsolatedInfoPage} &&
          RmaWipeEntries[i].num_pages == 1) isolated_wipe = 1'b1;
      if (RmaWipeEntries[i].bank == 0 &&
          RmaWipeEntries[i].part == FlashPartData &&
          RmaWipeEntries[i].start_page == 0 &&
          RmaWipeEntries[i].num_pages == ((PageW + 1)'(PagesPerBank))) data0_wipe = 1'b1;
      if (RmaWipeEntries[i].bank == 1 &&
          RmaWipeEntries[i].part == FlashPartData &&
          RmaWipeEntries[i].start_page == 0 &&
          RmaWipeEntries[i].num_pages == ((PageW + 1)'(PagesPerBank))) data1_wipe = 1'b1;
    end

    $display("HwInfoRules=%0d WipeEntries=%0d creator_rma_attr=%0d owner_rma_attr=%0d isolated_rma_attr=%0d creator_wipe=%0d owner_wipe=%0d isolated_wipe=%0d data0_wipe=%0d data1_wipe=%0d",
             HwInfoRules, WipeEntries, creator_rma_attr, owner_rma_attr, isolated_rma_attr,
             creator_wipe, owner_wipe, isolated_wipe, data0_wipe, data1_wipe);

    if (HwInfoRules != 5 || WipeEntries != 5 || !creator_rma_attr || !owner_rma_attr ||
        !isolated_rma_attr || !creator_wipe || !owner_wipe || !isolated_wipe ||
        !data0_wipe || !data1_wipe) begin
      $error("RMA partition coverage is incomplete");
      $fatal(1);
    end

    $display("RMA partition coverage is complete");
    $finish;
  end
endmodule
EOF

