  -o "$TB_DIR/simv" \
  -f "$TB_DIR/files.f" \
  -l "$COMPILE_LOG"
compile_rc=$?
set -e

if [ "$compile_rc" -ne 0 ]; then
  emit_result "FAIL"
  exit "$compile_rc"
fi

set +e
"$TB_DIR/simv" | tee "$RUN_LOG"
sim_rc=${PIPESTATUS[0]}
set -e

if [ "$sim_rc" -eq 0 ] && \
   grep -q "RMA partition coverage is complete" "$RUN_LOG" && \
   ! grep -Eq '^(Error|Fatal):' "$RUN_LOG"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

