#!/bin/bash
cd /home/opentitan || exit 1

TEST_NAME="lc_ctrl_scrap_transition"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
STATUS_FILE="${TB_DIR}/status.txt"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import lc_ctrl_pkg::*;
  import lc_ctrl_state_pkg::*;

  bit            test_failed;
  integer        status_fd;
  lc_state_e     lc_state_i;
  lc_cnt_e       lc_cnt_i;
  fsm_state_e    fsm_state_i;
  dec_lc_state_e dec_lc_state_i;
  dec_lc_state_e trans_target_i;
  lc_state_e     next_lc_state_o;
  lc_cnt_e       next_lc_cnt_o;
  logic          trans_cnt_oflw_error_o;
  logic          trans_invalid_error_o;

  lc_ctrl_state_transition dut (
    .lc_state_i(lc_state_i),
    .lc_cnt_i(lc_cnt_i),
    .fsm_state_i(fsm_state_i),
    .dec_lc_state_i(dec_lc_state_i),
    .trans_target_i(trans_target_i),
    .next_lc_state_o(next_lc_state_o),
    .next_lc_cnt_o(next_lc_cnt_o),
    .trans_cnt_oflw_error_o(trans_cnt_oflw_error_o),
    .trans_invalid_error_o(trans_invalid_error_o)
  );

  initial begin
    test_failed = 1'b0;

    // Reproduce the second programming pass of an RMA-to-SCRAP transition.
    lc_state_i = LcStRma;
    lc_cnt_i = LcCnt8;
    fsm_state_i = TransProgSt;
    dec_lc_state_i = DecLcStRma;
    trans_target_i = DecLcStScrap;
    #1;

    if (next_lc_state_o !== LcStScrap) begin
      $display("ERROR: Expected next_lc_state_o to be SCRAP, got %h", next_lc_state_o);
      test_failed = 1'b1;
    end
    if (next_lc_cnt_o !== LcCnt16) begin
      $display("ERROR: Expected next_lc_cnt_o to stay at LcCnt16 during TransProgSt, got %h",
               next_lc_cnt_o);
      test_failed = 1'b1;
    end
    if (trans_cnt_oflw_error_o !== 1'b0) begin
      $display("ERROR: Unexpected counter overflow error");
      test_failed = 1'b1;
    end
    if (trans_invalid_error_o !== 1'b0) begin
      $display("ERROR: Unexpected invalid transition error");
      test_failed = 1'b1;
    end

    status_fd = $fopen("/home/opentitan/.tb_lc_ctrl_scrap_transition/status.txt", "w");
    if (status_fd != 0) begin
      if (test_failed) begin
        $fdisplay(status_fd, "FAIL");
      end else begin
        $fdisplay(status_fd, "PASS");
      end
      $fclose(status_fd);
    end else begin
      $display("ERROR: Failed to open status file");
      test_failed = 1'b1;
    end

    if (!test_failed) begin
      $display("LC_CTRL_SCRAP_TRANSITION_OK");
    end
    $finish;
  end
endmodule
EOF

