cd "${TB_DIR}" || exit 1
rm -rf simv simv.daidir csrc ucli.key

vcs -full64 -sverilog \
  /home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv \
  /home/opentitan/hw/ip/lc_ctrl/rtl/lc_ctrl_state_pkg.sv \
  /home/opentitan/hw/ip/lc_ctrl/rtl/lc_ctrl_pkg.sv \
  /home/opentitan/hw/ip/lc_ctrl/rtl/lc_ctrl_state_transition.sv \
  "${TB_DIR}/tb.sv" \
  -l "${COMPILE_LOG}"
rc=$?

if [ "${rc}" -eq 0 ]; then
  ./simv -l "${RUN_LOG}"
