  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

fail() {
  local message="$1"
  local log_path="${2:-}"
  local rc="${3:-1}"

  echo "[ERROR] ${message}"
  if [[ -n "${log_path}" && -f "${log_path}" ]]; then
    tail -n 200 "${log_path}" || true
  fi
  emit_result "FAIL"
  exit "${rc}"
}

