if [ "$compile_rc" -eq 0 ]; then
  "$SIMV" | tee "$RUN_LOG"
  sim_rc=${PIPESTATUS[0]}
  # VCS can still exit 0 after $fatal, so require the terminal pass marker as well.
  if [ "$sim_rc" -eq 0 ] && grep -q "RUNTIME_PASS all_cases" "$RUN_LOG"; then
    rc=0
