    cfg.route_software_pct = 100;
    cfg.type_bypass_pct = 0;
    cfg.efuse_es_sw_reg_en_pct = 100;
    `DV_CHECK_RANDOMIZE_FATAL(cfg)
    `uvm_info(`gfn, $sformatf("%s", cfg.convert2string()), UVM_LOW)
  endfunction
endclass
EOF

  grep -q 'entropy_src_startup_phase_vseq.sv' \
    hw/ip/entropy_src/dv/env/seq_lib/entropy_src_vseq_list.sv || \
    printf '%s\n' '`include "entropy_src_startup_phase_vseq.sv"' >> \
