tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -uo pipefail

TB_ROOT=/home/opentitan/.tb_kmac_idle_manualrun_error
TEST_NAME=kmac_unmasked_idle_manualrun_error
SEQ_FILE=hw/ip/kmac/dv/env/seq_lib/kmac_idle_manualrun_error_vseq.sv
CORE_FILE=hw/ip/kmac/dv/env/kmac_env.core
VSEQ_LIST=hw/ip/kmac/dv/env/seq_lib/kmac_vseq_list.sv
SIM_CFG=hw/ip/kmac/dv/kmac_base_sim_cfg.hjson

rm -rf "$TB_ROOT"
mkdir -p "$TB_ROOT"

cat > "$SEQ_FILE" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class kmac_idle_manualrun_error_vseq extends kmac_base_vseq;

  `uvm_object_utils(kmac_idle_manualrun_error_vseq)
  `uvm_object_new

  constraint num_trans_c {
    num_trans == 1;
  }

  constraint kmac_cfg_c {
    kmac_en == 0;
    xof_en == 0;
    hash_mode == sha3_pkg::Sha3;
    strength == sha3_pkg::L256;
    key_len == Key256;
    en_sideload == 0;
    provide_sideload_key == 0;
    entropy_mode == EntropyModeSw;
    entropy_ready == 1;
    err_processed == 0;
    fname_len == 0;
    custom_str_len == 0;
    output_len == 32;
    msg.size() == 0;
  }

  virtual task pre_start();
    do_clear_all_interrupts = 0;
    super.pre_start();
  endtask

  task body();
    bit [TL_DW-1:0] err_code;

    `uvm_info(`gfn, "Issuing CmdManualRun from Idle and checking ERR_CODE", UVM_LOW)

    issue_cmd(CmdManualRun);

    repeat (20) begin
      csr_peek(.ptr(ral.err_code), .value(err_code), .check(UVM_NO_CHECK));
      if (err_code[31:24] != 8'h00) break;
      cfg.clk_rst_vif.wait_clks(1);
    end

    `DV_CHECK_FATAL(err_code[31:24] != 8'h00,
                    $sformatf("ERR_CODE did not latch after CmdManualRun: 0x%08x", err_code))
    `DV_CHECK_EQ_FATAL(err_code[31:24], 8'h08,
                       $sformatf("Unexpected ERR_CODE after CmdManualRun from Idle: 0x%08x",
                                 err_code))
    `DV_CHECK_EQ_FATAL(err_code[3:0], 4'h4,
                       $sformatf("Expected ERR_CODE info to capture CmdManualRun: 0x%08x",
                                 err_code))
  endtask

endclass
EOF

if ! grep -q 'kmac_idle_manualrun_error_vseq' "$CORE_FILE"; then
  sed -i '/seq_lib\/kmac_app_vseq\.sv/a\      - seq_lib\/kmac_idle_manualrun_error_vseq.sv: {is_include_file: true}' "$CORE_FILE"
fi

if ! grep -q 'kmac_idle_manualrun_error_vseq' "$VSEQ_LIST"; then
  sed -i '/`include "kmac_app_vseq.sv"/a\`include "kmac_idle_manualrun_error_vseq.sv"' "$VSEQ_LIST"
fi

python - <<'EOF'
from pathlib import Path

path = Path("hw/ip/kmac/dv/kmac_base_sim_cfg.hjson")
text = path.read_text(encoding="utf-8")
needle = """    {
      name: "{variant}_app"
      uvm_test_seq: kmac_app_vseq
    }
"""
insert = needle + """    {
      name: "{variant}_idle_manualrun_error"
      uvm_test_seq: kmac_idle_manualrun_error_vseq
    }
"""
if "{variant}_idle_manualrun_error" not in text:
    text = text.replace(needle, insert)
path.write_text(text, encoding="utf-8")
EOF

set +e
timeout 1800s python util/dvsim/dvsim.py \
  hw/ip/kmac/dv/kmac_unmasked_sim_cfg.hjson \
  -i "$TEST_NAME" \
  -t vcs \
  --fixed-seed 1 \
  -sr "$TB_ROOT/scratch" \
  2>&1 | tee "$TB_ROOT/dvsim.log"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

