fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" \
  run --target=sim --tool=vcs \
  --build-root "${BUILD_ROOT}" \
  lowrisc:dv:hmac_idle_test:0.1 > "${RUN_LOG}" 2>&1
run_rc=$?

if [[ ${run_rc} -eq 0 ]] && grep -q "IDLE_BEHAVIOR_OK" "${RUN_LOG}"; then
  tail -n 40 "${RUN_LOG}"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "fusesoc exit code: ${run_rc}"
tail -n 80 "${RUN_LOG}"
echo "HWE_BENCH_RESULTS_START"
echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

