tb_script:
#!/bin/bash
cd /home/opentitan
set +e
set -u

TEST_NAME="rom_ctrl_mux_req_reset"
TB_DIR="/home/opentitan/.tb_rom_ctrl_mux_reset_req"
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"
PASS_MARKER="$TB_DIR/pass.marker"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  integer      pass_fd;
  logic        clk_i;
  logic        rst_ni;
  logic        sel_i;
  logic [7:0]  bus_addr_i;
  logic        bus_req_i;
  logic        bus_gnt_o;
  logic [39:0] bus_rdata_o;
  logic        bus_rvalid_o;
  logic [7:0]  chk_addr_i;
  logic        chk_req_i;
  logic [39:0] chk_rdata_o;
  logic [7:0]  rom_addr_o;
  logic        rom_req_o;
  logic [39:0] rom_scr_rdata_i;
  logic [39:0] rom_clr_rdata_i;
  logic        rom_rvalid_i;
  logic        alert_o;

  rom_ctrl_mux #(
    .AW(8)
  ) dut (.*);

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic expect_bit(input string label, input logic actual, input logic expected);
    begin
      if (actual !== expected) begin
        $display("CHECK_FAIL label=%0s expected=%0b actual=%b time=%0t",
                 label, expected, actual, $time);
        $fatal(1, "Runtime check failed");
      end
    end
  endtask

  initial begin
    rst_ni = 1'b0;
    sel_i = 1'b1;
    bus_addr_i = '0;
    bus_req_i = 1'b0;
    chk_addr_i = 8'h3c;
    chk_req_i = 1'b0;
    rom_scr_rdata_i = '0;
    rom_clr_rdata_i = '0;
    rom_rvalid_i = 1'b0;

    #1;
    expect_bit("rom_req_during_reset", rom_req_o, 1'b0);

    @(posedge clk_i);
    rst_ni = 1'b1;
    #1;
    expect_bit("rom_req_after_reset_before_chk_req", rom_req_o, 1'b0);

    chk_req_i = 1'b1;
    #1;
    expect_bit("rom_req_after_chk_req", rom_req_o, 1'b1);

    sel_i = 1'b0;
    bus_req_i = 1'b1;
    #1;
    expect_bit("rom_req_bus_path", rom_req_o, 1'b1);

    pass_fd = $fopen("pass.marker", "w");
    if (pass_fd == 0) begin
      $fatal(1, "Unable to create pass marker");
    end
    $fdisplay(pass_fd, "TB_RUNTIME_PASS");
    $fclose(pass_fd);
    $display("TB_RUNTIME_PASS");
    $finish;
  end
endmodule
EOF

(
  cd "$TB_DIR" || exit 1
  vcs -full64 -sverilog \
    tb.sv \
    /home/opentitan/hw/ip/rom_ctrl/rtl/rom_ctrl_mux.sv \
    -o simv \
    -l "$COMPILE_LOG"
)
compile_rc=$?

if [ "$compile_rc" -ne 0 ]; then
  emit_result "FAIL"
  exit "$compile_rc"
fi

(
  cd "$TB_DIR" || exit 1
  set -o pipefail
  ./simv | tee "$RUN_LOG"
)
run_rc=$?

if [ "$run_rc" -eq 0 ] && [ -f "$PASS_MARKER" ]; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

