#!/bin/bash
cd /home/opentitan
set -u
set -o pipefail
set +e

export PATH="/tools/riscv/bin:/tools/verible/bin:$PATH"

TEST_NAME="aes_control_fatal_alert_clear"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
LOG_FILE="${TB_DIR}/fusesoc_run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/aes_control_fatal_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:aes_control_fatal_tb:0.1"
description: "Minimal aes_control fatal alert reproducer"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:aes:0.6
    files:
      - aes_control_fatal_tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    toplevel: aes_control_fatal_tb
    filesets:
      - files_dv
EOF

cat > "${TB_DIR}/aes_control_fatal_tb.sv" <<'EOF'
module aes_control_fatal_tb;
  import aes_pkg::*;
  import aes_reg_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic ctrl_qe_i;
