  logic [NumRegsIv-1:0] iv_qe_i;
  logic [NumRegsData-1:0] data_in_qe_i;
  logic [NumRegsData-1:0] data_out_re_i;
  sp2v_e [NumSlicesCtr-1:0] ctr_we_i;
  sp2v_e ctr_ready_i;
  sp2v_e cipher_in_ready_i;
  sp2v_e cipher_out_valid_i;
  sp2v_e cipher_crypt_i;
  sp2v_e cipher_dec_key_gen_i;
  logic cipher_key_clear_i;
  logic cipher_data_out_clear_i;
  logic prng_data_ack_i;
  logic prng_reseed_ack_i;
  logic output_lost_i;

  logic ctrl_we_o;
  logic data_in_we_o;
  sp2v_e data_out_we_o;
  dip_sel_e data_in_prev_sel_o;
  sp2v_e data_in_prev_we_o;
  si_sel_e state_in_sel_o;
  add_si_sel_e add_state_in_sel_o;
  add_so_sel_e add_state_out_sel_o;
  sp2v_e ctr_incr_o;
  sp2v_e cipher_in_valid_o;
  sp2v_e cipher_out_ready_o;
  sp2v_e cipher_crypt_o;
  sp2v_e cipher_dec_key_gen_o;
  logic cipher_key_clear_o;
  logic cipher_data_out_clear_o;
  key_init_sel_e key_init_sel_o;
  sp2v_e [NumRegsKey-1:0] key_init_we_o [NumSharesKey];
  iv_sel_e iv_sel_o;
  sp2v_e [NumSlicesCtr-1:0] iv_we_o;
  logic prng_data_req_o;
  logic prng_reseed_req_o;
  logic start_o;
  logic start_we_o;
  logic key_iv_data_in_clear_o;
  logic key_iv_data_in_clear_we_o;
  logic data_out_clear_o;
  logic data_out_clear_we_o;
  logic prng_reseed_o;
  logic prng_reseed_we_o;
  logic output_valid_o;
  logic output_valid_we_o;
  logic input_ready_o;
  logic input_ready_we_o;
  logic idle_o;
  logic idle_we_o;
  logic stall_o;
  logic stall_we_o;
  logic output_lost_o;
  logic output_lost_we_o;
  logic alert_o;

