    .ctr_ready_i,
    .ctr_we_i,
    .cipher_in_valid_o,
    .cipher_in_ready_i,
    .cipher_out_valid_i,
    .cipher_out_ready_o,
    .cipher_crypt_o,
    .cipher_crypt_i,
    .cipher_dec_key_gen_o,
    .cipher_dec_key_gen_i,
    .cipher_key_clear_o,
    .cipher_key_clear_i,
    .cipher_data_out_clear_o,
    .cipher_data_out_clear_i,
    .key_init_sel_o,
    .key_init_we_o,
    .iv_sel_o,
