#!/bin/bash

cd /home/opentitan || exit 1
set -uo pipefail

TEST_NAME="rom_ctrl_kmac_backpressure"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_assert.sv" <<'EOF'
`ifndef PRIM_ASSERT_SV
`define PRIM_ASSERT_SV
`define ASSERT_DEFAULT_CLK clk_i
`define ASSERT_DEFAULT_RST !rst_ni
`define ASSERT_I(__name, __prop)
`define ASSERT_INIT(__name, __prop)
`define ASSERT_FINAL(__name, __prop)
`define ASSERT(__name, __prop, __clk = `ASSERT_DEFAULT_CLK, __rst = `ASSERT_DEFAULT_RST)
`define ASSERT_NEVER(__name, __prop, __clk = `ASSERT_DEFAULT_CLK, __rst = `ASSERT_DEFAULT_RST)
`define ASSERT_KNOWN(__name, __sig, __clk = `ASSERT_DEFAULT_CLK, __rst = `ASSERT_DEFAULT_RST)
`define COVER(__name, __prop, __clk = `ASSERT_DEFAULT_CLK, __rst = `ASSERT_DEFAULT_RST)
`define ASSUME(__name, __prop, __clk = `ASSERT_DEFAULT_CLK, __rst = `ASSERT_DEFAULT_RST)
`define ASSUME_I(__name, __prop)
`endif
EOF

cat > "${TB_DIR}/prim_flop.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input logic clk_i,
  input logic rst_ni,
  input logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) q_o <= ResetValue;
    else q_o <= d_i;
  end
endmodule
EOF

cat > "${TB_DIR}/rom_ctrl_compare.sv" <<'EOF'
module rom_ctrl_compare #(
  parameter int NumWords = 2,
  parameter bit SkipCheck = 1'b1
) (
  input logic                   clk_i,
  input logic                   rst_ni,
  input logic                   start_i,
  output logic                  done_o,
  output logic                  good_o,
  input logic [NumWords*32-1:0] digest_i,
  input logic [NumWords*32-1:0] exp_digest_i,
  output logic                  alert_o
);
  assign done_o = start_i;
  assign good_o = 1'b1;
  assign alert_o = 1'b0;
endmodule
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  localparam int RomDepth = 4;
  localparam int TopCount = 1;

  logic clk_i;
  logic rst_ni;
  logic [TopCount*32-1:0] digest_i;
  logic [TopCount*32-1:0] exp_digest_i;
  logic [TopCount*32-1:0] digest_o;
  logic digest_vld_o;
  logic [31:0] exp_digest_o;
  logic exp_digest_vld_o;
  logic [prim_util_pkg::vbits(TopCount)-1:0] exp_digest_idx_o;
  rom_ctrl_pkg::pwrmgr_data_t pwrmgr_data_o;
  rom_ctrl_pkg::keymgr_data_t keymgr_data_o;
  logic kmac_rom_rdy_i;
  logic kmac_rom_vld_o;
  logic kmac_rom_last_o;
  logic kmac_done_i;
  logic [TopCount*32-1:0] kmac_digest_i;
  logic rom_select_o;
  logic [prim_util_pkg::vbits(RomDepth)-1:0] rom_addr_o;
  logic [31:0] rom_data_i;
  logic alert_o;

  rom_ctrl_fsm #(
    .RomDepth(RomDepth),
    .TopCount(TopCount),
    .SkipCheck(1'b1)
  ) dut (
    .clk_i,
    .rst_ni,
    .digest_i,
    .exp_digest_i,
    .digest_o,
    .digest_vld_o,
    .exp_digest_o,
    .exp_digest_vld_o,
    .exp_digest_idx_o,
    .pwrmgr_data_o,
    .keymgr_data_o,
    .kmac_rom_rdy_i,
    .kmac_rom_vld_o,
    .kmac_rom_last_o,
    .kmac_done_i,
    .kmac_digest_i,
    .rom_select_o,
    .rom_addr_o,
    .rom_data_i,
    .alert_o
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  initial begin
    digest_i = '0;
    exp_digest_i = '0;
    kmac_done_i = 1'b0;
    kmac_digest_i = '0;
    rom_data_i = 32'h12345678;
    kmac_rom_rdy_i = 1'b0;
    rst_ni = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(posedge clk_i);
    #1;
    if (kmac_rom_vld_o !== 1'b1) begin
      $error("Expected kmac_rom_vld_o to be high after reset release, got %b", kmac_rom_vld_o);
      $fatal(1);
    end
    if (rom_addr_o !== '0) begin
      $error("Expected rom_addr_o to start at 0, got %0d", rom_addr_o);
      $fatal(1);
    end

    // The fix makes the read address advance combinationally when ready rises.
    kmac_rom_rdy_i = 1'b1;
    #1;
    if (rom_addr_o !== 1) begin
      $error("Expected immediate address advance to 1 when ready rises, got %0d", rom_addr_o);
      $fatal(1);
    end

    @(posedge clk_i);
    #1;
    if (rom_addr_o !== 2) begin
      $error("Expected rom_addr_o to advance to 2 on the next cycle, got %0d", rom_addr_o);
      $fatal(1);
    end

    $display("ROM_CTRL_KMAC_BACKPRESSURE_OK");
    $finish;
  end
endmodule
EOF

