    .otp_addr_o,
    .otp_gnt_i,
    .otp_rvalid_i,
    .otp_rdata_i,
    .otp_err_i
  );

  initial begin
    clk_i = 1'b0;
    forever #5 clk_i = ~clk_i;
  end

  task automatic wait_for_init_done;
    int i;
    begin
      for (i = 0; i < 10; i++) begin
        @(negedge clk_i);
        #1;
        if (init_done_o === 1'b1) begin
          return;
        end
      end
      $fatal(1, "Partition failed to reach IdleSt after init");
    end
  endtask

  initial begin
    bit saw_gnt;
    int i;

    rst_ni = 1'b0;
    init_req_i = 1'b0;
    escalate_en_i = lc_ctrl_pkg::Off;
    access_i = '{read_lock: otp_ctrl_pkg::Unlocked, write_lock: otp_ctrl_pkg::Unlocked};
    tlul_req_i = 1'b0;
    tlul_addr_i = '0;
    otp_gnt_i = 1'b0;
    otp_rvalid_i = 1'b0;
    otp_rdata_i = '0;
    otp_err_i = prim_otp_pkg::NoError;
    saw_gnt = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    init_req_i = 1'b1;

    @(negedge clk_i);
    init_req_i = 1'b0;
    otp_gnt_i = 1'b1;

    @(negedge clk_i);
    otp_gnt_i = 1'b0;
    otp_rvalid_i = 1'b1;
    otp_rdata_i = 64'h0;
    otp_err_i = prim_otp_pkg::NoError;

    @(negedge clk_i);
    otp_rvalid_i = 1'b0;

    wait_for_init_done();

    escalate_en_i = lc_ctrl_pkg::On;
    @(negedge clk_i);
    escalate_en_i = lc_ctrl_pkg::Off;

    @(negedge clk_i);
    #1;
    if (error_o !== otp_ctrl_pkg::FsmStateError) begin
      $fatal(1, "Expected ErrorSt after escalate, got error_o=%0d", error_o);
    end

    tlul_req_i = 1'b1;
    #1;
    saw_gnt = tlul_gnt_o;

    @(posedge clk_i);
    tlul_req_i = 1'b0;

    for (i = 0; i < 6; i++) begin
      @(negedge clk_i);
      #1;
      saw_gnt |= tlul_gnt_o;
      if (tlul_rvalid_o === 1'b1) begin
        if (tlul_rerror_o !== 2'b11) begin
          $fatal(1, "Expected bus error response, got tlul_rerror_o=%b", tlul_rerror_o);
        end
        if (tlul_rdata_o !== 32'h0000_0000) begin
          $fatal(1, "Expected zero data on bus error, got tlul_rdata_o=0x%08x", tlul_rdata_o);
        end
        $display("TB_PASS: saw_gnt=%0b tlul_rerror_o=%b", saw_gnt, tlul_rerror_o);
        $finish;
      end
    end

    $fatal(1, "Timed out waiting for tlul_rvalid_o in ErrorSt; saw_gnt=%0b", saw_gnt);
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
${TB_DIR}/stubs.sv
/home/opentitan/hw/ip/otp_ctrl/rtl/otp_ctrl_part_unbuf.sv
${TB_DIR}/tb.sv
EOF

vcs -full64 -sverilog -timescale=1ns/1ps +define+VERILATOR \
  -Mdir="${TB_DIR}/csrc" \
  -o "${TB_DIR}/simv" \
  -f "${TB_DIR}/files.f" \
  -l "${BUILD_LOG}"
compile_rc=$?

if [ "${compile_rc}" -ne 0 ]; then
  emit_result "FAIL"
  exit "${compile_rc}"
fi

"${TB_DIR}/simv" -l "${RUN_LOG}"
run_rc=$?

if [ "${run_rc}" -eq 0 ] && grep -q "TB_PASS:" "${RUN_LOG}"; then
  emit_result "PASS"
else
  emit_result "FAIL"
  if [ "${run_rc}" -eq 0 ]; then
    run_rc=1
  fi
fi

exit "${run_rc}"

