    .rst_ni(rst_ni),
    .tl_i(tl_i),
    .tl_o(tl_o),
    .en_ifetch_i(InstrDis),
    .req_o(req_o),
    .gnt_i(gnt_i),
    .we_o(we_o),
    .addr_o(addr_o),
    .wdata_o(wdata_o),
    .wmask_o(wmask_o),
    .intg_error_o(intg_error_o),
    .rdata_i(rdata_i),
    .rvalid_i(rvalid_i),
    .rerror_i(rerror_i)
  );
endmodule
