#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="rstmgr_por_scan_release"
TB_DIR="/home/opentitan/.tb_rstmgr_por_scan"
COMPILE_LOG="$TB_DIR/compile.log"
RUN_LOG="$TB_DIR/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: $TEST_NAME ... $status"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/prim_assert.sv" <<'EOF'
`ifndef PRIM_ASSERT_SV
`define PRIM_ASSERT_SV
`define ASSERT_INIT(__name, __prop)
`define ASSERT_KNOWN(__name, __sig)
`define ASSERT(__name, __prop)
`endif
EOF

cat > "$TB_DIR/prim_clock_mux2.sv" <<'EOF'
module prim_clock_mux2 #(
  parameter bit NoFpgaBufG = 1'b0
) (
  input  logic clk0_i,
  input  logic clk1_i,
  input  logic sel_i,
  output logic clk_o
);
  assign clk_o = sel_i ? clk1_i : clk0_i;
endmodule
EOF

cat > "$TB_DIR/prim_flop.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input logic clk_i,
  input logic rst_ni,
  input logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) q_o <= ResetValue;
    else q_o <= d_i;
  end
endmodule
EOF

cat > "$TB_DIR/prim_flop_2sync.sv" <<'EOF'
module prim_flop_2sync #(
  parameter int Width = 16,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input logic clk_i,
  input logic rst_ni,
  input logic [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  logic [Width-1:0] stage1_q;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      stage1_q <= ResetValue;
      q_o <= ResetValue;
    end else begin
      stage1_q <= d_i;
      q_o <= stage1_q;
    end
  end
endmodule
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic scan_rst_ni = 1'b0;
  logic scanmode_i = 1'b0;
  logic rst_no;

  always #5 clk_i = ~clk_i;

  rstmgr_por #(
    .FilterStages(2),
    .StretchCount(4)
  ) dut (
    .clk_i,
    .rst_ni,
    .scan_rst_ni,
    .scanmode_i,
    .rst_no
  );

  task automatic fail(input string msg);
    begin
      $display("TB_FAIL: %s", msg);
      $fatal(1, "%s", msg);
    end
  endtask

  initial begin
    repeat (2) @(posedge clk_i);
    if (rst_no !== 1'b0) fail("rst_no should start low");

    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    scanmode_i = 1'b1;
    #1;
    scan_rst_ni = 1'b1;
    #1;

    if (rst_no !== 1'b1) fail("scan reset release did not immediately reach rst_no");

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

vcs -full64 -sverilog -timescale=1ns/1ps \
  +incdir+"$TB_DIR" \
  "$TB_DIR/prim_clock_mux2.sv" \
  "$TB_DIR/prim_flop.sv" \
  "$TB_DIR/prim_flop_2sync.sv" \
  hw/ip/rstmgr/rtl/rstmgr_por.sv \
  "$TB_DIR/tb.sv" \
  -o "$TB_DIR/simv" \
  -l "$COMPILE_LOG"
build_rc=$?

if [ $build_rc -ne 0 ]; then
  emit_result "FAIL"
  exit $build_rc
fi

"$TB_DIR/simv" -l "$RUN_LOG"
sim_rc=$?

if grep -q "TB_FAIL:" "$RUN_LOG"; then
  emit_result "FAIL"
  exit 1
fi

# VCS reports $fatal(1) as $finish, so the simulator exit code alone is not reliable here.
if grep -q "TB_PASS" "$RUN_LOG"; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
if [ $sim_rc -ne 0 ]; then
  exit $sim_rc
fi
exit 1

