#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="otp_ctrl_lfsr_timeout_sticky"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/prim_assert.sv" <<'EOF'
`ifndef PRIM_ASSERT_SV
`define PRIM_ASSERT_SV
`define ASSERT_INIT(NAME, EXPR)
`define ASSERT_KNOWN(NAME, SIG)
`endif
EOF

cat > "${TB_DIR}/tb_support_pkg.sv" <<'EOF'
package otp_ctrl_reg_pkg;
  parameter int NumPart = 1;
endpackage

package lc_ctrl_pkg;
  typedef enum logic [3:0] {
    Off = 4'h0,
    On  = 4'h1
  } lc_tx_t;
endpackage

package otp_ctrl_pkg;
  parameter int EdnDataWidth = 64;
  parameter int LfsrWidth = 40;
  typedef logic [LfsrWidth-1:0] lfsr_seed_t;
  typedef logic [LfsrWidth-1:0][$clog2(LfsrWidth)-1:0] lfsr_perm_t;
  localparam lfsr_seed_t RndCnstLfsrSeedDefault = '0;
  localparam lfsr_perm_t RndCnstLfsrPermDefault = '0;
endpackage
EOF

cat > "${TB_DIR}/prim_stubs.sv" <<'EOF'
module prim_lfsr #(
  parameter int LfsrDw = 40,
  parameter int EntropyDw = 40,
  parameter int StateOutDw = 40,
  parameter logic [LfsrDw-1:0] DefaultSeed = '0,
  parameter bit StatePermEn = 1'b0,
  parameter logic [LfsrDw-1:0][$clog2(LfsrDw)-1:0] StatePerm = '0,
  parameter bit ExtSeedSVA = 1'b0
) (
  input clk_i,
  input rst_ni,
  input seed_en_i,
  input [EntropyDw-1:0] seed_i,
  input lfsr_en_i,
  input [EntropyDw-1:0] entropy_i,
  output logic [StateOutDw-1:0] state_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      state_o <= DefaultSeed[StateOutDw-1:0];
    end else if (seed_en_i) begin
      state_o <= seed_i[StateOutDw-1:0];
    end else if (lfsr_en_i) begin
      state_o <= state_o + entropy_i[StateOutDw-1:0] + StateOutDw'(1);
    end
  end
endmodule

module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input clk_i,
  input rst_ni,
  input [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      q_o <= ResetValue;
    end else begin
      q_o <= d_i;
    end
  end
endmodule
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import otp_ctrl_reg_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic edn_req_o;
  logic edn_ack_i = 1'b0;
  logic [63:0] edn_data_i = '0;
  logic timer_en_i = 1'b0;
  logic otp_prog_busy_i = 1'b0;
  logic integ_chk_trig_i = 1'b0;
  logic cnsty_chk_trig_i = 1'b0;
  logic chk_pending_o;
  logic [31:0] timeout_i = 32'd2;
  logic [31:0] integ_period_msk_i = '0;
  logic [31:0] cnsty_period_msk_i = '0;
  logic [NumPart-1:0] integ_chk_req_o;
  logic [NumPart-1:0] cnsty_chk_req_o;
  logic [NumPart-1:0] integ_chk_ack_i = '0;
  logic [NumPart-1:0] cnsty_chk_ack_i = '0;
  lc_tx_t escalate_en_i = Off;
  logic chk_timeout_o;
  logic fsm_err_o;

  otp_ctrl_lfsr_timer dut (
    .clk_i,
    .rst_ni,
    .edn_req_o,
    .edn_ack_i,
    .edn_data_i,
    .timer_en_i,
    .otp_prog_busy_i,
    .integ_chk_trig_i,
    .cnsty_chk_trig_i,
    .chk_pending_o,
    .timeout_i,
    .integ_period_msk_i,
    .cnsty_period_msk_i,
    .integ_chk_req_o,
    .cnsty_chk_req_o,
    .integ_chk_ack_i,
    .cnsty_chk_ack_i,
    .escalate_en_i,
    .chk_timeout_o,
    .fsm_err_o
  );

  always #5 clk_i = ~clk_i;

  task automatic step;
    @(posedge clk_i);
    #1;
  endtask

  initial begin
    repeat (2) step();
    rst_ni = 1'b1;
    timer_en_i = 1'b1;

    step();
    integ_chk_trig_i = 1'b1;
    step();
    integ_chk_trig_i = 1'b0;

    repeat (20) begin
      step();
      if (chk_timeout_o === 1'b1) begin
        step();
        if (chk_timeout_o !== 1'b1) begin
          $fatal(1, "TB_FAIL: chk_timeout_o dropped after entering ErrorSt");
        end
        $display("TB_PASS: Timeout flag remained asserted after transition to ErrorSt");
        $finish;
      end
    end

    $fatal(1, "TB_FAIL: Timed out waiting for chk_timeout_o to assert");
  end
endmodule
EOF

set +e
vcs -full64 -sverilog +incdir+"${TB_DIR}" \
  "${TB_DIR}/tb_support_pkg.sv" \
  "${TB_DIR}/prim_stubs.sv" \
  "hw/ip/otp_ctrl/rtl/otp_ctrl_lfsr_timer.sv" \
  "${TB_DIR}/tb.sv" \
  -o "${TB_DIR}/simv" \
  -l "${COMPILE_LOG}"
compile_rc=$?
if [ "${compile_rc}" -ne 0 ]; then
  emit_result FAIL
  exit "${compile_rc}"
fi

"${TB_DIR}/simv" |& tee "${RUN_LOG}"
run_rc=${PIPESTATUS[0]}
set -e

if [ "${run_rc}" -eq 0 ] && grep -q "TB_PASS:" "${RUN_LOG}"; then
  emit_result PASS
  exit 0
fi

emit_result FAIL
exit 1

