tb_script:
#!/bin/bash
cd /home/opentitan || exit 1
set -uo pipefail

TEST_NAME="lc_ctrl_scrap_escalate"
SCRATCH_ROOT="/home/opentitan/.tb_lc_ctrl_scrap_escalate"
SIM_DIR=""
BUILD_LOG=""
RUN_LOG=""

report_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

cat > hw/ip/lc_ctrl/dv/tb.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

module tb;
  import jtag_pkg::*;
  import lc_ctrl_pkg::*;
  import lc_ctrl_reg_pkg::*;
  import lc_ctrl_state_pkg::*;
  import otp_ctrl_part_pkg::*;
  import otp_ctrl_pkg::*;
  import prim_alert_pkg::*;
  import prim_esc_pkg::*;
  import pwrmgr_pkg::*;
  import tlul_pkg::*;

  logic clk;
  logic rst_n;

  tl_h2d_t tl_i = '0;
  tl_d2h_t tl_o;
  jtag_req_t jtag_i = '0;
  jtag_rsp_t jtag_o;
  alert_rx_t [lc_ctrl_reg_pkg::NumAlerts-1:0] alert_rx_i = '{default: ALERT_RX_DEFAULT};
  alert_tx_t [lc_ctrl_reg_pkg::NumAlerts-1:0] alert_tx_o;
  esc_rx_t esc_wipe_secrets_tx_i = ESC_RX_DEFAULT;
  esc_tx_t esc_wipe_secrets_rx_o;
  esc_rx_t esc_scrap_state_tx_i = ESC_RX_DEFAULT;
  esc_tx_t esc_scrap_state_rx_o;
  pwr_lc_req_t pwr_lc_i = '0;
  pwr_lc_rsp_t pwr_lc_o;
  lc_otp_program_req_t lc_otp_program_o;
  lc_otp_program_rsp_t lc_otp_program_i = '0;
  lc_otp_token_req_t lc_otp_token_o;
  lc_otp_token_rsp_t lc_otp_token_i = '0;
  otp_lc_data_t otp_lc_data_i;
  otp_hw_cfg_t otp_hw_cfg_i = '0;
  lc_tx_t lc_dft_en_o;
  lc_tx_t lc_nvm_debug_en_o;
  lc_tx_t lc_hw_debug_en_o;
  lc_tx_t lc_cpu_en_o;
  lc_tx_t lc_creator_seed_sw_rw_en_o;
  lc_tx_t lc_owner_seed_sw_rw_en_o;
  lc_tx_t lc_iso_part_sw_rd_en_o;
  lc_tx_t lc_iso_part_sw_wr_en_o;
  lc_tx_t lc_seed_hw_rd_en_o;
  lc_tx_t lc_keymgr_en_o;
  lc_tx_t lc_escalate_en_o;
  lc_tx_t lc_check_byp_en_o;
  lc_tx_t lc_clk_byp_req_o;
  lc_tx_t lc_flash_rma_req_o;
  lc_flash_rma_seed_t lc_flash_rma_seed_o;
  lc_keymgr_div_t lc_keymgr_div_o;

  initial clk = 1'b0;
  always #5 clk = ~clk;

  initial begin
    rst_n = 1'b0;
    repeat (5) @(posedge clk);
    rst_n = 1'b1;
  end

  lc_ctrl dut (
    .clk_i                      (clk),
    .rst_ni                     (rst_n),
    .tl_i                       (tl_i),
    .tl_o                       (tl_o),
    .jtag_i                     (jtag_i),
    .jtag_o                     (jtag_o),
    .scanmode_i                 (Off),
    .alert_rx_i                 (alert_rx_i),
    .alert_tx_o                 (alert_tx_o),
    .esc_wipe_secrets_tx_i      (esc_wipe_secrets_tx_i),
    .esc_wipe_secrets_rx_o      (esc_wipe_secrets_rx_o),
    .esc_scrap_state_tx_i       (esc_scrap_state_tx_i),
    .esc_scrap_state_rx_o       (esc_scrap_state_rx_o),
    .pwr_lc_i                   (pwr_lc_i),
    .pwr_lc_o                   (pwr_lc_o),
    .lc_otp_program_o           (lc_otp_program_o),
    .lc_otp_program_i           (lc_otp_program_i),
    .lc_otp_token_o             (lc_otp_token_o),
    .lc_otp_token_i             (lc_otp_token_i),
    .otp_lc_data_i              (otp_lc_data_i),
    .lc_dft_en_o                (lc_dft_en_o),
    .lc_nvm_debug_en_o          (lc_nvm_debug_en_o),
    .lc_hw_debug_en_o           (lc_hw_debug_en_o),
    .lc_cpu_en_o                (lc_cpu_en_o),
    .lc_creator_seed_sw_rw_en_o (lc_creator_seed_sw_rw_en_o),
    .lc_owner_seed_sw_rw_en_o   (lc_owner_seed_sw_rw_en_o),
    .lc_iso_part_sw_rd_en_o     (lc_iso_part_sw_rd_en_o),
    .lc_iso_part_sw_wr_en_o     (lc_iso_part_sw_wr_en_o),
    .lc_seed_hw_rd_en_o         (lc_seed_hw_rd_en_o),
    .lc_keymgr_en_o             (lc_keymgr_en_o),
    .lc_escalate_en_o           (lc_escalate_en_o),
    .lc_check_byp_en_o          (lc_check_byp_en_o),
    .lc_clk_byp_req_o           (lc_clk_byp_req_o),
    .lc_clk_byp_ack_i           (Off),
    .lc_flash_rma_seed_o        (lc_flash_rma_seed_o),
    .lc_flash_rma_req_o         (lc_flash_rma_req_o),
    .lc_flash_rma_ack_i         (Off),
    .lc_keymgr_div_o            (lc_keymgr_div_o),
    .otp_hw_cfg_i               (otp_hw_cfg_i)
  );

  initial begin
    otp_lc_data_i = '0;
    otp_lc_data_i.valid = 1'b1;
    otp_lc_data_i.error = 1'b0;
    otp_lc_data_i.state = LcStScrap;
    otp_lc_data_i.count = LcCnt1;
    otp_lc_data_i.id_state = LcIdBlank;

    wait (rst_n === 1'b1);
    repeat (2) @(posedge clk);
    pwr_lc_i.lc_init = 1'b1;
    wait (pwr_lc_o.lc_done == 1'b1);
    repeat (2) @(posedge clk);

    if (lc_escalate_en_o != On) begin
      $error("Expected lc_escalate_en_o=On in encoded SCRAP state, got 0x%0h",
             lc_escalate_en_o);
      $fatal(1);
    end

    $display("TB_CHECK: lc_escalate_en_o asserted in encoded SCRAP state");
    $display("TEST PASSED UVM CHECKS");
    $finish;
  end

  initial begin
    repeat (2000) @(posedge clk);
    $error("Timed out waiting for lc_ctrl initialization");
    $fatal(1);
  end
endmodule
EOF

rm -rf "${SCRATCH_ROOT}"
timeout 1800 ./util/dvsim/dvsim.py \
  hw/ip/lc_ctrl/dv/lc_ctrl_sim_cfg.hjson \
  -i lc_ctrl_smoke \
  -t vcs \
  --fixed-seed 1 \
  --reseed 1 \
  --scratch-root "${SCRATCH_ROOT}" \
  --max-parallel 1
DVSIM_RC=$?

SIM_DIR="$(find "${SCRATCH_ROOT}" -type d -name 'lc_ctrl-sim-vcs' | head -n1)"
if [[ -n "${SIM_DIR}" ]]; then
  BUILD_LOG="$(find "${SIM_DIR}" -type f -path '*/default/build.log' | head -n1)"
  RUN_LOG="$(find "${SIM_DIR}" -type f -path '*/0.lc_ctrl_smoke/out/run.log' | head -n1)"
fi

if [[ ${DVSIM_RC} -eq 124 ]]; then
  report_result FAIL
  exit 124
fi

if [[ -z "${BUILD_LOG}" || ! -f "${BUILD_LOG}" ]]; then
  report_result FAIL
  exit 1
fi

if [[ ! -x "${SIM_DIR}/default/simv" && ${DVSIM_RC} -eq 0 ]]; then
  report_result FAIL
  exit 1
fi

if [[ -z "${RUN_LOG}" || ! -f "${RUN_LOG}" ]]; then
  report_result FAIL
  exit 1
fi

if grep -Fq 'TEST PASSED UVM CHECKS' "${RUN_LOG}"; then
  report_result PASS
  exit 0
fi

report_result FAIL
exit 1

