#!/bin/bash
cd /home/opentitan || exit 1

set -u
set -o pipefail

TEST_NAME="pwrmgr_escalation_reset_path"
TB_DIR="/home/opentitan/.tb_pwrmgr_escalation"
SETUP_DIR="${TB_DIR}/fusesoc"
BUILD_DIR="${SETUP_DIR}/build/lowrisc_ip_pwrmgr_0.1/default-vcs"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import pwrmgr_pkg::*;
  import pwrmgr_reg_pkg::*;
  import tlul_pkg::*;
  import prim_esc_pkg::*;

  logic clk_i = 1'b0;
  logic clk_slow_i = 1'b0;
  logic rst_ni = 1'b0;
  logic rst_slow_ni = 1'b0;

  tl_h2d_t tl_i = '0;
  tl_d2h_t tl_o;
  pwr_ast_rsp_t pwr_ast_i = PWR_AST_RSP_DEFAULT;
  pwr_ast_req_t pwr_ast_o;
  pwr_rst_rsp_t pwr_rst_i = PWR_RST_RSP_DEFAULT;
  pwr_rst_req_t pwr_rst_o;
  pwr_clk_rsp_t pwr_clk_i = '{clk_status: 1'b1};
  pwr_clk_req_t pwr_clk_o;
  pwr_otp_rsp_t pwr_otp_i = PWR_OTP_RSP_DEFAULT;
  pwr_otp_req_t pwr_otp_o;
  pwr_lc_rsp_t pwr_lc_i = PWR_LC_RSP_DEFAULT;
  pwr_lc_req_t pwr_lc_o;
  pwr_flash_rsp_t pwr_flash_i = PWR_FLASH_RSP_DEFAULT;
  pwr_flash_req_t pwr_flash_o;
  pwr_cpu_t pwr_cpu_i = PWR_CPU_DEFAULT;
  logic [NumWkups-1:0] wakeups_i = '0;
  logic [NumRstReqs-1:0] rstreqs_i = '0;
  esc_tx_t esc_rst_tx_i = ESC_TX_DEFAULT;
  esc_rx_t esc_rst_rx_o;
  logic intr_wakeup_o;

  bit saw_esc_en = 0;
  bit saw_masked_req = 0;
  bit saw_status = 0;

  always #5 clk_i = ~clk_i;
  always #11 clk_slow_i = ~clk_slow_i;

  always @(posedge clk_i) begin
    if (rst_ni) begin
      if (dut.u_esc_rx.esc_en_o === 1'b1) saw_esc_en = 1;
      if (dut.hw2reg.escalate_reset_status.d === 1'b1) saw_status = 1;
    end
  end

  always @(posedge clk_slow_i) begin
    if (rst_slow_ni) begin
      if (dut.slow_peri_reqs_masked.rstreqs[NumRstReqs] === 1'b1) saw_masked_req = 1;
    end
  end

  task automatic drive_escalation;
    begin
      @(negedge clk_i);
      esc_rst_tx_i.esc_p = 1'b1;
      esc_rst_tx_i.esc_n = 1'b0;
      repeat (4) @(posedge clk_i);
      @(negedge clk_i);
      esc_rst_tx_i = ESC_TX_DEFAULT;
    end
  endtask

  initial begin
    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    rst_slow_ni = 1'b1;

    repeat (4) @(posedge clk_i);
    drive_escalation();
    repeat (24) @(posedge clk_i);

    if (!saw_esc_en) begin
      $fatal(1, "No escalation detected");
    end
    if (!saw_masked_req) begin
      $fatal(1, "Escalation reset did not survive slow-domain masking");
    end
    if (!saw_status) begin
      $fatal(1, "Escalate reset status did not assert");
    end

    $display("TB_ESC_PASS");
    $finish;
  end

  pwrmgr dut (
    .clk_slow_i,
    .clk_i,
    .rst_slow_ni,
    .rst_ni,
    .tl_i,
    .tl_o,
    .pwr_ast_i,
    .pwr_ast_o,
    .pwr_rst_i,
    .pwr_rst_o,
    .pwr_clk_o,
    .pwr_clk_i,
    .pwr_otp_i,
    .pwr_otp_o,
    .pwr_lc_i,
    .pwr_lc_o,
    .pwr_flash_o,
    .pwr_flash_i,
    .esc_rst_tx_i,
    .esc_rst_rx_o,
    .pwr_cpu_i,
    .wakeups_i,
    .rstreqs_i,
    .intr_wakeup_o
  );
endmodule
EOF

if [[ ! -f "${BUILD_DIR}/lowrisc_ip_pwrmgr_0.1.scr" ]]; then
  rm -rf "${SETUP_DIR}"
  mkdir -p "${SETUP_DIR}"
  (
    cd "${SETUP_DIR}" || exit 1
    source /etc/opentitan_tools_path.sh >/dev/null 2>&1 || true
    fusesoc --cores-root /home/opentitan run --tool=vcs --setup lowrisc:ip:pwrmgr:0.1
  ) > "${TB_DIR}/fusesoc_setup.log" 2>&1
  setup_rc=$?
  if [[ ${setup_rc} -ne 0 ]]; then
    emit_result "FAIL"
    exit "${setup_rc}"
  fi
fi

awk '
  /lowrisc_ip_pwrmgr_pkg_0\.1\/rtl\/pwrmgr_pkg\.sv/ && !done {
    print "/home/opentitan/hw/top_earlgrey/ip/pwrmgr/rtl/autogen/pwrmgr_reg_pkg.sv"
    done = 1
  }
  { print }
  END {
    print "/home/opentitan/hw/top_earlgrey/ip/pwrmgr/rtl/autogen/pwrmgr_reg_top.sv"
    print "/home/opentitan/.tb_pwrmgr_escalation/tb.sv"
  }
' "${BUILD_DIR}/lowrisc_ip_pwrmgr_0.1.scr" > "${TB_DIR}/files.f"

rm -rf "${TB_DIR}/simv" "${TB_DIR}/simv.daidir" "${TB_DIR}/csrc"

(
  cd "${BUILD_DIR}" || exit 1
  vcs -full64 -sverilog -top tb -f "${TB_DIR}/files.f" \
    -o "${TB_DIR}/simv" -l "${COMPILE_LOG}"
) > >(tee "${TB_DIR}/compile.stdout") 2>&1
compile_rc=${PIPESTATUS[0]}

run_rc=1
if [[ ${compile_rc} -eq 0 ]]; then
  "${TB_DIR}/simv" -l "${RUN_LOG}" > >(tee "${TB_DIR}/run.stdout") 2>&1
  run_rc=${PIPESTATUS[0]}
fi

if [[ ${compile_rc} -eq 0 && ${run_rc} -eq 0 ]]; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
if [[ ${compile_rc} -ne 0 ]]; then
  exit "${compile_rc}"
fi
exit "${run_rc}"

#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="lc_ctrl_flash_access"
SCRATCH_ROOT="/home/opentitan/.tb_lc_ctrl_flash_access"
TB_SV="${SCRATCH_ROOT}/lc_ctrl_signal_decode_tb.sv"
BUILD_LOG="${SCRATCH_ROOT}/build.log"
RUN_LOG="${SCRATCH_ROOT}/run.log"
SIMV="${SCRATCH_ROOT}/simv"

rm -rf "${SCRATCH_ROOT}"
mkdir -p "${SCRATCH_ROOT}"

EXTRA_DEFINE=""
if grep -q "lc_creator_seed_sw_rw_en_o" hw/ip/lc_ctrl/rtl/lc_ctrl_signal_decode.sv; then
  EXTRA_DEFINE="+define+HAS_FINE_GRAIN_LC_PORTS"
fi

cat > "${TB_SV}" <<'EOF'
module tb;
  import lc_ctrl_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic lc_state_valid_i;
  lc_state_e lc_state_i;
  lc_id_state_e lc_id_state_i;
  fsm_state_e fsm_state_i;
  logic esc_wipe_secrets_i;

  lc_tx_t lc_dft_en_o;
  lc_tx_t lc_nvm_debug_en_o;
  lc_tx_t lc_hw_debug_en_o;
  lc_tx_t lc_cpu_en_o;
`ifdef HAS_FINE_GRAIN_LC_PORTS
  lc_tx_t lc_creator_seed_sw_rw_en_o;
  lc_tx_t lc_owner_seed_sw_rw_en_o;
  lc_tx_t lc_iso_part_sw_rd_en_o;
  lc_tx_t lc_iso_part_sw_wr_en_o;
  lc_tx_t lc_seed_hw_rd_en_o;
`else
  lc_tx_t lc_provision_wr_en_o;
  lc_tx_t lc_provision_rd_en_o;
  lc_tx_t lc_iso_flash_wr_en_o;
`endif
  lc_tx_t lc_keymgr_en_o;
  lc_tx_t lc_escalate_en_o;
  lc_keymgr_div_t lc_keymgr_div_o;

  int failure_count = 0;

  function automatic bit is_on(lc_tx_t value);
    return value == On;
  endfunction

  task automatic check_perm(
    input string case_name,
    input string perm_name,
    input bit actual,
    input bit expected
  );
    if (actual !== expected) begin
      $display("ACCESS_MISMATCH case=%0s perm=%0s actual=%0d expected=%0d",
               case_name, perm_name, actual, expected);
      failure_count++;
    end
  endtask

  task automatic drive_and_check(
    input string case_name,
    input lc_state_e state,
    input lc_id_state_e id_state,
    input bit exp_creator,
    input bit exp_owner,
    input bit exp_iso_rd,
    input bit exp_iso_wr,
    input bit exp_seed_hw
  );
    bit act_creator;
    bit act_owner;
    bit act_iso_rd;
    bit act_iso_wr;
    bit act_seed_hw;

    lc_state_valid_i = 1'b1;
    lc_state_i = state;
    lc_id_state_i = id_state;
    fsm_state_i = IdleSt;
    esc_wipe_secrets_i = 1'b0;

    @(posedge clk_i);
    #1;

`ifdef HAS_FINE_GRAIN_LC_PORTS
    act_creator = is_on(lc_creator_seed_sw_rw_en_o);
    act_owner = is_on(lc_owner_seed_sw_rw_en_o);
    act_iso_rd = is_on(lc_iso_part_sw_rd_en_o);
    act_iso_wr = is_on(lc_iso_part_sw_wr_en_o);
    act_seed_hw = is_on(lc_seed_hw_rd_en_o);
`else
    act_creator = is_on(lc_provision_wr_en_o);
    act_owner = is_on(lc_provision_rd_en_o);
    act_iso_rd = is_on(lc_provision_rd_en_o);
    act_iso_wr = is_on(lc_provision_wr_en_o) || is_on(lc_iso_flash_wr_en_o);
    act_seed_hw = !is_on(lc_provision_wr_en_o) && is_on(lc_provision_rd_en_o);
`endif

    $display("CASE %0s creator=%0d owner=%0d iso_rd=%0d iso_wr=%0d seed_hw=%0d",
             case_name, act_creator, act_owner, act_iso_rd, act_iso_wr, act_seed_hw);

    check_perm(case_name, "creator_seed_sw_rw", act_creator, exp_creator);
    check_perm(case_name, "owner_seed_sw_rw", act_owner, exp_owner);
    check_perm(case_name, "iso_part_sw_rd", act_iso_rd, exp_iso_rd);
    check_perm(case_name, "iso_part_sw_wr", act_iso_wr, exp_iso_wr);
    check_perm(case_name, "seed_hw_rd", act_seed_hw, exp_seed_hw);
  endtask

  always #5 clk_i = ~clk_i;

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    lc_state_valid_i = 1'b0;
    lc_state_i = LcStRaw;
    lc_id_state_i = LcIdBlank;
    fsm_state_i = ResetSt;
    esc_wipe_secrets_i = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    @(posedge clk_i);

    drive_and_check("raw_blank", LcStRaw, LcIdBlank, 1'b0, 1'b0, 1'b0, 1'b0, 1'b0);
    drive_and_check("test_unlocked", LcStTestUnlocked0, LcIdBlank, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0);
    drive_and_check("prod_blank", LcStProd, LcIdBlank, 1'b1, 1'b1, 1'b1, 1'b1, 1'b0);
    drive_and_check("prod_personalized", LcStProd, LcIdPersonalized, 1'b0, 1'b1, 1'b1, 1'b1,
                    1'b1);
    drive_and_check("dev_personalized", LcStDev, LcIdPersonalized, 1'b0, 1'b1, 1'b1, 1'b1,
                    1'b1);
    drive_and_check("rma_personalized", LcStRma, LcIdPersonalized, 1'b1, 1'b1, 1'b1, 1'b1,
                    1'b1);

    if (failure_count != 0) begin
      $fatal(1, "Observed %0d access mismatches", failure_count);
    end

    $display("LC_CTRL_FLASH_ACCESS_PASS");
    $finish;
  end

`ifdef HAS_FINE_GRAIN_LC_PORTS
  lc_ctrl_signal_decode dut (
    .clk_i,
    .rst_ni,
    .lc_state_valid_i,
    .lc_state_i,
    .lc_id_state_i,
    .fsm_state_i,
    .esc_wipe_secrets_i,
    .lc_dft_en_o,
    .lc_nvm_debug_en_o,
    .lc_hw_debug_en_o,
    .lc_cpu_en_o,
    .lc_creator_seed_sw_rw_en_o,
    .lc_owner_seed_sw_rw_en_o,
    .lc_iso_part_sw_rd_en_o,
    .lc_iso_part_sw_wr_en_o,
    .lc_seed_hw_rd_en_o,
    .lc_keymgr_en_o,
    .lc_escalate_en_o,
    .lc_keymgr_div_o
  );
`else
  lc_ctrl_signal_decode dut (
    .clk_i,
    .rst_ni,
    .lc_state_valid_i,
    .lc_state_i,
    .lc_id_state_i,
    .fsm_state_i,
    .esc_wipe_secrets_i,
    .lc_dft_en_o,
    .lc_nvm_debug_en_o,
    .lc_hw_debug_en_o,
    .lc_cpu_en_o,
    .lc_provision_wr_en_o,
    .lc_provision_rd_en_o,
    .lc_iso_flash_wr_en_o,
    .lc_keymgr_en_o,
    .lc_escalate_en_o,
    .lc_keymgr_div_o
  );
`endif
endmodule
EOF

pushd "${SCRATCH_ROOT}" >/dev/null
timeout 600 vcs \
  -full64 \
  -sverilog \
  -timescale=1ns/1ps \
  -l "${BUILD_LOG}" \
  -o "${SIMV}" \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  ${EXTRA_DEFINE} \
  /home/opentitan/hw/ip/prim/rtl/prim_assert.sv \
  /home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv \
  /home/opentitan/hw/ip/lc_ctrl/rtl/lc_ctrl_pkg.sv \
  /home/opentitan/hw/ip/lc_ctrl/rtl/lc_ctrl_signal_decode.sv \
  "${TB_SV}"
build_rc=$?
popd >/dev/null

if [[ "${build_rc}" -ne 0 ]]; then
  echo "[INFO] VCS build failed with exit code: ${build_rc}"
  if [[ -f "${BUILD_LOG}" ]]; then
    tail -n 120 "${BUILD_LOG}"
  fi
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
fi

pushd "${SCRATCH_ROOT}" >/dev/null
timeout 120 "${SIMV}" -l "${RUN_LOG}"
run_rc=$?
popd >/dev/null

if [[ "${run_rc}" -eq 0 ]] && grep -q "^LC_CTRL_FLASH_ACCESS_PASS$" "${RUN_LOG}"; then
  echo "[INFO] Simulation passed with expected marker"
  tail -n 80 "${RUN_LOG}"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "[INFO] Simulation failed or did not emit the PASS marker (exit code: ${run_rc})"
if [[ -f "${RUN_LOG}" ]]; then
  tail -n 120 "${RUN_LOG}"
fi
echo "HWE_BENCH_RESULTS_START"
echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

