tb_script:
#!/bin/bash
cd /home/opentitan
set +e
set -o pipefail

TEST_NAME="csrng_lc_dft_en_bypass"
TB_DIR="/home/opentitan/.tb_csrng_lc"
BUILD_ROOT="${TB_DIR}/build"
RUN_LOG="${TB_DIR}/run.log"

mkdir -p "${TB_DIR}"
rm -rf "${BUILD_ROOT}" "${RUN_LOG}"

cat > "${TB_DIR}/csrng_lc_repro.core" <<'EOF'
CAPI=2:
name: "local:tb:csrng_lc_repro:0.1"
description: "csrng lifecycle AES bypass reproducer"
filesets:
  files_rtl:
    depend:
      - lowrisc:ip:csrng
      - lowrisc:ip:lc_ctrl_pkg
      - lowrisc:prim:multibit_sync
    files:
      - checker.sv
      - tb.sv
    file_type: systemVerilogSource
targets:
  default: &default_target
    filesets:
      - files_rtl
    toplevel: tb
  sim:
    <<: *default_target
    default_tool: vcs
    tools:
      vcs:
        vcs_options:
          - "-ntb_opts uvm-1.2"
          - "-debug_access+f"
EOF

cat > "${TB_DIR}/checker.sv" <<'EOF'
module csrng_block_encrypt_chk (
  input logic              clk_i,
  input logic              rst_ni,
  input logic              block_encrypt_bypass_i,
  input logic              block_encrypt_req_i,
  input logic              block_encrypt_rdy_o,
  input logic [127:0]      block_encrypt_v_i,
  input logic [2:0]        block_encrypt_cmd_i,
  input logic [3:0]        block_encrypt_id_i,
  input logic              block_encrypt_ack_o,
  input logic [2:0]        block_encrypt_cmd_o,
  input logic [3:0]        block_encrypt_id_o,
  input logic [127:0]      block_encrypt_v_o
);
  logic [127:0] req_v;
  logic [2:0] req_cmd;
  logic [3:0] req_id;
  logic req_seen;

  always_ff @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
      req_seen <= 1'b0;
    end else begin
      if (block_encrypt_req_i && block_encrypt_rdy_o) begin
        req_v <= block_encrypt_v_i;
        req_cmd <= block_encrypt_cmd_i;
        req_id <= block_encrypt_id_i;
        req_seen <= 1'b1;
      end

      if (block_encrypt_ack_o && req_seen) begin
        if (block_encrypt_v_o == req_v) begin
          $fatal(1, "block_encrypt bypass must be ignored when lc_dft is Off");
        end
        if (block_encrypt_cmd_o !== req_cmd) begin
          $fatal(1, "block_encrypt cmd mismatch");
        end
        if (block_encrypt_id_o !== req_id) begin
          $fatal(1, "block_encrypt id mismatch");
        end
        req_seen <= 1'b0;
        $finish;
      end
    end
  end
endmodule

bind csrng_block_encrypt csrng_block_encrypt_chk u_csrng_block_encrypt_chk (
  .clk_i,
  .rst_ni,
  .block_encrypt_bypass_i,
  .block_encrypt_req_i,
  .block_encrypt_rdy_o,
  .block_encrypt_v_i,
  .block_encrypt_cmd_i,
  .block_encrypt_id_i,
  .block_encrypt_ack_o,
  .block_encrypt_cmd_o,
  .block_encrypt_id_o,
  .block_encrypt_v_o
);
EOF

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import uvm_pkg::*;
  import csrng_pkg::*;
  import csrng_reg_pkg::*;
  import entropy_src_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;

  csrng_reg2hw_t reg2hw;
  csrng_hw2reg_t hw2reg;
  entropy_src_hw_if_req_t entropy_src_hw_if_o;
  entropy_src_hw_if_rsp_t entropy_src_hw_if_i;
  csrng_req_t [1:0] app_i;
  csrng_rsp_t [1:0] app_o;
  logic intr_cs_cmd_req_done_o;
  logic intr_cs_entropy_req_o;
  logic intr_cs_hw_inst_exc_o;
  logic intr_cs_fifo_err_o;
  logic [3:0] lc_dft_force;
  bit lc_dft_forced;

  always #5 clk_i = ~clk_i;

  csrng_core dut (
    .clk_i,
    .rst_ni,
    .reg2hw,
    .hw2reg,
    .efuse_sw_app_enable_i(1'b0),
    .entropy_src_hw_if_o,
    .entropy_src_hw_if_i,
    .csrng_cmd_i(app_i),
    .csrng_cmd_o(app_o),
    .intr_cs_cmd_req_done_o,
    .intr_cs_entropy_req_o,
    .intr_cs_hw_inst_exc_o,
    .intr_cs_fifo_err_o
  );

  task automatic send_cmd_word(input logic [31:0] word);
    reg2hw.cmd_req.q = word;
    reg2hw.cmd_req.qe = 1'b1;
    @(posedge clk_i);
    reg2hw.cmd_req.qe = 1'b0;
    @(posedge clk_i);
  endtask

  initial begin
    reg2hw = '0;
    entropy_src_hw_if_i = '0;
    app_i[0] = CSRNG_REQ_DEFAULT;
    app_i[1] = CSRNG_REQ_DEFAULT;

    lc_dft_force = lc_ctrl_pkg::Off;
    lc_dft_forced = uvm_hdl_force("tb.dut.lc_dft_en_i", lc_dft_force);

    repeat (4) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (4) @(posedge clk_i);

    reg2hw.ctrl.enable.q = 1'b1;
    reg2hw.ctrl.aes_cipher_disable.q = 1'b1;

    send_cmd_word(32'h0000_01c1);
    repeat (12) send_cmd_word(32'h0000_0000);

    repeat (1000) @(posedge clk_i);
    $fatal(1, "timeout waiting for block_encrypt ack");
  end
endmodule
EOF

fusesoc --cores-root /home/opentitan --cores-root "${TB_DIR}" \
  run --no-export \
  --build-root "${BUILD_ROOT}" \
  --target=sim \
  --tool=vcs \
  local:tb:csrng_lc_repro | tee "${RUN_LOG}"
rc=${PIPESTATUS[0]}
if [ "${rc}" -eq 0 ] && grep -q 'block_encrypt bypass must be ignored when lc_dft is Off' "${RUN_LOG}"; then
  rc=1
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

