#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME=otp_ctrl_scrmbl_roundtrip
WORK_CORE_DIR=hw/ip/otp_ctrl/dv/roundtrip_msb
BUILD_ROOT=/home/opentitan/.tb_otp_scrmbl_build
CORE_FILE="${WORK_CORE_DIR}/otp_ctrl_scrmbl_roundtrip_sim.core"
TB_FILE="${WORK_CORE_DIR}/otp_ctrl_scrmbl_roundtrip_tb.sv"
SIM_LOG="${BUILD_ROOT}/sim-vcs/vcs.log"

report_and_exit() {
  local status="$1"
  local code="$2"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  exit "${code}"
}

rm -rf "${WORK_CORE_DIR}" "${BUILD_ROOT}"
mkdir -p "${WORK_CORE_DIR}"
export PATH="/opt/synopsys/vcs/T-2022.06-SP2-10/bin:${PATH}"

cat > "${CORE_FILE}" <<'EOF'
CAPI=2:
name: "lowrisc:dv:otp_ctrl_scrmbl_roundtrip_sim:0.1"
description: "OTP scrambler roundtrip sim"
filesets:
  files_dv:
    depend:
      - lowrisc:ip:otp_ctrl_pkg:0.1
      - lowrisc:prim:all
    files:
      - otp_ctrl_scrmbl_roundtrip_tb.sv
      - ../../rtl/otp_ctrl_scrmbl.sv
    file_type: systemVerilogSource

targets:
  sim:
    toplevel: otp_ctrl_scrmbl_roundtrip_tb
    filesets:
      - files_dv
    default_tool: vcs
    tools:
      vcs:
        vcs_options:
          - "-timescale=1ns/1ps"
EOF

cat > "${TB_FILE}" <<'EOF'
module otp_ctrl_scrmbl_roundtrip_tb;
  import otp_ctrl_pkg::*;
  import lc_ctrl_pkg::*;

  logic clk_i;
  logic rst_ni;
  otp_scrmbl_cmd_e cmd_i;
  logic [ConstSelWidth-1:0] sel_i;
  logic [ScrmblBlockWidth-1:0] data_i;
  logic valid_i;
  logic ready_o;
  logic [ScrmblBlockWidth-1:0] data_o;
  logic valid_o;
  lc_tx_t escalate_en_i;
  logic fsm_err_o;

  otp_ctrl_scrmbl dut (
    .clk_i,
    .rst_ni,
    .cmd_i,
    .sel_i,
    .data_i,
    .valid_i,
    .ready_o,
    .data_o,
    .valid_o,
    .escalate_en_i,
    .fsm_err_o
  );

  always #5 clk_i = ~clk_i;

  task automatic issue_cmd(
      input otp_scrmbl_cmd_e cmd,
      input logic [ConstSelWidth-1:0] sel,
      input logic [ScrmblBlockWidth-1:0] data
  );
    begin
      @(posedge clk_i);
      while (!ready_o) @(posedge clk_i);
      cmd_i <= cmd;
      sel_i <= sel;
      data_i <= data;
      valid_i <= 1'b1;
      @(posedge clk_i);
      valid_i <= 1'b0;
      data_i <= '0;
    end
  endtask

  task automatic wait_result(output logic [ScrmblBlockWidth-1:0] data);
    begin
      do @(posedge clk_i); while (!valid_o);
      data = data_o;
    end
  endtask

  task automatic check_roundtrip(
      input key_sel_e key_sel,
      input logic [ScrmblBlockWidth-1:0] plain
  );
    logic [ScrmblBlockWidth-1:0] cipher;
    logic [ScrmblBlockWidth-1:0] recovered;
    begin
      issue_cmd(Encrypt, key_sel, plain);
      wait_result(cipher);
      issue_cmd(Decrypt, key_sel, cipher);
      wait_result(recovered);
      if (fsm_err_o) begin
        $display("FSM error asserted");
        $fatal(1);
      end
      if (recovered !== plain) begin
        $display("ROUNDTRIP_MISMATCH key=%0d plain=%h cipher=%h recovered=%h",
                 key_sel, plain, cipher, recovered);
        $fatal(1);
      end
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    cmd_i = Encrypt;
    sel_i = '0;
    data_i = '0;
    valid_i = 1'b0;
    escalate_en_i = Off;

    repeat (5) @(posedge clk_i);
    rst_ni = 1'b1;
    repeat (2) @(posedge clk_i);

    check_roundtrip(Secret0Key, 64'h0123_4567_89ab_cdef);
    check_roundtrip(Secret1Key, 64'hfedc_ba98_7654_3210);
    check_roundtrip(Secret2Key, 64'h0f1e_2d3c_4b5a_6978);

    $display("ROUNDTRIP_PASS");
    $finish;
  end
endmodule
EOF

timeout 900 fusesoc \
  --cores-root . \
  --cores-root "${WORK_CORE_DIR}" \
  run \
  --no-export \
  --build-root "${BUILD_ROOT}" \
  --setup \
  --build \
  --run \
  --target=sim \
  --tool=vcs \
  lowrisc:dv:otp_ctrl_scrmbl_roundtrip_sim:0.1
rc=$?

if [[ ${rc} -eq 124 ]]; then
  echo "[ERROR] FuseSoC/VCS timed out after 900 seconds"
  report_and_exit FAIL 124
fi

if [[ -f "${SIM_LOG}" ]] && grep -Eq '^ROUNDTRIP_PASS$' "${SIM_LOG}"; then
  report_and_exit PASS 0
fi

if [[ -f "${SIM_LOG}" ]]; then
  echo "[ERROR] Simulation failed"
  tail -n 80 "${SIM_LOG}"
else
  echo "[ERROR] FuseSoC run failed before generating ${SIM_LOG}"
fi

report_and_exit FAIL 1

#!/bin/bash
set -uo pipefail

cd /home/opentitan || exit 1

TEST_NAME="prim_intr_hw_one_cycle_delay"
