SIMV="${TB_DIR}/simv"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_FILE}" <<'EOF'
module tb_prim_intr_hw;
  logic clk_i = 1'b0;
  logic rst_ni = 1'b0;
  logic event_intr_i = 1'b0;
  logic reg2hw_intr_enable_q_i = 1'b0;
  logic reg2hw_intr_test_q_i = 1'b0;
  logic reg2hw_intr_test_qe_i = 1'b0;
  logic reg2hw_intr_state_q_i = 1'b0;
  logic hw2reg_intr_state_de_o;
  logic hw2reg_intr_state_d_o;
  logic intr_o;

  always #5 clk_i = ~clk_i;

  prim_intr_hw dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .event_intr_i(event_intr_i),
    .reg2hw_intr_enable_q_i(reg2hw_intr_enable_q_i),
    .reg2hw_intr_test_q_i(reg2hw_intr_test_q_i),
    .reg2hw_intr_test_qe_i(reg2hw_intr_test_qe_i),
    .reg2hw_intr_state_q_i(reg2hw_intr_state_q_i),
    .hw2reg_intr_state_de_o(hw2reg_intr_state_de_o),
    .hw2reg_intr_state_d_o(hw2reg_intr_state_d_o),
    .intr_o(intr_o)
  );

  initial begin
    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    reg2hw_intr_enable_q_i = 1'b1;
    reg2hw_intr_state_q_i = 1'b1;

    #1;
    if (intr_o !== 1'b0) begin
      $fatal(1, "intr_o asserted before the next clock edge");
    end

    @(posedge clk_i);
    #1;
    if (intr_o !== 1'b1) begin
      $fatal(1, "intr_o did not assert after one clock delay");
    end

    @(negedge clk_i);
    reg2hw_intr_state_q_i = 1'b0;

    #1;
    if (intr_o !== 1'b1) begin
      $fatal(1, "intr_o deasserted before the next clock edge");
    end

    @(posedge clk_i);
    #1;
    if (intr_o !== 1'b0) begin
      $fatal(1, "intr_o did not clear after one clock delay");
    end

    $finish;
  end
endmodule
EOF

compile_rc=0
sim_rc=1

set +e
vcs -full64 -sverilog -timescale=1ns/1ps \
  -l "${COMPILE_LOG}" \
  -o "${SIMV}" \
  hw/ip/prim/rtl/prim_intr_hw.sv \
