  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi
echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"

if [ "${compile_rc}" -ne 0 ]; then
  echo "[INFO] VCS compile failed. Log: ${COMPILE_LOG}" >&2
  tail -n 40 "${COMPILE_LOG}" >&2
elif [ -f "${RUN_LOG}" ]; then
  echo "[INFO] VCS simulation failed. Log: ${RUN_LOG}" >&2
  tail -n 40 "${RUN_LOG}" >&2
fi

exit 1

