class aes_ctrl_update_vseq extends aes_base_vseq;
  `uvm_object_utils(aes_ctrl_update_vseq)
  `uvm_object_new

  task body();
    bit [7:0][31:0] key = '{
      32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff,
      32'h0f1e2d3c, 32'h4b5a6978, 32'h8796a5b4, 32'hc3d2e1f0
    };
    bit [3:0][31:0] iv_first = '{
