    };
    bit [3:0][31:0] iv_second = '{
      32'h89abcdef, 32'h01234567, 32'hfedcba98, 32'h76543210
    };
    bit [3:0][31:0] data_first = '{
      32'h00112233, 32'h44556677, 32'h8899aabb, 32'hccddeeff
