#!/bin/bash
cd /home/opentitan || exit 1
set +e

TEST_NAME="alert_handler_clr_corner"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/alert_handler_reg_pkg.sv" <<'EOF'
package alert_handler_reg_pkg;
  localparam int unsigned NAlerts = 1;
  localparam int unsigned EscCntDw = 4;
  localparam int unsigned AccuCntDw = 4;
  localparam logic [31:0] LfsrSeed = 32'h1;
  localparam bit [NAlerts-1:0] AsyncOn = '0;
  localparam int unsigned N_CLASSES = 4;
  localparam int unsigned N_ESC_SEV = 4;
  localparam int unsigned N_PHASES = 4;
  localparam int unsigned N_LOC_ALERT = 1;
  localparam int unsigned PING_CNT_DW = 16;
  localparam int unsigned PHASE_DW = 2;
  localparam int unsigned CLASS_DW = 2;
endpackage
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module alert_handler_esc_timer_tb;
  import alert_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic en_i;
  logic clr_i;
  logic accum_trig_i;
  logic timeout_en_i;
  logic [EscCntDw-1:0] timeout_cyc_i;
  logic [N_ESC_SEV-1:0] esc_en_i;
  logic [N_ESC_SEV-1:0][PHASE_DW-1:0] esc_map_i;
  logic [N_PHASES-1:0][EscCntDw-1:0] phase_cyc_i;
  logic esc_trig_o;
  logic [EscCntDw-1:0] esc_cnt_o;
  logic [N_ESC_SEV-1:0] esc_sig_en_o;
  cstate_e esc_state_o;

  alert_handler_esc_timer dut (
    .clk_i,
    .rst_ni,
    .en_i,
    .clr_i,
    .accum_trig_i,
    .timeout_en_i,
    .timeout_cyc_i,
    .esc_en_i,
    .esc_map_i,
    .phase_cyc_i,
    .esc_trig_o,
    .esc_cnt_o,
    .esc_sig_en_o,
    .esc_state_o
  );

  always #5 clk_i = ~clk_i;

  task automatic drive_cycle(input logic accum, input logic clr);
    @(negedge clk_i);
    accum_trig_i = accum;
    clr_i = clr;
    @(posedge clk_i);
    #1;
  endtask

  initial begin
    clk_i = 0;
    rst_ni = 0;
    en_i = 1'b1;
    clr_i = 1'b0;
    accum_trig_i = 1'b0;
    timeout_en_i = 1'b0;
    timeout_cyc_i = '0;
    esc_en_i = '0;
    esc_map_i = '{default: '0};
    phase_cyc_i = '{default: 4'd2};

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    @(posedge clk_i);
    #1;

    // Sanity check that a normal accumulation trigger still starts escalation.
    drive_cycle(1'b1, 1'b0);
    if (esc_state_o != Phase0 || esc_cnt_o != EscCntDw'(1)) begin
      $error("normal accumulation trigger did not start escalation: state=%0d cnt=%0d",
             esc_state_o, esc_cnt_o);
      $fatal(1);
    end

    accum_trig_i = 1'b0;
    clr_i = 1'b1;
    @(posedge clk_i);
    #1;
    if (esc_state_o != Idle) begin
      $error("clear did not return the timer to Idle: state=%0d", esc_state_o);
      $fatal(1);
    end
    clr_i = 1'b0;

    // The bug: clr_i and accum_trig_i in the same cycle must not enter Phase0.
    drive_cycle(1'b1, 1'b1);
    if (esc_state_o != Idle || esc_cnt_o != '0) begin
      $error("corner case reproduced: simultaneous clr and accum trigger moved state=%0d cnt=%0d",
             esc_state_o, esc_cnt_o);
      $fatal(1);
    end

    accum_trig_i = 1'b0;
    clr_i = 1'b0;
    repeat (2) @(posedge clk_i);
    #1;
    if (esc_state_o != Idle || esc_trig_o != 1'b0) begin
      $error("timer did not stay idle after corner-case clear: state=%0d esc_trig=%0b",
             esc_state_o, esc_trig_o);
      $fatal(1);
    end

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
$TB_DIR/alert_handler_reg_pkg.sv
/home/opentitan/hw/ip/alert_handler/rtl/alert_pkg.sv
/home/opentitan/hw/ip/alert_handler/rtl/alert_handler_esc_timer.sv
$TB_DIR/tb.sv
EOF

vcs -full64 -sverilog -assert svaext -timescale=1ns/1ps \
  -f "$TB_DIR/files.f" \
  -top alert_handler_esc_timer_tb \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log"
compile_rc=$?

if [ "$compile_rc" -eq 0 ]; then
  "$TB_DIR/simv" -l "$TB_DIR/run.log"
  run_rc=$?
else
  run_rc=$compile_rc
fi

if [ "$compile_rc" -eq 0 ] && [ "$run_rc" -eq 0 ] && \
   [ -f "$TB_DIR/run.log" ] && grep -Fq "TB_PASS" "$TB_DIR/run.log"; then
  rc=0
else
  rc=1
fi

if [ "$compile_rc" -ne 0 ] && [ -f "$TB_DIR/compile.log" ]; then
  tail -n 80 "$TB_DIR/compile.log"
fi

if [ "$run_rc" -ne 0 ] && [ -f "$TB_DIR/run.log" ]; then
  tail -n 80 "$TB_DIR/run.log"
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

