cat > "$TB_SV" <<'EOF'
module tb;
  logic clk_i;
  logic rst_ni;
  logic req_i;
  logic gnt_o;
  logic [31:0] addr_i;
  logic we_i;
  logic [31:0] wdata_i;
  logic [3:0] be_i;
  logic valid_o;
  logic [31:0] rdata_o;
  logic err_o;
  tlul_pkg::tl_h2d_t tl_o;
  tlul_pkg::tl_d2h_t tl_i;

  dut_wrap u_dut (
    .clk_i,
    .rst_ni,
    .req_i,
    .gnt_o,
    .addr_i,
    .we_i,
    .wdata_i,
    .be_i,
    .valid_o,
    .rdata_o,
    .err_o,
    .tl_o,
    .tl_i
  );

  initial clk_i = 1'b0;
  always #5 clk_i = ~clk_i;

  task automatic drive_read_without_be;
    begin
      tl_i.a_ready = 1'b1;
      req_i = 1'b1;
      we_i = 1'b0;
      be_i = 4'b0000;
      addr_i = 32'h1000_0000;
      wdata_i = 32'h0000_0000;
      @(posedge clk_i);
      #1;
      if (tl_o.a_opcode !== tlul_pkg::Get) begin
        $fatal(1, "expected Get opcode, got %0d", tl_o.a_opcode);
      end
      if (tl_o.a_mask !== 4'hf) begin
        $fatal(1, "read mask mismatch: expected 0xf got 0x%0h", tl_o.a_mask);
      end
      req_i = 1'b0;
      @(posedge clk_i);
    end
  endtask

  task automatic drive_partial_write;
    begin
      tl_i.a_ready = 1'b1;
      req_i = 1'b1;
      we_i = 1'b1;
      be_i = 4'b0011;
      addr_i = 32'h1000_0000;
      wdata_i = 32'h1122_3344;
      @(posedge clk_i);
      #1;
      if (tl_o.a_opcode !== tlul_pkg::PutPartialData) begin
        $fatal(1, "partial write opcode mismatch: expected PutPartialData got %0d",
               tl_o.a_opcode);
      end
      if (tl_o.a_mask !== 4'b0011) begin
        $fatal(1, "partial write mask mismatch: expected 0x3 got 0x%0h", tl_o.a_mask);
      end
      req_i = 1'b0;
      @(posedge clk_i);
    end
  endtask

  initial begin
    tl_i = '0;
    req_i = 1'b0;
    we_i = 1'b0;
    be_i = 4'b0000;
    addr_i = 32'h0000_0000;
    wdata_i = 32'h0000_0000;
    rst_ni = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    @(posedge clk_i);

    drive_read_without_be();
    drive_partial_write();

    $display("TB_PASS");
    $finish;
  end
endmodule
EOF

cat > "$FILELIST" <<EOF
+incdir+/home/opentitan/hw/ip/prim/rtl
/home/opentitan/hw/top_earlgrey/rtl/top_pkg.sv
/home/opentitan/hw/ip/tlul/rtl/tlul_pkg.sv
$DUT_FILE
$WRAP_SV
$TB_SV
EOF

vcs -full64 -sverilog -f "$FILELIST" -top tb -Mdir="$TB_DIR/csrc" -o "$SIMV" -l "$COMPILE_LOG"
compile_rc=$?

if [[ $compile_rc -ne 0 ]]; then
  echo "[ERROR] VCS compile failed for $TEST_NAME"
  tail -n 80 "$COMPILE_LOG"
  emit_result FAIL
  exit 1
fi

"$SIMV" -l "$RUN_LOG"
run_rc=$?

if [[ $run_rc -eq 0 ]] && grep -q "TB_PASS" "$RUN_LOG"; then
  emit_result PASS
  exit 0
fi

echo "[ERROR] Simulation failed or did not reach TB_PASS for $TEST_NAME"
tail -n 80 "$RUN_LOG"
emit_result FAIL
exit 1

resolved_issues.body:
It is invalid to write to the HMAC FIFO when `hash_start = 0`, however with the current hardware doing so can cause the core to lock up. From my testing this happens when doing a two writes to `MSG_FIFO` after `fifo_depth = 16`.

This isn't ideal behavior since it forces the DIF implementation to track this bit of state in order to prevent a potential deadlock. It would be better for these writes to get treated as a no-op so an invalid state can't lock up the system.

## Steps to reproduce

If you would like to see this behavior for yourself you can checkout my HMAC DIF branch jon-flatley/opentitan@b3a31b01b47cbc7fa9d7eb5162c0fe2a33ba32d4 and apply this patch to set the test to run without setting `hash_start`:

<details>
  <summary>Test patch</summary>
  
  ```patch
---
 sw/device/lib/dif/dif_hmac.c         | 7 ++++++-
 sw/device/tests/hmac/dif_hmac_test.c | 1 +
 2 files changed, 7 insertions(+), 1 deletion(-)

diff --git a/sw/device/lib/dif/dif_hmac.c b/sw/device/lib/dif/dif_hmac.c
index af4a6537..49780b91 100644
--- a/sw/device/lib/dif/dif_hmac.c
+++ b/sw/device/lib/dif/dif_hmac.c
@@ -6,6 +6,7 @@
 
 #include "hmac_regs.h"  // Generated.
 #include "sw/device/lib/base/memory.h"
+#include "sw/device/lib/log.h"
 
 #define HMAC_HASH_SIZE_BITS 256u
 #define HMAC_KEY_REG_COUNT (HMAC_HASH_SIZE_BITS / 32)
@@ -115,7 +116,7 @@ dif_hmac_fifo_error_t dif_hmac_fifo_push(const dif_hmac_t *hmac,
     return kDifHmacFifoErrorInvalidArgument;
   }
 
-  if (!hmac->hmac_started) {
+  if (false && !hmac->hmac_started) {
     return kDifHmacFifoErrorInvalidState;
   }
 
@@ -127,6 +128,8 @@ dif_hmac_fifo_error_t dif_hmac_fifo_push(const dif_hmac_t *hmac,
 
   // Bring |data_sent| into alignment so we can use |read32()| in the next loop.
   while (unaligned_bytes > 0 && get_fifo_available_space(hmac) > 0) {
+    LOG_INFO("Unaligned bytes remaining = %d\r\n", unaligned_bytes);
+    LOG_INFO("FIFO depth = %d\r\n", get_fifo_entry_count(hmac));
     mmio_region_write8(hmac->base_addr, HMAC_MSG_FIFO_REG_OFFSET, *data_sent);
     data_sent += sizeof(uint8_t);
     --unaligned_bytes;
@@ -134,6 +137,8 @@ dif_hmac_fifo_error_t dif_hmac_fifo_push(const dif_hmac_t *hmac,
 
   // Write whole words until the FIFO fills or there are no words left to send.
   while (words_remaining > 0 && get_fifo_available_space(hmac) > 0) {
+    LOG_INFO("Words remaining = %d\r\n", words_remaining);
+    LOG_INFO("FIFO depth = %d\r\n", get_fifo_entry_count(hmac));
     uint32_t word = read_32(data_sent);
 
     mmio_region_write32(hmac->base_addr, HMAC_MSG_FIFO_REG_OFFSET, word);
diff --git a/sw/device/tests/hmac/dif_hmac_test.c b/sw/device/tests/hmac/dif_hmac_test.c
index ecc5a5fc..2447809a 100644
--- a/sw/device/tests/hmac/dif_hmac_test.c
+++ b/sw/device/tests/hmac/dif_hmac_test.c
@@ -45,6 +45,7 @@ static bool test_setup(const dif_hmac_config_t *config, dif_hmac_t *hmac) {
         return false;
     }
   }
+  return true;
 
   switch (dif_hmac_start(hmac)) {
     case kDifHmacErrorNone:
-- 

  ```
  
</details>

With openocd/gdb you can see things get hung up here:
```
0x200003e0 in mmio_region_write32 (value=543452769, offset=2048, base=...)
    at /home/jflat/ws/opentitan/sw/device/lib/base/mmio.h:137
137	  ((volatile uint32_t *)base.base)[offset / sizeof(uint32_t)] = value;
```

The test I'm using can be build with (I've been testing on fpga)
```
ninja -C build-out sw/device/tests/hmac/dif_hmac_test_fpga_nexysvideo
```

And deployed with
```
./build-bin/sw/host/spiflash/spiflash --input \
build-bin/sw/device/tests/hmac/dif_hmac_test_fpga_nexysvideo.bin
```

fix_patch:
diff --git a/hw/ip/hmac/rtl/hmac.sv b/hw/ip/hmac/rtl/hmac.sv
index 24cce7e8d4787..217e700cadf7a 100644
--- a/hw/ip/hmac/rtl/hmac.sv
+++ b/hw/ip/hmac/rtl/hmac.sv
@@ -101,6 +101,7 @@ module hmac

   hmac_reg2hw_cfg_reg_t cfg_reg;
   logic                 cfg_block;  // Prevent changing config
+  logic                 msg_allowed; // MSG_FIFO from software is allowed

   ///////////////////////
   // Connect registers //
@@ -177,6 +178,17 @@ module hmac
       cfg_reg <= reg2hw.cfg ;
     end
   end
+
+  // Open up the MSG_FIFO from the TL-UL port when it is ready
+  always_ff @(posedge clk_i or negedge rst_ni) begin
+    if (!rst_ni) begin
+      msg_allowed <= '0;
+    end else if (hash_start) begin
+      msg_allowed <= 1'b 1;
+    end else if (packer_flush_done) begin
+      msg_allowed <= 1'b 0;
+    end
+  end
   ////////////////
   // Interrupts //
   ////////////////
@@ -291,7 +303,7 @@ module hmac
   // TL-UL to MSG_FIFO byte write handling
   logic msg_write;

-  assign msg_write = msg_fifo_req & msg_fifo_we & ~hmac_fifo_wsel;
+  assign msg_write = msg_fifo_req & msg_fifo_we & ~hmac_fifo_wsel & msg_allowed;

   logic [$clog2(32+1)-1:0] wmask_ones;

@@ -426,9 +438,11 @@ module hmac
   /////////////////////////
   logic msg_push_sha_disabled, hash_start_sha_disabled, update_seckey_inprocess;
   logic hash_start_active;  // `reg_hash_start` set when hash already in active
+  logic msg_push_not_allowed; // Message is received when `hash_start` isn't set
   assign msg_push_sha_disabled = msg_write & ~sha_en;
   assign hash_start_sha_disabled = reg_hash_start & ~sha_en;
   assign hash_start_active = reg_hash_start & cfg_block;
+  assign msg_push_not_allowed = msg_fifo_req & ~msg_allowed;

   always_comb begin
     update_seckey_inprocess = 1'b0;
@@ -449,7 +463,8 @@ module hmac
   // is pending to avoid any race conditions.
   assign err_valid = ~reg2hw.intr_state.hmac_err.q &
                    ( msg_push_sha_disabled | hash_start_sha_disabled
-                   | update_seckey_inprocess | hash_start_active);
+                   | update_seckey_inprocess | hash_start_active
+                   | msg_push_not_allowed );

   always_comb begin
     err_code = NoError;
@@ -469,6 +484,10 @@ module hmac
         err_code = SwHashStartWhenActive;
       end

+      msg_push_not_allowed: begin
+        err_code = SwPushMsgWhenDisallowed;
+      end
+
       default: begin
         err_code = NoError;
       end
diff --git a/hw/ip/hmac/rtl/hmac_pkg.sv b/hw/ip/hmac/rtl/hmac_pkg.sv
index 32dd72351ddb9..c93eae2a8abe0 100644
--- a/hw/ip/hmac/rtl/hmac_pkg.sv
+++ b/hw/ip/hmac/rtl/hmac_pkg.sv
@@ -96,7 +96,8 @@ package hmac_pkg;
     SwPushMsgWhenShaDisabled   = 32'h 0000_0001,
     SwHashStartWhenShaDisabled = 32'h 0000_0002,
     SwUpdateSecretKeyInProcess = 32'h 0000_0003,
-    SwHashStartWhenActive      = 32'h 0000_0004
+    SwHashStartWhenActive      = 32'h 0000_0004,
+    SwPushMsgWhenDisallowed    = 32'h 0000_0005
   } err_code_e;

 endpackage : hmac_pkg

resolved_issues.body:
I simulated I2C IP with EEPROM model.
Usually, an I2C host holds SCL to low after a target asserts ACK.
![fnxAG](https://user-images.githubusercontent.com/56853860/75740193-6283f680-5d4a-11ea-9c52-4acecc1ff966.png)

At the simulation, after the target transmits ack signal, I2C changes its state from _PopFmtFifo_ to _Idle_.
You can see "SCL" pulse at this screenshot.
I guess FSM should be changed a little bit to handle the _PopFmtFifo case_ differently from the _stop_ case or the _idle case.

![i2c_glitches](https://user-images.githubusercontent.com/56853860/75739693-f6ed5980-5d48-11ea-8627-e1e0800c3ebb.png)
![I2C_Glithces_2](https://user-images.githubusercontent.com/56853860/75740031-f0131680-5d49-11ea-8752-8bbacf73984c.png)


Test Sequence

		tl_driver.write(i2c_reg_pkg::I2C_TIMING0_OFFSET, {tlow, thigh});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING1_OFFSET, {t_f, t_r});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING2_OFFSET, {thd_sta, tsu_sta});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING3_OFFSET, {thd_dat, tsu_dat});
		tl_driver.write(i2c_reg_pkg::I2C_TIMING4_OFFSET, {t_buf, tsu_sto});
		tl_driver.write(i2c_reg_pkg::I2C_FIFO_CTRL_OFFSET, 32'h00000003);	// FIFO RESET
		tl_driver.write(i2c_reg_pkg::I2C_CTRL_OFFSET, 32'h00000001);		// Enable I2C Host

		@ (posedge clk_i);

		// EEPROM START (DEV : 0xA0, WR)
		start = 1'b1;
		fbyte = 8'ha0;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

		// EEPROM ADDR_MSB = 0x0
		start = 1'b0;
		fbyte = 8'h00;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

		// EEPROM ADDR_LSB = 0x0
		start = 1'b0;
		fbyte = 8'h00;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

                // EEPROM Write Data 0x0 ~ 0x9
		repeat(10) begin
			tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});
			fbyte = fbyte + 1;
		end

                // EEPROM Write Data 0xA and Stop
		stop = 1'b1;
		tl_driver.write(i2c_reg_pkg::I2C_FDATA_OFFSET, {nakok, rcont, read, stop, start, fbyte});

