#!/bin/bash
set +e

cd /home/opentitan || exit 1

TB_DIR=/home/opentitan/.tb_prim_esc_sender
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import prim_pkg::*;
  import alert_pkg::*;

  logic clk_i;
  logic rst_ni;

  logic en_i;
  logic clr_i;
  logic accum_trig_i;
  logic timeout_en_i;
  logic [EscCntDw-1:0] timeout_cyc_i;
  logic [N_ESC_SEV-1:0] esc_timer_en_i;
  logic [N_ESC_SEV-1:0][PHASE_DW-1:0] esc_map_i;
  logic [N_PHASES-1:0][EscCntDw-1:0] phase_cyc_i;
  logic esc_trig_o;
  logic [EscCntDw-1:0] esc_cnt_o;
  logic [N_ESC_SEV-1:0] esc_sig_en_o;
  cstate_e esc_state_o;

  logic ping_en_i;
  logic ping_ok_o;
  logic integ_fail_o;
  esc_rx_t esc_rx_i;
  esc_tx_t esc_tx_o;

  bit case_active;
  bit saw_integ_fail;
  bit saw_esc_high;
  bit saw_resp_high;

  alert_handler_esc_timer i_esc_timer (
    .clk_i,
    .rst_ni,
    .en_i,
    .clr_i,
    .accum_trig_i,
    .timeout_en_i,
    .timeout_cyc_i,
    .esc_en_i(esc_timer_en_i),
    .esc_map_i,
    .phase_cyc_i,
    .esc_trig_o,
    .esc_cnt_o,
    .esc_sig_en_o,
    .esc_state_o
  );

  prim_esc_sender i_sender (
    .clk_i,
    .rst_ni,
    .ping_en_i,
    .ping_ok_o,
    .integ_fail_o,
    .esc_en_i(esc_sig_en_o[0]),
    .esc_rx_i,
    .esc_tx_o
  );

  always #5 clk_i = ~clk_i;

  assert property (@(posedge clk_i) disable iff (!rst_ni)
      i_sender.state_q == i_sender.CheckEscRespLo && esc_tx_o.esc_p && !integ_fail_o |=>
      i_sender.state_q == i_sender.CheckEscRespHi)
  else $fatal(1, "TB_ASSERT state_lo_to_hi violated");

  assert property (@(posedge clk_i) disable iff (!rst_ni)
      i_sender.state_q == i_sender.CheckEscRespHi && esc_tx_o.esc_p && !integ_fail_o |=>
      i_sender.state_q == i_sender.CheckEscRespLo)
  else $fatal(1, "TB_ASSERT state_hi_to_lo violated");

  assert property (@(posedge clk_i) disable iff (!rst_ni)
      i_sender.state_q == i_sender.CheckEscRespHi |-> $past(esc_tx_o.esc_p))
  else $fatal(1, "TB_ASSERT hi_state_backcheck violated");

  assert property (@(posedge clk_i) disable iff (!rst_ni)
      i_sender.state_q == i_sender.CheckEscRespLo |-> $past(esc_tx_o.esc_p))
  else $fatal(1, "TB_ASSERT lo_state_backcheck violated");

  always @(posedge clk_i) begin
    if (!rst_ni) begin
      saw_integ_fail <= 1'b0;
      saw_esc_high <= 1'b0;
      saw_resp_high <= 1'b0;
    end else if (case_active) begin
      $display("TB_TRACE t=%0t phase0=%0d esc_sig_en=%0b esc_p=%0b resp_p=%0b state_q=%0d esc_state=%0d integ_fail=%0b",
               $time, phase_cyc_i[0], esc_sig_en_o[0], esc_tx_o.esc_p, esc_rx_i.resp_p,
               i_sender.state_q, esc_state_o, integ_fail_o);
      if (integ_fail_o) saw_integ_fail <= 1'b1;
      if (esc_tx_o.esc_p) saw_esc_high <= 1'b1;
      if (esc_rx_i.resp_p) saw_resp_high <= 1'b1;
    end
  end

  task automatic reset_dut();
    begin
      rst_ni = 1'b0;
      en_i = 1'b1;
      clr_i = 1'b0;
      accum_trig_i = 1'b0;
      timeout_en_i = 1'b0;
      timeout_cyc_i = '0;
      esc_timer_en_i = '0;
      esc_map_i = '0;
      phase_cyc_i = '0;
      ping_en_i = 1'b0;
      esc_rx_i.resp_p = 1'b0;
      esc_rx_i.resp_n = 1'b1;
      case_active = 1'b0;
      repeat (3) @(posedge clk_i);
      rst_ni = 1'b1;
      repeat (2) @(posedge clk_i);
    end
  endtask

  task automatic configure_timer(input int phase0_cycles);
    begin
      esc_timer_en_i = '0;
      esc_timer_en_i[0] = 1'b1;
      esc_map_i = '0;
      esc_map_i[0] = PHASE_DW'(0);
      phase_cyc_i = '0;
      phase_cyc_i[0] = EscCntDw'(phase0_cycles);
      phase_cyc_i[1] = EscCntDw'(0);
      phase_cyc_i[2] = EscCntDw'(0);
      phase_cyc_i[3] = EscCntDw'(0);
    end
  endtask

  task automatic trigger_escalation();
    begin
      accum_trig_i = 1'b1;
      @(posedge clk_i);
      accum_trig_i = 1'b0;
    end
  endtask

  task automatic emulate_dv_resp_driver();
    begin
      wait (esc_tx_o.esc_p === 1'b1);
      @(posedge clk_i);
      while (esc_tx_o.esc_p === 1'b1) begin
        esc_rx_i.resp_p <= 1'b1;
        esc_rx_i.resp_n <= 1'b0;
        @(posedge clk_i);
        esc_rx_i.resp_p <= 1'b0;
        esc_rx_i.resp_n <= 1'b1;
        @(posedge clk_i);
      end
    end
  endtask

  task automatic run_case(
    input string name,
    input int phase0_cycles
  );
    begin
      saw_integ_fail = 1'b0;
      saw_esc_high = 1'b0;
      saw_resp_high = 1'b0;
      case_active = 1'b1;

      configure_timer(phase0_cycles);
      $display("TB_CASE_BEGIN name=%s phase0_cycles=%0d", name, phase0_cycles);

      fork
        emulate_dv_resp_driver();
      join_none

      trigger_escalation();
      wait (esc_state_o == Terminal);
      repeat (6) @(posedge clk_i);
      disable fork;
      case_active = 1'b0;

      if (!saw_esc_high) begin
        $fatal(1, "TB_CHECK %s: sender never raised esc_tx_o.esc_p", name);
      end

      if (!saw_resp_high) begin
        $fatal(1, "TB_CHECK %s: response driver never raised resp_p", name);
      end

      if (saw_integ_fail) begin
        $fatal(1, "TB_CHECK %s: observed unexpected integ_fail_o pulse", name);
      end

      $display("TB_CASE_END name=%s saw_integ_fail=%0d", name, saw_integ_fail);
    end
  endtask

  initial begin
    clk_i = 1'b0;

    reset_dut();
    run_case("even_phase_cycle", 4);

    reset_dut();
    run_case("odd_phase_cycle", 3);

    $display("TB_DONE PASS");
    $finish;
  end
endmodule
EOF

