#!/bin/bash
cd /home/opentitan
set +e
set -o pipefail

TEST_NAME="debug_rom_exception_restore"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

report_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  timeunit 1ns;
  timeprecision 1ps;

  localparam int unsigned REG_S0         = 8;
  localparam int unsigned REG_A0         = 10;
  localparam int unsigned CSR_DSCRATCH0  = 12'h7b2;
  localparam int unsigned CSR_DSCRATCH1  = 12'h7b3;
  localparam int unsigned CSR_MHARTID    = 12'hf14;
  localparam logic [31:0] EXPECTED_S0    = 32'h0000ffff;
  localparam logic [31:0] EXPECTED_A0    = 32'h12345678;
  localparam logic [31:0] WORKING_A0     = 32'hdeadc0de;
  localparam logic [31:0] CORRUPTED_S0   = 32'h00000000;
  localparam int unsigned FLAG_ADDR      = 32'h00000400;

  logic clk = 1'b0;
  logic req = 1'b0;
  logic [63:0] addr = '0;
  logic [63:0] rdata;

  logic [31:0] regs [0:31];
  logic [31:0] csr_dscratch0;
  logic [31:0] csr_dscratch1;
  logic [31:0] csr_mhartid;
  byte unsigned mem_bytes [int unsigned];
  logic [31:0] pc;
  bit reentered;
  bit restore_complete;
  logic [31:0] last_instr;
  int step_count;

  debug_rom dut (
    .clk_i   (clk),
    .req_i   (req),
    .addr_i  (addr),
    .rdata_o (rdata)
  );

  always #5 clk = ~clk;

  function automatic logic [31:0] read_reg(input int unsigned idx);
    if (idx == 0) return 32'h0;
    return regs[idx];
  endfunction

  task automatic write_reg(input int unsigned idx, input logic [31:0] value);
    if (idx != 0) regs[idx] = value;
  endtask

  function automatic logic [31:0] read_csr(input logic [11:0] csr);
    case (csr)
      CSR_DSCRATCH0: return csr_dscratch0;
      CSR_DSCRATCH1: return csr_dscratch1;
      CSR_MHARTID:   return csr_mhartid;
      default:       return 32'h0;
    endcase
  endfunction

  task automatic write_csr(input logic [11:0] csr, input logic [31:0] value);
    case (csr)
      CSR_DSCRATCH0: csr_dscratch0 = value;
      CSR_DSCRATCH1: csr_dscratch1 = value;
      default: ;
    endcase
  endtask

  function automatic logic [7:0] read_byte(input int unsigned byte_addr);
    if (mem_bytes.exists(byte_addr)) return mem_bytes[byte_addr];
    return 8'h00;
  endfunction

  task automatic write_word(input int unsigned byte_addr, input logic [31:0] value);
    mem_bytes[byte_addr + 0] = value[7:0];
    mem_bytes[byte_addr + 1] = value[15:8];
    mem_bytes[byte_addr + 2] = value[23:16];
    mem_bytes[byte_addr + 3] = value[31:24];
  endtask

  task automatic fail_test(input string msg);
    $display("%s", msg);
    $display("TB_STATUS: FAIL");
    $fatal(1, "TB failure");
  endtask

  task automatic fetch_instr(input logic [31:0] fetch_pc, output logic [31:0] instr);
    @(negedge clk);
    addr = {32'h0, fetch_pc & 32'hfffffff8};
    req  = 1'b1;
    @(posedge clk);
    #1;
    @(negedge clk);
    req = 1'b0;
    @(posedge clk);
    #1;
    instr = fetch_pc[2] ? rdata[63:32] : rdata[31:0];
  endtask

  task automatic execute_instr(input logic [31:0] instr);
    int unsigned opcode;
    int unsigned rd;
    int unsigned rs1;
    int unsigned rs2;
    int unsigned funct3;
    int unsigned funct7;
    logic [11:0] csr;
    int signed imm_i;
    int signed imm_s;
    int signed imm_b;
    int signed imm_j;
    logic [31:0] next_pc;

    opcode = instr[6:0];
    rd     = instr[11:7];
    funct3 = instr[14:12];
    rs1    = instr[19:15];
    rs2    = instr[24:20];
    funct7 = instr[31:25];
    csr    = instr[31:20];

    imm_i = $signed({{20{instr[31]}}, instr[31:20]});
    imm_s = $signed({{20{instr[31]}}, instr[31:25], instr[11:7]});
    imm_b = $signed({{19{instr[31]}}, instr[31], instr[7], instr[30:25], instr[11:8], 1'b0});
    imm_j = $signed({{11{instr[31]}}, instr[31], instr[19:12], instr[20], instr[30:21], 1'b0});
    next_pc = pc + 32'd4;

    case (opcode)
      7'b1101111: begin
        write_reg(rd, pc + 32'd4);
        pc = pc + imm_j;
      end
      7'b0010111: begin
        write_reg(rd, pc + {instr[31:12], 12'h000});
        pc = next_pc;
      end
      7'b0010011: begin
        unique case (funct3)
          3'b000: write_reg(rd, read_reg(rs1) + imm_i);
          3'b001: write_reg(rd, read_reg(rs1) << instr[24:20]);
          3'b101: write_reg(rd, read_reg(rs1) >> instr[24:20]);
          3'b111: write_reg(rd, read_reg(rs1) & imm_i[31:0]);
          default: begin
            $display("Unsupported OP-IMM instruction: 0x%08x", instr);
            fail_test("TB encountered unsupported OP-IMM instruction");
          end
        endcase
        pc = next_pc;
      end
      7'b0110011: begin
        if (funct3 == 3'b000 && funct7 == 7'b0000000) begin
          write_reg(rd, read_reg(rs1) + read_reg(rs2));
          pc = next_pc;
        end else begin
          $display("Unsupported OP instruction: 0x%08x", instr);
          fail_test("TB encountered unsupported OP instruction");
        end
      end
      7'b0000011: begin
        if (funct3 == 3'b100) begin
          write_reg(rd, {24'h0, read_byte(read_reg(rs1) + imm_i)});
          pc = next_pc;
        end else begin
          $display("Unsupported LOAD instruction: 0x%08x", instr);
          fail_test("TB encountered unsupported LOAD instruction");
        end
      end
      7'b0100011: begin
        if (funct3 == 3'b010) begin
          write_word(read_reg(rs1) + imm_s, read_reg(rs2));
          pc = next_pc;
        end else begin
          $display("Unsupported STORE instruction: 0x%08x", instr);
          fail_test("TB encountered unsupported STORE instruction");
        end
      end
      7'b1100011: begin
        if (funct3 == 3'b001) begin
          if (read_reg(rs1) != read_reg(rs2)) pc = pc + imm_b;
          else pc = next_pc;
        end else begin
          $display("Unsupported BRANCH instruction: 0x%08x", instr);
          fail_test("TB encountered unsupported BRANCH instruction");
        end
      end
      7'b1110011: begin
        if (instr == 32'h00100073) begin
          if (!reentered) begin
            reentered = 1'b1;
            pc = 32'h0;
          end else begin
            $display("Unexpected second ebreak at pc=0x%08x", pc);
            fail_test("TB saw an unexpected second ebreak");
          end
        end else if (funct3 == 3'b001) begin
          write_csr(csr, read_reg(rs1));
          pc = next_pc;
        end else if (funct3 == 3'b010) begin
          write_reg(rd, read_csr(csr));
          pc = next_pc;
          if (reentered && rd == REG_A0 && csr == CSR_DSCRATCH1) begin
            restore_complete = 1'b1;
          end
        end else begin
          $display("Unsupported SYSTEM instruction: 0x%08x", instr);
          fail_test("TB encountered unsupported SYSTEM instruction");
        end
      end
      7'b0001111: begin
        pc = next_pc;
      end
      default: begin
        $display("Unsupported opcode 0x%02x at pc=0x%08x instr=0x%08x", opcode, pc, instr);
        fail_test("TB encountered unsupported opcode");
      end
    endcase
  endtask

  initial begin
    foreach (regs[i]) regs[i] = '0;

    csr_dscratch0 = EXPECTED_S0;
    csr_dscratch1 = EXPECTED_A0;
    csr_mhartid   = 32'h0;

    regs[REG_S0] = CORRUPTED_S0;
    regs[REG_A0] = WORKING_A0;

    mem_bytes[FLAG_ADDR] = 8'h01;

    pc = 32'h00000008;
    reentered = 1'b0;
    restore_complete = 1'b0;
    step_count = 0;

    repeat (2) @(posedge clk);

    while (!restore_complete) begin
      if (step_count > 64) begin
        $display("Execution did not reach restore path, last pc=0x%08x", pc);
        fail_test("TB did not reach the restore path");
      end
      fetch_instr(pc, last_instr);
      execute_instr(last_instr);
      step_count++;
    end

    if (regs[REG_S0] !== EXPECTED_S0) begin
      $display("s0 restore mismatch: got=0x%08x expected=0x%08x", regs[REG_S0], EXPECTED_S0);
      fail_test("TB observed an s0 restore mismatch");
    end

    if (regs[REG_A0] !== EXPECTED_A0) begin
      $display("a0 restore mismatch: got=0x%08x expected=0x%08x", regs[REG_A0], EXPECTED_A0);
      fail_test("TB observed an a0 restore mismatch");
    end

    $display("Restored s0=0x%08x a0=0x%08x after debug exception re-entry", regs[REG_S0], regs[REG_A0]);
    $display("TB_STATUS: PASS");
    $finish;
  end
endmodule
EOF

timeout 1800 vcs -full64 -sverilog -timescale=1ns/1ps \
  -l "$TB_DIR/compile.log" \
  -o "$TB_DIR/simv" \
  "$TB_DIR/tb.sv" \
  hw/vendor/pulp_riscv_dbg/debug_rom/debug_rom.sv
compile_rc=$?
if [ $compile_rc -ne 0 ]; then
  report_result "FAIL"
  exit $compile_rc
fi

timeout 1800 "$TB_DIR/simv" | tee "$TB_DIR/run.log"
run_rc=${PIPESTATUS[0]}
tb_status="$(awk '/TB_STATUS:/ {status=$2} END {print status}' "$TB_DIR/run.log")"

if [ $run_rc -eq 0 ] && [ "$tb_status" = "PASS" ]; then
  report_result "PASS"
  exit 0
fi

report_result "FAIL"
if [ $run_rc -eq 124 ]; then
  exit 124
fi
if [ "$tb_status" = "FAIL" ]; then
  exit 1
fi
exit $run_rc

