tb_script:
#!/bin/bash
cd /home/opentitan
set +e

export PATH=/tools/riscv/bin:/tools/verible/bin:$PATH

VSEQ_PATH="hw/ip/aes/dv/env/seq_lib/aes_busy_ctrl_ignore_vseq.sv"
LIST_PATH="hw/ip/aes/dv/env/seq_lib/aes_vseq_list.sv"
LOG_DIR="/home/opentitan/.tb_aes_busy_ctrl_ignore"
RUN_LOG="${LOG_DIR}/make.log"

mkdir -p "${LOG_DIR}"

emit_result() {
  local status="$1"
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: aes_busy_ctrl_ignore_test ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
}

cat >"${VSEQ_PATH}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class aes_busy_ctrl_ignore_vseq extends aes_base_vseq;
  `uvm_object_utils(aes_busy_ctrl_ignore_vseq)

  `uvm_object_new

  logic [127:0] plain_text   = 128'hDEADBEEFEEDDBBAABAADBEEFDEAFBEAD;
  logic [255:0] init_key     = 256'h0000111122223333444455556666777788889999AAAABBBBCCCCDDDDEEEEFFFF;
  logic [127:0] cypher_text, decrypted_text;
  bit [31:0] status;
  bit saw_busy;

  task body();
    `uvm_info(`gfn, "STARTING AES BUSY CTRL IGNORE SEQUENCE", UVM_LOW)

    set_mode(ENCRYPT);
    ral.ctrl.key_len.set(3'b001);
    ral.ctrl.manual_start_trigger.set(1'b1);
    csr_update(.csr(ral.ctrl));

    write_key(init_key);
    add_data(plain_text);
    csr_wr(.csr(ral.trigger), .value(32'h1));

    saw_busy = 1'b0;
    for (int i = 0; i < 20; i++) begin
      csr_rd(.ptr(ral.status), .value(status));
      if (status[0] == 1'b0) begin
        saw_busy = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    if (!saw_busy) begin
      `uvm_fatal(`gfn, "AES never entered the busy state after trigger")
    end
    cfg.clk_rst_vif.wait_clks(2);

    `uvm_info(`gfn, "Writing CTRL while AES is busy", UVM_LOW)
    ral.ctrl.mode.set(DECRYPT);
    ral.ctrl.key_len.set(3'b100);
    csr_update(.csr(ral.ctrl));

    read_data(cypher_text);
    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));

    `uvm_info(`gfn, "Running a legal decrypt after the busy write", UVM_LOW)
    ral.ctrl.mode.set(DECRYPT);
    ral.ctrl.key_len.set(3'b001);
    ral.ctrl.manual_start_trigger.set(1'b1);
    csr_update(.csr(ral.ctrl));
    write_key(init_key);
    add_data(cypher_text);
    csr_wr(.csr(ral.trigger), .value(32'h1));
    csr_spinwait(.ptr(ral.status.idle), .exp_data(1'b1));
    csr_wr(.csr(ral.trigger), .value(32'h1));
    read_data(decrypted_text);

    if (decrypted_text != plain_text) begin
      `uvm_fatal(`gfn, $sformatf("Busy CTRL write affected AES result. decrypted=%032h expected=%032h cipher=%032h",
                                 decrypted_text, plain_text, cypher_text))
    end

    `uvm_info(`gfn, $sformatf("Busy CTRL write was ignored as expected. decrypted=%032h",
                              decrypted_text), UVM_LOW)
  endtask : body
endclass : aes_busy_ctrl_ignore_vseq
EOF

