#!/bin/bash
cd /home/opentitan || exit 1

set +e

TEST_NAME="tlul_adapter_sram_illegal_opcode"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/tb.sv" <<'EOF'
module tb;
  import tlul_pkg::*;

  logic clk_i;
  logic rst_ni;

  tl_h2d_t tl_i;
  tl_d2h_t tl_o;

  logic        req_o;
  logic        gnt_i;
  logic        we_o;
  logic [11:0] addr_o;
  logic [31:0] wdata_o;
  logic [31:0] wmask_o;
  logic [31:0] rdata_i;
  logic        rvalid_i;
  logic [1:0]  rerror_i;
  bit          saw_req_to_sram;
  bit          saw_error_rsp;

  tlul_adapter_sram #(
    .SramAw(12),
    .SramDw(32),
    .Outstanding(1),
    .ByteAccess(1'b1),
    .ErrOnWrite(1'b0)
  ) dut (
    .clk_i,
    .rst_ni,
    .tl_i,
    .tl_o,
    .req_o,
    .gnt_i,
    .we_o,
    .addr_o,
    .wdata_o,
    .wmask_o,
    .rdata_i,
    .rvalid_i,
    .rerror_i
  );

  initial begin
    clk_i = 1'b0;
    forever #5 clk_i = ~clk_i;
  end

  task automatic apply_reset;
    begin
      saw_req_to_sram = 1'b0;
      saw_error_rsp = 1'b0;
      tl_i = '0;
      gnt_i = 1'b1;
      rdata_i = '0;
      rvalid_i = 1'b0;
      rerror_i = '0;
      rst_ni = 1'b0;
      repeat (5) @(posedge clk_i);
      rst_ni = 1'b1;
      repeat (2) @(posedge clk_i);
    end
  endtask

  task automatic send_illegal_opcode;
    begin
      tl_i.a_valid   = 1'b1;
      tl_i.a_opcode  = tl_a_op_e'(3'h7);
      tl_i.a_param   = '0;
      tl_i.a_size    = 2'h2;
      tl_i.a_source  = 8'h3c;
      tl_i.a_address = 32'h0000_0010;
      tl_i.a_mask    = 4'hf;
      tl_i.a_data    = 32'hfeed_c0de;
      tl_i.a_user    = '0;
      tl_i.d_ready   = 1'b1;

      do begin
        @(posedge clk_i);
        if (req_o) begin
          saw_req_to_sram = 1'b1;
        end
      end while (!tl_o.a_ready);

      tl_i.a_valid   = 1'b0;
      tl_i.a_opcode  = Get;
      tl_i.a_param   = '0;
      tl_i.a_size    = '0;
      tl_i.a_source  = '0;
      tl_i.a_address = '0;
      tl_i.a_mask    = '0;
      tl_i.a_data    = '0;
      tl_i.a_user    = '0;
    end
  endtask

  initial begin
    apply_reset();
    send_illegal_opcode();

    repeat (10) begin
      @(posedge clk_i);
      if (req_o) begin
        saw_req_to_sram = 1'b1;
      end
      if (tl_o.d_valid && tl_i.d_ready && tl_o.d_error &&
          (tl_o.d_opcode == AccessAck) &&
          (tl_o.d_source == 8'h3c)) begin
        saw_error_rsp = 1'b1;
      end
    end

    if (saw_req_to_sram) begin
      $fatal(1, "RUNTIME_ERROR: illegal opcode request was forwarded to SRAM");
    end

    if (!saw_error_rsp) begin
      $fatal(1, "RUNTIME_ERROR: missing AccessAck error response for illegal opcode");
    end

    $display("RUNTIME_PASS: illegal opcode was handled internally");
    $finish(0);
  end
endmodule
EOF

cat > "${TB_DIR}/files.f" <<'EOF'
hw/top_earlgrey/rtl/top_pkg.sv
hw/ip/prim/rtl/prim_assert.sv
hw/ip/prim/rtl/prim_fifo_sync.sv
hw/ip/tlul/rtl/tlul_pkg.sv
hw/ip/tlul/rtl/tlul_err.sv
hw/ip/tlul/rtl/tlul_adapter_sram.sv
/home/opentitan/.tb_tlul_adapter_sram_illegal_opcode/tb.sv
EOF

vcs -full64 -sverilog -timescale=1ns/1ps -assert svaext \
  -f "${TB_DIR}/files.f" \
  -l "${COMPILE_LOG}" \
  -o "${TB_DIR}/simv"
compile_rc=$?

if [ "${compile_rc}" -ne 0 ]; then
  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit "${compile_rc}"
fi

"${TB_DIR}/simv" -l "${RUN_LOG}"
sim_rc=$?

if [ "${sim_rc}" -eq 0 ] && grep -q '^RUNTIME_PASS:' "${RUN_LOG}"; then
  run_rc=0
else
  run_rc=1
fi

echo "HWE_BENCH_RESULTS_START"
if [ "${run_rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${run_rc}"

