`timescale 1ns/1ps

module tb;
  import top_pkg::*;
  import tlul_pkg::*;

  logic clk;
  logic rst_ni;
  tl_h2d_t tl_i;
  tl_d2h_t tl_o;
  logic re_o;
  logic we_o;
  logic [7:0] addr_o;
  logic [31:0] wdata_o;
  logic [3:0] be_o;
  logic [31:0] rdata_i;
  logic error_i;

