    .be_o    (be_o),
    .rdata_i (rdata_i),
    .error_i (error_i)
  );

  always #5 clk = ~clk;

  task automatic check(input bit cond, input string msg);
    if (!cond) begin
      $display("SIM_FAIL %s", msg);
      $fatal(1, "%s", msg);
    end
  endtask

  initial begin
    int wait_cycles;
    bit saw_response;

    clk = 0;
    rst_ni = 0;
    tl_i = '0;
    rdata_i = 32'h1234_5678;
    error_i = 1'b0;

    repeat (3) @(posedge clk);
    rst_ni = 1;
    @(posedge clk);

    tl_i.a_valid = 1'b1;
    tl_i.d_ready = 1'b1;
