if grep -q "TB_FAIL" "$RUN_LOG"; then
  emit_result "FAIL"
  exit 1
fi

if [ "$run_rc" -eq 0 ]; then
  emit_result "PASS"
  exit 0
fi

emit_result "FAIL"
exit 1

