    echo "ERROR: tb_script_fixed.sh exited during step: ${CURRENT_STEP} (status=${rc})"
    if [[ -f "${WORK_DIR}/dvsim.log" ]]; then
      echo "ERROR: tail of ${WORK_DIR}/dvsim.log"
      tail -n 50 "${WORK_DIR}/dvsim.log"
    fi
    emit_result "${rc}"
  fi
}

trap 'on_exit $?' EXIT

cd /home/opentitan

mkdir -p "${WORK_DIR}"
rm -f "${WORK_DIR}/dvsim.log"

if [[ -f /etc/opentitan_tools_path.sh ]]; then
  CURRENT_STEP="sourcing /etc/opentitan_tools_path.sh"
  set +e
  # shellcheck source=/etc/opentitan_tools_path.sh
  source /etc/opentitan_tools_path.sh
  source_rc=$?
  set -e
  if [[ "${source_rc}" -ne 0 ]]; then
    echo "WARN: /etc/opentitan_tools_path.sh returned ${source_rc}; continuing with current environment"
  fi
fi

CURRENT_STEP="writing entropy_src_repcnt_watermark_vseq.sv"
cat > hw/ip/entropy_src/dv/env/seq_lib/entropy_src_repcnt_watermark_vseq.sv <<'SVEOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class entropy_src_repcnt_watermark_vseq extends entropy_src_base_vseq;
  `uvm_object_utils(entropy_src_repcnt_watermark_vseq)

  localparam int unsigned RepcntThreshold = 3;
  localparam int unsigned WindowSize = 64;
  localparam int unsigned RepeatCount = 6;
  localparam bit [entropy_src_pkg::RNG_BUS_WIDTH-1:0] RepeatSymbol = '1;

  `uvm_object_new

  virtual task entropy_src_init();
    cfg.otp_en_es_fw_read       = prim_mubi_pkg::MuBi8True;
    cfg.otp_en_es_fw_over       = prim_mubi_pkg::MuBi8True;
    cfg.regwen                  = 1'b1;
    cfg.enable                  = prim_mubi_pkg::MuBi4True;
    cfg.route_software          = prim_mubi_pkg::MuBi4True;
    cfg.type_bypass             = prim_mubi_pkg::MuBi4True;
    cfg.boot_bypass_disable     = prim_mubi_pkg::MuBi4False;
    cfg.entropy_data_reg_enable = prim_mubi_pkg::MuBi4True;
    cfg.rng_bit_enable          = prim_mubi_pkg::MuBi4False;
    cfg.rng_bit_sel             = '0;

    cfg.otp_en_es_fw_read_vif.drive(.val(cfg.otp_en_es_fw_read));
    cfg.otp_en_es_fw_over_vif.drive(.val(cfg.otp_en_es_fw_over));

    csr_wr(.ptr(ral.regwen), .value(cfg.regwen));

    ral.health_test_windows.fips_window.set(WindowSize);
    ral.health_test_windows.bypass_window.set(WindowSize);
    csr_update(.csr(ral.health_test_windows));

    ral.repcnt_thresholds.fips_thresh.set(RepcntThreshold);
    ral.repcnt_thresholds.bypass_thresh.set(RepcntThreshold);
    csr_update(.csr(ral.repcnt_thresholds));

    ral.repcnts_thresholds.fips_thresh.set(RepcntThreshold);
    ral.repcnts_thresholds.bypass_thresh.set(RepcntThreshold);
    csr_update(.csr(ral.repcnts_thresholds));

    ral.entropy_control.es_type.set(cfg.type_bypass);
    ral.entropy_control.es_route.set(cfg.route_software);
    csr_update(.csr(ral.entropy_control));

    ral.conf.enable.set(cfg.enable);
    ral.conf.entropy_data_reg_enable.set(cfg.entropy_data_reg_enable);
    ral.conf.boot_bypass_disable.set(cfg.boot_bypass_disable);
    ral.conf.rng_bit_enable.set(cfg.rng_bit_enable);
    ral.conf.rng_bit_sel.set(cfg.rng_bit_sel);
    csr_update(.csr(ral.conf));
  endtask

  task body();
    push_pull_host_seq#(entropy_src_pkg::RNG_BUS_WIDTH) rng_seq;
    bit [TL_DW-1:0] reg_data;
    int unsigned repcnt_watermark;
    int unsigned repcnts_watermark;

    cfg.m_rng_agent_cfg.zero_delays = 1'b1;
    cfg.m_rng_agent_cfg.clear_h_user_data();
    repeat (RepeatCount) cfg.m_rng_agent_cfg.add_h_user_data(RepeatSymbol);

    rng_seq = push_pull_host_seq#(entropy_src_pkg::RNG_BUS_WIDTH)::type_id::create("rng_seq");
    rng_seq.num_trans = RepeatCount;

    cfg.clk_rst_vif.wait_clks(5);
    rng_seq.start(p_sequencer.rng_sequencer_h);
    cfg.clk_rst_vif.wait_clks(20);

    csr_rd(.ptr(ral.repcnt_hi_watermarks), .value(reg_data));
    repcnt_watermark = reg_data[31:16];
    if (repcnt_watermark != RepeatCount) begin
      `uvm_fatal(`gfn, $sformatf("Expected repcnt bypass watermark %0d, got %0d (raw=0x%08x)",
                                 RepeatCount, repcnt_watermark, reg_data))
    end

    csr_rd(.ptr(ral.repcnts_hi_watermarks), .value(reg_data));
    repcnts_watermark = reg_data[31:16];
    if (repcnts_watermark != RepeatCount) begin
      `uvm_fatal(`gfn, $sformatf("Expected repcnts bypass watermark %0d, got %0d (raw=0x%08x)",
                                 RepeatCount, repcnts_watermark, reg_data))
    end
  endtask
endclass
SVEOF

