"""
if "name: entropy_src_repcnt_watermark" not in text:
    if anchor not in text:
        raise RuntimeError("sim_cfg anchor not found")
    text = text.replace(anchor, entry + anchor)
    sim_cfg.write_text(text, encoding="utf-8")
PY

