tb_script:
#!/bin/bash
set -uo pipefail

cd /home/opentitan

TEST_NAME="rv_dm_sba_spi_hosts"
TB_DIR="/home/opentitan/.tb_rv_dm_spi_host_sba"
BUILD_ROOT="$TB_DIR/build"
FUSESOC_LOG="$TB_DIR/fusesoc.log"
RUN_LOG="$BUILD_ROOT/sim-vcs/vcs.log"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/rv_dm_spi_host_sba_tb.core" <<'EOF'
CAPI=2:
name: "lowrisc:dv:rv_dm_spi_host_sba_tb:0.1"
description: "Directed xbar_main SBA access test for spi_host0 and spi_host1"

filesets:
  files_dv:
    depend:
      - lowrisc:constants:top_pkg
      - lowrisc:top_earlgrey:xbar_main
      - lowrisc:tlul:trans_intg
    files:
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    default_tool: vcs
    filesets:
      - files_dv
    toplevel: rv_dm_spi_host_sba_tb
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module rv_dm_spi_host_sba_tb;
  import tlul_pkg::*;
  import tl_main_pkg::*;
  import prim_mubi_pkg::*;

  typedef enum int {
    SpiHost0Sel = 0,
    SpiHost1Sel = 1
  } device_sel_e;

  logic clk_main_i = 0;
  logic clk_fixed_i = 0;
  logic clk_spi_host0_i = 0;
  logic clk_spi_host1_i = 0;
  logic rst_n = 0;

  always #5 clk_main_i = ~clk_main_i;
  always #5 clk_fixed_i = ~clk_fixed_i;
  always #5 clk_spi_host0_i = ~clk_spi_host0_i;
  always #5 clk_spi_host1_i = ~clk_spi_host1_i;

  tl_h2d_t tl_rv_dm__sba_i;
  tl_d2h_t tl_rv_dm__sba_o;
  tl_h2d_t tl_spi_host0_o;
  tl_h2d_t tl_spi_host1_o;
  tl_d2h_t tl_spi_host0_i_raw;
  tl_d2h_t tl_spi_host1_i_raw;
  tl_d2h_t tl_spi_host0_i;
  tl_d2h_t tl_spi_host1_i;

  int spi_host0_req_count;
  int spi_host1_req_count;
  logic spi_host0_pending;
  logic spi_host1_pending;
  logic [top_pkg::TL_AIW-1:0] spi_host0_source;
  logic [top_pkg::TL_AIW-1:0] spi_host1_source;
  logic [top_pkg::TL_SZW-1:0] spi_host0_size;
  logic [top_pkg::TL_SZW-1:0] spi_host1_size;

  localparam logic [31:0] SpiHost0Data = 32'hA5A50001;
  localparam logic [31:0] SpiHost1Data = 32'hA5A50002;
  localparam int MaxAcceptCycles = 20;
  localparam int MaxResponseCycles = 80;

  tlul_rsp_intg_gen u_spi_host0_rsp_intg (
    .tl_i(tl_spi_host0_i_raw),
    .tl_o(tl_spi_host0_i)
  );

  tlul_rsp_intg_gen u_spi_host1_rsp_intg (
    .tl_i(tl_spi_host1_i_raw),
    .tl_o(tl_spi_host1_i)
  );

  xbar_main dut (
    .clk_main_i(clk_main_i),
    .clk_fixed_i(clk_fixed_i),
    .clk_spi_host0_i(clk_spi_host0_i),
    .clk_spi_host1_i(clk_spi_host1_i),
    .rst_main_ni(rst_n),
    .rst_fixed_ni(rst_n),
    .rst_spi_host0_ni(rst_n),
    .rst_spi_host1_ni(rst_n),
    .tl_rv_core_ibex__corei_i(TL_H2D_DEFAULT),
    .tl_rv_core_ibex__corei_o(),
    .tl_rv_core_ibex__cored_i(TL_H2D_DEFAULT),
    .tl_rv_core_ibex__cored_o(),
    .tl_rv_dm__sba_i(tl_rv_dm__sba_i),
    .tl_rv_dm__sba_o(tl_rv_dm__sba_o),
    .tl_rv_dm__regs_o(),
    .tl_rv_dm__regs_i(TL_D2H_DEFAULT),
    .tl_rv_dm__rom_o(),
    .tl_rv_dm__rom_i(TL_D2H_DEFAULT),
    .tl_rom_ctrl__rom_o(),
    .tl_rom_ctrl__rom_i(TL_D2H_DEFAULT),
    .tl_rom_ctrl__regs_o(),
    .tl_rom_ctrl__regs_i(TL_D2H_DEFAULT),
    .tl_peri_o(),
    .tl_peri_i(TL_D2H_DEFAULT),
    .tl_spi_host0_o(tl_spi_host0_o),
    .tl_spi_host0_i(tl_spi_host0_i),
    .tl_spi_host1_o(tl_spi_host1_o),
    .tl_spi_host1_i(tl_spi_host1_i),
    .tl_flash_ctrl__core_o(),
    .tl_flash_ctrl__core_i(TL_D2H_DEFAULT),
    .tl_flash_ctrl__prim_o(),
    .tl_flash_ctrl__prim_i(TL_D2H_DEFAULT),
    .tl_flash_ctrl__mem_o(),
    .tl_flash_ctrl__mem_i(TL_D2H_DEFAULT),
    .tl_hmac_o(),
    .tl_hmac_i(TL_D2H_DEFAULT),
    .tl_kmac_o(),
    .tl_kmac_i(TL_D2H_DEFAULT),
    .tl_aes_o(),
    .tl_aes_i(TL_D2H_DEFAULT),
    .tl_entropy_src_o(),
    .tl_entropy_src_i(TL_D2H_DEFAULT),
    .tl_csrng_o(),
    .tl_csrng_i(TL_D2H_DEFAULT),
    .tl_edn0_o(),
    .tl_edn0_i(TL_D2H_DEFAULT),
    .tl_edn1_o(),
    .tl_edn1_i(TL_D2H_DEFAULT),
    .tl_rv_plic_o(),
    .tl_rv_plic_i(TL_D2H_DEFAULT),
    .tl_otbn_o(),
    .tl_otbn_i(TL_D2H_DEFAULT),
    .tl_keymgr_o(),
    .tl_keymgr_i(TL_D2H_DEFAULT),
    .tl_rv_core_ibex__cfg_o(),
    .tl_rv_core_ibex__cfg_i(TL_D2H_DEFAULT),
    .tl_sram_ctrl_main__regs_o(),
    .tl_sram_ctrl_main__regs_i(TL_D2H_DEFAULT),
    .tl_sram_ctrl_main__ram_o(),
    .tl_sram_ctrl_main__ram_i(TL_D2H_DEFAULT),
    .scanmode_i(MuBi4False)
  );

  function automatic tl_h2d_t make_get(input logic [31:0] addr,
                                       input logic [top_pkg::TL_AIW-1:0] source);
    tl_h2d_t req;
    req = TL_H2D_DEFAULT;
    req.a_valid = 1'b1;
    req.a_opcode = Get;
    req.a_size = 2;
    req.a_source = source;
    req.a_address = addr;
    req.a_mask = '1;
    req.a_user.cmd_intg = tlul_pkg::get_cmd_intg(req);
    req.a_user.data_intg = tlul_pkg::get_data_intg(req.a_data);
    return req;
  endfunction

  task automatic expect_sba_read(input string name,
                                 input logic [31:0] addr,
                                 input logic [31:0] exp_data,
                                 input device_sel_e expected_device);
    tl_h2d_t req;
    int start_host0;
    int start_host1;
    bit accepted;
    bit responded;

    start_host0 = spi_host0_req_count;
    start_host1 = spi_host1_req_count;
    req = make_get(addr, '0);
    tl_rv_dm__sba_i = req;

    accepted = 0;
    for (int i = 0; i < MaxAcceptCycles; i++) begin
      @(posedge clk_main_i);
      if (tl_rv_dm__sba_i.a_valid && tl_rv_dm__sba_o.a_ready) begin
        accepted = 1;
        break;
      end
    end
    if (!accepted) begin
      $fatal(1, "%s request was not accepted", name);
    end

    tl_rv_dm__sba_i = TL_H2D_DEFAULT;

    responded = 0;
    for (int i = 0; i < MaxResponseCycles; i++) begin
      @(posedge clk_main_i);
      if (tl_rv_dm__sba_o.d_valid) begin
        responded = 1;
        if (tl_rv_dm__sba_o.d_error) begin
          $fatal(1, "%s returned d_error", name);
        end
        if (tl_rv_dm__sba_o.d_opcode !== AccessAckData) begin
          $fatal(1, "%s returned unexpected opcode %0d", name, tl_rv_dm__sba_o.d_opcode);
        end
        if (tl_rv_dm__sba_o.d_data !== exp_data) begin
          $fatal(1, "%s returned 0x%08h instead of 0x%08h", name,
                 tl_rv_dm__sba_o.d_data, exp_data);
        end
        break;
      end
    end
    if (!responded) begin
      $fatal(1, "%s timed out waiting for a response", name);
    end

    case (expected_device)
      SpiHost0Sel: begin
        if (spi_host0_req_count != start_host0 + 1) begin
          $fatal(1, "%s did not reach spi_host0", name);
        end
        if (spi_host1_req_count != start_host1) begin
          $fatal(1, "%s unexpectedly reached spi_host1", name);
        end
      end
      SpiHost1Sel: begin
        if (spi_host1_req_count != start_host1 + 1) begin
          $fatal(1, "%s did not reach spi_host1", name);
        end
        if (spi_host0_req_count != start_host0) begin
          $fatal(1, "%s unexpectedly reached spi_host0", name);
        end
      end
      default: begin
        $fatal(1, "%s used an invalid device selector", name);
      end
    endcase
  endtask

  always_ff @(posedge clk_spi_host0_i or negedge rst_n) begin
    if (!rst_n) begin
      tl_spi_host0_i_raw <= TL_D2H_DEFAULT;
      spi_host0_pending <= 1'b0;
      spi_host0_source <= '0;
      spi_host0_size <= '0;
      spi_host0_req_count <= 0;
    end else begin
      tl_spi_host0_i_raw <= TL_D2H_DEFAULT;
      tl_spi_host0_i_raw.a_ready <= !spi_host0_pending;
      if (spi_host0_pending) begin
        tl_spi_host0_i_raw.d_valid <= 1'b1;
        tl_spi_host0_i_raw.d_opcode <= AccessAckData;
        tl_spi_host0_i_raw.d_size <= spi_host0_size;
        tl_spi_host0_i_raw.d_source <= spi_host0_source;
        tl_spi_host0_i_raw.d_data <= SpiHost0Data;
        if (tl_spi_host0_o.d_ready) begin
          spi_host0_pending <= 1'b0;
        end
      end else if (tl_spi_host0_o.a_valid) begin
        spi_host0_req_count <= spi_host0_req_count + 1;
        spi_host0_source <= tl_spi_host0_o.a_source;
        spi_host0_size <= tl_spi_host0_o.a_size;
        spi_host0_pending <= 1'b1;
      end
    end
  end

  always_ff @(posedge clk_spi_host1_i or negedge rst_n) begin
    if (!rst_n) begin
      tl_spi_host1_i_raw <= TL_D2H_DEFAULT;
      spi_host1_pending <= 1'b0;
      spi_host1_source <= '0;
      spi_host1_size <= '0;
      spi_host1_req_count <= 0;
    end else begin
      tl_spi_host1_i_raw <= TL_D2H_DEFAULT;
      tl_spi_host1_i_raw.a_ready <= !spi_host1_pending;
      if (spi_host1_pending) begin
        tl_spi_host1_i_raw.d_valid <= 1'b1;
        tl_spi_host1_i_raw.d_opcode <= AccessAckData;
        tl_spi_host1_i_raw.d_size <= spi_host1_size;
        tl_spi_host1_i_raw.d_source <= spi_host1_source;
        tl_spi_host1_i_raw.d_data <= SpiHost1Data;
        if (tl_spi_host1_o.d_ready) begin
          spi_host1_pending <= 1'b0;
        end
      end else if (tl_spi_host1_o.a_valid) begin
        spi_host1_req_count <= spi_host1_req_count + 1;
        spi_host1_source <= tl_spi_host1_o.a_source;
        spi_host1_size <= tl_spi_host1_o.a_size;
        spi_host1_pending <= 1'b1;
      end
    end
  end

  initial begin
    tl_rv_dm__sba_i = TL_H2D_DEFAULT;
    repeat (5) @(posedge clk_main_i);
    rst_n = 1'b1;
    repeat (5) @(posedge clk_main_i);

    expect_sba_read("rv_dm_sba_spi_host0", tl_main_pkg::ADDR_SPACE_SPI_HOST0, SpiHost0Data,
                    SpiHost0Sel);
    expect_sba_read("rv_dm_sba_spi_host1", tl_main_pkg::ADDR_SPACE_SPI_HOST1, SpiHost1Data,
                    SpiHost1Sel);

    repeat (5) @(posedge clk_main_i);
    $display("TESTBENCH_PASS");
    $finish(0);
  end
endmodule
EOF

PATH="/opt/micromamba/envs/opentitan/bin:/tools/riscv/bin:/tools/verible/bin:${PATH}"
fusesoc --cores-root /home/opentitan --cores-root "$TB_DIR" \
  run --target=sim --tool=vcs --build-root "$BUILD_ROOT" \
  lowrisc:dv:rv_dm_spi_host_sba_tb >"$FUSESOC_LOG" 2>&1
build_rc=$?
pass_found=1

if [[ -f "$RUN_LOG" ]] && grep -q "TESTBENCH_PASS" "$RUN_LOG"; then
  pass_found=0
elif grep -q "TESTBENCH_PASS" "$FUSESOC_LOG"; then
  pass_found=0
fi

echo "HWE_BENCH_RESULTS_START"
if [[ $build_rc -eq 0 && $pass_found -eq 0 ]]; then
  echo "TEST: ${TEST_NAME} ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: ${TEST_NAME} ... FAIL"
echo "HWE_BENCH_RESULTS_END"

if [[ -f "$RUN_LOG" ]]; then
  tail -n 80 "$RUN_LOG"
else
  tail -n 80 "$FUSESOC_LOG"
fi
exit 1

resolved_issues.body:
The AES DIF is currently mixing up different fields of the AES main control register such as MODE, OPERATION and MANUAL_OPERATION. From the documentation, the meaning of these fields should be pretty clear:

![operation_mode](https://user-images.githubusercontent.com/20307557/151838737-47e895e1-0f07-411e-a554-86c3b5c30c77.png)
![manual_operation](https://user-images.githubusercontent.com/20307557/151838748-eab9236a-12a3-4567-9ce7-f7244c049099.png)

Instead the `configure` function in the AES DIF looks as follows:
```c
/**
 * Configures AES. Is used by every `dif_aes_start_<mode>` function.
 *
 * @param aes AES state data.
 * @param transaction Configuration data, common across all Cipher modes.
 * @param cipher_mode_val Cipher Mode register write value.
 * @return `dif_result_t`.
 */
static dif_result_t configure(const dif_aes_t *aes,
                              const dif_aes_transaction_t *transaction,
                              aes_mode_field_val_t cipher_mode_val) { // <--- the MODE is actually already part of the transaction.
  aes_key_field_val_t key_len_val = key_to_field(transaction->key_len);
  if (key_len_val == kAesKeyFieldValInvalid) {
    return kDifError;
  }

  uint32_t reg =
      bitfield_field32_write(0, AES_CTRL_SHADOWED_KEY_LEN_FIELD, key_len_val);

  reg = bitfield_field32_write(reg, AES_CTRL_SHADOWED_MODE_FIELD,
                               cipher_mode_val);

  if (transaction->mode == kDifAesModeDecrypt) {  // <-- comparing MODE with OPERATION values
    reg = bitfield_bit32_write(reg, AES_CTRL_SHADOWED_OPERATION_BIT, true);
  } else {
    reg = bitfield_bit32_write(reg, AES_CTRL_SHADOWED_OPERATION_BIT, false);
  }

  if (transaction->operation == kDifAesOperationManual) { // <-- comparing OPERATION with MANUAL_OPERATION values
    reg =
        bitfield_bit32_write(reg, AES_CTRL_SHADOWED_MANUAL_OPERATION_BIT, true);
  } else {
    reg = bitfield_bit32_write(reg, AES_CTRL_SHADOWED_MANUAL_OPERATION_BIT,
                               false);
  }

  if (transaction->masking == kDifAesMaskingForceZero) {
    reg =
        bitfield_bit32_write(reg, AES_CTRL_SHADOWED_FORCE_ZERO_MASKS_BIT, true);
  } else {
    reg = bitfield_bit32_write(reg, AES_CTRL_SHADOWED_FORCE_ZERO_MASKS_BIT,
                               false);
  }

  aes_shadowed_write(aes->base_addr, AES_CTRL_SHADOWED_REG_OFFSET, reg);

  return kDifOk;
}

```
The following things are wrong
- [x] The MODE field from the `transaction` isn't used at all. This means we actually can't configure modes other than ECB. What the unit tests do instead is to provide a separate MODE value with the `cipher_mode_val` argument. The unit tests should probably set up separate transactions instead of calling the configure with the same `transaction` argument but varying `cipher_mode_val`.
- [x] The transaction's MODE is compared against OPERATION values to decide what OPERATION to configure. See #10483
- [x] The transaction's OPERATION is compared with MANUAL_OPERATION values to decide what MANUAL_OPERATION to configure. See #10483
- [ ] I has been brought up by @timothytrippel https://github.com/lowRISC/opentitan/pull/10483#discussion_r796076893 that to simplify things we could replace `manual_operation_t` by a `dif_toggle_t`.

I will do a PR to fix 2 and 3 but someone from the software team should probably have a look at the unit tests (Point 1).

