extern dif_result_t dif_aes_start_cfb(
    const dif_aes_t *aes, const dif_aes_transaction_t *transaction,
    dif_aes_key_share_t key, dif_aes_iv_t iv) __attribute__((weak));

const test_config_t kTestConfig;

static uint32_t expected_operation_field(dif_aes_operation_t operation) {
  switch (operation) {
    case kDifAesOperationEncrypt:
      return 0x1;
    case kDifAesOperationDecrypt:
      return 0x2;
    default:
      return 0x0;
  }
}

static uint32_t expected_mode_field(dif_aes_mode_t mode) {
  switch (mode) {
    case kDifAesModeEcb:
      return 0x1;
    case kDifAesModeCbc:
      return 0x2;
    case kDifAesModeCfb:
      return 0x4;
    case kDifAesModeOfb:
      return 0x8;
    case kDifAesModeCtr:
      return 0x10;
    default:
      return 0x20;
  }
}

static uint32_t expected_key_len_field(dif_aes_key_length_t key_len) {
  switch (key_len) {
    case kDifAesKey128:
      return 0x1;
    case kDifAesKey192:
      return 0x2;
    case kDifAesKey256:
      return 0x4;
    default:
      return 0x0;
  }
}

static dif_result_t aes_start_compat(const dif_aes_t *aes,
                                     const dif_aes_transaction_t *transaction,
                                     dif_aes_key_share_t key,
                                     const dif_aes_iv_t *iv) {
  if (dif_aes_start != NULL) {
    return dif_aes_start(aes, transaction, key, iv);
  }

  switch (transaction->mode) {
    case kDifAesModeEcb:
      return dif_aes_start_ecb != NULL ? dif_aes_start_ecb(aes, transaction, key)
                                       : kDifError;
    case kDifAesModeCbc:
      return (dif_aes_start_cbc != NULL && iv != NULL)
                 ? dif_aes_start_cbc(aes, transaction, key, *iv)
                 : kDifBadArg;
    case kDifAesModeCtr:
      return (dif_aes_start_ctr != NULL && iv != NULL)
                 ? dif_aes_start_ctr(aes, transaction, key, *iv)
                 : kDifBadArg;
    case kDifAesModeOfb:
      return (dif_aes_start_ofb != NULL && iv != NULL)
                 ? dif_aes_start_ofb(aes, transaction, key, *iv)
                 : kDifBadArg;
    case kDifAesModeCfb:
      return (dif_aes_start_cfb != NULL && iv != NULL)
                 ? dif_aes_start_cfb(aes, transaction, key, *iv)
                 : kDifBadArg;
    default:
      return kDifBadArg;
  }
}

static void check_ctrl_matches_transaction(const dif_aes_t *aes,
                                           dif_aes_transaction_t transaction) {
  uint32_t ctrl =
      mmio_region_read32(aes->base_addr, AES_CTRL_SHADOWED_REG_OFFSET);
  uint32_t got_operation =
      bitfield_field32_read(ctrl, AES_CTRL_SHADOWED_OPERATION_FIELD);
  uint32_t got_mode = bitfield_field32_read(ctrl, AES_CTRL_SHADOWED_MODE_FIELD);
  uint32_t got_key_len =
      bitfield_field32_read(ctrl, AES_CTRL_SHADOWED_KEY_LEN_FIELD);

  uint32_t exp_operation = expected_operation_field(transaction.operation);
  uint32_t exp_mode = expected_mode_field(transaction.mode);
  uint32_t exp_key_len = expected_key_len_field(transaction.key_len);

  LOG_INFO("transaction op=%u mode=%u key_len=%u", transaction.operation,
           transaction.mode, transaction.key_len);
  LOG_INFO("expected ctrl op=%u mode=%u key_len=%u", exp_operation, exp_mode,
           exp_key_len);
  LOG_INFO("ctrl op=%u mode=%u key_len=%u", got_operation, got_mode,
           got_key_len);

  CHECK(got_operation == exp_operation, "operation field mismatch: exp=%u got=%u",
        exp_operation, got_operation);
  CHECK(got_mode == exp_mode, "mode field mismatch: exp=%u got=%u", exp_mode,
        got_mode);
  CHECK(got_key_len == exp_key_len, "key length field mismatch: exp=%u got=%u",
        exp_key_len, got_key_len);
}

static void check_matching_transaction_start(const dif_aes_t *aes) {
  dif_aes_key_share_t key = {
      .share0 = {0x03020100, 0x07060504, 0x0b0a0908, 0x0f0e0d0c,
                 0x13121110, 0x17161514, 0x1b1a1918, 0x1f1e1d1c},
      .share1 = {0},
  };
  dif_aes_iv_t iv = {.iv = {0x33221100, 0x77665544, 0xbbaa9988, 0xffeeddcc}};
  dif_aes_transaction_t transaction = {
      .operation = kDifAesOperationDecrypt,
      .mode = kDifAesModeCbc,
      .key_len = kDifAesKey256,
      .manual_operation = kDifAesManualOperationAuto,
      .masking = kDifAesMaskingForceZero,
  };

  CHECK_DIF_OK(dif_aes_reset(aes));
  CHECK_DIF_OK(aes_start_compat(aes, &transaction, key, &iv));
  check_ctrl_matches_transaction(aes, transaction);
  CHECK_DIF_OK(dif_aes_end(aes));
}

static void check_legacy_wrapper_rejects_mode_mismatch(const dif_aes_t *aes) {
  if (dif_aes_start_cbc == NULL) {
    LOG_INFO("legacy CBC wrapper unavailable; skipping mismatch check");
    return;
  }

  dif_aes_key_share_t key = {
      .share0 = {0x11111111, 0x22222222, 0x33333333, 0x44444444,
                 0x55555555, 0x66666666, 0x77777777, 0x88888888},
      .share1 = {0},
  };
  dif_aes_iv_t iv = {.iv = {0x01234567, 0x89abcdef, 0xfedcba98, 0x76543210}};
  dif_aes_transaction_t transaction = {
      .operation = kDifAesOperationEncrypt,
      .mode = kDifAesModeCtr,
      .key_len = kDifAesKey128,
      .manual_operation = kDifAesManualOperationAuto,
      .masking = kDifAesMaskingInternalPrng,
  };

  CHECK_DIF_OK(dif_aes_reset(aes));
  dif_result_t result = dif_aes_start_cbc(aes, &transaction, key, iv);
  LOG_INFO("legacy CBC wrapper mismatch result=%d for transaction.mode=%u",
           result, transaction.mode);
  CHECK(result != kDifOk,
        "legacy CBC wrapper accepted mismatched transaction.mode=%u",
        transaction.mode);
}

bool test_main(void) {
  entropy_testutils_boot_mode_init();

  dif_aes_t aes;
  CHECK_DIF_OK(
      dif_aes_init(mmio_region_from_addr(TOP_EARLGREY_AES_BASE_ADDR), &aes));

  check_matching_transaction_start(&aes);
  check_legacy_wrapper_rejects_mode_mismatch(&aes);

  CHECK_DIF_OK(dif_aes_reset(&aes));
  return true;
}
EOF

