tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="kmac_unmasked_entropy_refresh_shadow_reg"
TB_DIR="/home/opentitan/.tb_kmac_entropy_refresh_shadow"

mkdir -p "$TB_DIR"

python3 - <<'PY'
from pathlib import Path

vseq_body = """// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class kmac_entropy_refresh_shadow_vseq extends kmac_common_vseq;
  `uvm_object_utils(kmac_entropy_refresh_shadow_vseq)
  `uvm_object_new

  virtual function bit has_threshold_field(dv_base_reg csr);
    dv_base_reg_field fields[$];

    csr.get_dv_base_reg_fields(fields);
    foreach (fields[i]) begin
      if (fields[i].get_name() == "threshold") return 1'b1;
    end
    return 1'b0;
  endfunction

  virtual function dv_base_reg get_entropy_refresh_threshold_reg();
    dv_base_reg regs[$];

    ral.get_dv_base_regs(regs);
    foreach (regs[i]) begin
      if (uvm_re_match("entropy_refresh*", regs[i].get_name())) continue;
      if (has_threshold_field(regs[i])) return regs[i];
    end

    `uvm_fatal(`gfn, "Failed to locate the entropy refresh threshold CSR")
    return null;
  endfunction

  virtual task body();
    dv_base_reg       target_csr;
    dv_base_reg_field threshold_fld;
    uvm_reg_data_t    origin_val;
    uvm_reg_data_t    staged_val;
    uvm_reg_data_t    readback_val;
    uvm_reg_data_t    reg_mask;

    target_csr = get_entropy_refresh_threshold_reg();
    threshold_fld = target_csr.get_dv_base_reg_field_by_name("threshold");
    reg_mask = threshold_fld.get_field_mask();

    csr_rd(.ptr(target_csr), .value(origin_val));

    `DV_CHECK_STD_RANDOMIZE_WITH_FATAL(staged_val,
                                       (staged_val & reg_mask) != (origin_val & reg_mask);
                                       (staged_val & ~reg_mask) == 0;)

    shadow_reg_wr(.csr(target_csr), .wdata(staged_val), .en_shadow_wr(0));
    csr_utils_pkg::wait_no_outstanding_access();
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd(.ptr(target_csr), .value(readback_val));
    `DV_CHECK_EQ(readback_val & reg_mask, origin_val & reg_mask,
                 $sformatf("%0s committed after a single write", target_csr.get_name()))

    shadow_reg_wr(.csr(target_csr), .wdata(staged_val), .en_shadow_wr(1));
    csr_utils_pkg::wait_no_outstanding_access();
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd(.ptr(target_csr), .value(readback_val));
    `DV_CHECK_EQ(readback_val & reg_mask, staged_val & reg_mask,
                 $sformatf("%0s did not commit after two matching writes",
                           target_csr.get_name()))
  endtask

endclass
"""

vseq_list_path = Path("/home/opentitan/hw/ip/kmac/dv/env/seq_lib/kmac_vseq_list.sv")
vseq_list_text = vseq_list_path.read_text(encoding="utf-8")
if "class kmac_entropy_refresh_shadow_vseq extends kmac_common_vseq;" not in vseq_list_text:
    vseq_list_text = vseq_list_text.rstrip() + "\n\n" + vseq_body
    vseq_list_path.write_text(vseq_list_text, encoding="utf-8")

sim_cfg_path = Path("/home/opentitan/hw/ip/kmac/dv/kmac_base_sim_cfg.hjson")
test_name = '"{variant}_entropy_refresh_shadow_reg"'
test_block = """    {
      name: "{variant}_entropy_refresh_shadow_reg"
      uvm_test_seq: kmac_entropy_refresh_shadow_vseq
      reseed: 1
      run_opts: ["+en_scb=0"]
    }
"""
sim_cfg_text = sim_cfg_path.read_text(encoding="utf-8")
if test_name not in sim_cfg_text:
    marker = "  ]\n\n  // List of regressions.\n"
    if marker not in sim_cfg_text:
        raise SystemExit("Could not find insertion point in kmac_base_sim_cfg.hjson")
    sim_cfg_text = sim_cfg_text.replace(marker, test_block + "  ]\n\n  // List of regressions.\n", 1)
    sim_cfg_path.write_text(sim_cfg_text, encoding="utf-8")
PY

set +e
timeout 1800 ./util/dvsim/dvsim.py \
  hw/ip/kmac/dv/kmac_unmasked_sim_cfg.hjson \
  -i "$TEST_NAME" \
  -t vcs \
  --fixed-seed 1 \
  --reseed 1 \
  --max-parallel 1 \
  --branch tb-kmac-shadow \
  --scratch-root "$TB_DIR/scratch" \
  --local \
  --purge
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

