tb_script:
#!/bin/bash
set -uo pipefail

cd /home/opentitan

export PATH="/home/opentitan_tools/riscv/bin:/home/opentitan_tools/verible/bin:$PATH"

TB_NAME="keymgr_key_ecc_fault"
TB_ROOT="/home/opentitan/.tb_keymgr_key_ecc"
VSEQ_DIR="/home/opentitan/hw/ip/keymgr/dv/env/seq_lib"
VSEQ_FILE="${VSEQ_DIR}/keymgr_key_ecc_vseq.sv"
VSEQ_LIST="${VSEQ_DIR}/keymgr_vseq_list.sv"
CORE_FILE="/home/opentitan/hw/ip/keymgr/dv/env/keymgr_env.core"
SIM_CFG="/home/opentitan/hw/ip/keymgr/dv/keymgr_sim_cfg.hjson"
INCLUDE_LINE='`include "keymgr_key_ecc_vseq.sv"'

mkdir -p "${TB_ROOT}"
rm -rf "${TB_ROOT}/scratch"

cat > "${VSEQ_FILE}" <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_key_ecc_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_key_ecc_vseq)
  `uvm_object_new

  localparam string KeyStateBitPath = "tb.dut.u_ctrl.key_state_q[0][0][0][0]";

  virtual task pre_start();
    expect_fatal_alerts = 1;
    super.pre_start();
  endtask

  task body();
    uvm_hdl_data_t bit_val;
    uvm_hdl_data_t forced_val;
    bit alert_seen = 0;

    `uvm_info(`gfn, "Corrupting key_state_q and expecting a fatal fault", UVM_MEDIUM)
    cfg.clk_rst_vif.wait_clks(10);

    cfg.en_scb = 0;
    cfg.keymgr_vif.en_chk = 0;
    $assertoff(0, "tb.keymgr_kmac_intf.req_data_if.H_DataStableWhenValidAndNotReady_A");

    `DV_CHECK_FATAL(uvm_hdl_check_path(KeyStateBitPath))
    `DV_CHECK_FATAL(uvm_hdl_read(KeyStateBitPath, bit_val))

    forced_val = (bit_val[0] == 1'b0);
    `DV_CHECK_FATAL(uvm_hdl_force(KeyStateBitPath, forced_val))
    cfg.clk_rst_vif.wait_clks(2);
    `DV_CHECK_FATAL(uvm_hdl_release(KeyStateBitPath))

    repeat (200) begin
      if (cfg.m_alert_agent_cfg["fatal_fault_err"].vif.is_alert_handshaking()) begin
        alert_seen = 1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end

    `DV_CHECK_FATAL(alert_seen, "Expected fatal_fault_err after corrupting key_state_q")
    cfg.m_alert_agent_cfg["fatal_fault_err"].vif.wait_ack_complete();
    cfg.clk_rst_vif.wait_clks(5);
    csr_rd_check(.ptr(ral.working_state), .compare_value(keymgr_pkg::StInvalid));
  endtask

  virtual function bit get_check_en();
    return 0;
  endfunction
endclass
EOF

if ! grep -Fq "${INCLUDE_LINE}" "${VSEQ_LIST}"; then
  printf '%s\n' "${INCLUDE_LINE}" >> "${VSEQ_LIST}"
fi

if ! grep -Fq "seq_lib/keymgr_key_ecc_vseq.sv" "${CORE_FILE}"; then
  sed -i '/seq_lib\/keymgr_stress_all_vseq.sv/a\      - seq_lib/keymgr_key_ecc_vseq.sv: {is_include_file: true}' "${CORE_FILE}"
fi

if ! grep -Fq "name: keymgr_key_ecc" "${SIM_CFG}"; then
  python - <<'PY'
from pathlib import Path

path = Path("/home/opentitan/hw/ip/keymgr/dv/keymgr_sim_cfg.hjson")
text = path.read_text(encoding="utf-8")
marker = "\n  ]\n\n  // List of regressions.\n"
block = """
    {
      name: keymgr_key_ecc
      uvm_test_seq: keymgr_key_ecc_vseq
    }"""
if "name: keymgr_key_ecc" not in text:
    text = text.replace(marker, f"{block}{marker}", 1)
    path.write_text(text, encoding="utf-8")
PY
fi

set +e
./util/dvsim/dvsim.py \
  hw/ip/keymgr/dv/keymgr_sim_cfg.hjson \
  -i keymgr_key_ecc \
  -t vcs \
  --local \
  --max-parallel 1 \
  --scratch-root "${TB_ROOT}/scratch" \
  --fixed-seed 1 \
  --run-opts +en_scb=0 \
  --no-rerun \
  2>&1 | tee "${TB_ROOT}/dvsim.log"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TB_NAME} ... PASS"
else
  echo "TEST: ${TB_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

