#!/bin/bash
set -uo pipefail

cd /home/opentitan || exit 1

TEST_NAME="spi_device_wren_wrdi_status"
TB_DIR="/home/opentitan/.tb_spi_device_wren"
COMPILE_LOG="${TB_DIR}/compile.log"
RUN_LOG="${TB_DIR}/run.log"
WORK_LOG="${TB_DIR}/work.log"

rc=1
stage="setup"
result_emitted=0

print_result() {
  local status="$1"

  if [ "${result_emitted}" -ne 0 ]; then
    return
  fi

  echo "HWE_BENCH_RESULTS_START"
  echo "TEST: ${TEST_NAME} ... ${status}"
  echo "HWE_BENCH_RESULTS_END"
  result_emitted=1
}

dump_log_tail() {
  local log_file="$1"
  local label="$2"

  if [ -f "${log_file}" ]; then
    echo "===== ${label} (tail) ====="
    tail -n 80 "${log_file}"
  fi
}

dump_failure_context() {
  if [ "${rc}" -eq 0 ]; then
    return
  fi

  echo "[ERROR] tb_script failed during stage: ${stage}"
  echo "[INFO] Live setup output is mirrored in ${WORK_LOG}"

  case "${stage}" in
    setup)
      ;;
    compile)
      dump_log_tail "${COMPILE_LOG}" "compile.log"
      ;;
    run)
      dump_log_tail "${RUN_LOG}" "run.log"
      ;;
    *)
      dump_log_tail "${COMPILE_LOG}" "compile.log"
      dump_log_tail "${RUN_LOG}" "run.log"
      ;;
  esac
}

on_exit() {
  local exit_code=$?

  if [ "${result_emitted}" -ne 0 ]; then
    return
  fi

  if [ "${exit_code}" -ne 0 ] && [ "${rc}" -eq 0 ]; then
    rc="${exit_code}"
  fi

  dump_failure_context
  print_result "FAIL"
}

finish() {
  rc="$1"

  if [ "${rc}" -ne 0 ]; then
    dump_failure_context
    print_result "FAIL"
  else
    print_result "PASS"
  fi

  trap - EXIT
  exit "${rc}"
}

trap on_exit EXIT

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}/include"

exec > >(tee "${WORK_LOG}") 2>&1

echo "[INFO] Generating register headers with python3/reggen."
python3 - "${TB_DIR}/include" <<'PY'
import pathlib
import sys

out_dir = pathlib.Path(sys.argv[1])
repo_root = pathlib.Path("/home/opentitan")

sys.path.insert(0, str(repo_root / "util"))

from reggen.gen_cheader import gen_cdefines
from reggen.ip_block import IpBlock

for rel_path, out_name in (
    ("hw/ip/spi_device/data/spi_device.hjson", "spi_device_regs.h"),
    ("hw/ip/flash_ctrl/data/flash_ctrl.hjson", "flash_ctrl_regs.h"),
):
    block = IpBlock.from_path(str(repo_root / rel_path), [])
    with (out_dir / out_name).open("w", encoding="utf-8") as handle:
        gen_cdefines(block, handle, None, "")
PY
setup_rc=$?
if [ "${setup_rc}" -ne 0 ]; then
  rc="${setup_rc}"
  finish "${rc}"
fi

  cat > "${TB_DIR}/extract_spi_cmdinfo.c" <<'EOF'
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "hw/top_earlgrey/sw/autogen/top_earlgrey.h"
#include "spi_device_regs.h"
#include "sw/device/lib/base/bitfield.h"
#include "sw/device/silicon_creator/lib/drivers/spi_device.h"

#define MMIO_WORDS 8192
static uint32_t mmio_space[MMIO_WORDS];

static size_t idx_from_addr(uint32_t addr) {
  return (size_t)((addr - TOP_EARLGREY_SPI_DEVICE_BASE_ADDR) / 4u);
}

uint8_t abs_mmio_read8(uint32_t addr) {
  uint32_t word = mmio_space[idx_from_addr(addr & ~3u)];
  return (word >> ((addr & 3u) * 8u)) & 0xffu;
}

void abs_mmio_write8(uint32_t addr, uint8_t value) {
  size_t idx = idx_from_addr(addr & ~3u);
  uint32_t shift = (addr & 3u) * 8u;
  uint32_t mask = 0xffu << shift;
  mmio_space[idx] = (mmio_space[idx] & ~mask) | ((uint32_t)value << shift);
}

void abs_mmio_write8_shadowed(uint32_t addr, uint8_t value) {
  abs_mmio_write8(addr, value);
  abs_mmio_write8(addr, value);
}

uint32_t abs_mmio_read32(uint32_t addr) {
  return mmio_space[idx_from_addr(addr)];
}

void abs_mmio_write32(uint32_t addr, uint32_t value) {
  mmio_space[idx_from_addr(addr)] = value;
}

void abs_mmio_write32_shadowed(uint32_t addr, uint32_t value) {
  abs_mmio_write32(addr, value);
  abs_mmio_write32(addr, value);
}

#include "sw/device/silicon_creator/lib/drivers/spi_device.c"

int main(void) {
  memset(mmio_space, 0, sizeof(mmio_space));
  mmio_space[idx_from_addr(TOP_EARLGREY_SPI_DEVICE_BASE_ADDR +
                           SPI_DEVICE_CONTROL_REG_OFFSET)] = 0xffffffffu;

  spi_device_init();

  uint32_t wren = mmio_space[idx_from_addr(TOP_EARLGREY_SPI_DEVICE_BASE_ADDR +
                                           SPI_DEVICE_CMD_INFO_WREN_REG_OFFSET)];
  uint32_t wrdi = mmio_space[idx_from_addr(TOP_EARLGREY_SPI_DEVICE_BASE_ADDR +
                                           SPI_DEVICE_CMD_INFO_WRDI_REG_OFFSET)];

  printf("%u 0x%02x %u 0x%02x\n",
         bitfield_bit32_read(wren, SPI_DEVICE_CMD_INFO_WREN_VALID_BIT),
         bitfield_field32_read(wren, SPI_DEVICE_CMD_INFO_WREN_OPCODE_FIELD),
