  cat > "${TB_DIR}/spid_common_min.sv" <<'EOF'
interface spi_if (input clk);
  logic csb;
  logic [3:0] sd_in;
  logic [3:0] sd_out;

  modport tb  (input clk, output csb, output sd_in, input sd_out);
  modport dut (input clk, input  csb, input  sd_in, output sd_out);
endinterface

package spid_common_min;
  import spi_device_pkg::*;
  `include "tb_cmdinfo_cfg.svh"

  typedef enum int unsigned {
    IoNone   = 0,
    IoSingle = 1,
    IoDual   = 2,
    IoQuad   = 3
  } mode_e;

  typedef enum int unsigned {
    DirNone  = 0,
    DirIn    = 1,
    DirOut   = 2,
    DirInout = 3,
    DirZ     = 4
  } dir_e;

  typedef logic [7:0] spi_data_t;
  typedef spi_data_t spi_queue_t[$];

  typedef struct packed {
    spi_data_t data;
    mode_e     mode;
    dir_e      dir;
  } spi_fifo_t;

  localparam cmd_info_t CmdInfoDefault = '{
    valid:           1'b0,
    opcode:          8'h00,
    addr_mode:       AddrDisabled,
    addr_swap_en:    1'b0,
    mbyte_en:        1'b0,
    dummy_en:        1'b0,
    dummy_size:      '0,
    payload_en:      4'b0001,
    payload_dir:     PayloadIn,
    payload_swap_en: 1'b0,
    upload:          1'b0,
    busy:            1'b0
  };

  parameter cmd_info_t [NumTotalCmdInfo-1:0] CmdInfo = '{
    CmdInfoReadStatus1: '{
      valid:           1'b1,
      opcode:          8'h05,
      addr_mode:       AddrDisabled,
      addr_swap_en:    1'b0,
      mbyte_en:        1'b0,
      dummy_en:        1'b0,
      dummy_size:      '0,
      payload_en:      4'b0010,
      payload_dir:     PayloadOut,
      payload_swap_en: 1'b0,
      upload:          1'b0,
      busy:            1'b0
    },
    CmdInfoReadStatus2: '{
      valid:           1'b1,
      opcode:          8'h35,
      addr_mode:       AddrDisabled,
      addr_swap_en:    1'b0,
      mbyte_en:        1'b0,
      dummy_en:        1'b0,
      dummy_size:      '0,
      payload_en:      4'b0010,
      payload_dir:     PayloadOut,
      payload_swap_en: 1'b0,
      upload:          1'b0,
      busy:            1'b0
    },
    CmdInfoReadStatus3: '{
      valid:           1'b1,
      opcode:          8'h15,
      addr_mode:       AddrDisabled,
      addr_swap_en:    1'b0,
      mbyte_en:        1'b0,
      dummy_en:        1'b0,
      dummy_size:      '0,
      payload_en:      4'b0010,
      payload_dir:     PayloadOut,
      payload_swap_en: 1'b0,
      upload:          1'b0,
      busy:            1'b0
    },
    CmdInfoWrEn: '{
      valid:           `TB_WREN_VALID,
      opcode:          `TB_WREN_OPCODE,
      addr_mode:       AddrDisabled,
      addr_swap_en:    1'b0,
      mbyte_en:        1'b0,
      dummy_en:        1'b0,
      dummy_size:      '0,
      payload_en:      4'b0001,
      payload_dir:     PayloadIn,
      payload_swap_en: 1'b0,
      upload:          1'b0,
      busy:            1'b0
    },
    CmdInfoWrDi: '{
      valid:           `TB_WRDI_VALID,
      opcode:          `TB_WRDI_OPCODE,
      addr_mode:       AddrDisabled,
      addr_swap_en:    1'b0,
      mbyte_en:        1'b0,
      dummy_en:        1'b0,
      dummy_size:      '0,
      payload_en:      4'b0001,
      payload_dir:     PayloadIn,
      payload_swap_en: 1'b0,
      upload:          1'b0,
      busy:            1'b0
    },
    default: CmdInfoDefault
  };

  task automatic spi_start(virtual spi_if.tb sif);
    @(negedge sif.clk);
    sif.csb = 1'b0;
  endtask

  task automatic spi_end(virtual spi_if.tb sif);
    @(posedge sif.clk);
    sif.csb <= 1'b1;
  endtask

  task automatic spi_sendbyte(virtual spi_if.tb sif, input spi_data_t data,
                              input mode_e mode);
    sif.sd_in[3:0] = 'Z;
    case (mode)
      IoSingle: begin
        for (int i = 7; i >= 0; i--) begin
          sif.sd_in[0] = data[i];
          @(negedge sif.clk);
        end
      end
      IoDual: begin
        for (int i = 6; i >= 0; i -= 2) begin
          sif.sd_in[1:0] = data[i+:2];
          @(negedge sif.clk);
          if (i == 0) break;
        end
      end
      IoQuad: begin
        for (int i = 4; i >= 0; i -= 4) begin
          sif.sd_in[3:0] = data[i+:4];
          @(negedge sif.clk);
        end
      end
      default: begin
      end
    endcase
  endtask

  task automatic spi_receivebyte(virtual spi_if.tb sif,
                                 output spi_data_t rcv_byte,
                                 input mode_e mode);
    sif.sd_in[3:0] = 4'hz;
    case (mode)
      IoSingle: begin
        for (int i = 7; i >= 0; i--) begin
          @(posedge sif.clk);
          rcv_byte[i] = sif.sd_out[1];
        end
      end
      IoDual: begin
        for (int i = 6; i >= 0; i -= 2) begin
          @(posedge sif.clk);
          rcv_byte[i+:2] = sif.sd_out[0+:2];
        end
      end
      IoQuad: begin
        for (int i = 4; i >= 0; i -= 4) begin
          @(posedge sif.clk);
          rcv_byte[i+:4] = sif.sd_out[0+:4];
        end
      end
      default: begin
        rcv_byte = '0;
      end
    endcase
    @(negedge sif.clk);
  endtask

  task automatic spi_transaction(virtual spi_if.tb sif, ref spi_fifo_t d_in[$],
                                 ref spi_queue_t d_out);
    spi_data_t rcv_byte;
    mode_e mode = IoSingle;
    dir_e dir = DirIn;

    spi_start(sif);
    foreach (d_in[i]) begin
      if (d_in[i].dir != DirNone) dir = d_in[i].dir;
      if (d_in[i].mode != IoNone) mode = d_in[i].mode;

      case (dir)
        DirIn: begin
          spi_sendbyte(sif, d_in[i].data, mode);
        end
        DirOut: begin
          spi_receivebyte(sif, rcv_byte, mode);
          d_out.push_back(rcv_byte);
        end
        DirZ: begin
          sif.sd_in[3:0] = 4'hz;
          @(negedge sif.clk);
        end
        default: begin
          $fatal(1, "Unsupported dir %0d", dir);
        end
      endcase
    end
    spi_end(sif);
  endtask

  task automatic spiflash_readstatus(virtual spi_if.tb sif,
                                     input spi_data_t opcode,
                                     output spi_data_t status);
    spi_fifo_t send_data[$];
    spi_queue_t rcv_data;

    send_data.push_back('{data: opcode, dir: DirIn, mode: IoSingle});
    send_data.push_back('{data: '0, dir: DirOut, mode: IoNone});
    spi_transaction(sif, send_data, rcv_data);
    status = rcv_data.pop_front();
  endtask

  task automatic spiflash_wren(virtual spi_if.tb sif, input spi_data_t opcode);
    spi_fifo_t send_data[$];
    spi_queue_t rcv_data;

    send_data.push_back('{data: opcode, dir: DirIn, mode: IoSingle});
    spi_transaction(sif, send_data, rcv_data);
  endtask

  task automatic spiflash_wrdi(virtual spi_if.tb sif, input spi_data_t opcode);
    spiflash_wren(sif, opcode);
  endtask
endpackage
EOF

  cat > "${TB_DIR}/spid_status_tb_min.sv" <<'EOF'
module spid_status_tb_min;
  import spi_device_pkg::*;
  import spid_common_min::*;

  localparam time ClkPeriod = 10ns;
  localparam time SckPeriod = 14ns;

  logic clk;
  logic rst_n;
  logic sck;
  logic sck_rst_n;

  spi_if sif(sck);
  virtual spi_if.tb tb_sif = sif.tb;

  logic [3:0] dut_sd_en, dut_sd;
  for (genvar i = 0; i < 4; i++) begin : g_dut_sif
    assign sif.sd_out[i] = dut_sd_en[i] ? dut_sd[i] : 1'bz;
  end

  wire sck_en = ~sif.csb;
  wire gated_sck = sck_en ? sck : 1'b0;
  wire gated_sck_inverted = ~gated_sck;
  wire rst_spi_n = sck_rst_n && ~sif.csb;

  sel_datapath_e dut_sel_dp;
  logic [CmdInfoIdxW-1:0] cmd_info_idx;
  cmd_info_t cmd_info;

  logic sys_status_we;
  logic [23:0] sys_status_in, sys_status_out;
  logic busy_set;
  spi_mode_e spi_mode;
  logic s2p_valid;
  spi_byte_t s2p_data;
  logic p2s_valid, p2s_sent;
  logic [7:0] p2s_data;
  io_mode_e dut_iomode, s2p_iomode;
  logic sck_we_set, sck_we_clr;

  task automatic check_bit1(string tag, logic [7:0] data, bit exp);
    if (data[1] !== exp) begin
      $fatal(1, "%s expected bit1=%0b got status=0x%02x", tag, exp, data);
    end
  endtask

  initial begin
    clk = 1'b0;
    forever #(ClkPeriod / 2) clk = ~clk;
  end

  initial begin
    sck = 1'b0;
    forever #(SckPeriod / 2) sck = ~sck;
  end

  initial begin
    sif.csb = 1'b1;
    sys_status_we = 1'b0;
    sys_status_in = '0;
    busy_set = 1'b0;
    spi_mode = FlashMode;
    rst_n = 1'b0;
    sck_rst_n = 1'b0;
    repeat (4) @(posedge clk);
    rst_n = 1'b1;
    sck_rst_n = 1'b1;

    fork
      begin
        #20us;
        $fatal(1, "timeout");
      end
      begin : run_test
        spi_data_t data;

        repeat (10) @(negedge sck);
        spiflash_readstatus(tb_sif, 8'h05, data);
        check_bit1("initial", data, 1'b0);

        repeat (20) @(negedge sck);
        spiflash_wren(tb_sif, 8'h06);
        repeat (20) @(negedge sck);
        spiflash_readstatus(tb_sif, 8'h05, data);
        check_bit1("after_wren", data, 1'b1);

        repeat (20) @(negedge sck);
        spiflash_wrdi(tb_sif, 8'h04);
        repeat (20) @(negedge sck);
        spiflash_readstatus(tb_sif, 8'h05, data);
        check_bit1("after_wrdi", data, 1'b0);

        $display("TEST PASSED CHECKS");
        $finish;
      end
    join_any
  end

  spid_status dut (
    .clk_i(gated_sck),
    .rst_ni(rst_spi_n),
    .clk_out_i(gated_sck_inverted),
    .clk_csb_i(sif.csb),
    .sys_clk_i(clk),
    .sys_rst_ni(rst_n),
    .sys_csb_deasserted_pulse_i(1'b0),
    .sys_status_we_i(sys_status_we),
    .sys_status_i(sys_status_in),
    .sys_status_o(sys_status_out),
    .sel_dp_i(dut_sel_dp),
    .cmd_info_i(cmd_info),
    .cmd_info_idx_i(cmd_info_idx),
    .outclk_p2s_valid_o(p2s_valid),
    .outclk_p2s_byte_o(p2s_data),
    .outclk_p2s_sent_i(p2s_sent),
    .io_mode_o(dut_iomode),
    .inclk_busy_set_i(busy_set),
    .inclk_we_set_i(sck_we_set),
    .inclk_we_clr_i(sck_we_clr),
    .csb_busy_broadcast_o()
  );

  spi_cmdparse cmdparse (
    .clk_i(gated_sck),
    .rst_ni(rst_spi_n),
    .data_valid_i(s2p_valid),
    .data_i(s2p_data),
    .spi_mode_i(spi_mode),
    .cmd_info_i(spid_common_min::CmdInfo),
    .io_mode_o(s2p_iomode),
    .sel_dp_o(dut_sel_dp),
    .cmd_info_o(cmd_info),
    .cmd_info_idx_o(cmd_info_idx),
    .cfg_intercept_en_status_i(1'b1),
    .cfg_intercept_en_jedec_i(1'b1),
    .cfg_intercept_en_sfdp_i(1'b1),
    .intercept_status_o(),
    .intercept_jedec_o(),
    .intercept_sfdp_o(),
    .cmd_config_req_o(),
    .cmd_config_idx_o()
  );

  assign sck_we_set = (dut_sel_dp == DpWrEn);
  assign sck_we_clr = (dut_sel_dp == DpWrDi);

  spi_s2p s2p (
    .clk_i(gated_sck),
    .rst_ni(rst_spi_n),
    .s_i(sif.sd_in),
    .data_valid_o(s2p_valid),
    .data_o(s2p_data),
    .bitcnt_o(),
    .order_i(1'b0),
    .io_mode_i(s2p_iomode)
  );

  spi_p2s p2s (
    .clk_i(gated_sck_inverted),
    .rst_ni(rst_spi_n),
    .data_valid_i(p2s_valid),
    .data_i(p2s_data),
    .data_sent_o(p2s_sent),
    .csb_i(sif.csb),
    .s_en_o(dut_sd_en),
    .s_o(dut_sd),
    .cpha_i(1'b0),
    .order_i(1'b0),
    .io_mode_i(dut_iomode)
  );
endmodule
EOF

