#!/bin/bash
set +e

cd /home/opentitan || exit 1

TB_DIR=/home/opentitan/.tb_prog_lvl
SCRATCH_ROOT="${TB_DIR}/scratch"
TEST_NAME="flash_ctrl_prog_lvl_intr_directionality"

rm -rf "${TB_DIR}"
mkdir -p "${TB_DIR}"

cat > "${TB_DIR}/flash_ctrl_prog_lvl_intr_vseq.sv" <<'EOF'
import uvm_pkg::*;
import flash_ctrl_env_pkg::*;
import csr_utils_pkg::*;
`include "uvm_macros.svh"

class flash_ctrl_prog_lvl_intr_vseq extends flash_ctrl_base_vseq;
  `uvm_object_utils(flash_ctrl_prog_lvl_intr_vseq)

  `uvm_object_new

  virtual task body();
    bit [31:0] intr_mask;
    flash_op_t flash_op;

    cfg.scb_check = 1'b1;
    cfg.flash_mem_bkdr_init(FlashPartData, FlashMemInitSet);
    flash_ctrl_default_region_cfg(.read_en(4'h6),
                                  .program_en(4'h6),
                                  .erase_en(4'h6));
    clear_all_interrupts();

    intr_mask = 1 << FlashCtrlIntrProgLvl;
    flash_ctrl_fifo_levels_cfg_intr(.read_fifo_intr_level(0), .program_fifo_intr_level(1));
    cfg_interrupts(intr_mask, 1'b1);

    flash_op.addr = 0;
    flash_op.partition = FlashPartData;
    flash_op.erase_type = 1'b0;
    flash_op.op = 2'h1;
    flash_op.prog_sel = 1'b0;
    flash_op.num_words = 2;
    flash_ctrl_start_op(flash_op);
    cfg.clk_rst_vif.wait_clks(2);

    mem_wr(.ptr(ral.prog_fifo), .offset(0), .data(32'h0123_4567));
    cfg.clk_rst_vif.wait_clks(4);
    check_interrupts(intr_mask, 1'b0);

    mem_wr(.ptr(ral.prog_fifo), .offset(0), .data(32'h89ab_cdef));
    cfg.clk_rst_vif.wait_clks(4);
    check_interrupts(intr_mask, 1'b0);

    apply_reset();
    clear_all_interrupts();
    cfg_interrupts(intr_mask, 1'b1);
    csr_wr(.ptr(ral.intr_test), .value(intr_mask));
    check_interrupts(intr_mask, 1'b1);
    clear_all_interrupts();
  endtask
endclass
EOF

cat > "${TB_DIR}/job_prefix.sh" <<'EOF'
#!/bin/bash
set -e

cmd="$1"
shift

if [[ "$(basename "$cmd")" == "vcs" ]]; then
  exec "$cmd" "$@" /home/opentitan/.tb_prog_lvl/flash_ctrl_prog_lvl_intr_vseq.sv
fi

if [[ "$cmd" == */simv ]]; then
  new_args=()
  for arg in "$@"; do
    if [[ "$arg" == +UVM_TEST_SEQ=* ]]; then
      continue
    fi
    new_args+=("$arg")
  done
  new_args+=("+UVM_TEST_SEQ=flash_ctrl_prog_lvl_intr_vseq")
  exec "$cmd" "${new_args[@]}"
fi

exec "$cmd" "$@"
EOF
chmod +x "${TB_DIR}/job_prefix.sh"

export PATH="/tools/riscv/bin:${PATH}"

python ./util/dvsim/dvsim.py hw/ip/flash_ctrl/dv/flash_ctrl_sim_cfg.hjson \
  -i flash_ctrl_smoke \
  -t vcs \
  --fixed-seed 1 \
  --build-seed 1 \
  --max-parallel 1 \
  --scratch-root "${SCRATCH_ROOT}" \
  --purge \
  --job-prefix "${TB_DIR}/job_prefix.sh" \
  --build-opts +warn=noLNX_OS_VERUN
rc=$?

echo "HWE_BENCH_RESULTS_START"
if [ "${rc}" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

