#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="otp_ctrl_dif_lock_behavior"
TB_DIR="/home/opentitan/.tb_otp_ctrl_dif_lock"
LOG="$TB_DIR/dvsim.log"

mkdir -p "$TB_DIR"

cat > /home/opentitan/sw/device/tests/otp_ctrl_smoketest.c <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

#include <stdbool.h>

#include "sw/device/lib/base/bitfield.h"
#include "sw/device/lib/dif/dif_otp_ctrl.h"
#include "sw/device/lib/testing/test_framework/check.h"
#include "sw/device/lib/testing/test_framework/ottf_main.h"

#include "hw/top_earlgrey/sw/autogen/top_earlgrey.h"
#include "otp_ctrl_regs.h"  // Generated.

static dif_otp_ctrl_t otp;

OTTF_DEFINE_TEST_CONFIG();

bool test_main(void) {
  CHECK_DIF_OK(dif_otp_ctrl_init(
      mmio_region_from_addr(TOP_EARLGREY_OTP_CTRL_CORE_BASE_ADDR), &otp));

  uint32_t trigger_regwen = mmio_region_read32(
      otp.base_addr, OTP_CTRL_CHECK_TRIGGER_REGWEN_REG_OFFSET);
  CHECK(bitfield_bit32_read(
            trigger_regwen,
            OTP_CTRL_CHECK_TRIGGER_REGWEN_CHECK_TRIGGER_REGWEN_BIT),
        "CHECK_TRIGGER_REGWEN unexpectedly locked before test setup.");

  uint32_t reg =
      bitfield_bit32_write(0, OTP_CTRL_CHECK_REGWEN_CHECK_REGWEN_BIT, false);
  mmio_region_write32(otp.base_addr, OTP_CTRL_CHECK_REGWEN_REG_OFFSET, reg);

  bool is_locked = false;
  CHECK_DIF_OK(dif_otp_ctrl_config_is_locked(&otp, &is_locked));
  CHECK(is_locked, "CHECK_REGWEN should be locked after a direct rw0c write.");

  dif_otp_ctrl_config_t config = {
      .check_timeout = 100000,
      .integrity_period_mask = 0x3ffff,
      .consistency_period_mask = 0x3ffffff,
  };
  CHECK(dif_otp_ctrl_configure(&otp, config) == kDifLocked,
        "dif_otp_ctrl_configure() should be blocked once CHECK_REGWEN locks.");

  dif_result_t check_result = dif_otp_ctrl_check_integrity(&otp);
  CHECK(check_result == kDifOk,
        "dif_otp_ctrl_check_integrity() should stay available when only "
        "CHECK_REGWEN is locked, got %d.",
        check_result);

  return true;
}
EOF

