patch_rules_python_wheel() {
  local outbase
  local wheel_py

  outbase=$(./bazelisk.sh info output_base)
  wheel_py=$(find "${outbase}/external/rules_python" \
    -path "*/python/pip_install/extract_wheels/lib/wheel.py" 2>/dev/null | head -n 1 || true)

  if [ -z "${wheel_py}" ]; then
    ./bazelisk.sh query //sw/device/tests:alert_handler_lpg_clkoff_test_sim_dv >/dev/null 2>&1 || true
    wheel_py=$(find "${outbase}/external/rules_python" \
      -path "*/python/pip_install/extract_wheels/lib/wheel.py" 2>/dev/null | head -n 1 || true)
  fi

  if [ -z "${wheel_py}" ]; then
    echo "rules_python wheel.py not found" >&2
    return 1
  fi

  python3 - "${wheel_py}" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
text = path.read_text()

if "No METADATA found in wheel" not in text:
    if "import email" not in text:
        text = text.replace("import configparser\n", "import configparser\nimport email\n", 1)
    old = """    @property
    def metadata(self) -> pkginfo.Wheel:
        return pkginfo.get_metadata(self.path)
"""
    new = """    @property
    def metadata(self) -> pkginfo.Wheel:
        metadata = pkginfo.get_metadata(self.path)
        if metadata is not None and getattr(metadata, "name", None) and getattr(metadata, "version", None):
            return metadata

        with zipfile.ZipFile(self.path, "r") as whl:
            meta_files = sorted(
                n for n in whl.namelist() if n.endswith(".dist-info/METADATA") and n.count("/") == 1
            ) or sorted(n for n in whl.namelist() if n.endswith(".dist-info/METADATA"))
            if not meta_files:
                raise ValueError(f"No METADATA found in wheel: {self.path}")
            msg = email.message_from_string(whl.read(meta_files[0]).decode("utf-8", "replace"))

        class _FallbackMetadata:
            pass

        fallback = _FallbackMetadata()
        fallback.name = msg.get("Name")
        fallback.version = msg.get("Version")
        fallback.requires_dist = msg.get_all("Requires-Dist") or []
        return fallback
"""
    if old not in text:
        raise SystemExit("expected wheel.py metadata block not found")
    path.write_text(text.replace(old, new, 1))
PY

  ./bazelisk.sh shutdown >/dev/null 2>&1 || true
  rm -rf \
    "${outbase}/external/ot_python_deps" \
    "${outbase}/external/ot_python_wheels" \
    "${outbase}/external/+pip_deps_ot_python_deps" \
    2>/dev/null || true
}

