// This function will run after every device reset.
bool test_main(void) {
  init_peripherals();

  const test_t *peripheral = &kPeripherals[1];
  bool is_cause = false;
  uint32_t polls = 0;

  alert_handler_config_peripherals(
      /*num_peripherals=*/1, /*first_peripheral=*/peripheral,
      /*ping_timeout=*/256);

  set_peripheral_clock(peripheral, kDifToggleEnabled);
  busy_spin_micros(100);

  LOG_INFO("Trigger fatal alert %s", peripheral->name);
  while (!is_cause && polls < 20000) {
    CHECK_DIF_OK(dif_alert_handler_alert_is_cause(
        &alert_handler, peripheral->alert_ids[0], &is_cause));
    if (!is_cause) {
      busy_spin_micros(1);
    }
    ++polls;
  }
  CHECK(is_cause, "Timed out waiting for initial HMAC fatal alert cause");

  set_peripheral_clock(peripheral, kDifToggleDisabled);
  CHECK_DIF_OK(
      dif_alert_handler_alert_acknowledge(&alert_handler, peripheral->alert_ids[0]));
  CHECK_DIF_OK(dif_alert_handler_alert_is_cause(
      &alert_handler, peripheral->alert_ids[0], &is_cause));
  CHECK(!is_cause, "Expected HMAC alert cause to clear after acknowledge");

  busy_spin_micros(100);
  set_peripheral_clock(peripheral, kDifToggleEnabled);
  busy_spin_micros(100);

  CHECK_DIF_OK(dif_alert_handler_alert_is_cause(
      &alert_handler, peripheral->alert_ids[0], &is_cause));
  CHECK(is_cause,
        "Expected HMAC fatal alert cause to reassert after clock restore");

  return true;
}
EOF
}

