#!/bin/bash
set -uo pipefail

cd /home/opentitan || exit 1

TEST_NAME="hmac_sha512_status"
rc=0

python - <<'PY' || rc=$?
from pathlib import Path
import re
import textwrap

root = Path("/home/opentitan")

scoreboard = root / "hw/ip/hmac/dv/env/hmac_scoreboard.sv"
scoreboard_text = scoreboard.read_text(encoding="utf-8")
scoreboard_text, n = re.subn(
    r"bit\s+do_read_check\s*=\s*1'b[01];",
    "bit     do_read_check           = 1'b1;",
    scoreboard_text,
    count=1,
)
if n != 1:
    raise SystemExit("Failed to enable HMAC CSR read checks")

scoreboard.write_text(scoreboard_text, encoding="utf-8")

vseq = root / "hw/ip/hmac/dv/env/seq_lib/hmac_sha512_status_vseq.sv"
vseq.write_text(
    textwrap.dedent(
        """\
        // Copyright lowRISC contributors (OpenTitan project).
        // Licensed under the Apache License, Version 2.0, see LICENSE for details.
        // SPDX-License-Identifier: Apache-2.0

        class hmac_sha512_status_vseq extends hmac_base_vseq;
          `uvm_object_utils(hmac_sha512_status_vseq)
          `uvm_object_new

          localparam int MsgBytes = HMAC_BLK_SIZE_SHA2_384_512;
          localparam int NumStatusReads = 220;

          virtual task pre_start();
            do_hmac_init = 1'b0;
            super.pre_start();
          endtask

          task automatic write_msg_words(bit [7:0] msg[]);
            bit [7:0]       word_bytes[4];
            bit [TL_DW-1:0] word;

            for (int i = 0; i < msg.size(); i += 4) begin
              for (int j = 0; j < 4; j++) word_bytes[j] = msg[i + j];
              word = {>>byte{word_bytes}};
              tl_access(.addr(cfg.ral.get_addr_from_offset(HMAC_MSG_FIFO_BASE)),
                        .write(1'b1),
                        .data(word),
                        .mask('1),
                        .blocking(1'b1));
            end
            csr_utils_pkg::wait_no_outstanding_access();
          endtask

          task body();
            bit [7:0]       msg[MsgBytes];
            bit [TL_DW-1:0] status;
            bit [TL_DW-1:0] intr_state;

            foreach (msg[i]) msg[i] = i[7:0];

            hmac_init(.sha_en(1'b1),
                      .hmac_en(1'b0),
                      .endian_swap(1'b1),
                      .digest_swap(1'b0),
                      .key_swap(1'b0),
                      .digest_size(SHA2_512),
                      .key_length(Key_256),
                      .intr_fifo_empty_en(1'b0),
                      .intr_hmac_done_en(1'b1),
                      .intr_hmac_err_en(1'b1));

            rd_digest();
            trigger_hash();
            write_msg_words(msg);

            csr_rd(.ptr(ral.status), .value(status));
            trigger_process();

            repeat (NumStatusReads) begin
              cfg.clk_rst_vif.wait_clks(1);
              csr_rd(.ptr(ral.status), .value(status));
              if (cfg.intr_vif.pins[HmacDone] === 1'b1) break;
            end

            if (cfg.intr_vif.pins[HmacDone] !== 1'b1) begin
              `uvm_fatal(`gfn, "Timed out waiting for HmacDone")
            end

            cfg.clk_rst_vif.wait_clks(2);
            csr_rd(.ptr(ral.status), .value(status));
            csr_rd(.ptr(ral.intr_state), .value(intr_state));
            csr_wr(.ptr(ral.intr_state), .value(intr_state));
            rd_digest();
          endtask
        endclass
        """
    ),
    encoding="utf-8",
)

vseq_list = root / "hw/ip/hmac/dv/env/seq_lib/hmac_vseq_list.sv"
vseq_include = '`include "hmac_sha512_status_vseq.sv"\n'
vseq_list_text = vseq_list.read_text(encoding="utf-8")
if vseq_include not in vseq_list_text:
    vseq_list_text += vseq_include
    vseq_list.write_text(vseq_list_text, encoding="utf-8")

env_core = root / "hw/ip/hmac/dv/env/hmac_env.core"
env_core_text = env_core.read_text(encoding="utf-8")
core_entry = "      - seq_lib/hmac_sha512_status_vseq.sv: {is_include_file: true}\n"
if core_entry not in env_core_text:
    marker = "      - seq_lib/hmac_stress_all_vseq.sv: {is_include_file: true}\n"
    if marker not in env_core_text:
        raise SystemExit("Failed to find insertion point in hmac_env.core")
    env_core_text = env_core_text.replace(marker, marker + core_entry, 1)
    env_core.write_text(env_core_text, encoding="utf-8")

sim_cfg = root / "hw/ip/hmac/dv/hmac_sim_cfg.hjson"
sim_cfg_text = sim_cfg.read_text(encoding="utf-8")
test_block = textwrap.dedent(
    """\

    {
      name: hmac_sha512_status
      uvm_test_seq: hmac_sha512_status_vseq
      reseed: 1
    }"""
)
if "name: hmac_sha512_status" not in sim_cfg_text:
    marker = "\n  ]\n\n  // List of regressions."
    if marker not in sim_cfg_text:
        raise SystemExit("Failed to find tests list terminator in hmac_sim_cfg.hjson")
    sim_cfg_text = sim_cfg_text.replace(marker, f"{test_block}\n  ]\n\n  // List of regressions.", 1)
    sim_cfg.write_text(sim_cfg_text, encoding="utf-8")
PY

if [[ "$rc" -eq 0 ]]; then
  rm -rf /home/opentitan/scratch
  ./util/dvsim/dvsim.py hw/ip/hmac/dv/hmac_sim_cfg.hjson \
    -i "${TEST_NAME}" \
    -t vcs \
    --fixed-seed=1 \
    --build-seed=1
  rc=$?
fi

echo "HWE_BENCH_RESULTS_START"
if [[ "$rc" -eq 0 ]]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

