#!/bin/bash
set -u -o pipefail

cd /home/opentitan

TB_DIR=/home/opentitan/.tb_prim_packer_backpressure
rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'SV'
`timescale 1ns/1ps
`include "/home/opentitan/hw/ip/prim/rtl/prim_assert.sv"
`include "/home/opentitan/hw/ip/prim/rtl/prim_packer.sv"

module tb;
  logic clk_i;
  logic rst_ni;
  logic valid_i;
  logic [3:0] data_i;
  logic [3:0] mask_i;
  logic ready_o;
  logic valid_o;
  logic [3:0] data_o;
  logic [3:0] mask_o;
  logic ready_i;
  logic flush_i;
  logic flush_done_o;

  prim_packer #(
    .InW(4),
    .OutW(4)
  ) dut (
    .clk_i,
    .rst_ni,
    .valid_i,
    .data_i,
    .mask_i,
    .ready_o,
    .valid_o,
    .data_o,
    .mask_o,
    .ready_i,
    .flush_i,
    .flush_done_o
  );

  always #5 clk_i = ~clk_i;

  task automatic drive(
    input logic valid,
    input logic [3:0] data,
    input logic [3:0] mask,
    input logic out_ready,
    input logic flush
  );
    valid_i = valid;
    data_i = data;
    mask_i = mask;
    ready_i = out_ready;
    flush_i = flush;
    #1;
  endtask

  task automatic check_cond(input logic cond, input string msg);
    if (!cond) begin
      $display("TB_ERROR: %s", msg);
      $fatal(1, "%s", msg);
    end
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    valid_i = 1'b0;
    data_i = '0;
    mask_i = '0;
    ready_i = 1'b0;
    flush_i = 1'b0;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;

    @(negedge clk_i);
    drive(1'b1, 4'hA, 4'b0011, 1'b0, 1'b0);
    check_cond(ready_o === 1'b1, "first partial write should be accepted");

    @(posedge clk_i);
    @(negedge clk_i);
    drive(1'b1, 4'h5, 4'b1111, 1'b0, 1'b0);
    check_cond(valid_o === 1'b1, "full word should be pending on the output");
    check_cond(mask_o === 4'b1111, "packer must present a full-width mask before flush");
    check_cond(ready_o === 1'b0, "ready_o must deassert when storage is insufficient");

    @(posedge clk_i);
    @(negedge clk_i);
    drive(1'b1, 4'h5, 4'b1111, 1'b1, 1'b0);
    check_cond(ready_o === 1'b1, "ready_o should return once output can drain data");
    check_cond(valid_o === 1'b1, "output word should remain valid while request is pending");

    @(posedge clk_i);
    @(negedge clk_i);
    drive(1'b0, 4'h0, 4'h0, 1'b1, 1'b0);
    @(posedge clk_i);

    $display("TB_PASS: prim_packer back-pressure behavior is correct");
    $finish(0);
  end
endmodule
SV

compile_rc=0
sim_rc=0

(
  cd "$TB_DIR"
  vcs -full64 -sverilog tb.sv -o simv -l compile.log
) || compile_rc=$?

if [ "$compile_rc" -eq 0 ]; then
  (
    cd "$TB_DIR"
    ./simv -l sim.log
  ) || sim_rc=$?
fi

# VCS reports the failure in the runtime log but may still exit with code 0.
if [ "$compile_rc" -eq 0 ] && [ "$sim_rc" -eq 0 ]; then
  if ! grep -q "TB_PASS: prim_packer back-pressure behavior is correct" "$TB_DIR/sim.log"; then
    sim_rc=1
  fi
fi

rc=$compile_rc
if [ "$rc" -eq 0 ] && [ "$sim_rc" -ne 0 ]; then
  rc=$sim_rc
fi

if [ "$compile_rc" -ne 0 ]; then
  tail -n 80 "$TB_DIR/compile.log" || true
fi

if [ "$sim_rc" -ne 0 ]; then
  tail -n 80 "$TB_DIR/sim.log" || true
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: prim_packer_backpressure ... PASS"
else
  echo "TEST: prim_packer_backpressure ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

