// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class keymgr_cmd_onehot_fault_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_cmd_onehot_fault_vseq)
  `uvm_object_new

  localparam int AlertTimeoutClks = 200;
  localparam int StateTimeoutClks = 200;

  virtual task body();
    bit alert_seen;
    bit disabled_seen;
    bit [TL_DW-1:0] reg_val;
    uvm_hdl_data_t force_val = 1;

    // Reach StInit first so the next advance launches a KMAC-backed operation.
    keymgr_advance(.wait_done(1));

    cfg.en_scb = 0;
    $assertoff(0, "tb.keymgr_kmac_intf");
    $assertoff(0, "tb.dut.tlul_assert_device.gen_device.dDataKnown_A");
    cfg.keymgr_vif.force_cmds = 3'b111;
    cfg.keymgr_vif.is_cmd_err = 1'b1;

    // Start an advance operation without waiting so we can inject a transient multi-hot command.
    keymgr_advance(.wait_done(0));

    repeat (AlertTimeoutClks) begin
      csr_rd(.ptr(ral.op_status), .value(reg_val));
      if (reg_val == keymgr_pkg::OpWip) break;
      cfg.clk_rst_vif.wait_clks(1);
    end
    if (reg_val != keymgr_pkg::OpWip) begin
      `uvm_fatal(`gfn, "Timed out waiting for keymgr advance operation to enter OpWip")
    end

    if (!uvm_hdl_force("tb.dut.u_ctrl.adv_en_o", force_val)) begin
      `uvm_fatal(`gfn, "Failed to force tb.dut.u_ctrl.adv_en_o")
    end
    if (!uvm_hdl_force("tb.dut.u_ctrl.id_en_o", force_val)) begin
      `uvm_fatal(`gfn, "Failed to force tb.dut.u_ctrl.id_en_o")
    end
    if (!uvm_hdl_force("tb.dut.u_ctrl.gen_en_o", force_val)) begin
      `uvm_fatal(`gfn, "Failed to force tb.dut.u_ctrl.gen_en_o")
    end
    cfg.clk_rst_vif.wait_clks(1);
    void'(uvm_hdl_release("tb.dut.u_ctrl.adv_en_o"));
    void'(uvm_hdl_release("tb.dut.u_ctrl.id_en_o"));
    void'(uvm_hdl_release("tb.dut.u_ctrl.gen_en_o"));

    repeat (AlertTimeoutClks) begin
      if (cfg.m_alert_agent_cfg["fatal_fault_err"].vif.alert_tx_final.alert_p) begin
        alert_seen = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    if (!alert_seen) begin
      `uvm_fatal(`gfn, "Timed out waiting for fatal_fault_err after multi-hot command fault")
    end
    check_fatal_alert_nonblocking("fatal_fault_err");

    repeat (StateTimeoutClks) begin
      csr_rd(.ptr(ral.working_state), .value(reg_val));
      if (reg_val == keymgr_pkg::StDisabled) begin
        disabled_seen = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    if (!disabled_seen) begin
      `uvm_fatal(`gfn, "Timed out waiting for keymgr to enter StDisabled")
    end
  endtask : body

  task post_start();
    do_reset_at_end_of_seq = 1'b1;
    super.post_start();
    cfg.en_scb = 1'b1;
    $asserton(0, "tb.keymgr_kmac_intf");
    $asserton(0, "tb.dut.tlul_assert_device.gen_device.dDataKnown_A");
  endtask
endclass : keymgr_cmd_onehot_fault_vseq
EOF

