// Trigger a fatal background check timeout and verify that OTP invalidates
// all buffered outputs, not just the FSM that observed the fatal condition.
class otp_ctrl_local_escalation_vseq extends otp_ctrl_base_vseq;
  `uvm_object_utils(otp_ctrl_local_escalation_vseq)

  `uvm_object_new

  localparam uint CheckPeriod       = 1;
  localparam uint CheckWaitCycles   = ((CheckPeriod + 1) << 8) + 10;
  localparam uint EscalationTimeout = 50;

  task body();
    bit alert_seen;
    bit outputs_invalidated;

    cfg.en_scb = 0;

    `DV_CHECK_EQ(cfg.otp_ctrl_vif.otp_hw_cfg_o.valid, lc_ctrl_pkg::On)
    `DV_CHECK_EQ(cfg.otp_ctrl_vif.lc_data_o.valid, 1'b1)

    csr_wr(ral.integrity_check_period, CheckPeriod);

