      if (cfg.otp_ctrl_vif.otp_hw_cfg_o.valid == lc_ctrl_pkg::Off &&
          cfg.otp_ctrl_vif.lc_data_o.valid == 1'b0) begin
        outputs_invalidated = 1'b1;
        break;
      end
      cfg.clk_rst_vif.wait_clks(1);
    end
    `DV_CHECK_FATAL(outputs_invalidated,
