class keymgr_init_lc_disable_vseq extends keymgr_base_vseq;
  `uvm_object_utils(keymgr_init_lc_disable_vseq)
  `uvm_object_new

  keymgr_scoreboard scb_h;

  virtual task pre_start();
    uvm_component comp;

    super.pre_start();
    cfg.en_scb = 0;

    comp = uvm_root::get().find("uvm_test_top.env.scoreboard");
    `DV_CHECK_NE_FATAL(comp, null)
    `downcast(scb_h, comp)
    scb_h.do_alert_check = 0;
  endtask

  virtual task body();
    `uvm_info(`gfn, "Start deterministic LC-disable during init sequence", UVM_MEDIUM)

    cfg.keymgr_vif.keymgr_en = lc_ctrl_pkg::On;
    keymgr_advance(.wait_done(0));

    wait (cfg.keymgr_vif.start_edn_req == 1'b1);
    cfg.clk_rst_vif.wait_clks(1);
    cfg.keymgr_vif.keymgr_en = lc_ctrl_pkg::Off;

    csr_spinwait(.ptr(ral.op_status.status), .exp_data(keymgr_pkg::OpWip),
                 .compare_op(CompareOpNe), .spinwait_delay_ns(10));

    csr_rd_check(.ptr(ral.op_status), .compare_value(keymgr_pkg::OpDoneFail));
    csr_rd_check(.ptr(ral.working_state), .compare_value(keymgr_pkg::StInvalid));
    cfg.clk_rst_vif.wait_clks(5);
  endtask

  virtual function bit get_check_en();
    return 0;
  endfunction

  task post_start();
    if (scb_h != null) begin
      scb_h.do_alert_check = 1;
    end
    cfg.en_scb = 1;
    super.post_start();
  endtask
endclass : keymgr_init_lc_disable_vseq
