#!/bin/bash
set -u

cd /home/opentitan

TEST_NAME="spi_host_stall_ready_mask"
TB_DIR="/home/opentitan/.tb_${TEST_NAME}"

rm -rf "$TB_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  import spi_host_cmd_pkg::*;

  logic clk_i;
  logic rst_ni;
  logic en_i;
  command_t command_i;
  logic command_valid_i;
  logic command_ready_o;
  logic sck_o;
  logic [0:0] csb_o;
  logic [3:0] sd_en_o;
  logic cmd_end_o;
  logic wr_en_o;
  logic sr_wr_ready_i;
  logic rd_en_o;
  logic sr_rd_ready_i;
  logic sample_en_o;
  logic shift_en_o;
  logic [1:0] speed_o;
  logic full_cyc_o;
  logic rx_stall_o;
  logic tx_stall_o;
  logic active_o;
  logic sw_rst_i;

  spi_host_fsm #(
    .NumCS(1)
  ) dut (
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .en_i(en_i),
    .command_i(command_i),
    .command_valid_i(command_valid_i),
    .command_ready_o(command_ready_o),
    .sck_o(sck_o),
    .csb_o(csb_o),
    .sd_en_o(sd_en_o),
    .cmd_end_o(cmd_end_o),
    .wr_en_o(wr_en_o),
    .sr_wr_ready_i(sr_wr_ready_i),
    .rd_en_o(rd_en_o),
    .sr_rd_ready_i(sr_rd_ready_i),
    .sample_en_o(sample_en_o),
    .shift_en_o(shift_en_o),
    .speed_o(speed_o),
    .full_cyc_o(full_cyc_o),
    .rx_stall_o(rx_stall_o),
    .tx_stall_o(tx_stall_o),
    .active_o(active_o),
    .sw_rst_i(sw_rst_i)
  );

  always #5 clk_i = ~clk_i;

  task automatic drive_write_cmd();
    command_i = '0;
    command_i.csid = '0;
    command_i.segment.speed = Standard;
    command_i.segment.cmd_wr_en = 1'b1;
    command_i.segment.cmd_rd_en = 1'b0;
    command_i.segment.len = 9'd0;
    command_i.segment.csaat = 1'b0;
    command_i.configopts = '0;
  endtask

  initial begin
    clk_i = 1'b0;
    rst_ni = 1'b0;
    en_i = 1'b1;
    sw_rst_i = 1'b0;
    command_i = '0;
    command_valid_i = 1'b0;
    sr_wr_ready_i = 1'b1;
    sr_rd_ready_i = 1'b1;

    repeat (2) @(posedge clk_i);
    rst_ni = 1'b1;
    @(posedge clk_i);

    drive_write_cmd();
    sr_wr_ready_i = 1'b0;
    command_valid_i = 1'b1;
    #1;

    if (tx_stall_o !== 1'b1) begin
      $display("TB_FAIL: expected tx_stall_o to assert for a stalled write command");
      $finish;
    end

    if (command_ready_o !== 1'b0) begin
      $display("TB_FAIL: command_ready_o must be low during stall, got %0b", command_ready_o);
      $finish;
    end

    $display("TB_PASS: command_ready_o stayed low while tx_stall_o was asserted");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/files.f" <<EOF
/home/opentitan/hw/ip/prim/rtl/prim_util_pkg.sv
/home/opentitan/hw/ip/prim/rtl/prim_assert.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_reg_pkg.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_cmd_pkg.sv
/home/opentitan/hw/ip/spi_host/rtl/spi_host_fsm.sv
$TB_DIR/tb.sv
EOF

set +e
vcs -full64 -sverilog -timescale=1ns/1ps -top tb \
  +incdir+/home/opentitan/hw/ip/prim/rtl \
  -f "$TB_DIR/files.f" \
  -Mdir="$TB_DIR/csrc" \
  -o "$TB_DIR/simv" \
  -l "$TB_DIR/compile.log"
compile_rc=$?

run_rc=0
if [ "$compile_rc" -eq 0 ]; then
  "$TB_DIR/simv" -l "$TB_DIR/run.log"
  run_rc=$?
  if [ "$run_rc" -eq 0 ]; then
    if grep -q "TB_FAIL:" "$TB_DIR/run.log"; then
      run_rc=1
    elif grep -q "TB_PASS:" "$TB_DIR/run.log"; then
      run_rc=0
    else
      run_rc=1
    fi
  fi
fi
set -e

if [ "$compile_rc" -ne 0 ]; then
  rc="$compile_rc"
else
  rc="$run_rc"
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

