tb_script:
#!/bin/bash
set -euo pipefail

cd /home/opentitan
source /etc/opentitan_tools_path.sh 2>/dev/null || true

TB_DIR=/home/opentitan/.tb_uart_status
mkdir -p "${TB_DIR}"

python3 <<'PY'
from pathlib import Path

path = Path("hw/ip/uart/dv/env/uart_scoreboard.sv")
text = path.read_text()
original = text

old_predict = """  virtual function void predict_tx_watermark_intr(uint tx_q_size = tx_q.size);
    uint watermark = get_watermark_bytes_by_level(ral.fifo_ctrl.txilvl.get_mirrored_value());
    intr_exp[TxWatermark] = get_non_sticky_interrupt(.cur_intr(intr_exp[TxWatermark]),
                                                     .new_intr(tx_q_size < watermark),
                                                     .triggered(tx_watermark_triggered));
  endfunction
"""
new_predict = """  virtual function void predict_tx_watermark_intr(uint tx_q_size = tx_q.size);
    uint watermark = get_watermark_bytes_by_level(ral.fifo_ctrl.txilvl.get_mirrored_value());
    intr_exp[TxWatermark] = (tx_q_size < watermark);
  endfunction
"""
if old_predict in text:
    text = text.replace(old_predict, new_predict)

old_clear = """            cfg.clk_rst_vif.wait_clks(1);
            intr_exp &= ~intr_wdata;"""
new_clear = """            cfg.clk_rst_vif.wait_clks(1);
            intr_wdata[TxWatermark] = 1'b0;
            intr_exp &= ~intr_wdata;"""
if "intr_wdata[TxWatermark] = 1'b0;" not in text and \
        "intr_exp &= ~(intr_wdata & ~(1 << TxWatermark));" not in text:
    if old_clear not in text:
        raise SystemExit("Failed to patch TxWatermark clear handling in uart_scoreboard.sv")
    text = text.replace(old_clear, new_clear)

reset_start = text.index('  virtual function void reset(string kind = "HARD");')
check_start = text.index("  function void check_phase", reset_start)
reset_block = text[reset_start:check_start]
old_reset = """    intr_exp             = ral.intr_state.get_reset();
    rdata_exp            = ral.rdata.get_reset();
"""
new_reset = """    intr_exp             = ral.intr_state.get_reset();
    predict_tx_watermark_intr();
    rdata_exp            = ral.rdata.get_reset();
"""
if "predict_tx_watermark_intr();" not in reset_block:
    if old_reset not in text:
        raise SystemExit("Failed to patch reset-time TxWatermark prediction in uart_scoreboard.sv")
    text = text.replace(old_reset, new_reset)

reset_block = text[reset_start:text.index("  function void check_phase", reset_start)]
has_predict = (
    "intr_exp[TxWatermark] = (tx_q_size < watermark);" in text or
    "intr_exp[TxWatermark] = (tx_q_size < watermark) || status_intr_test[TxWatermark];" in text
)
has_clear_mask = (
    "intr_wdata[TxWatermark] = 1'b0;" in text or
    "intr_exp &= ~(intr_wdata & ~(1 << TxWatermark));" in text
)
has_reset_predict = "predict_tx_watermark_intr();" in reset_block

if not (has_predict and has_clear_mask and has_reset_predict):
    raise SystemExit("uart_scoreboard.sv is missing the required TxWatermark hot-fix")

if text != original:
    path.write_text(text)
PY

cat > hw/ip/uart/dv/env/seq_lib/uart_status_watermark_vseq.sv <<'EOF'
// Copyright lowRISC contributors.
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class uart_status_watermark_vseq extends uart_intr_vseq;
  `uvm_object_utils(uart_status_watermark_vseq)
  `uvm_object_new

  task body();
    int level;
    int watermark_bytes;

    do_clear_all_interrupts = 0;
    do_dut_shutdown = 0;
    cfg.m_uart_agent_cfg.en_rx_checks = 0;

    do_interrupt = 1'b1;
    baud_rate = BaudRate9600;
    en_tx = 1'b1;
    en_rx = 1'b1;
    en_parity = 1'b0;
    odd_parity = 1'b0;
    en_noise_filter = 1'b0;
    uart_period_glitch_pct = 0;
    dly_to_access_fifo = 0;
    en_intr = '0;
    en_intr[TxWatermark] = 1'b1;

    uart_init();

    ral.fifo_ctrl.txilvl.set(1);
    ral.fifo_ctrl.rxilvl.set(0);
    csr_update(ral.fifo_ctrl);
    clear_fifos(.clear_tx_fifo(1), .clear_rx_fifo(1));
    cfg.clk_rst_vif.wait_clks(2);

    // A status interrupt must reflect the empty TX FIFO immediately after reset or FIFO clear.
    check_one_intr(.uart_intr(TxWatermark), .exp(1));
    csr_wr(.ptr(ral.intr_state), .value(1 << TxWatermark));
    check_one_intr(.uart_intr(TxWatermark), .exp(1));

    level = ral.fifo_ctrl.txilvl.get_mirrored_value();
    watermark_bytes = get_watermark_bytes_by_level(level) + 1;
    drive_tx_bytes(.num_bytes(watermark_bytes - 1));
    check_one_intr(.uart_intr(TxWatermark), .exp(1));
    drive_tx_bytes(.num_bytes(1));
    check_one_intr(.uart_intr(TxWatermark), .exp(0));

    csr_spinwait(.ptr(ral.fifo_status.txlvl),
                 .exp_data(get_watermark_bytes_by_level(level)),
                 .compare_op(CompareOpLt));
    check_one_intr(.uart_intr(TxWatermark), .exp(1));

    wait_for_all_tx_bytes();
    cfg.m_uart_agent_cfg.vif.wait_for_tx_idle();
  endtask : body
endclass : uart_status_watermark_vseq
EOF

grep -q 'uart_status_watermark_vseq.sv' hw/ip/uart/dv/env/seq_lib/uart_vseq_list.sv || \
  printf '\n`include "uart_status_watermark_vseq.sv"\n' >> hw/ip/uart/dv/env/seq_lib/uart_vseq_list.sv

grep -q 'seq_lib/uart_status_watermark_vseq.sv' hw/ip/uart/dv/env/uart_env.core || \
  perl -0pi -e 's/(\- seq_lib\/uart_intr_vseq\.sv: \{is_include_file: true\}\n)/$1      - seq_lib\/uart_status_watermark_vseq.sv: {is_include_file: true}\n/' \
    hw/ip/uart/dv/env/uart_env.core

perl -0pi -e 's/uvm_test_seq: uart_intr_vseq/uvm_test_seq: uart_status_watermark_vseq/' \
  hw/ip/uart/dv/uart_sim_cfg.hjson

rm -rf /home/opentitan/scratch/HEAD/uart-sim-vcs

set +e
./util/dvsim/dvsim.py hw/ip/uart/dv/uart_sim_cfg.hjson \
  -i uart_intr \
  -t vcs \
  --fixed-seed=1 \
  --build-seed=1 2>&1 | tee "${TB_DIR}/dvsim.log"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [[ "${rc}" -eq 0 ]]; then
  echo "TEST: uart_status_watermark ... PASS"
else
  echo "TEST: uart_status_watermark ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "${rc}"

