#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="hmac_secure_wipe_overwrite"
TB_DIR="/home/opentitan/.tb_hmac_secure_wipe"
LOG_DIR="$TB_DIR/logs"
SCRATCH_DIR="$TB_DIR/scratch"
VSEQ_FILE="/home/opentitan/hw/ip/hmac/dv/env/seq_lib/hmac_secure_wipe_overwrite_vseq.sv"
VSEQ_LIST_FILE="/home/opentitan/hw/ip/hmac/dv/env/seq_lib/hmac_vseq_list.sv"
SIM_CFG_FILE="$TB_DIR/hmac_secure_wipe_tbgen_sim_cfg.hjson"
RUN_LOG="$LOG_DIR/dvsim.log"

mkdir -p "$LOG_DIR"
rm -rf "$SCRATCH_DIR"

cat > "$VSEQ_FILE" <<'EOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class hmac_secure_wipe_overwrite_vseq extends hmac_base_vseq;
  `uvm_object_utils(hmac_secure_wipe_overwrite_vseq)
  `uvm_object_new

  localparam bit [31:0] kWipeValue = 32'hffff_ffff;

  virtual task body();
    bit [31:0] key[];
    bit [7:0] msg[];
    bit [31:0] digest_before[16];
    bit [31:0] digest_after[16];
    bit seen_non_wipe_value;

    key = new[NUM_KEYS];
    foreach (key[i]) begin
      key[i] = 32'h1020_3040 + i;
    end

    msg = new[19];
    msg = '{
      8'h73, 8'h65, 8'h63, 8'h75, 8'h72, 8'h65, 8'h5f, 8'h77, 8'h69, 8'h70,
      8'h65, 8'h5f, 8'h63, 8'h68, 8'h65, 8'h63, 8'h6b, 8'h21, 8'h0a
    };

    hmac_init(.sha_en(1'b1),
              .hmac_en(1'b1),
              .endian_swap(1'b1),
              .digest_swap(1'b1),
              .digest_size(4'b0010),
              .key_length(5'b0_0010),
              .intr_fifo_empty_en(1'b1),
              .intr_hmac_done_en(1'b1),
              .intr_hmac_err_en(1'b1));

    wr_key(key);
    trigger_hash();
    wr_msg(msg, /* non_blocking */ 1'b0);
    trigger_process();

    csr_spinwait(.ptr(ral.intr_state.hmac_done), .exp_data(1'b1));
    csr_wr(.ptr(ral.intr_state.hmac_done), .value(1'b1));

    csr_rd_digest(digest_before);
    seen_non_wipe_value = 1'b0;
    for (int i = 0; i < 8; i++) begin
      if (digest_before[i] != kWipeValue) begin
        seen_non_wipe_value = 1'b1;
      end
    end
    `DV_CHECK_EQ(seen_non_wipe_value, 1'b1,
                 "Digest unexpectedly matched wipe value before wipe_secret")

    csr_wr(.ptr(ral.wipe_secret), .value(kWipeValue));
    cfg.wipe_secret_triggered = 1'b1;
    csr_rd_digest(digest_after);

    for (int i = 0; i < 8; i++) begin
      `DV_CHECK_EQ(digest_after[i], kWipeValue,
                   $sformatf("digest_after[%0d] should be overwritten", i))
    end
    for (int i = 8; i < 16; i++) begin
      `DV_CHECK_EQ(digest_after[i], 32'h0000_0000,
                   $sformatf("digest_after[%0d] should remain zero in SHA-256 mode", i))
    end
    cfg.wipe_secret_triggered = 1'b0;
  endtask
endclass
EOF

sed -i '/hmac_secure_wipe_overwrite_vseq\.sv/d' "$VSEQ_LIST_FILE"
echo '`include "/home/opentitan/hw/ip/hmac/dv/env/seq_lib/hmac_secure_wipe_overwrite_vseq.sv"' \
  >> "$VSEQ_LIST_FILE"

cat > "$SIM_CFG_FILE" <<'EOF'
{
  import_cfgs: ["{proj_root}/hw/ip/hmac/dv/hmac_sim_cfg.hjson"]
  tests: [
    {
      name: hmac_secure_wipe_overwrite
      uvm_test_seq: hmac_secure_wipe_overwrite_vseq
      reseed: 1
    }
  ]
}
EOF

set +e
timeout 1700s ./util/dvsim/dvsim.py "$SIM_CFG_FILE" \
  -i "$TEST_NAME" \
  -t vcs \
  --fixed-seed 1 \
  --build-seed 1 \
  --reseed 1 \
  --scratch-root "$SCRATCH_DIR" \
  --purge \
  2>&1 | tee "$RUN_LOG"
rc=${PIPESTATUS[0]}
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

#!/bin/bash
set -euo pipefail

cd /home/opentitan

TEST_NAME="usbdev_setup_priority_over_stall_response"
TB_ROOT="/home/opentitan/.tb_${TEST_NAME}"
SEQ_FILE="hw/ip/usbdev/dv/env/seq_lib/${TEST_NAME}_vseq.sv"
SIM_CFG="${TB_ROOT}/${TEST_NAME}_sim_cfg.hjson"
SCRATCH_ROOT="${TB_ROOT}/scratch"
SEED="6059828404840696268329756370818438228836193083784097444560659638759758565984"

mkdir -p "$TB_ROOT"

cat > "$SEQ_FILE" <<'EOF'
// Copyright lowRISC contributors (OpenTitan project).
// Licensed under the Apache License, Version 2.0, see LICENSE for details.
// SPDX-License-Identifier: Apache-2.0

class usbdev_setup_priority_over_stall_response_vseq extends usbdev_base_vseq;
  `uvm_object_utils(usbdev_setup_priority_over_stall_response_vseq)

  `uvm_object_new

  virtual task body();
    buf_init();

    // Accept both OUT and SETUP traffic on EP0, but STALL the OUT transaction.
    configure_out_trans(ep_default);
    configure_setup_trans(ep_default);
    csr_wr(.ptr(ral.out_stall[0].endpoint[ep_default]), .value(1'b1));

    // A long OUT packet that is rejected with STALL must still roll back internal RX state.
    send_prnd_out_packet(ep_default, PidTypeData0, .randomize_length(1'b0), .num_of_bytes(64));
    check_response_matches(PidTypeStall);

    // The next SETUP transaction must still be received correctly.
    send_prnd_setup_packet(ep_default);
    check_response_matches(PidTypeAck);
    check_rx_packet(ep_default, .setup(1'b1), .exp_buffer_id(setup_buffer_id),
                    .exp_byte_data(m_data_pkt.data), .buffer_known(1'b1));
  endtask
endclass : usbdev_setup_priority_over_stall_response_vseq
EOF

if ! grep -q "${TEST_NAME}_vseq.sv" hw/ip/usbdev/dv/env/seq_lib/usbdev_vseq_list.sv; then
  sed -i '/`include "usbdev_setup_priority_vseq.sv"/i `include "usbdev_setup_priority_over_stall_response_vseq.sv"' \
    hw/ip/usbdev/dv/env/seq_lib/usbdev_vseq_list.sv
fi

if ! grep -q "seq_lib/${TEST_NAME}_vseq.sv" hw/ip/usbdev/dv/env/usbdev_env.core; then
  sed -i '/seq_lib\/usbdev_setup_priority_vseq.sv/i\      - seq_lib\/usbdev_setup_priority_over_stall_response_vseq.sv: {is_include_file: true}' \
    hw/ip/usbdev/dv/env/usbdev_env.core
fi

cat > "$SIM_CFG" <<'EOF'
{
  import_cfgs: ["{proj_root}/hw/ip/usbdev/dv/usbdev_sim_cfg.hjson"]
  tests: [
    {
      name: usbdev_setup_priority_over_stall_response
      uvm_test_seq: usbdev_setup_priority_over_stall_response_vseq
      reseed: 1
    }
  ]
}
EOF

rm -rf "$SCRATCH_ROOT"
mkdir -p "$SCRATCH_ROOT"

set +e
timeout 1800 ./util/dvsim/dvsim.py "$SIM_CFG" \
  -i "$TEST_NAME" \
  -t vcs \
  --fixed-seed "$SEED" \
  --scratch-root "$SCRATCH_ROOT" \
  -v m
rc=$?
set -e

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: ${TEST_NAME} ... PASS"
else
  echo "TEST: ${TEST_NAME} ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"

#!/bin/bash
cd /home/opentitan
set +e

TEST_NAME="prim_count_err_o_skew"
TB_DIR="/home/opentitan/.tb_prim_count_skew"
BUILD_DIR="/home/opentitan/build/local_dv_prim_count_skew_0.1"
RUN_LOG="$TB_DIR/run.log"

rm -rf "$TB_DIR" "$BUILD_DIR"
mkdir -p "$TB_DIR"

cat > "$TB_DIR/prim_flop.sv" <<'EOF'
module prim_flop #(
  parameter int Width = 1,
  parameter logic [Width-1:0] ResetValue = '0
) (
  input clk_i,
  input rst_ni,
  input [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);
  if (ResetValue == '0) begin : gen_fast_q
    always @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) q_o <= ResetValue;
      else q_o <= #1 d_i;
    end
  end else begin : gen_slow_q
    always @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) q_o <= ResetValue;
      else q_o <= #3 d_i;
    end
  end
endmodule
EOF

cat > "$TB_DIR/tb.sv" <<'EOF'
module tb;
  localparam int Width = 2;

  logic clk_i;
  logic rst_ni;
  logic clr_i;
  logic set_i;
  logic [Width-1:0] set_cnt_i;
  logic incr_en_i;
  logic decr_en_i;
  logic [Width-1:0] step_i;
  logic commit_i;
  logic [Width-1:0] cnt_o;
  logic [Width-1:0] cnt_after_commit_o;
  logic err_o;
  int err_pulses;

  prim_count #(
    .Width(Width),
    .ResetValue('0),
    .EnableAlertTriggerSVA(0)
  ) dut (
    .clk_i,
    .rst_ni,
    .clr_i,
    .set_i,
    .set_cnt_i,
    .incr_en_i,
    .decr_en_i,
    .step_i,
    .commit_i,
    .cnt_o,
    .cnt_after_commit_o,
    .err_o
  );

  initial clk_i = 0;
  always #5 clk_i = ~clk_i;

  always @(posedge err_o) begin
    err_pulses++;
    $display("ERR pulse at %0t cnt_o=%0d cnt_after_commit_o=%0d", $time, cnt_o,
             cnt_after_commit_o);
  end

  task automatic drive_idle();
    clr_i = 0;
    set_i = 0;
    set_cnt_i = '0;
    incr_en_i = 0;
    decr_en_i = 0;
    step_i = 'd1;
    commit_i = 0;
  endtask

  initial begin
    err_pulses = 0;
    drive_idle();
    rst_ni = 0;
    repeat (2) @(negedge clk_i);
    rst_ni = 1;

    repeat (3) begin
      @(negedge clk_i);
      incr_en_i = 1;
      commit_i = 1;
      step_i = 'd1;
      @(negedge clk_i);
      drive_idle();
    end

    repeat (2) @(negedge clk_i);
    if (err_pulses != 0) begin
      $fatal(1, "err_o pulsed %0d times during legal count updates", err_pulses);
    end
    $display("PASS no err_o pulses observed");
    $finish;
  end
endmodule
EOF

cat > "$TB_DIR/prim_count_skew.core" <<'EOF'
CAPI=2:
name: "local:dv:prim_count_skew:0.1"
description: "prim_count skewed flop glitch check"
filesets:
  files_dv:
    depend:
      - lowrisc:prim:count
    files:
      - prim_flop.sv
      - tb.sv
    file_type: systemVerilogSource

targets:
  sim:
    toplevel: tb
    default_tool: vcs
    filesets:
      - files_dv
EOF

fusesoc --cores-root . --cores-root "$TB_DIR" run --target=sim --tool=vcs \
  local:dv:prim_count_skew:0.1 >"$RUN_LOG" 2>&1
tool_rc=$?
cat "$RUN_LOG"

# VCS/FuseSoC does not reliably propagate a failing simulation as a non-zero exit
# code here, so fall back to the runtime log when needed.
if [ "$tool_rc" -ne 0 ]; then
  rc="$tool_rc"
elif grep -q "PASS no err_o pulses observed" "$RUN_LOG" && ! grep -q '^Fatal:' "$RUN_LOG"; then
  rc=0
else
  rc=1
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$rc" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$rc"
